ALTER TABLE public.films ADD COLUMN IF NOT EXISTS posters_i18n JSONB DEFAULT '{}'::jsonb;


UPDATE public.films SET tmdb_id = 98, titoli_i18n = '{"it":"Il Gladiatore","de":"Gladiator","en":"Gladiator","es":"Gladiator","fr":"Gladiator"}'::jsonb, trame_i18n = '{"it":"Il generale romano Massimo Decimo Meridio viene tradito dal perfido Commodo, figlio dell''imperatore Marco Aurelio, che usurpa il trono e fa sterminare la famiglia di Massimo. Catturato e ridotto in schiavitù, Massimo viene addestrato come gladiatore dal lanista Prossimo. La sua straordinaria abilità nell''arena lo condurrà fino al Colosseo a Roma, dove cercherà la sua vendetta contro il nuovo imperatore.","de":"Der gefeierte römische Feldherr Maximus wird vom sterbenden Kaiser Marcus Aurelius gebeten, seine Nachfolge anzutreten. Um dies zu verhindern, tötet Aurelius’ Sohn seinen Vater und ordnet die Exekution von Maximus und seiner Familie an. Maximus gelingt die Flucht. Verwundet wird er von einem Sklavenhändler gefangen genommen und muss sich fortan als Gladiator beweisen. Als Kampfmaschine hat er schließlich nur noch ein Ziel: Rache an seinem Peiniger zu nehmen …","en":"After the death of Emperor Marcus Aurelius, his devious son takes power and demotes Maximus, one of Rome''s most capable generals who Marcus preferred. Eventually, Maximus is forced to become a gladiator and battle to the death against other men for the amusement of paying audiences.","es":"En el año 180, el Imperio Romano domina todo el mundo conocido. Tras una gran victoria sobre los bárbaros del norte, el anciano emperador Marco Aurelio decide transferir el poder a Máximo, bravo general de sus ejércitos y hombre de inquebrantable lealtad al imperio. Pero su hijo Cómodo, que aspiraba al trono, no lo acepta y trata de asesinar a Máximo.","fr":"Le général romain Maximus est le plus fidèle soutien de l''empereur Marc Aurèle, qu''il a conduit de victoire en victoire avec une bravoure et un dévouement exemplaires. Jaloux du prestige de Maximus, et plus encore de l''amour que lui voue l''empereur, le fils de Marc Aurèle, Commode, s''arroge brutalement le pouvoir, puis ordonne l''arrestation du général et son exécution. Maximus échappe à ses assassins mais ne peut empêcher le massacre de sa famille. Capturé par un marchand d''esclaves, il devient gladiateur et prépare sa vengeance."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/euOKjQaV1QXtzLyNZAa1PMHGJlJ.jpg","de":"https://image.tmdb.org/t/p/w500/32wJunadteAxUkXnbQ1lHjjp5pa.jpg","en":"https://image.tmdb.org/t/p/w500/aDb548BOkFfI4nFm0kx8A3Ezh7H.jpg","es":"https://image.tmdb.org/t/p/w500/90QFOG5zSN4cbrIVs4DL4ePAuA5.jpg","fr":"https://image.tmdb.org/t/p/w500/56Yb1T9GgYqMBM9nI8JxfmPSN8v.jpg"}'::jsonb WHERE id = 2;
UPDATE public.films SET tmdb_id = 7191, titoli_i18n = '{"it":"Cloverfield","en":"Cloverfield","es":"Monstruoso","fr":"Cloverfield","de":"Cloverfield"}'::jsonb, trame_i18n = '{"it":"Durante una festa di addio a New York per Rob, un ragazzo in partenza per il Giappone, la città viene scossa dall''attacco improvviso di un mostro gigante di origine sconosciuta. Rob e i suoi amici si avventurano tra le rovine di Manhattan per salvare Beth, la ragazza di cui Rob è innamorato, rimasta intrappolata nel suo appartamento. L''intera vicenda è raccontata attraverso il punto di vista di una videocamera amatoriale che documenta in tempo reale il caos e la sopravvivenza del gruppo.","en":"Five young New Yorkers throw their friend a going-away party the night that a monster the size of a skyscraper descends upon the city. Told from the point of view of their video camera, the film is a document of their attempt to survive the most surreal, horrifying event of their lives.","es":"La noche en que varios jóvenes neoyorquinos celebran la fiesta de despedida de un amigo en Manhattan, un monstruo del tamaño de un rascacielos llega a la ciudad. Contada desde el punto de vista de la videocámara de uno de ellos, este es el escalofriante documento sobre sus intentos por sobrevivir durante los momentos más increíbles y terroríficos de sus vidas.","fr":"New York - Ses amis et relations ont organisé chez Rob une fête en l''honneur de son départ pour le Japon. Parmi eux, Hud, vidéaste d''un soir, chargé d''immortaliser l''événement. Soudain une violente secousse ébranle l''immeuble. Les invités se précipitent dans la rue où une foule inquiète s''est rassemblée en quelques instants. Une ombre immense se profile dans le ciel, un grondement sourd se fait entendre... et la tête de la Statue de la Liberté s''effondre brutalement sur la chaussée. L''attaque du siècle vient de commencer...","de":"Eine ausgelassene Abschiedsparty mitten in Manhattan, doch plötzlich wackeln sprichwörtlich die Wände und Explosionen ziehen eine Schneise durch Manhattan, infernalisches Gebrüll tönt durch die Straßenschluchten und etwas, das dem Meer entstiegen ist, hat der Freiheitsstatue den Kopf abgerissen und schleudert diesen zur Begrüßung quer durch die halbe Stadt.  Das Monstrum wird „Cloverfield“ genannt und für die gerade eben noch Feiernden bedeutet das erst mal nur eins: Raus aus der Stadt, möglichst lebendig, und auch ohne in die Schusslinie der Army zu geraten, die „Cloverfield“ alles entgegen feuert, was verfügbar ist."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/z8CrCAEsLSdvrbZ1OjkvOmmAlYa.jpg","en":"https://image.tmdb.org/t/p/w500/qIegUGJqyMMCRjkKV1s7A9MqdJ8.jpg","es":"https://image.tmdb.org/t/p/w500/8FBpammgqlX9j9yQt301PHh4sJb.jpg","fr":"https://image.tmdb.org/t/p/w500/zyzGgP5IIkO9d3PQz7me0pPl2vm.jpg","de":"https://image.tmdb.org/t/p/w500/lmQPopu8A4W9HuskcaGTpqILRsj.jpg"}'::jsonb WHERE id = 3;
UPDATE public.films SET tmdb_id = 3049, titoli_i18n = '{"it":"Ace Ventura - L''acchiappanimali","en":"Ace Ventura: Pet Detective","fr":"Ace Ventura, détective chiens et chats","es":"Ace Ventura, un detective diferente","de":"Ace Ventura - Ein tierischer Detektiv"}'::jsonb, trame_i18n = '{"it":"Ace Ventura è un eccentrico e stravagante investigatore privato specializzato nel ritrovare animali scomparsi. Alla vigilia del Super Bowl, viene ingaggiato per ritrovare Snowflake, il delfino mascotta dei Miami Dolphins, finito al centro di un misterioso complotto di vendetta legato all''ex giocatore Ray Finkle.","en":"He''s Ace Ventura: Pet Detective. The Ace is on the case to find the Miami Dolphins'' missing mascot and quarterback Dan Marino. He goes eyeball to eyeball with a man-eating shark, stakes out the Miami Dolphins and woos and wows the ladies. Whether he''s undercover, under fire or underwater, he always gets his man… or beast!","fr":"Ace Ventura, un jeune homme décontracté à la banane arrogante et à la démarche élastique, est le Sherlock Holmes de la gent animale. Le voici à nouveau sur les dents quand le dauphin nommé Flocon de neige, mascotte de l''équipe de football américain de Miami, manque à l''appel.","es":"El detective Ace Ventura, especializado en rescatar animales secuestrados, recibe el encargo de localizar y rescatar el delfin Copo de Nieve, mascota del equipo de fútbol de Miami, que ha sido secuestrado el día anterior a la gran final que debe disputar el equipo.","de":"Detektiv Ace Ventura ist darauf spezialisiert, verlorengegangene Haustiere aufzuspüren. Als ihm der Fall des entführten Delphins Snowflake, dem Maskottchen der Footballmannschaft Miami Dolphins, übertragen wird, erweisen sich die animalischen Instinkte des Schnüfflers als äußerst hilfreich. Bei seinen Ermittlungen stößt Ace zwischen Liebesabenteuern und handgreiflichen Auseinandersetzungen mit den Cops schließlich auf einen ehemaligen Dolphins-Spieler, der nach einem Irrenhausaufenthalt untergetaucht ist."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ptTaBr68fiHfjDVNmQRoOantMDy.jpg","en":"https://image.tmdb.org/t/p/w500/pqiRuETmuSybfnVZ7qyeoXhQyN1.jpg","fr":"https://image.tmdb.org/t/p/w500/tquh5DEbgRPFBHukUp9mcPbjEBb.jpg","es":"https://image.tmdb.org/t/p/w500/zByKfhPuFUEymc0uzHGdIfO7dx5.jpg","de":"https://image.tmdb.org/t/p/w500/h8fixwTBtiEHRHFLjzgulZeHXwp.jpg"}'::jsonb WHERE id = 4;
UPDATE public.films SET tmdb_id = 238, titoli_i18n = '{"it":"Il Padrino","en":"The Godfather","fr":"Le Parrain","de":"Der Pate","es":"El padrino"}'::jsonb, trame_i18n = '{"it":"A New York, nel 1945, Don Vito Corleone è il capo di una potente famiglia mafiosa. Dopo aver rifiutato di entrare nel business della droga proposto da un clan rivale, Don Vito subisce un grave attentato. Suo figlio minore Michael, un eroe di guerra fino ad allora estraneo alle attività criminali della famiglia, decide di intervenire per proteggere il padre e vendicarsi. Questo evento darà inizio alla sua inesorabile ascesa e trasformazione nel nuovo spietato Padrino.","en":"Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.","fr":"La Seconde Guerre mondiale vient de s''achever. À New York, le « parrain » Don Corleone, l''un des chefs respectés de la mafia, se sent vieillir. Il refuse de s''adapter à son temps et de se lancer, comme ses pairs, dans le trafic de drogue. Une frilosité qui entrave la bonne marche des affaires des autres « familles » et qui lui vaut d''être la cible d''un attentat. Don Corleone survit à ses blessures, mais reste très diminué. Mike, son plus jeune fils, qui jusque-là se tenait à l''écart des affaires de son père, devient le plus dévoué de ses héritiers. Plus efficace que ses frères, Sonny et Fredo, il venge son père et organise l''élimination de ses adversaires…","de":"Don Vito Corleone ist der Kopf einer der einflußreichsten Mafia-Familien New Yorks. Als die anderen Familien der Stadt beschließen, neben Glücksspiel und Schutzgelderpressungen nun auch den Handel mit Drogen als Erwerbsquelle zu nutzen und sich Don Corleone diesem Vorhaben nicht anschließen möchte, wird er zum Ziel eines hinterhältigen Mordanschlags. Nun steht Vitos Sohn Michael in der Verantwortung, in die Fußstapfen seines Vaters zu treten, obwohl er mit den Geschäften der Familie bis dato nichts zu tun haben wollte.","es":"Don Vito Corleone, conocido dentro de los círculos del hampa como \"El Padrino\", es el patriarca de una de las cinco familias que ejercen el mando de la Cosa Nostra en Nueva York (Estados Unidos) durante la década de 1940. Don Corleone tiene cuatro hijos: una chica, Connie, y tres varones; Sonny, Michael y Fredo. Cuando Vito reclina intervenir en el negocio de estupefacientes, empieza una cruenta lucha de violentos episodios entre las distintas familias del crimen organizado."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/gemuM3FvVaWSEBrfk6nVFIOBhBY.jpg","en":"https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg","fr":"https://image.tmdb.org/t/p/w500/k3uIbYtiuK8pwbCcbma29nTqmgG.jpg","de":"https://image.tmdb.org/t/p/w500/uumEbSnYqeV1oennyVx8DPVjujF.jpg","es":"https://image.tmdb.org/t/p/w500/5HlLUsmsv60cZVTzVns9ICZD6zU.jpg"}'::jsonb WHERE id = 6;
UPDATE public.films SET tmdb_id = 240, titoli_i18n = '{"it":"Il Padrino - Parte II","de":"Der Pate - Teil II","en":"The Godfather Part II","fr":"Le Parrain, 2e partie","es":"El padrino II"}'::jsonb, trame_i18n = '{"it":"Il film sviluppa due linee narrative parallele: da un lato segue la giovinezza di Vito Corleone, dalla fuga dalla Sicilia ai primi del Novecento fino alla sua ascesa come ''Padrino'' a New York; dall''altro racconta le vicende del figlio Michael negli anni ''50, intenzionato ad espandere l''impero di famiglia a Las Vegas e a Cuba, affrontando tradimenti interni, indagini governative e una progressiva disgregazione morale e familiare.","de":"Michael Corleone ist jetzt der Pate seiner Familie und führt diese Aufgabe mit der nötigen Gnadenlosigkeit aus. Als er in Las Vegas und auf Kuba expandieren will, weil ihm die alten Geschäftsideen nichts mehr einbringen, treten Schwierigkeiten auf. Um diese zu klären, veranlaßt Michael eine große Säuberungsaktion, die auch vor den Familienmitgliedern nicht halt macht.","en":"In the continuing saga of the Corleone crime family, a young Vito Corleone grows up in Sicily and in 1910s New York. In the 1950s, Michael Corleone attempts to expand the family business into Las Vegas, Hollywood and Cuba.","fr":"Depuis la mort de Don Vito Corleone, son fils Michael règne sur la famille. Amené à négocier avec la mafia juive, il perd alors le soutien d''un de ses lieutenants, Frankie Pentageli. Échappant de justesse à un attentat, Michael tente de retrouver le coupable, soupçonnant Hyman Roth, le chef de la mafia juive. Vito Corleone, immigrant italien, arrive à New York au début du siècle ; très vite, il devient un des caïds du quartier, utilisant la violence comme moyen de régler toutes les affaires. Seul au départ, il bâtit peu à peu un véritable empire, origine de la fortune de la famille des Corleone.","es":"Continuación de la saga de los Corleone con dos historias paralelas: la elección de Michael Corleone como jefe de los negocios familiares y los orígenes del patriarca, el ya fallecido Don Vito, primero en Sicilia y luego en Estados Unidos, donde, empezando desde abajo, llegó a ser un poderosísimo jefe de la mafia de Nueva York."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/jftmAcdl5D94eANbhHugbUJDULI.jpg","de":"https://image.tmdb.org/t/p/w500/ydzBlAMJTo9jOG5i8aRpZec0jF3.jpg","en":"https://image.tmdb.org/t/p/w500/8a1lJs7mFyGhGhZZDT1azJUoQiZ.jpg","fr":"https://image.tmdb.org/t/p/w500/fATmEcLwO3tTiisa8gYxhV3x4sS.jpg","es":"https://image.tmdb.org/t/p/w500/mbry0W5PRylSUHsYzdiY2FSJwze.jpg"}'::jsonb WHERE id = 7;
UPDATE public.films SET tmdb_id = 242, titoli_i18n = '{"fr":"Le Parrain, 3e partie","de":"Der Pate - Teil III","es":"El padrino III","en":"The Godfather Part III","it":"Il Padrino - Parte III"}'::jsonb, trame_i18n = '{"fr":"Atteignant la soixantaine, Michael Corleone désire à la fois renouer avec les siens et se réhabiliter aux yeux de la société, surtout de l''Église. Il arrivera presque à ses fins, mais sa vie passée et ses anciens ennemis le rattraperont plus vite. Michael Corleone est fatigué. Il veut prendre ses distances avec les activités mafieuses de sa famille. Il veut convertir ces activités en affaires légales. Kay, son ex-femme, lui fait même accepter que leur fils devienne un chanteur d''opéra et ne reprenne pas les activités familiales. Pendant ce temps, la fille de Michael, Mary, et son neveu, le fils de Sonny, Vincent, nouent une idylle qui n''est pas la bienvenue dans la famille. Il décide d''aider le Vatican à renflouer ses caisses et reçoit en échange le contrôle d''une entreprise immobilière leur appartenant. Attisant la jalousie de ses pairs, Michael échappe de justesse à un attentat commis par l''un d''eux. Vincent se propose alors pour reprendre les affaires de la famille en main.","de":"Der alternde Don Michael Corleone möchte den Familienbetrieb legalisieren und sich langsam aus dem Geschäft zurückziehen. Während er sich als Förderer der katholischen Kirche versucht, macht ihm vor allem ein Mensch zu schaffen: Vincent Mancini, Michaels zukünftiger Schwiegersohn und potentieller Nachfolger. Dieser schmiedet nämlich ganz andere Pläne.","es":"Michael Corleone, heredero del imperio de don Vito Corleone, intenta rehabilitarse socialmente y legitimar todas las posesiones de la familia negociando con el Vaticano. Después de luchar toda su vida se encuentra cansado y centra todas sus esperanzas en encontrar un sucesor que se haga cargo de los negocios. Vincent, el hijo ilegítimo de su hermano Sonny, parece ser el elegido.","en":"In the midst of trying to legitimize his business dealings in 1979 New York and Italy, aging mafia don, Michael Corleone seeks forgiveness for his sins while taking a young protege under his wing.","it":"Ormai anziano e tormentato dai sensi di colpa per i crimini del passato, in particolare per l''omicidio del fratello Fredo, Michael Corleone cerca di legalizzare le attività della famiglia e di ripulire il proprio nome attraverso una colossale donazione alla Chiesa Cattolica. Mentre tenta di districarsi dalle trame di potere e corruzione all''interno del Vaticano, Michael deve anche gestire la successione dinastica, designando come suo erede l''irrequieto e violento nipote Vincent Mancini, figlio naturale di suo fratello Sonny."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/6qDyBIl9vizY5pneZ2tREaa86UC.jpg","de":"https://image.tmdb.org/t/p/w500/iVjSuqHFFOqCFM4rdhUyysYWnnj.jpg","es":"https://image.tmdb.org/t/p/w500/l2D8Gzuzw8hN41UthdqM9Osu9I3.jpg","en":"https://image.tmdb.org/t/p/w500/lm3pQ2QoQ16pextRsmnUbG2onES.jpg","it":"https://image.tmdb.org/t/p/w500/niNFWEtPFgawysw20luHEonC4WI.jpg"}'::jsonb WHERE id = 8;
UPDATE public.films SET tmdb_id = 87, titoli_i18n = '{"it":"Indiana Jones e il tempio maledetto","fr":"Indiana Jones et le Temple maudit","en":"Indiana Jones and the Temple of Doom","es":"Indiana Jones y el templo maldito","de":"Indiana Jones und der Tempel des Todes"}'::jsonb, trame_i18n = '{"it":"Nel 1935, l''archeologo Indiana Jones sfugge a un agguato della malavita a Shanghai e si ritrova precipitato in India insieme alla cantante Willie Scott e al piccolo Short Round. Raggiunto un povero villaggio oppresso dalla sfortuna, accetta di aiutare gli abitanti a recuperare una pietra sacra Sankara rubata e a liberare tutti i bambini rapiti. La sua missione lo porterà al palazzo di Pankot, nascondiglio della spietata setta dei Thuggee, dedita a sacrifici umani e al culto della dea Kali.","fr":"L''archéologue Indiana Jones est obligé de fuir un cabaret de Shanghai après une négociation houleuse. En compagnie de la chanteuse Willie Scott et du petit Demi-Lune, il se retrouve sur un glacier himalayen, dans un village dont une secte a dérobé le diamant magique et enlevé les enfants afin de les sacrifier.","en":"After arriving in India, Indiana Jones is asked by a desperate village to find a mystical stone. He agrees – and stumbles upon a secret cult plotting a terrible plan in the catacombs of an ancient palace.","es":"1935. Shanghai. El intrépido arqueólogo Indiana Jones, tras meterse en jaleos en un local nocturno, consigue escapar junto a una bella cantante y su joven acompañante. Tras un accidentado vuelo, los tres acaban en la India, donde intentarán ayudar a los habitantes de un pequeño poblado, cuyos niños han sido raptados.","de":"Indiana Jones kehrt zurück! Nachdem er bei der Erringung eines Diamanten in einem Nachtclub in Shanghai beinahe vergiftet, erdolcht und erschossen wurde, flieht er mit einer halbhysterischen Clubsängerin und seinem jungen asiatischen Freund Short Round mit einem Flugzeug. Doch über Indien wird auch hier ein Mordversuch gegen sie ausgeführt und alle drei müssen abspringen. Sie gelangen in ein Dorf, aus dem heilige Steine und sämtliche Kinder entführt wurden. Die Spur führt zu einem Fürstenpalast im Dschungel, wo sie einem machtgierigen Jungfürsten auf die Spur kommen, der die Kinder in den Minen arbeiten läßt. Doch hinter ihm steht ein noch machtvollerer Sektenführer..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/xrLwCgzIcxg8sYr9uuTLdeqtg3Z.jpg","fr":"https://image.tmdb.org/t/p/w500/oiUd1KUXWZeDPGMr8TrtZcXzpQU.jpg","en":"https://image.tmdb.org/t/p/w500/gpdVNUaa4LhRMLfJOPj1AZdhAZ3.jpg","es":"https://image.tmdb.org/t/p/w500/tLEaz41vKyKY7AgCTGgijLGWzbk.jpg","de":"https://image.tmdb.org/t/p/w500/7NBTcdNtaTEYoKRP8VdXRgWO6rk.jpg"}'::jsonb WHERE id = 10;
UPDATE public.films SET tmdb_id = 89, titoli_i18n = '{"it":"Indiana Jones e l''ultima crociata","en":"Indiana Jones and the Last Crusade","es":"Indiana Jones y la última cruzada","fr":"Indiana Jones et la dernière croisade","de":"Indiana Jones und der letzte Kreuzzug"}'::jsonb, trame_i18n = '{"it":"Nel 1938, l''archeologo Indiana Jones viene contattato dal magnate Walter Donovan per ritrovare il Santo Graal, la coppa che donerebbe la vita eterna. L''incarico assume una valenza personale quando Indy apprende che il precedente capo della spedizione, misteriosamente scomparso, è suo padre, il professor Henry Jones Sr., uno studioso da sempre ossessionato dalla reliquia. Raggiunta Venezia con l''aiuto dell''affascinante dottoressa Elsa Schneider, Indy ritrova il diario del genitore e scopre che l''uomo è tenuto prigioniero dai nazisti in un castello al confine tra Germania e Austria. Dopo aver liberato il padre, padre e figlio fuggono attraverso l''Europa e il Medio Oriente, affrontando tradimenti e letali trappole millenarie all''interno del tempio segreto di Alessandretta per impedire a Hitler di impadronirsi del potere del Graal.","en":"In 1938, an art collector appeals to eminent archaeologist Dr. Indiana Jones to embark on a search for the Holy Grail. Indy learns that a medieval historian has vanished while searching for it, and the missing man is his own father, Dr. Henry Jones Sr.. He sets out to rescue his father by following clues in the old man''s notebook, which his father had mailed to him before he went missing. Indy arrives in Venice, where he enlists the help of a beautiful academic, Dr. Elsa Schneider, along with Marcus Brody and Sallah. Together they must stop the Nazis from recovering the power of eternal life and taking over the world!","es":"En 1938, dos años después de encontrar el Arca de la Alianza, Indiana Jones es convencido por un millonario para que lo ayude a encontrar el Santo Grial antes de que caiga en manos del ejército nazi. Sin embargo, el verdadero motivo para involucrarse es encontrar a su padre, el doctor Henry Jones, con quien ha mantenido una fría relación desde su juventud y que ha desaparecido mientras seguía la pista del tesoro bíblico.","fr":"Indiana Jones se lance cette fois‐ci à la recherche du Saint Graal, accompagné de l''éminent et très maladroit Dr Henry Jones, son père. Malheureusement, ils ne sont pas les seuls lancés sur la trace du trésor, les nazis le convoitent également.","de":"Wir schreiben das Jahr 1938: Doktor Jones wird vom Mäzen eines Museums beauftragt, den Heiligen Gral und somit die wichtigste Reliquie der Christenheit zu finden. Jones'' Einwand, es würde der falsche Jones gefragt werden, denn der eigentliche Experte sei sein Vater Henry, fördert nur die Erkenntnis zu Tage, dass Jones senior bereits die Spur aufgenommen hatte, mittlerweile aber verschwunden ist. Nun ist des Doktors Jagdinstinkt geweckt. Besorgt um das Wohlergehen des Vaters und mit dem Museumskurator Marcus Brody im Gepäck tritt Jones eine Reise in die alte Welt an, um das zustande zu bringen, was die mittelalterlichen Kreuzzüge nicht geschafft hatten: den Kelch zu finden, der beim letzten Abendmahl gereicht worden war und das Blut Jesu am Kreuz aufgefangen hatte. Erwartungsgemäß ist aber nicht nur der Doktor auf der Suche - auch die Schergen Hitlers wollen sich die Sagen umwobenen Kräfte des Kelches sichern, verheißt er doch das ewige Leben…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/bPcdsUvGwyeIfyFkzebJdUcw8Fd.jpg","en":"https://image.tmdb.org/t/p/w500/sizg1AU8f8JDZX4QIgE4pjUMBvx.jpg","es":"https://image.tmdb.org/t/p/w500/5h45gK147AAJpLLC7Cicr597urz.jpg","fr":"https://image.tmdb.org/t/p/w500/73gYk4vShggfajlthEcOsY5ZhQI.jpg","de":"https://image.tmdb.org/t/p/w500/kaAhHlHv2SU7AK5xOMYzsqe2mrr.jpg"}'::jsonb WHERE id = 11;
UPDATE public.films SET tmdb_id = 217, titoli_i18n = '{"it":"Indiana Jones e il regno del teschio di cristallo","en":"Indiana Jones and the Kingdom of the Crystal Skull","es":"Indiana Jones y el reino de la calavera de cristal","de":"Indiana Jones und das Königreich des Kristallschädels","fr":"Indiana Jones et le royaume du crâne de cristal"}'::jsonb, trame_i18n = '{"it":"Nel 1957, in piena Guerra Fredda, l''anziano archeologo Indiana Jones viene rapito insieme al collega George McHale da agenti sovietici guidati dalla spietata Irina Spalko. Costretto ad aiutarli a penetrare in un magazzino segreto nell''Area 51 per recuperare i resti mummificati di un essere extraterrestre, Indy riesce a fuggire. Poco dopo viene avvicinato dal giovane ribelle Mutt Williams, il quale gli chiede aiuto per trovare il professor Harold Oxley e sua madre, misteriosamente rapiti in Perù. I due si mettono sulle tracce di un leggendario teschio di cristallo dai poteri sconosciuti, finendo per scontrarsi nuovamente con i sovietici lungo una pericolosa spedizione nella giungla amazzonica alla volta della mitica città di Akator.","en":"Set during the Cold War, the Soviets—led by sword-wielding Irina Spalko—are in search of a crystal skull which has supernatural powers related to a mystical Lost City of Gold. Indy is coerced to head to Peru at the behest of a young man whose friend—and Indy''s colleague—Professor Oxley has been captured for his knowledge of the skull''s whereabouts.","es":"Indiana Jones y el joven Mutt se proponen encontrar la Calavera de Cristal de Akator. Los agentes soviéticos tienen ese mismo objetivo. Liderados por la bella Irina Spalko, creen que el artilugio ayudará a su país a dominar el mundo si consiguen descifrar su secreto.","de":"1957 in der Wüste Nevadas, der Kalte Krieg ist in vollem Gange und Indiana Jones den Russen in die Hände gefallen. Indy gelingt die Flucht, doch die Russen – unter der Führung von Irina Spalko, Stalins Lieblingsagentin und ihres Zeichens Parapsychologin, - entwenden ein mysteriöses Skelett, das offenbar in Verbindung mit dem Verschwinden von Indys altem Freund und Kollegen Harold Oxleys steht, der in Peru verschollen ist. Gemeinsam mit Oxleys Ziehsohn Mutt macht sich Indy im Dschungel des Amazonas auf die Suche nach dem legendären Kristallschädel, dem magische Kräfte nachgesagt werden und der Oxley offenbar in den Wahnsinn getrieben hat. Eine Schatzsuche auf Leben und Tod beginnt.","fr":"La nouvelle aventure d’Indiana Jones débute dans un désert du sud‐ouest des États‐Unis. Nous sommes en 1957, en pleine guerre froide. Indy et son copain Mac viennent tout juste d’échapper à une bande d’agents soviétiques à la recherche d’une mystérieuse relique surgie du fond des temps. De retour au Marshall College, le Professeur Jones apprend une très mauvaise nouvelle : ses récentes activités l’ont rendu suspect aux yeux du gouvernement américain. Le doyen Stanforth, qui est aussi un proche ami, se voit contraint de le licencier. À la sortie de la ville, Indiana fait la connaissance d’un jeune motard rebelle, Mutt, qui lui fait une proposition inattendue."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qkQf6FVvtRKKk1JQAWTJZDPiy5r.jpg","en":"https://image.tmdb.org/t/p/w500/56As6XEM1flWvprX4LgkPl8ii4K.jpg","es":"https://image.tmdb.org/t/p/w500/caC98g0VyWVztBStLu46rpKlbGw.jpg","de":"https://image.tmdb.org/t/p/w500/2ycEOvqsjdvKqQkybBtLUmcqxLK.jpg","fr":"https://image.tmdb.org/t/p/w500/hwLaM3EaV7QvYhSFHbZ0VpuUY7Y.jpg"}'::jsonb WHERE id = 12;
UPDATE public.films SET tmdb_id = 335977, titoli_i18n = '{"en":"Indiana Jones and the Dial of Destiny","it":"Indiana Jones e il quadrante del destino","es":"Indiana Jones y el dial del destino","fr":"Indiana Jones et le Cadran de la destinée","de":"Indiana Jones und das Rad des Schicksals"}'::jsonb, trame_i18n = '{"en":"Finding himself in a new era, and approaching retirement, Indy wrestles with fitting into a world that seems to have outgrown him. But as the tentacles of an all-too-familiar evil return in the form of an old rival, Indy must don his hat and pick up his whip once more to make sure an ancient and powerful artifact doesn''t fall into the wrong hands.","it":"Nel 1969, l''archeologo Indiana Jones è ormai prossimo al pensionamento e vive una vita tranquilla. Tutto cambia quando viene visitato dalla sua figlioccia Helena Shaw, che è alla ricerca di un raro e potente manufatto che suo padre aveva affidato a Indy anni prima: il Quadrante di Archimede, un dispositivo capace di individuare fessure temporali. Helena ruba l''oggetto per venderlo al miglior offerente, costringendo Indy a mettersi al suo inseguimento. Nel frattempo, anche Jürgen Voller, un ex scienziato nazista che ora lavora per la NASA, è sulle tracce del Quadrante con l''obiettivo di riscrivere la storia.","es":"El arqueólogo Indiana Jones deberá emprender otra aventura contra el tiempo para intentar recuperar un dial legendario que puede cambiar el curso de la historia. Acompañado por su ahijada, Jones pronto se encuentra enfrentándose a Jürgen Voller, un ex nazi que trabaja para la NASA.","fr":"1969. Après avoir passé plus de dix ans à enseigner au Hunter College de New York, l''estimé docteur Jones, professeur d''archéologie, est sur le point de prendre sa retraite et de couler des jours paisibles. Tout bascule après la visite surprise de sa filleule Helena Shaw, qui est à la recherche d''un artefact rare que son père a confié à Indy des années auparavant : le fameux cadran d''Archimède, une relique qui aurait le pouvoir de localiser les fissures temporelles. En arnaqueuse accomplie, Helena vole l’objet et quitte précipitamment le pays afin de le vendre au plus offrant. Indy n''a d''autre choix que de se lancer à sa poursuite. Il ressort son fédora et son blouson de cuir pour une dernière virée...","de":"Indy befindet sich in einer neuen Ära und nähert sich dem Ruhestand. Er ringt damit, sich in eine Welt einzufügen, die über ihn hinausgewachsen zu sein scheint. Doch als die Tentakel eines allzu vertrauten Bösen in Form eines alten Rivalen zurückkehren, muss Indy erneut seinen Hut aufsetzen und seine Peitsche in die Hand nehmen, um sicherzustellen, dass ein uraltes und mächtiges Artefakt nicht in die falschen Hände gerät."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/Af4bXE63pVsb2FtbW8uYIyPBadD.jpg","it":"https://image.tmdb.org/t/p/w500/cavpmNgWlOIRENlEscbg1bJ2mX2.jpg","es":"https://image.tmdb.org/t/p/w500/vb6NkmZbOtdNj4ZbmHwNsiyaHMc.jpg","fr":"https://image.tmdb.org/t/p/w500/64TyGedJPmfwfO0dIQWFDLIw1U7.jpg","de":"https://image.tmdb.org/t/p/w500/scZQqSJjHw4mdsz7YfIUvOaRi7O.jpg"}'::jsonb WHERE id = 13;
UPDATE public.films SET tmdb_id = 15014, titoli_i18n = '{"en":"Bianca","es":"Bianca","it":"Bianca","de":"Bianca","fr":"Bianca"}'::jsonb, trame_i18n = '{"en":"Michele, a young mathematics professor, moves into a new flat. Lonely, depressed and neurotic, he spends his time obsessively monitoring the couples around him, especially his neighbors, a young pair struggling to make their relationship work. When Bianca, a new teacher at the local high school, enters his life, Michele finds himself falling in love. At the same time, a string of murders rocks the neighborhood, casting suspicion on him.","es":"Michele (Nanni Moretti) es un profesor de matemáticas que acaba de conseguir un nuevo trabajo en un colegio. Tras el asesinato de una mujer en su barrio, Michele conoce a Bianca (Laura Morante), una atractiva compañera de trabajo. (FILMAFFINITY)","it":"Michele Apicella, un giovane e nevrotico professore di matematica con numerose manie ossessive, viene assunto presso l''atipico liceo sperimentale ''Marilyn Monroe''. Michele tende a spiare e giudicare la vita dei suoi vicini e amici, cercando una perfezione ideale nei rapporti umani. Quando inizia una storia d''amore con la nuova collega di francese, Bianca, la sua stabilità mentale viene messa a dura prova. Contemporaneamente, un commissario di polizia indaga su una serie di misteriosi omicidi che colpiscono le persone vicine a Michele.","de":"Michele ist Mathematikprofessor und hat gerade eine neue Stelle in einer Schule mit einigen eigentümlichen Lehrmethoden angetreten. Nachdem eine Frau in seiner Nachbarschaft ermordet wird, lernt Michele die schöne Kollegin Bianca kennen, und es beginnt eine Beziehung zwischen den beiden. Wohin soll diese Beziehung führen, und wird Michele der Polizei helfen können, den Mörder zu fassen?","fr":"Michele Apicella, professeur de mathématiques, a une curieuse manie : épier de sa terrasse tous ses voisins et les mettre en fiche. Il s''intéresse plus particulièrement à Bianca, adorable professeur de français. Quand une série de meurtres se produit autour de lui, Michele devient le suspect idéal."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/lnXZLkJ3MFgAFAiyVJGfTUykNkU.jpg","es":"https://image.tmdb.org/t/p/w500/lnXZLkJ3MFgAFAiyVJGfTUykNkU.jpg","it":"https://image.tmdb.org/t/p/w500/lnXZLkJ3MFgAFAiyVJGfTUykNkU.jpg","de":"https://image.tmdb.org/t/p/w500/lnXZLkJ3MFgAFAiyVJGfTUykNkU.jpg","fr":"https://image.tmdb.org/t/p/w500/kLp1GFBAy0fFCsP4NXLec8PnEjF.jpg"}'::jsonb WHERE id = 14;
UPDATE public.films SET tmdb_id = 11319, titoli_i18n = '{"it":"Le avventure di Bianca e Bernie","es":"Los rescatadores","fr":"Les Aventures de Bernard et Bianca","en":"The Rescuers","de":"Bernard & Bianca - Die Mäusepolizei"}'::jsonb, trame_i18n = '{"it":"All''interno delle Nazioni Unite ha sede la Società Internazionale di Salvataggio, un''organizzazione segreta composta da topi da tutto il mondo incaricata di prestare soccorso a chi ne ha bisogno. Quando viene ritrovato un messaggio in bottiglia inviato da Penny, una bambina orfana rapita, la determinata topina ungherese Bianca si offre volontaria per salvarla e sceglie come compagno di viaggio il timido e superstizioso usciere Bernie. I due scoprono che Penny è stata rapita dalla spietata Madame Medusa, intenzionata a usarla per farsi strada nelle strette cavità sotterranee della Baia del Diavolo e recuperare il diamante più grande del mondo, ''L''Occhio del Diavolo''. Con l''aiuto dell''albatros Orville, della libellula Evinrude e degli stravaganti abitanti della palude, Bianca e Bernie affronteranno alligatori e insidie per liberare la bambina.","es":"Una niña huérfana que ha sido secuestrada envía una nota dentro de una botella pidiendo ayuda. Bernardo y Bianca, dos valientes ratones, miembros de la Sociedad Internacional de Rescate, reciben el mensaje que los llevará al peligroso \"Pantano del Diablo\". Allí, ayudados por la libélula Evinrude y los habitantes del pantano, vivirán un sinfín de emocionantes aventuras luchando contra la malvada Madame Medusa","fr":"Dans les sous‐sols des Nations Unies à New York, un groupe de souris tient conseil. Il s’agit du comité de soutien aux personnes en difficulté. Bianca, déléguée coquette, choisit Bernard tendre souriceau timide et courageux pour voler au secours d’une petite orpheline séquestrée, Penny.","en":"Two agents of the mouse-run International Rescue Aid Society search for a little orphan girl kidnapped by sinister treasure hunters.","de":"Die Vollwaise Penny wird von der bösen Madame Medusa entführt. Mit Hilfe des Mädchens plant die gierige Alte, in den Besitz des größten Diamanten der Welt zu gelangen. Penny schafft es jedoch, eine Flaschenpost abzuschicken. Als die abenteuerlustige Artgenossin Bianca von dem Hilferuf erfährt, entschließt sie sich, das Kind zu retten. Zusammen mit dem verschmitzten Mäuse-Hausmeister Bernard und dem unbeholfenen Albatros Orville sucht sie Medusas Versteck auf."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qf2w4N26UeoS6aXcwtMGRy4zTJU.jpg","es":"https://image.tmdb.org/t/p/w500/4Vi5VEkVWdqJgbG3pGdREFOwZdJ.jpg","fr":"https://image.tmdb.org/t/p/w500/lIlr6NuCZvYO62M6at27cclPSed.jpg","en":"https://image.tmdb.org/t/p/w500/9jpDjrRyvv9Nw0piXOpHHQTfxw9.jpg","de":"https://image.tmdb.org/t/p/w500/pm501ckgnaNRl3itHGEVjZlOtvL.jpg"}'::jsonb WHERE id = 15;
UPDATE public.films SET tmdb_id = 11135, titoli_i18n = '{"it":"Bianca e Bernie nella terra dei canguri","de":"Bernard & Bianca im Känguruland","en":"The Rescuers Down Under","fr":"Bernard et Bianca au pays des kangourous","es":"Los rescatadores en Cangurolandia"}'::jsonb, trame_i18n = '{"it":"Nell''Outback australiano, un ragazzino di nome Cody fa amicizia con Marahute, una gigantesca e rarissima aquila dorata. Quando il crudele bracconiere Percival McLeach lo scopre, rapisce Cody con l''intento di farsi rivelare l''ubicazione del nido dell''animale. La Società Internazionale di Salvataggio allerta immediatamente i due celebri agenti speciali a quattro zampe, Bianca e Bernie. Volando in Australia a bordo dell''albatros Wilbur e affiancati dalla guida locale Jake, un vivace topo saltatore, i due intraprenderanno una rischiosa missione per liberare Cody e salvare Marahute.","de":"Bernard und Bianca werden nach Australien beordert, um den Jungen Cody aus den Fängen des üblen Wilderes McLeach und seiner Gefährtin, der Eidechse Joanna zu befreien. Cody, der dem goldenen Adler Marahute aus einer Leach-Falle zur Freiheit verholfen hat, soll dem Bösewicht das Versteck des Adlers und seiner Brut verraten. Mit Hilfe des charmanten Busmaus-Machos Jake - auf deren Avancen gegenüber Bianca der gute Bernard mit stiller Eifersucht reagiert - und dem Albatros Wilbur gelingt es den deiden Mäusepolizisten Cody und die Tiere aus McLeachs Gewalt zu befreien und den Schurken zur Strecke zu bringen. Auch Bernard winkt das Happy End, er darf endlich die geliebte Bianca heiraten.","en":"A lawless poacher wants to capture a majestic and rare golden eagle, so he kidnaps the boy who knows where to find the bird. Not to worry -- the Rescue Aid Society''s top agents, heroic mice Miss Bianca and Bernard, fly to Australia to save the day. Accompanying the fearless duo are bumbling albatross Wilbur and local field operative Jake the Kangaroo Rat.","fr":"Au cœur imprévisible de l''Australie, Cody, un jeune garçon, développe une amitié incroyable avec un aigle royal. Mais quand un impitoyable braconnier tente de capturer l''aigle, Cody le défend. Comme il ne peut y arriver seul, il demande l''aide des souris les plus braves, Bernard et Bianca. Avec leur hilarant ami Wilbur, ces souris se lancent dans la plus dangereuse des missions.","es":"Esta vez, nuestros ratoncitos agentes secretos se encuentran en el corazón de la indomable selva australiana cuando tienen que acudir en ayuda de Cody, un jovencito que lucha por salvar un águila de un despiadado cazador furtivo."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/awNvQik4yvfEZWOfT13DTpNmyEn.jpg","de":"https://image.tmdb.org/t/p/w500/l9JUGkPc3WoNRLaghZUGe6KshTV.jpg","en":"https://image.tmdb.org/t/p/w500/5koTDBmMAkJOgAe4PL4163UKjvG.jpg","fr":"https://image.tmdb.org/t/p/w500/59b4X60bwEYgZ4BfSE56oKqoYBK.jpg","es":"https://image.tmdb.org/t/p/w500/hyuP9jI0Q6bBDEvvsYD8ka27QD0.jpg"}'::jsonb WHERE id = 16;
UPDATE public.films SET tmdb_id = 182415, titoli_i18n = '{"en":"White as Milk, Red as Blood","it":"Bianca come il latte, rossa come il sangue","fr":"Bianca come il latte, rossa come il sangue","es":"Blanca como la nieve, roja como la sangre","de":"Bianca come il latte, rossa come il sangue"}'::jsonb, trame_i18n = '{"en":"Like all sixteen-year-olds, Leo prefers the company of friends, motorbike rides and music to school. None of the teachers seem to be able to arouse his interest until the arrival in his class of a young history and philosophy substitute who, with his modern methods, helps him see the world with different eyes. In love with Beatrice, the ethereal girl of his dreams, Leo divides the world by colours. Beatrice is the red of love but he is forced to confront his own beliefs and fears when he discovers that the girl is suffering from leukemia, a disease that he links to white, a symbol of emptiness and loss.","it":"Leo è un sedicenne che vive la scuola e la vita con passione, associando le sue emozioni ai colori: il bianco rappresenta il vuoto e la paura, mentre il rosso è il colore dell''amore e della passione per Beatrice, la ragazza di cui è innamorato. Quando scopre che Beatrice è gravemente malata di leucemia, il mondo di Leo crolla. Nel tentativo di aiutarla e di farla sorridere, il ragazzo intraprende un percorso di crescita personale affrontando la sofferenza, sostenuto dall''amica di sempre Silvia e da un professore di filosofia che lo stimola a trovare il proprio posto nel mondo.","fr":"Un adolescent névrosé et incapable d''apprécier les plaisirs de la vie voit son existence bouleversée par sa rencontre avec une jeune fille atteinte d''une grave maladie.","es":"Entre mensajes de móvil, deberes, pósters, canciones, partidos, motos, miradas y sonrisas se encuentra Leo, un joven inmerso en el torbellino de la adolescencia. Está enamorado de Beatrice, pero no sabe ni cómo acercarse. Pronto descubrirá que la chica de sus sueños sufre un gran dolor."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/eZQFj0tgsErtr6CcIkyLFXGNBGa.jpg","it":"https://image.tmdb.org/t/p/w500/eZQFj0tgsErtr6CcIkyLFXGNBGa.jpg","fr":"https://image.tmdb.org/t/p/w500/eZQFj0tgsErtr6CcIkyLFXGNBGa.jpg","es":"https://image.tmdb.org/t/p/w500/cbnB5DQ9kuqCxNw4JmojKwTHyAl.jpg","de":"https://image.tmdb.org/t/p/w500/eZQFj0tgsErtr6CcIkyLFXGNBGa.jpg"}'::jsonb WHERE id = 17;
UPDATE public.films SET tmdb_id = 64032, titoli_i18n = '{"fr":"Le Navire blanc","it":"La nave bianca","de":"La nave bianca","es":"La nave bianca","en":"The White Ship"}'::jsonb, trame_i18n = '{"fr":"La vie à bord d''un navire hôpital de la marine italienne.","it":"Durante la seconda guerra mondiale, un giovane marinaio imbarcato su una nave da guerra italiana rimane ferito all''addome durante uno scontro navale nel Mediterraneo. Dopo essere stato operato d''urgenza a bordo, viene trasferito sulla nave ospedale ''Arno'' (la nave bianca del titolo) per le cure successive. A bordo della nave troverà assistenza e conforto grazie alle cure di un''infermiera volontaria della Croce Rossa, la quale scoprirà essere proprio la ragazza con cui il giovane intratteneva una romantica corrispondenza epistolare senza averla mai incontrata prima.","en":"Although released anonymously, as was the custom with all films produced by the Italian Navy, La Nave Bianca is the first feature-length effort directed by Roberto Rossellini; it is also very much the work of its co-writer and supervisor Francesco De Robertis. The film combines a documentary look at the Italian Navy during World War II with newsreel combat footage and a scripted love story performed by non-professional actors."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg","it":"https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg","de":"https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg","es":"https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg","en":"https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg"}'::jsonb WHERE id = 18;
UPDATE public.films SET tmdb_id = 16219, titoli_i18n = '{"de":"Fäuste - Du musst um dein Recht kämpfen","it":"Gladiator","fr":"Gladiator","en":"Gladiator","es":"Gladiator"}'::jsonb, trame_i18n = '{"de":"College-Boy Tommy kann ganz schön hinlangen, wenn’s sein muss. Und es muss sein. Schießereien und Überfälle stehen im Viertel an der Tagesordnung. Für Tommy die härteste Schule. Der zwielichtige Box-Promoter Horn erkennt schnell, dass der Junge mit dem ungeheuren Punch bares Geld wert ist. Mr. Horn, “The Power”, zwingt Tommy zu illegalen Fights in den Ring. Der Tod kämpft in jeder Runde mit.","it":"Un giovane di Chicago si trasferisce in un quartiere difficile e si ritrova coinvolto nel giro delle scommesse clandestine di pugilato per saldare i debiti del padre. Per uscire dal tunnel dovrà affrontare sul ring il suo amico più caro e un promotore privo di scrupoli.","fr":"Chicago. Pour payer les dettes de son père, Tommy Riley, adolescent secret et doué pour les sports de combat, accepte de participer a des matches de boxe clandestins organises par Horn, ancien boxeur sans scrupule. Ce dernier rêve de faire monter sur le ring un jeune Blanc qui déchainera les passions raciales et l''enrichira un peu plus.","en":"Tommy Riley has moved with his dad to Chicago from a ''nice place''. He keeps to himself, goes to school. However, after a street fight, he''s noticed and quickly falls into the world of illegal underground boxing — where punches can kill.","es":"Un chico de clase media se traslada a la dura zona sur de Chicago, donde se introducirá como luchador en el mundo ilegal de las peleas de boxeo no autorizadas."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/oPWaj3kqbhBlaQpVsT2dhjM44E3.jpg","it":"https://image.tmdb.org/t/p/w500/S708nk4QDy5PU5c4Xc61SXZTzM.jpg","fr":"https://image.tmdb.org/t/p/w500/6bGrJkzRZxF8rOWZxX5roE6d89Q.jpg","en":"https://image.tmdb.org/t/p/w500/w0YjBWVfu689txEXZG3xa4Aev3i.jpg","es":"https://image.tmdb.org/t/p/w500/o5333m4CcButz0I7NrxDXlTRB70.jpg"}'::jsonb WHERE id = 20;
UPDATE public.films SET tmdb_id = 137548, titoli_i18n = '{"it":"Gladiatori di Roma","de":"Die Gladiatoren von Rom","fr":"Gladiateurs de Rome","en":"Gladiators of Rome","es":"Gladiatori di Roma"}'::jsonb, trame_i18n = '{"it":"Rimasto orfano dopo l''eruzione di Pompei, il piccolo Timo viene adottato dal generale Chirone e cresciuto nell''accademia di gladiatori più famosa di Roma. Senza alcuna passione per il combattimento, dovrà trasformarsi in un vero eroe per conquistare il cuore della bella Lucilla.","de":"Es ist die Zeit des römischen Imperiums. Der junge Timo wurde durch die Zerstörung Pompejis zum Waisenkind, doch der gütige General Chirone adoptiert ihn und bildet ihn an der besten Gladiatorenschule Roms aus. Doch so ganz zum legendären Krieger taugt Timo nicht - im Gegenteil. Er möchte lieber mit seinen Freunden Ciccius und Mauritius rumhängen als sich den Gängelungen und absurden Trainingsmethoden seines Stiefvaters aussetzen. Bis er eines Tages die wundervolle Lucilla trifft und plötzlich sein Kampfgeist geweckt wird. Wird er der größte Gladiator werden, den Rom je gesehen hat?","fr":"Dans la Rome impériale, devenu orphelin suite à la terrible éruption qui a détruit Pompéi, le petit Timo est adopté par le général Chirone et élevé à l’académie des gladiateurs la plus célèbre de Rome. La vie de gladiateur n’est pas du tout faite pour Timo, dont la seule aspiration consiste à se payer du bon temps avec ses amis Ciccius et Mauritius pour échapper aux sessions d’entraînements de son père adoptif. Tout change lorsque Lucilla, la fille de Chirone, revient de Grèce. Désormais, Timo ne souhaite qu’une chose : devenir un valeureux gladiateur dans le but de conquérir le cœur de sa belle amie d’enfance et de convaincre Chirone de l’accepter comme futur gendre…","en":"A new hero is born in this hilarious, animated adventure of epic proportions! Timo, a student at the Gladiators? Academy in Rome, has no desire to become a legendary gladiator like his stepfather. That is, until the mesmerizing Lucilla walks into his life.  With the help of an unlikely band of sidekicks, Timo is determined to be the gladiator of her dreams and embarks on an action-packed journey to become the Colosseum?s first victor!","es":"Un nuevo héroe nace en este hilarante, aventura animada de proporciones épicas. Timo, un estudiante de la Academia de los Gladiadores ''en Roma, no tiene ningún deseo de convertirse en un gladiador legendario como su ..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/7F35x1EAYjZ4REVBDxGCX4f9ByS.jpg","de":"https://image.tmdb.org/t/p/w500/wSyJQ5bIcdL6W15whJEgvseYUM3.jpg","fr":"https://image.tmdb.org/t/p/w500/tIOzh5MzmvE6RxKy3rhPbJNnHdL.jpg","en":"https://image.tmdb.org/t/p/w500/9Qyx97TwsPQ1uR82wwQ2dzY0wOU.jpg","es":"https://image.tmdb.org/t/p/w500/7F35x1EAYjZ4REVBDxGCX4f9ByS.jpg"}'::jsonb WHERE id = 21;
UPDATE public.films SET tmdb_id = 164728, titoli_i18n = '{"it":"Il gladiatore invincibile","en":"The Invincible Gladiator","es":"Il gladiatore invincibile","fr":"Il gladiatore invincibile","de":"Der unbesiegbare Gladiator"}'::jsonb, trame_i18n = '{"en":"A Roman warrior leads a revolt against an evil ruler. A young, diminutive ruler makes a big decision to unseat a nobleman whose ego has outgrown him. But can the 10-year-old take on such an impressive nemesis?","it":"Il gladiatore Rezius viene inviato in una provincia imperiale per sedare una ribellione, ma scopre che i ribelli stanno lottando contro un tiranno corrotto. Deciderà di schierarsi dalla parte degli oppressi per riportare la giustizia."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/bc8Hy1jtLAAiQ1n8PeiIngxUqlp.jpg","en":"https://image.tmdb.org/t/p/w500/zela8yXh9bWUBab7911vSLb9OGm.jpg","es":"https://image.tmdb.org/t/p/w500/bc8Hy1jtLAAiQ1n8PeiIngxUqlp.jpg","fr":"https://image.tmdb.org/t/p/w500/bc8Hy1jtLAAiQ1n8PeiIngxUqlp.jpg","de":"https://image.tmdb.org/t/p/w500/bc8Hy1jtLAAiQ1n8PeiIngxUqlp.jpg"}'::jsonb WHERE id = 22;
UPDATE public.films SET tmdb_id = 5714, titoli_i18n = '{"it":"Il gladiatore che sfidò l''impero","es":"Il Gladiatore che sfidò l''impero","de":"Die Rache des Spartakus","fr":"Il Gladiatore che sfidò l''impero","en":"Challenge of the Gladiator"}'::jsonb, trame_i18n = '{"it":"Durante l''impero di Marco Aurelio, il corrotto senatore Lucio Quintilio trama per impossessarsi di un leggendario tesoro e usurpare il potere. A contrastare i suoi piani diabolici si erge il valoroso gladiatore Marco che, alleatosi con i ribelli e i fedeli all''imperatore, affronterà duri scontri e insidie nell''arena per ristabilire la giustizia e salvare l''impero.","de":"Unter dem Pseudonym Rock Stevens rettet Peter Lupus als muskelstrotzender Thraker Spartacus sein Volk vor der Vernichtung und befreit die Römer von einem verräterischen Tyrannen.","en":"Treacherous Roman senator Lucius Quintilius plans a secret journey into Thrace to recover a legendary treasure. He is accompanied by his daughter Livia posing as a Christian slave girl, his cruel henchman Commodio, and Terenzius, an ex-gladiator and Nero look-alike who fools the local Thracians into believing he is the real Emperor. But Lucius''s plans are thwarted by Spartacus and his band of rebels who succeed in capturing the treasure for Thrace. When news arrives from Rome that the real Nero has died, local Roman governor Consul Metellus joins forces with Spartacus to defeat the traitors."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/8h2SzRMQhza5IVQCIv30nLIyXEV.jpg","es":"https://image.tmdb.org/t/p/w500/keKrpGdwvxRPHOyKPnlrVu5dQiU.jpg","de":"https://image.tmdb.org/t/p/w500/keKrpGdwvxRPHOyKPnlrVu5dQiU.jpg","fr":"https://image.tmdb.org/t/p/w500/keKrpGdwvxRPHOyKPnlrVu5dQiU.jpg","en":"https://image.tmdb.org/t/p/w500/keKrpGdwvxRPHOyKPnlrVu5dQiU.jpg"}'::jsonb WHERE id = 23;
UPDATE public.films SET tmdb_id = 93492, titoli_i18n = '{"it":"I sette gladiatori","fr":"I sette gladiatori","es":"Los siete espartanos","de":"Die sieben Gladiatoren","en":"Gladiators 7"}'::jsonb, trame_i18n = '{"it":"Marcus, un valoroso gladiatore, fugge da Roma per fare ritorno a Sparta, la sua terra natale. Al suo arrivo scopre che il suo popolo è sottomesso alla tirannia di un governatore spietato. Per liberare la sua gente, Marcus decide di reclutare altri sei abili e forti gladiatori, unendo le forze per guidare una rivolta contro l''oppressore.","es":"Darío regresa a Esparta después de haber alcanzado la libertad por su valentía en una lucha, como gladiador en el circo romano. Al llegar a Esparta descubre que su padre ha sido asesinado por Hiarbaa. Este quiere asesinar también a Darío para afianzarse en el poder y casarse con Aglaia, prometida de Darío e hija de Milone... (FILMAFFINITY)","de":"Als der Spartaner Darius chancenlos in der Arena kämpft, bricht er blutüberströmt zusammen. Doch der Kaiser schenkt ihm trotzdem die Freiheit und Darius kehrt in seine Heimat zurück, wo er auch schon von einem weiteren Märtyrer erwartet wird, der ihn töten möchte. Darius bildet eine Gruppe von sieben Gladiatoren, um den Tyrannen Hierba zu stoppen.","en":"Framed for the escape of five gladiators from the arena, the son of one of Sparta''s leading citizens is sentenced to the arena as gladiator himself and forced to fight for his life in the Roman Colosseum. Years later he manages to escape and return to Sparta, only to find out that his father has been murdered--even though it was ruled a \"suicide\"--and the woman he loves is about to marry the evil king who has usurped the throne. He sets out to find six of his fellow gladiators and return to Sparta to save his woman and place the rightful king on the throne."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kKdn10PWQKCpVgE5w01yg24wnQo.jpg","fr":"https://image.tmdb.org/t/p/w500/kKdn10PWQKCpVgE5w01yg24wnQo.jpg","es":"https://image.tmdb.org/t/p/w500/2h3DwYZOXIjKgXxYpQnULwPMCAY.jpg","de":"https://image.tmdb.org/t/p/w500/u9JTB147rHHC4IOjyr0GkF1tU31.jpg","en":"https://image.tmdb.org/t/p/w500/jAQg4h3AhSgOH3jLRlcRCzagFXW.jpg"}'::jsonb WHERE id = 24;
UPDATE public.films SET tmdb_id = 134998, titoli_i18n = '{"it":"L''ultimo gladiatore","en":"Messalina Against the Son of Hercules","fr":"Hercule contre les mercenaires","es":"El último gladiador","de":"Der letzte der Gladiatoren"}'::jsonb, trame_i18n = '{"it":"Nell''antica Roma, oppressa dalla follia e dal dispotismo dell''imperatore Caligola, il valoroso gladiatore Cassio Cherone decide di ribellarsi alla tirannia. Coinvolto negli intrighi di palazzo e nelle congiure senatorie, Cassio affronta pericoli nell''arena e scontri mortali, lottando per rovesciare il sovrano crudele, proteggere la donna che ama e restituire dignità e pace al popolo romano.","en":"While fighting in Britain, Roman forces commanded by Caligula capture the noble warrior, Glaucus. Seeing in him gladiator material, Caligula takes Glaucus back to Rome along with other hostages including Glaucus''s girlfriend, Ena. A man seeking to restore the Roman Republic then assassinates Caligula after which Claudius is proclaimed emperor. Messalina -- Claudius''s beautiful but evil wife -- then maneuvers to replace Claudius with her lover, Silio. She forces Glaucus to help her in this quest by threatening to harm the enslaved Ena.  Written by dinky-4 of Minneapolis","fr":"L''ambitieuse Messaline souhaite plus que tout le pouvoir. Pour parvenir à ses fins, elle demande l''aide d''Hercule, un esclave d''une incroyable force. Mais celui-ci refuse. Pour obliger Hercule a accepter son offre, Messaline fait emprisonner Ena, sa fiancée...","es":"Roma, año 41 DC. El emperador Calígula (Charles Borromel) conquista Bretaña y hace esclavo al bárbaro Glauco (Richard Harrison), llevándole a la capital con la intención de verle morir en la arena frente a los gladiadores. El bretón resulta ser un guerrero excepcional que conseguirá acabar con todos y escapar, liberando también a sus compañeros de encierro. Pero las aventuras de Glauco no han hecho más que empezar; aún tendrá que afrontar muchos combates antes de poder liberar a su mujer, Hena (Marilú Tolo) y volver a Bretaña.","de":"Caligula, der wahnsinnige römische Imperator, führt einen sinnlosen Krieg gegen Britannien. Glaucus, ein britischer Sklave, kämpft derart beeindruckend, dass er bald unbesiegter Gladiator der römischen Arenen wird. Als er jedoch Caligula töten will, lässt dieser ihn in den Kerker werfen. Die intrigante Messalina sieht nun ihre Chance, den heldenhaften Briten einzusetzen, den Herrscher vom Thron zu stürzen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/lSpPctLSS2F0W4XgQCzTWrtEMl9.jpg","en":"https://image.tmdb.org/t/p/w500/lSpPctLSS2F0W4XgQCzTWrtEMl9.jpg","fr":"https://image.tmdb.org/t/p/w500/lSpPctLSS2F0W4XgQCzTWrtEMl9.jpg","es":"https://image.tmdb.org/t/p/w500/rILHj2xmI19KeKw6GexyXM9981m.jpg","de":"https://image.tmdb.org/t/p/w500/lSpPctLSS2F0W4XgQCzTWrtEMl9.jpg"}'::jsonb WHERE id = 25;
UPDATE public.films SET tmdb_id = 211179, titoli_i18n = '{"it":"Il magnifico gladiatore","es":"Il magnifico gladiatore","fr":"Le gladiateur magnifique","de":"Der größte der Gladiatoren","en":"The Magnificent Gladiator"}'::jsonb, trame_i18n = '{"it":"Attalo, gladiatore da tutti stimato, si trova vittima degli intrighi di palazzo dell''imperatore Gallieno. Dovrà far valere il suo valore sia nell''arena che contro i cospiratori politicamente corrotti.","fr":"Hercule, fils du roi de Dacie, se fiance a Velida, fille de l''empereur Galien Zudo qui veut le trône enlève l''empereur et le remplace par un sosie qui annule le mariage et fiance Velida avec Zudo. Hercule découvre la vérité et délivre l''empereur. Zudo est tue. Hercule peut alors épouser Velida avec la bénédiction de l''empereur.","de":"Als die römischen Truppen unter Cesar Galienius (Franco Cobianchi) Dacien erobern, fällt dem Imperator auch Attalus (Mark Forest), der Prinz von Dacien in die Hände. Dessen großes Talent zum Kämpfen bleibt Galienius nicht verborgen so dass er ihn zum Gladiator ausbilden lässt. Durch seinen Mut in der Arena gewinnt Attalus nicht nur schnell an Popularität beim römischen Volk, sondern auch das Herz von Valida, der jungen Tochter des Imperators. Die aufkeimende Liebe der beiden wird aber nicht von jedem kommentarlos hingenommen. Der Oberbefehlshaber der Truppen Zullo (Paolo Gozlino) hat nämlich schon lange ein Auge auf die römische Jungfer geworfen, und spinnt ein Komplott, dass ihm nicht nur Attalus vom Hals schaffen und Valida in seine Arme treiben, sondern auch die Macht des Imperators sichern soll.","en":"Attalus, a war prisoner by Rome, proves his valor in the arena, becomes a gladiator trainer, conquers the women''s hearts and the men''s envy, and saves Rome from a political plot to a usurper to occupy the throne."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ePP3X8YRlXaQm5ERlX2W5o0rX0Z.jpg","es":"https://image.tmdb.org/t/p/w500/ePP3X8YRlXaQm5ERlX2W5o0rX0Z.jpg","fr":"https://image.tmdb.org/t/p/w500/ePP3X8YRlXaQm5ERlX2W5o0rX0Z.jpg","de":"https://image.tmdb.org/t/p/w500/ePP3X8YRlXaQm5ERlX2W5o0rX0Z.jpg","en":"https://image.tmdb.org/t/p/w500/7iJtohz1AiSKaV8uOp23smvnO3J.jpg"}'::jsonb WHERE id = 26;
UPDATE public.films SET tmdb_id = 238033, titoli_i18n = '{"it":"Spartacus e i 10 gladiatori","fr":"Spartacus et les dix Gladiateurs","es":"Espartaco y los diez gladiadores","en":"Spartacus and the Ten Gladiators","de":"Spartacus und die zehn Gladiatoren"}'::jsonb, trame_i18n = '{"it":"Dieci gladiatori inviati per dare la caccia al ribelle Spartacus scoprono la nobiltà della sua causa. Decideranno di unire le forze con gli schiavi in rivolta contro le legioni romane.","fr":"Pour construire un aqueduc, le sénateur romain Varron engage dix gladiateurs. En chemin, ils portent secours à la fille de Varron qui est attaquée par une bande de coupe-jarrets. Devant cet exploit, Varron leur propose de capturer Spartacus, chef des esclaves révoltés, en échange de la liberté…","es":"Espartaco es un esclavo noble y honrado, a quien los patricios obligan a luchar en brutales peleas de gladiadores. Un buen día decide poner fin a esta injusticia y lidera una rebelión que, por un momento, consigue poner en jaque la paz interior del Imperio Romano.","en":"The story of Spartacus and 10 other gladiators who rebelled against the bloody coliseum sports. They escape and are faced at every turn by Roman soldiers bent on taking them back to the Coliseum - dead or alive!","de":"Einen Überfall auf eine Reisegruppe können die zehn Gladiatoren gerade noch verhindern. Auch das Leben von Livia, der hübschen Tochter des römischen Senators Varro, ist gerettet. Der beeindruckte Senator beauftragt daraufhin die zehn Gladiatoren, den berüchtigten Rebellen Spartacus und seine Bande gefangen zu nehmen. Doch hinter diesem Auftrag verbirgt sich ein finsterer Plan. Er lässt die Gladiatoren in die Verliese seines Palastes sperren, um einen feigen Überfall auf das Lager verüben zu können. Dies ist für Spartacus und die zehn Gladiatoren das Signal zum großen Aufstand."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/gZsGyRcXRCICiSlnBfyH5SecIad.jpg","fr":"https://image.tmdb.org/t/p/w500/3nVbJy4v2sJXpk63SaN0vNUO2En.jpg","es":"https://image.tmdb.org/t/p/w500/a7IdTHSJ0aIsqBIHX1V6jIYmYQB.jpg","en":"https://image.tmdb.org/t/p/w500/gZsGyRcXRCICiSlnBfyH5SecIad.jpg","de":"https://image.tmdb.org/t/p/w500/bFPGWSo1FRa5v4M1gJ3Ur95conX.jpg"}'::jsonb WHERE id = 27;
UPDATE public.films SET tmdb_id = 158093, titoli_i18n = '{"en":"Gladiator of Rome","it":"Il gladiatore di Roma","es":"El retorno de Maciste","fr":"Il gladiatore di Roma","de":"Der Gladiator von Rom"}'::jsonb, trame_i18n = '{"en":"A warrior protecting a slave girl, who is really a princess, winds up as a gladiator in the Roman arenas.","it":"Nell''antica Roma sotto Caracalla, la giovane erede al trono di Cilicia viene protetta da uno schiavo gladiatore che difenderà la sua vita dai traditori e dai pretendenti al trono.","es":"Una princesa silesiana cuya familia ha sido cruelmente asesinada, es vendida como esclava por los romanos. Lo mismo ocurre con su sirviente Marcus, quien recibe la formación de un gladiador.","de":"Die schöne Nisa ist die Sklavin einer reichen römischen Familie. Sie ist in Wirklichkeit eine Königstochter und wird von Marcus, einem übermenschlich starken Mann, beschützt. Valerius, der Sohn der Familie, ist in Nisa verliebt und möchte sie heiraten. Durch einen heimtückischen Angriff auf das Haus seiner Eltern werden Marcus und Nisa entführt. Marcus soll als Gladiator in der Arena Roms kämpfen und Nisa soll als Christin zum Tode verurteilt werden. Valerius versucht alles, um sie zu befreien. Marcus steht ihm bei, nachdem er seine Fesseln gesprengt hat und mit den anderen Gladiatoren geflohen ist."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/bnYYCgn7hBtV6Xq4PF8GttGMvI3.jpg","it":"https://image.tmdb.org/t/p/w500/smcfYvcMixH12ZlMM3M9RG7q50l.jpg","es":"https://image.tmdb.org/t/p/w500/smcfYvcMixH12ZlMM3M9RG7q50l.jpg","fr":"https://image.tmdb.org/t/p/w500/smcfYvcMixH12ZlMM3M9RG7q50l.jpg","de":"https://image.tmdb.org/t/p/w500/ovxKFqNMOoSJoZ6APUM6bEvvzjN.jpg"}'::jsonb WHERE id = 28;
UPDATE public.films SET tmdb_id = 329964, titoli_i18n = '{"it":"Ursus il gladiatore ribelle","en":"The Rebel Gladiators","es":"Ursus, il gladiatore ribelle","de":"Kampf der Giganten","fr":"Ursus, il gladiatore ribelle"}'::jsonb, trame_i18n = '{"it":"Ursus accetta di combattere come gladiatore per salvare la vita della donna che ama, prigioniera di un governatore crudele. La sua forza sovrumana scatenerà una rivolta nell''arena.","en":"In order to persuade the Emperor to spare his village, the mighty Ursus is forced to fight the greatest gladiator in Rome in the Roman Arena."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg","en":"https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg","es":"https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg","de":"https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg","fr":"https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg"}'::jsonb WHERE id = 29;
UPDATE public.films SET tmdb_id = 169925, titoli_i18n = '{"es":"La carga de los jinetes indios","it":"L''indiana bianca","de":"Der brennende Pfeil","en":"The Charge at Feather River","fr":"La Charge sur la rivière rouge"}'::jsonb, trame_i18n = '{"es":"Una expedición de rescate, formada por hombres inexpertos, debe liberar a dos mujeres blancas que han sido secuestradas por los indios cheyenne. (FILMAFFINITY)","de":"Der Ex-Offizier Miles Archer (Guy Madison) soll mit einer zusammengewürfelten Gruppe von Männern zwei Schwestern aus den Händen der Cheyenne befreien. Zwar glückt die Aktion,\r doch die Indianer verfolgen den Trupp. Weitere Schwierigkeiten ergeben sich, als die jüngere (Vera Miles) der Schwestern, wieder zurück zu den Indianern will...","en":"A frontier scout leads prisoners on a death mission to save a railroad and rescue two women.","fr":"Sur le territoire du Colorado, Miles Archer est demandé par la cavalerie à Fort Soufflet pour aider à sauver deux femmes blanches enlevés par le Cheyenne et à assurer la sécurité pour les équipes de construction de chemin de fer.","it":"Nel selvaggio West, Sharon Purcell, una giovane donna per metà bianca e per metà nativa americana, vive al confine tra le due culture affrontando il disprezzo e il pregiudizio di entrambe le comunità. La situazione degenera quando un potente e avido proprietario terriero tenta con ogni mezzo di sottrarre le terre alla tribù indiana locale per espandere il proprio dominio. In mezzo alle crescenti tensioni e allo scoppio delle ostilità, Sharon cercherà disperatamente di favorire la convivenza pacifica, aiutata da un coraggioso funzionario governativo determinato a ristabilire la giustizia e a far rispettare i trattati."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/8A87PHLaDCEyeqTVBzHhQJ6R22p.jpg","it":"https://image.tmdb.org/t/p/w500/awt4WEDwcKuTw4oaiLwzfh7xnt7.jpg","de":"https://image.tmdb.org/t/p/w500/leM8HYHS8exQzmMVzoSa4Z4oIts.jpg","en":"https://image.tmdb.org/t/p/w500/awt4WEDwcKuTw4oaiLwzfh7xnt7.jpg","fr":"https://image.tmdb.org/t/p/w500/j1PTX1nMkaKnIMMPnPKOLUiFZMR.jpg"}'::jsonb WHERE id = 30;
UPDATE public.films SET tmdb_id = 85, titoli_i18n = '{"it":"Indiana Jones e i predatori dell''arca perduta","en":"Raiders of the Lost Ark","de":"Jäger des verlorenen Schatzes","es":"En busca del arca perdida","fr":"Les Aventuriers de l''arche perdue"}'::jsonb, trame_i18n = '{"it":"Nel 1936, l''archeologo e avventuriero Indiana Jones viene incaricato dai servizi segreti dell''esercito statunitense di trovare la leggendaria Arca dell''Alleanza, lo scrigno sacro contenente i Dieci Comandamenti, prima che cada nelle mani delle forze naziste di Adolf Hitler, intenzionate a sfruttarne il presunto potere sovrannaturale per dominare il mondo. Affiancato dalla sua fiera ex compagna Marion Ravenwood e dal fidato amico Sallah, Jones affronta una pericolosa caccia al tesoro tra le montagne del Nepal e le sabbie dell''Egitto, sfidando trappole mortali e il suo rivale senza scrupoli, l''archeologo francese René Belloq.","en":"When Dr. Indiana Jones – the tweed-suited professor who just happens to be a celebrated archaeologist – is hired by the government to locate the legendary Ark of the Covenant, he finds himself up against the entire Nazi regime.","de":"Der Archäologe Dr. Henry Jones wird von Regierungsagenten auf die Bundeslade angesetzt, das Behältnis, in dem Moses Gesetzestafeln aufbewahrt wurden. Laut Geheiminformationen suchen auch die Nazis nach der Lade, da sie den Besitzer unbesiegbar machen soll. Jones, genannt Indiana Jones, reist daraufhin nach Nepal, wo er einen alten Kollegen aufspüren will, jedoch nur dessen Tochter findet, die sich ihm anschließt. Ein altes Schmuckstück führt sie nach Ägypten, wo die Nazis mit Belloqs Hilfe bereits Ausgrabungen vornehmen. So kommt es zum Wettlauf um die Auffindung der Quelle der Seelen…","es":"Año 1936, Indiana Jones es un profesor de arqueología, dispuesto a correr peligrosas aventuras con tal de conseguir valiosas reliquias históricas. Después de una infructuosa misión en Sudamérica, el gobierno estadounidense le encarga la búsqueda del Arca de la Alianza, donde se conservan las Tablas de la Ley que Dios entregó a Moisés. Según la leyenda, quien las posea tendrá un poder absoluto, razón por la cual también la buscan los nazis.","fr":"L''Arche d''Alliance contenant les tables de la Loi brisées par Moïse, voici 3.000 ans, est l''objet de la convoitise des nazis. L''archéologue aventurier Indiana Jones se lance à sa recherche, poursuivi par son ennemi Belloq."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/g7brmwhpIPZoRLlHSU9sDbyGW3D.jpg","en":"https://image.tmdb.org/t/p/w500/ceG9VzoRAVGwivFU403Wc3AHRys.jpg","de":"https://image.tmdb.org/t/p/w500/8cWx3s2Wfo15DzUyIE8scg3eNdb.jpg","es":"https://image.tmdb.org/t/p/w500/tECLVwLCMexSkls33RTCwedRZ6d.jpg","fr":"https://image.tmdb.org/t/p/w500/by5xmwAUVzXc3WyIyjMYCVaL5Lj.jpg"}'::jsonb WHERE id = 31;
UPDATE public.films SET tmdb_id = 558449, titoli_i18n = '{"it":"Il gladiatore II","en":"Gladiator II","es":"Gladiator II","fr":"Gladiator II","de":"Gladiator II"}'::jsonb, trame_i18n = '{"it":"Anni dopo aver assistito alla tragica morte del venerato eroe Massimo Decimo Meridio per mano del suo perfido zio, Lucio si ritrova costretto a fare il suo ingresso nel Colosseo. La sua patria è stata infatti conquistata dai tirannici imperatori che ora governano Roma con il pugno di ferro. Con la rabbia nel cuore e il destino dell''Impero in bilico, Lucio deve scavare nel proprio passato per trovare la forza e l''orgoglio necessari a restituire la gloria di Roma al suo popolo.","en":"Years after witnessing the death of the revered hero Maximus at the hands of his uncle, Lucius is forced to enter the Colosseum after his home is conquered by the tyrannical Emperors who now lead Rome with an iron fist. With rage in his heart and the future of the Empire at stake, Lucius must look to his past to find strength and honor to return the glory of Rome to its people.","es":"Dieciséis años después de la muerte de Marco Aurelio, Roma está gobernada por los despiadados emperadores gemelos Geta y Caracalla. El nieto de Aurelio, Lucio Vero, vive bajo el seudónimo de Hanno con su esposa Arishat en el reino norteafricano de Numidia. El ejército romano dirigido por el general Acacio invade y conquista el reino, esclavizando a Lucio junto con otros supervivientes. Los esclavos son llevados a Ostia, donde Lucio es comprado por el maestro de cuadra Macrinus, que le promete la oportunidad de vengarse matando a Acacio si gana suficientes combates para llegar al Coliseo.","fr":"Des années après avoir assisté à la mort du héros vénéré Maximus aux mains de son oncle, Lucius est forcé d''entrer dans le Colisée lorsque son pays est conquis par les empereurs tyranniques qui gouvernent désormais Rome d''une main de fer. La rage au cœur et l''avenir de l''Empire en jeu, Lucius doit se tourner vers son passé pour trouver la force et l''honneur de rendre la gloire de Rome à son peuple.","de":"Jahre nachdem er Zeuge des Todes des verehrten Helden Maximus durch die Hand seines Onkels wurde, wird Lucius gezwungen, das Kolosseum zu betreten, nachdem seine Heimat von den tyrannischen Kaisern erobert wurde, die Rom nun mit eiserner Faust regieren. Mit Wut in seinem Herzen und der Zukunft des Imperiums auf dem Spiel muss Lucius in seine Vergangenheit blicken, um Kraft und Ehre zu finden, um den Ruhm Roms an sein Volk zurückzugeben."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/tVBCG6qHQQaq2doZsOvpGNcwMuP.jpg","en":"https://image.tmdb.org/t/p/w500/2cxhvwyEwRlysAmRH4iodkvo0z5.jpg","es":"https://image.tmdb.org/t/p/w500/ckTXrwlr4cRVxpBFEZcEmDzrmea.jpg","fr":"https://image.tmdb.org/t/p/w500/sUnGXbEdXlgHlK3EkmB5w2NiLlc.jpg","de":"https://image.tmdb.org/t/p/w500/kLkMt9bB7XDzwQ5wy6OWtdpwgcD.jpg"}'::jsonb WHERE id = 32;
UPDATE public.films SET tmdb_id = 120, titoli_i18n = '{"it":"Il Signore degli Anelli - La Compagnia dell''Anello","es":"El señor de los anillos: La comunidad del anillo","fr":"Le Seigneur des anneaux : La Communauté de l''anneau","de":"Der Herr der Ringe - Die Gefährten","en":"The Lord of the Rings: The Fellowship of the Ring"}'::jsonb, trame_i18n = '{"it":"Un giovane hobbit di nome Frodo Baggins eredita un anello magico di inestimabile potere dal suo zio Bilbo. Per evitare che il Signore Oscuro Sauron lo riconquisti e sottometta la Terra di Mezzo, Frodo deve intraprendere un periglioso viaggio verso il Monte Fato insieme a una variegata compagnia di eroi.","es":"En la Tierra Media, el Señor Oscuro Saurón creó los Grandes Anillos de Poder, forjados por los herreros Elfos. Tres para los reyes Elfos, siete para los Señores Enanos, y nueve para los Hombres Mortales. Secretamente, Saurón también forjó un anillo maestro, el Anillo Único, que contiene en sí el poder para esclavizar a toda la Tierra Media. Con la ayuda de un grupo de amigos y de valientes aliados, Frodo emprende un peligroso viaje con la misión de destruir el Anillo Único. Pero el Señor Oscuro Sauron, quien creara el Anillo, envía a sus servidores para perseguir al grupo. Si Sauron lograra recuperar el Anillo, sería el final de la Tierra Media.","fr":"Le jeune hobbit Frodon Sacquet hérite d''un anneau. Il s''agit de l''Anneau Unique, instrument de pouvoir absolu qui permettrait à Sauron, de régner sur la Terre du Milieu et de réduire en esclavage ses peuples… À moins que Frodon et ses fidèles compagnons ne parviennent à emporter l''Anneau jusqu''en Mordor, lieu où il a été forgé, et à le détruire pour toujours…","de":"Dem Hobbit Bilbo Beutlin fällt zufällig ein machtvoller Ring in die kleinen Hände. Dieses Schmuckstück erlaubte es dem finsteren Herrscher Sauron einst, die Welt zu unterjochen. Der Ring schien über Jahrhunderte verloren, bis Bilbo ihn an sich nahm und seinen „Schatz“ sechzig Jahre lang bewahrte. An seinem 111. Geburtstag gibt er ihn schweren Herzens an seinen Neffen Frodo weiter und verlässt seine Heimat Mittelerde. Für den jungen Hobbit Frodo wird der Ring jedoch zur schweren Bürde. Der böse Geist Saurons, der in dem „Einen“ gefangen ist, wird immer stärker. Frodo bleibt nur eine Möglichkeit: Er muss ihn vernichten. Allerdings ist das nicht gerade einfach. Nur in den ewigen Feuern des Schicksalsberges im Lande Mordor, wo der Ring geschmiedet wurde, kann er auch vernichtet werden. Doch bis dahin muss Frodo an der Seite des Zauberers Gandalf und seiner Gefährten durch Feindesland ziehen, immer verfolgt von Saurons Lakaien …","en":"Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/iZTDPQYgr3rhL7hPIYFt17ATp8.jpg","es":"https://image.tmdb.org/t/p/w500/9xtH1RmAzQ0rrMBNUMXstb2s3er.jpg","fr":"https://image.tmdb.org/t/p/w500/5OPg6M0yHr21Ovs1fni2H1xpKuF.jpg","de":"https://image.tmdb.org/t/p/w500/k6lw7hhaMDzJ170bfZfBbnipxcW.jpg","en":"https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg"}'::jsonb WHERE id = 33;
UPDATE public.films SET tmdb_id = 121, titoli_i18n = '{"it":"Il Signore degli Anelli - Le due torri","fr":"Le Seigneur des anneaux : Les Deux Tours","en":"The Lord of the Rings: The Two Towers","de":"Der Herr der Ringe - Die zwei Türme","es":"El señor de los anillos: Las dos torres"}'::jsonb, trame_i18n = '{"it":"La Compagnia si è divisa: Frodo e Sam proseguono verso Mordor guidati dalla subdola creatura Gollum, mentre Aragorn, Legolas e Gimli accorrono in aiuto del regno di Rohan. Insieme dovranno affrontare le schiere oscure di Saruman nella leggendaria battaglia del Fosso di Helm.","fr":"La Communauté est dissoute, mais la quête pour détruire l''Anneau Unique se poursuit. Accompagné par son fidèle Sam et guidé par l''étrange Gollum, Frodon cherche un moyen d''entrer en Mordor. Alors que l''armée de Saroumane se met en marche, les autres compagnons de la Communauté se préparent à la bataille. La Guerre de l''Anneau a commencé !","en":"Frodo Baggins and the other members of the Fellowship continue on their sacred quest to destroy the One Ring--but on separate paths. Their destinies lie at two towers - Orthanc Tower in Isengard, where the corrupt wizard Saruman awaits, and Sauron''s fortress at Barad-dur, deep within the dark lands of Mordor.","de":"Der Weg der Gefährten hat sich geteilt. Ringträger Frodo und sein treuer Begleiter Sam treffen in den Bergen von Emyn Muil auf Gollum, dem einst Bilbo Beutlin den Einen Ring wegnahm. Gollums Versuch, den mächtigen Ring von Frodo zu stehlen, misslingt, doch die Hobbits bringen es nicht übers Herz, die Kreatur zu töten. Stattdessen soll Gollum die beiden nach Mordor an die Pforten von Barad-Dûr, Saurons Festung, führen, wo Frodo den Ring vernichten will. Währenddessen folgen Aragorn, Elben-Bogenschütze Legolas und Zwerg Gimli den Spuren der von Orks verschleppten Hobbits. Im Menschenkönigreich Rohan ersuchen sie Unterstützung. Doch König Theoden steht unter einem tödlichen Bann Saurons. Erst als Gandalf als wiedergeborener weißer Zauberer zurückkehrt, wendet sich das Blatt. Er befreit Theoden von dem Fluch und bringt die Menschen von Rohan hinter sich. Unterdessen rückt Saurons Verbündeter Saruman mit einer 10.000 Mann starken Armee von Uruk-hais in RIchtung der Menschenstadt vor...","es":"La Compañía del Anillo se ha disuelto. El portador del anillo Frodo y su fiel amigo Sam se dirigen hacia Mordor para destruir el Anillo Único y acabar con el poder de Sauron. Mientras, y tras la dura batalla contra los orcos donde cayó Boromir, el hombre Aragorn, el elfo Legolas y el enano Gimli intentan rescatar a los medianos Merry y Pipin, secuestrados por los ogros de Mordor. Por su parte, Saurón y el traidor Sarumán continúan con sus planes en Mordor, en espera de la guerra contra las razas libres de la Tierra Media."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/jIhivyKlNwLmFJ2W6X98vh2XFwu.jpg","fr":"https://image.tmdb.org/t/p/w500/qVHBqQYLDRs7ESjP9q6o9iPHLWj.jpg","en":"https://image.tmdb.org/t/p/w500/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg","de":"https://image.tmdb.org/t/p/w500/tgBCeAjPwXeUaf8LsRL0LzBIcdR.jpg","es":"https://image.tmdb.org/t/p/w500/up6gIHZlfEQZkHIfQwcOOaGOzOt.jpg"}'::jsonb WHERE id = 34;
UPDATE public.films SET tmdb_id = 122, titoli_i18n = '{"it":"Il Signore degli Anelli - Il ritorno del re","en":"The Lord of the Rings: The Return of the King","es":"El señor de los anillos: El retorno del rey","fr":"Le Seigneur des anneaux : Le Retour du roi","de":"Der Herr der Ringe - Die Rückkehr des Königs"}'::jsonb, trame_i18n = '{"it":"L''epico scontro finale per la salvaguardia della Terra di Mezzo ha inizio. Mentre Aragorn reclami il suo trono e conduce l''esercito dei popoli liberi ai Cancelli Nero per distrarre le armate oscure, Frodo e Sam affrontano il massacrante tratto finale del viaggio verso il Monte Fato.","en":"As armies mass for a final battle that will decide the fate of the world--and powerful, ancient forces of Light and Dark compete to determine the outcome--one member of the Fellowship of the Ring is revealed as the noble heir to the throne of the Kings of Men. Yet, the sole hope for triumph over evil lies with a brave hobbit, Frodo, who, accompanied by his loyal friend Sam and the hideous, wretched Gollum, ventures deep into the very dark heart of Mordor on his seemingly impossible quest to destroy the Ring of Power.​","es":"Las fuerzas de Saruman han sido destruidas, y su fortaleza sitiada. Ha llegado el momento de que se decida el destino de la Tierra Media, y por primera vez en mucho tiempo, parece que hay una pequeña esperanza. La atención del señor oscuro Sauron se centra ahora en Gondor, el último reducto de los hombres, y del cual Aragorn tendrá que reclamar el trono para ocupar su puesto de rey. Pero las fuerzas de Sauron ya se preparan para lanzar el último y definitivo ataque contra el reino de Gondor, la batalla que decidirá el destino de todos. Mientras tanto, Frodo y Sam continuan su camino hacia Mordor, a la espera de que Sauron no repare en que dos pequeños Hobbits se acercan cada día más al final de su camino, el Monte del Destino.","fr":"La bataille pour la Terre du Milieu a commencé. Frodon et Sam, guidés par Gollum, poursuivent leur mission à travers les terres du Mordor pour détruire l''Anneau Unique. Tandis que le pouvoir de Sauron grandit, Aragorn, l''héritier du trône du Gondor, rassemble l''armée des Hommes contre les forces du Mal, afin de laisser une chance au porteur de l''Anneau d''accomplir sa quête…","de":"Saurons Heer will Minas Tirith angreifen, die in Felsen errichtete Hauptstadt von Gondor. Angesichts der Bedrohlichkeit des feindlichen Heeres wiegt es umso schwerer, dass Gondors König fehlt und nur der schwächliche Truchsess Denethor über das einst mächtige Königreich wacht. Wird Aragorn die Kraft aufbringen, jene Aufgabe zu übernehmen, für die sein Schicksal ihn bestimmt hat? Während Gandalf verzweifelt versucht, die mutlosen Kämpfer von Gondor zu motivieren, sammelt Théoden die Krieger von Rohan, um am Kampf teilzunehmen. Aber obwohl sie tapfer und leidenschaftlich Widerstand leisten, haben die Streitkräfte der Menschen dem überwältigenden Ansturm der feindlichen Legionen gegen das Königreich kaum etwas entgegenzusetzen. Jeder Sieg fordert große Opfer. Trotz der starken Verluste stellen sich die Gefährten der größten Schlacht ihres Lebens - vereint durch ein einziges Ziel: Sauron muss so lange abgelenkt werden, bis Frodo den Ring vernichtet hat..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/eCua9No8HqVxGajDQrG8mvRCtJM.jpg","en":"https://image.tmdb.org/t/p/w500/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg","es":"https://image.tmdb.org/t/p/w500/mWuFbQrXyLk2kMBKF9TUPtDwuPx.jpg","fr":"https://image.tmdb.org/t/p/w500/ypUCFOvOf07bcHy81jng9LyMUfi.jpg","de":"https://image.tmdb.org/t/p/w500/uFjlP9U9UOZAzGB25HUtmlEpXbc.jpg"}'::jsonb WHERE id = 35;
UPDATE public.films SET tmdb_id = 123, titoli_i18n = '{"it":"Il Signore degli Anelli","en":"The Lord of the Rings","de":"Der Herr der Ringe","es":"El Señor de los Anillos","fr":"Le Seigneur des anneaux"}'::jsonb, trame_i18n = '{"it":"Adattamento animato classico realizzato tramite la tecnica del rotoscopio che ripercorre le vicende della Compagnia dell''Anello. Frodo e i suoi compagni intraprendono un lungo viaggio per sconfiggere l''oscurità che minaccia la Terra di Mezzo.","en":"Young Hobbit Frodo Baggins is thrown into an amazing adventure when he''s tasked with destroying the One Ring, created by the dark lord Sauron. Frodo must travel in a small fellowship of nine warriors and accomplices. But it won''t be an easy journey for the Fellowship of the Ring, on the ultimate quest to rid Middle-earth of evil.","de":"Der junge Hobbit Frodo Beutlin bekommt von Gandalf die Aufgabe, den Einen Ring zu zerstören, der die Macht des Dunklen Herrschers Sauron enthält. Frodo schließt sich der Gemeinschaft des Rings an, zu der auch seine Freunde Sam, Merry und Pippin, der Grenzgänger Aragorn, der Krieger Boromir, der Elf Legolas, der Zwerg Gimli und Gandalf der Graue gehören. Die Gemeinschaft bricht nach Bruchtal auf, wird aber von den Schwarzen Reitern verfolgt. Sie durchqueren die gefährlichen Zwergenminen von Moria, treffen auf den undurchschaubaren Gollum und kämpfen in der Schlacht von Helms Klamm.","es":"Adaptación en dibujos animados de la extraordinaria novela de Tolkien, centrada en la primera mitad de la trilogía: \"The Fellowhip of the Ring\" y la primera parte de \"The Two Towers\". En la Tierra Media, desde las verdes praderas de la Comarca, Frodo Bolsón, sobrino de Bilbo Bolsón, se embarca en una larga y peligrosa aventura para evitar que un anillo mágico que perteneció a su tío caiga ahora en poder del malvado Sauron, dueño de Mordor.","fr":"Dans les Terres du Milieu, l''Anneau unique forgé par Sauron le maléfique pour dominer les hommes, les elfes et les nains est tombé par inadvertance dans les mains de Frodon, paisible hobbit. Ce n''est qu''une question de temps avant que les sinistres Cavaliers Noirs, les Servants de l''Anneau, retrouvent sa trace. Sous la direction de Gandalf le magicien, une expédition est alors montée avec pour mission une tâche quasi-impossible : détruire l''Anneau, en le jetant dans le feu de la Montagne du Destin, au coeur du territoire de l''ennemi..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zC18JY8JMNw4xZFjaaEYZw6H3A8.jpg","en":"https://image.tmdb.org/t/p/w500/liW0mjvTyLs7UCumaHhx3PpU4VT.jpg","de":"https://image.tmdb.org/t/p/w500/k0YO6bHkPOyhnw3nn17k6LVXbrO.jpg","es":"https://image.tmdb.org/t/p/w500/6SHIZpuZ2cGoTGq5nbihIgy43rC.jpg","fr":"https://image.tmdb.org/t/p/w500/lH5at1RvvglQmnoBkytTTPZfw94.jpg"}'::jsonb WHERE id = 36;
UPDATE public.films SET tmdb_id = 185, titoli_i18n = '{"es":"La naranja mecánica","it":"Arancia Meccanica","en":"A Clockwork Orange","fr":"Orange mécanique","de":"Uhrwerk Orange"}'::jsonb, trame_i18n = '{"es":"Gran Bretaña, en un futuro indeterminado. Alex es un joven muy agresivo que tiene dos pasiones: la violencia desaforada y Beethoven. Es el jefe de la banda de los drugos, que dan rienda suelta a sus instintos más salvajes apaleando, violando y aterrorizando a la población. Cuando esa escalada de terror llega hasta el asesinato, Alex es detenido y, en prisión, se someterá voluntariamente a una innovadora experiencia de reeducación que pretende anular drásticamente cualquier atisbo de conducta antisocial.","it":"In una Gran Bretagna distopica e futuristica, il giovane Alex DeLarge è il leader dei Drughi, una banda di criminali dedita ad atti brutali di ''ultraviolenza''. Dopo essere stato arrestato per omicidio e condannato al carcere, Alex accetta di sottoporsi alla ''Cura Ludovico'', un innovativo e controverso trattamento di condizionamento psicologico promosso dal governo. Il trattamento lo rende fisicamente incapace di compiere o persino di pensare ad azioni violente, ma al contempo lo priva del suo libero arbitrio, lasciandolo del tutto indifeso di fronte alla società e alla vendetta delle sue vecchie vittime.","en":"In a near-future Britain, young Alexander DeLarge and his pals get their kicks beating and raping anyone they please. When not destroying the lives of others, Alex swoons to the music of Beethoven. The state, eager to crack down on juvenile crime, gives an incarcerated Alex the option to undergo an invasive procedure that''ll rob him of all personal agency. In a time when conscience is a commodity, can Alex change his tune?","fr":"Au XXIe siècle, où règnent la violence et le sexe, Alex, jeune chef de bande, exerce avec sadisme une terreur aveugle. Après son emprisonnement, des psychanalystes l''emploient comme cobaye dans des expériences destinées à juguler la criminalité…","de":"Die Handlung spielt im London einer nicht allzu weit entfernten Zukunft und kreist um den jungen Alex. Der liebt Beethoven und ist Anführer der Droogs, einer Jugendgang. Die Gruppe selbst fällt mit nur durch den Akt an sich motivierten Gewalttaten und Vergewaltigungen Wehrloser auf. Nachdem die Jungs wieder mal einen Einbruch nebst Mord begangen haben, wird Alex von einem rebellierenden Gangmitglied niedergeschlagen und der Polizei überlassen. Der ehemalige Anführer kommt ins Gefängnis. Zwei Jahre später muss er als Versuchsobjekt an einer neuartigen, von der Regierung initiierten Aversionstherapie teilnehmen. Die Therapie dauert 14 Tage lang und konfrontiert Alex immer wieder mit Filmszenen stärkster Brutalität. Anschließend kommt er frei, ist nun allerdings nichts weiter als eine willenlose Hülle."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/p40pYh2EBPoyVyqw6qy2PAZkFVA.jpg","it":"https://image.tmdb.org/t/p/w500/7dbLsJo2DiyhPZO3iQc70LwDMzv.jpg","en":"https://image.tmdb.org/t/p/w500/4sHeTAp65WrSSuc05nRBKddhBxO.jpg","fr":"https://image.tmdb.org/t/p/w500/n2oKNiEq9DZljqs6xsxs8hnsW9p.jpg","de":"https://image.tmdb.org/t/p/w500/mB07QYollr6luCA9koLaywmZWDY.jpg"}'::jsonb WHERE id = 37;
UPDATE public.films SET tmdb_id = 646, titoli_i18n = '{"es":"Agente 007 contra el Dr. No","de":"James Bond 007 jagt Dr. No","en":"Dr. No","it":"Agente 007 - Licenza di uccidere","fr":"James Bond 007 contre Dr. No"}'::jsonb, trame_i18n = '{"es":"James Bond llega a Jamaica con la misión de investigar los asesinatos de un agente especial británico y su secretaria. Pero, al mismo tiempo, descubre la existencia de una siniestra organización en la isla Crab Key. En esta ocasión su enemigo es el Doctor No, que, ayudado por su cómplice, el profesor Dent, se propone ejecutar un siniestro plan: desviar la trayectoria de los cohetes de Cabo Cañaveral.","de":"Der mysteriöse Wissenschaftler Dr. No sabotiert von seiner geheimen Basis auf Jamaica aus das amerikanische Raumfahrtprogramm. Der Secret Service setzt seinen besten Agenten auf den Wissenschaftler an.","en":"Agent 007 battles mysterious Dr. No, a scientific genius bent on destroying the U.S. space program. As the countdown to disaster begins, Bond must go to Jamaica, where he encounters beautiful Honey Ryder, to confront a megalomaniacal villain in his massive island headquarters.","it":"L''agente segreto britannico James Bond, noto come 007, viene inviato in Giamaica per indagare sulla misteriosa scomparsa di un suo collega, lo chef della sezione di Kingston, e della sua segretaria. Con l''aiuto dell''agente della CIA Felix Leiter e del luogo Quarrel, Bond risale le tracce fino all''isola sotterranea di Crab Key. Lì fa la conoscenza della splendida Honey Ryder e scopre il covo del sinistro Dottor No, un genio del male affiliato all''organizzazione criminale SPECTRE. Dr. No intende utilizzare un''arma a raggi atomici per deviare la rotta dei missili spaziali americani lanciati da Cape Canaveral. 007 dovrà fare affidamento sulle sue abilità e sul suo fascino per distruggere la base segreta e sventare la minaccia globale.","fr":"Le chef des services secrets de Sa Majesté britannique, « M », envoie en mission à la Jamaïque l''agent spécial 007, James Bond, enquêter sur la disparition d''un de ses collègues. L''espion va affronter la puissance maléfique de Spectre, organisation criminelle qui vise à la domination du monde, personnifiée par le redoutable Dr No. Au gré de ses aventures, il rencontrera la sublime Honey, qui surgit de l''eau vêtue d''un bikini blanc."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/51Sy8Uu8Qwz6WWeqY17zHqXZU5d.jpg","de":"https://image.tmdb.org/t/p/w500/1NN9uwOnZiw4rj3drWHo0JVGZuq.jpg","en":"https://image.tmdb.org/t/p/w500/9zCOLJmLNst0sCPZlkW1IRoH65E.jpg","it":"https://image.tmdb.org/t/p/w500/7zrD13m7zmWrJncWO5UXPLGzeW6.jpg","fr":"https://image.tmdb.org/t/p/w500/txWTVoO9VltSsEghOoxdn8y6UqK.jpg"}'::jsonb WHERE id = 44;
UPDATE public.films SET tmdb_id = 658, titoli_i18n = '{"en":"Goldfinger","it":"Agente 007 - Missione Goldfinger","de":"James Bond 007 - Goldfinger","es":"James Bond contra Goldfinger","fr":"Goldfinger"}'::jsonb, trame_i18n = '{"en":"Special agent 007 comes face to face with one of the most notorious villains of all time, and now he must outwit and outgun the powerful tycoon to prevent him from cashing in on a devious scheme to raid Fort Knox -- and obliterate the world''s economy.","it":"L''agente segreto James Bond viene incaricato di indagare sui loschi affari di Auric Goldfinger, un magnate ossessionato dal metallo prezioso. Bond scopre un diabolico piano denominato ''Operazione Grand Slam'': Goldfinger intende far esplodere una bomba atomica all''interno del deposito aureo di Fort Knox per contaminare l''oro degli Stati Uniti e far schizzare alle stelle il valore del proprio monopolio. Tra insidiosi nemici come il letale scagnozzo Oddjob e l''affascinante pilota Pussy Galore, 007 dovrà fare di tutto per sventare il catastrofico piano.","de":"Die teuerste Art zu töten. James Bond, der Superagent seiner Majestät, wird auf die Fährte eines verbrecherischen Genies gesetzt, das die Goldreserven von Fort Knox in seinen Besitz bringen will. Bonds Gegner Goldfinger ist der Mann, der seine abtrünnig gewordene Geliebte einem tödlichen Veredelungsprozeß aussetzte, indem er sie mit Gold überzog. Männliche Rivalen barbiert Odd-Job, der Leibwächter des exzentrischen Mulitmillionärs, mit seiner rasiermesserscharfen Hutkrempe aus Metall. Mit Hilfe von Pussy Galore will Bond den Raub des Goldes vereiteln...","es":"Un malvado magnate, Auric Goldfinger, quiere hacer estallar una bomba atómica en Fort Knox, donde está toda la reserva federal de oro de los Estados Unidos, para poder así incrementar enormemente el precio del metal dorado.","fr":"L''agent secret 007 est chargé d''enquêter sur les revenus d''Auric Goldfinger. La banque d''Angleterre a découvert qu''il entreposait d''énormes quantités d''or, mais s''inquiète de ne pas savoir dans quel but. Quelques verres, parties de golf, poursuites et autres aventures galantes plus loin, James Bond découvre en réalité les préparatifs du « crime du siècle », dont les retombées pourraient amener le chaos économique sur les pays développés du bloc de l''Ouest…"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/aKNFzaqQgPzsGXnsMc4kJH5hFIV.jpg","it":"https://image.tmdb.org/t/p/w500/JcIhKJxmi7DQHsKV174WztIT4n.jpg","de":"https://image.tmdb.org/t/p/w500/okCBHoGLpyvZq8WRUZo9cKtox2I.jpg","es":"https://image.tmdb.org/t/p/w500/tA0AqFwuFvQCzLdBzEnIlK4RayX.jpg","fr":"https://image.tmdb.org/t/p/w500/8hN3D6rsQ98jSlkeMc43kfQ9pox.jpg"}'::jsonb WHERE id = 45;
UPDATE public.films SET tmdb_id = 524, titoli_i18n = '{"it":"Casino","es":"Casino","fr":"Casino","de":"Casino","en":"Casino"}'::jsonb, trame_i18n = '{"it":"Sam ''Ace'' Rothstein viene incaricato dalla mafia di gestire il casinò Tangiers a Las Vegas negli anni ''70. La sua gestione efficace viene però minacciata dall''amico d''infanzia e gangster Nikki Santoro e dalla tempestosa relazione con la moglie Ginger. Tra cupidigia, inganni e declino dell''impero mafioso, la storia ripercorre l''ascesa e la caduta dei boss nella capitale del gioco d''azzardo.","es":"Las Vegas, 1973. Sam \"Ace\" Rothstein, un profesional de las apuestas, es el eficaz director de un importante casino que pertenece a un grupo de mafiosos. Su misión es controlar el funcionamiento del negocio y garantizar que la corriente de dinero que va a parar a manos de sus jefes siga fluyendo. Las Vegas es un lugar ideal para millonarios y políticos, pero es también lugar de paso de tahúres, prestamistas, traficantes de drogas y matones. Un día el violento Nicky Santoro, al que sus jefes han encargado que cuide de Sam, llega a Las Vegas con la intención de quedarse.","fr":"Dans les années soixante-dix à Las Vegas, Ace Rothstein dirige d''une main de fer l''hôtel-casino Tangiers, financé en sous-main par le puissant syndicat des camionneurs. Le Tangiers est l''un des casinos les plus prospères de la ville et Ace est devenu le grand manitou de Las Vegas, secondé par son ami d''enfance, Nicky Santoro. Impitoyable avec les tricheurs, Rothstein se laisse un jour séduire par une virtuose de l''arnaque d''une insolente beauté, Ginger McKenna. Amoureux, il lui ouvre les portes de son paradis et l''épouse. Ses ennuis commencent alors.","de":"Sam „Ace“ Rothstein sorgt dafür, dass in den Casinos von Las Vegas alles gut läuft. Das heißt: die Politiker müssen geschmiert werden, die Spieler dürfen nicht zu viel gewinnen, und die eigenen Kassen werden immer wieder um einige Millionen erleichtert. Tatkräftige Unterstützung erhält der Manager dabei von dem Schläger Nicky Santoro. Als „Ace“ sich in die attraktive Prostituierte Ginger McKenna verliebt, beginnen die Dinge außer Kontrolle zu geraten. Denn Ginger ist nicht nur drogen-, sondern auch extrem geltungssüchtig.","en":"In Las Vegas, two best friends-a casino executive and a Mafia enforcer--compete for a gambling empire and a fast-living, fast-loving socialite."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/bUQRgD54q9OrwHrvJN36jJiWhoP.jpg","es":"https://image.tmdb.org/t/p/w500/7x8lsyTB0G7OrLzQ7qxt3ywQ4OY.jpg","fr":"https://image.tmdb.org/t/p/w500/4a0I37pYcdFY6HeutalHQTGs0sl.jpg","de":"https://image.tmdb.org/t/p/w500/76C391pg53WIxUEH1aZjT3ve1Nl.jpg","en":"https://image.tmdb.org/t/p/w500/gziIkUSnYuj9ChCi8qOu2ZunpSC.jpg"}'::jsonb WHERE id = 46;
UPDATE public.films SET tmdb_id = 36557, titoli_i18n = '{"it":"Casino Royale","es":"Casino Royale","fr":"Casino Royale","de":"James Bond 007 - Casino Royale","en":"Casino Royale"}'::jsonb, trame_i18n = '{"it":"Dopo aver ottenuto lo status di agente 00 e la licenza di uccidere, James Bond viene inviato in missione per fermare Le Chiffre, un brillante e spietato banchiere che finanzia organizzazioni terroristiche internazionali. Avendo perso ingenti somme di denaro appartenenti ai suoi pericolosi clienti a causa di un attentato sventato dallo stesso Bond, Le Chiffre organizza una partita di poker Texas Hold''em ad altissima posta al Casino Royale, in Montenegro, nel tentativo disperato di recuperare i fondi. L''MI6 affida a Bond il compito di batterlo al tavolo verde per costringerlo a chiedere asilo al governo britannico in cambio di informazioni cruciali. Affiancato dall''affascinante e riservata funzionaria del Tesoro Vesper Lynd, incaricata di monitorare i fondi statali della posta in gioco, l''agente 007 si ritrova invischiato in un mortale gioco di strategia, inganni e violenza, che lo porterà a scoprire il peso emotivo del proprio mestiere e il sapore del tradimento.","es":"La primera misión del agente británico James Bond como agente 007 lo lleva hasta Le Chiffre, banquero de los terroristas de todo el mundo. Para detenerlo y desmantelar la red terrorista, Bond debe derrotarlo en una arriesgada partida de póquer en el Casino Royale. Al principio a Bond le disgusta Vesper Lynd, la hermosa oficial del Tesoro que debe vigilar el dinero del gobierno. Pero, a medida que Bond y Vesper se ven obligados a defenderse juntos de los mortales ataques de Le Chiffre y sus secuaces, nace entre ellos una atracción mutua.","fr":"Pour sa première mission, James Bond affronte le tout-puissant banquier privé du terrorisme international, Le Chiffre. Pour achever de le ruiner et démanteler le plus grand réseau criminel qui soit, Bond doit le battre lors d''une partie de poker à haut risque au Casino Royale. La très belle Vesper, attachée au Trésor, l''accompagne afin de veiller à ce que l''agent 007 prenne soin de l''argent du gouvernement britannique qui lui sert de mise, mais rien ne va se passer comme prévu. Alors que Bond et Vesper s''efforcent d''échapper aux tentatives d''assassinat du Chiffre et de ses hommes, d''autres sentiments surgissent entre eux, ce qui ne fera que les rendre plus vulnérables...","de":"Sein erster Auftrag, nachdem er die Lizenz zum Töten erhalten hat, führt den MI6-Agenten James Bond nach Madagaskar, wo er auf den Terroristen Mollaka angesetzt wird. Zwar verläuft nicht alles nach Plan, doch als Bond auf eigene Faust weiter ermittelt, kommt er auf die Spur von Le Chiffre, dem Bankier einer weltweit operierenden Terror-Organisation. Dieser plant, das Vermögen seiner Organisation durch ein illegales Pokerspiel im „Casino Royale“ in Montenegro um ein Vielfaches zu erhöhen, wofür natürlich auch ein hoher Einsatz nötig ist. Der MI6 sieht daher die Chance, die Terroristen in den finanziellen Ruin zu treiben und beauftragt James Bond, die Pläne von Le Chiffre zunichte zu machen.","en":"Le Chiffre, a banker to the world''s terrorists, is scheduled to participate in a high-stakes poker game in Montenegro, where he intends to use his winnings to establish his financial grip on the terrorist market. M sends Bond—on his maiden mission as a 00 Agent—to attend this game and prevent Le Chiffre from winning. With the help of Vesper Lynd and Felix Leiter, Bond enters the most important poker game in his already dangerous career."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/wmRTS3WrXRi8GJdpDae1NifYNwx.jpg","es":"https://image.tmdb.org/t/p/w500/qplE2N7QWTO6w7X8zW46X3cGUBZ.jpg","fr":"https://image.tmdb.org/t/p/w500/1ST7phuvQsaAIIkRyAtESZFLMx9.jpg","de":"https://image.tmdb.org/t/p/w500/uvigE215SzXdsEFPN0XRFR9RPiA.jpg","en":"https://image.tmdb.org/t/p/w500/lMrxYKKhd4lqRzwUHAy5gcx9PSO.jpg"}'::jsonb WHERE id = 47;
UPDATE public.films SET tmdb_id = 31414, titoli_i18n = '{"it":"Sátántangó","es":"Sátántangó","en":"Satantango","de":"Satanstanz","fr":"Le Tango de Satan"}'::jsonb, trame_i18n = '{"it":"In un desolate e piovoso villaggio ungherese dopo la chiusura di una fattoria collettiva, gli abitanti vivono nell''apatia e nel sospetto reciproco. Il presunto ritorno del carismatico Irimiás, ritenuto morto da tutti, riaccende una labile speranza che si trasforma presto in una complessa danza di manipolazione e inganno.","es":"La historia relata gradualmente los problemas de una granja colectiva durante unos pocos días de otoño en los años de la Hungría post-comunista, observada desde la perspectiva de distintos personajes. (FILMAFFINITY)","en":"Inhabitants of a small village in Hungary deal with the effects of the fall of Communism. The town''s source of revenue, a factory, has closed, and the locals, who include a doctor and three couples, await a cash payment offered in the wake of the shuttering. Irimias, a villager thought to be dead, returns and, unbeknownst to the locals, is a police informant. In a scheme, he persuades the villagers to form a commune with him.","de":"Am Vorabend einer großen Auszahlung sehen sich die Pläne der Bewohner einer zusammenbrechenden Kolchose in Verzweiflung verwandelt, als sie feststellen, dass Irimiás, ein ehemaliger Kollege, den sie für tot hielten, in die Gemeinschaft zurückkehrt.","fr":"Dans un petit village hongrois, deux mystérieuses personnes que chacun croyait disparues refont parler d''elles. Une épopée de plus de sept heures sur la chute du communisme en Europe de l''Est."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/cOrtWdUflqXL9BqoQNjv9WwQiPs.jpg","es":"https://image.tmdb.org/t/p/w500/cOrtWdUflqXL9BqoQNjv9WwQiPs.jpg","en":"https://image.tmdb.org/t/p/w500/hySy5g6xncM3U1iRsdPgYyahXM0.jpg","de":"https://image.tmdb.org/t/p/w500/cOrtWdUflqXL9BqoQNjv9WwQiPs.jpg","fr":"https://image.tmdb.org/t/p/w500/cOrtWdUflqXL9BqoQNjv9WwQiPs.jpg"}'::jsonb WHERE id = 48;
UPDATE public.films SET tmdb_id = 24428, titoli_i18n = '{"it":"The Avengers","en":"The Avengers","es":"Vengadores","de":"Marvel''s The Avengers","fr":"Avengers"}'::jsonb, trame_i18n = '{"it":"Quando Loki, il malvagio fratellastro di Thor, minaccia la sicurezza della Terra impossessandosi del potente Tesseract, Nick Fury, direttore dell''agenzia di spionaggio S.H.I.E.L.D., decide di attivare il protocollo Avengers. Per sconfiggere la minaccia aliena, Fury riunisce una squadra di supereroi straordinari, tra cui Iron Man, Captain America, Thor, Hulk, Vedova Nera e Occhio di Falco. Nonostante le iniziali incomprensioni e i conflitti interni, il gruppo dovrà unire le forze per salvare l''umanità.","en":"When an unexpected enemy emerges and threatens global safety and security, Nick Fury, director of the international peacekeeping agency known as S.H.I.E.L.D., finds himself in need of a team to pull the world back from the brink of disaster. Spanning the globe, a daring recruitment effort begins!","es":"Cuando un enemigo inesperado surge como una gran amenaza para la seguridad mundial, Nick Fury, director de la Agencia SHIELD, decide reclutar a un equipo para salvar al mundo de un desastre casi seguro.","de":"Nick Fury ist der Anführer der Organisation S.H.I.E.L.D., einer internationalen Friedensorganisation. Die Behörde ist ein Who''s Who der Marvel Superhelden, mit Iron Man, Thor, Captain America, Hawkeye, dem Unglaublichen Hulk und Black Widow. Als die weltweite Sicherheit von Thors sinistrem Halbbruder Loki und seiner Schar bedroht wird, werden Nick Fury und sein Team all ihre Kräfte brauchen, um die Welt vor einer Katastrophe zu bewahren ...","fr":"Lorsque la sécurité et l’équilibre de la planète sont menacés par un ennemi d’un genre nouveau, Nick Fury, le directeur du SHIELD, l’agence internationale du maintien de la paix, réunit une équipe pour empêcher le monde de basculer dans le chaos. Partout sur Terre, le recrutement des nouveaux héros dont le monde a besoin commence…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/o6IvnjWsAjPja21JA1EHo0XcYTy.jpg","en":"https://image.tmdb.org/t/p/w500/RYMX2wcKCBAr24UyPD7xwmjaTn.jpg","es":"https://image.tmdb.org/t/p/w500/ugX4WZJO3jEvTOerctAWJLinujo.jpg","de":"https://image.tmdb.org/t/p/w500/hGTqvK9WaI74szUDPMHXrrHfiH3.jpg","fr":"https://image.tmdb.org/t/p/w500/ylsAO88v2tF0iXRFojPa0UaAJf1.jpg"}'::jsonb WHERE id = 49;
UPDATE public.films SET tmdb_id = 99861, titoli_i18n = '{"en":"Avengers: Age of Ultron","it":"Avengers: Age of Ultron","de":"Avengers: Age of Ultron","fr":"Avengers : L''Ère d''Ultron","es":"Vengadores: La era de Ultrón"}'::jsonb, trame_i18n = '{"en":"When Tony Stark tries to jumpstart a dormant peacekeeping program, things go awry and Earth’s Mightiest Heroes are put to the ultimate test as the fate of the planet hangs in the balance. As the villainous Ultron emerges, it is up to The Avengers to stop him from enacting his terrible plans, and soon uneasy alliances and unexpected action pave the way for an epic and unique global adventure.","it":"Quando Tony Stark e Bruce Banner cercano di avviare un programma di mantenimento della pace inattivo chiamato Ultron, le cose vanno terribilmente storte e il sistema intelligenza artificiale sviluppa una coscienza divina, decidendo che l''unico modo per salvare la Terra è sterminare l''umanità. Gli Avengers devono riunirsi e stringere imprevedibili alleanze per fermare il temibile Ultron e i suoi piani di distruzione globale.","de":"Milliardär, Lebemann und Genie Tony Stark aka Iron Man will ein inaktives Friedensprogramm in Gang bringen, doch dabei geht etwas schief. So taucht der niederträchtige Roboter-Bösewicht Ultron auf und verfolgt Pläne zur Ausrottung der Menschheit. Nun ist es an den Helden, sich wieder zu sammeln und das schreckliche Schicksal der Welt abzuwenden. Zusammen mit Iron Man treten Thor, Captain America, Hulk, Black Widow und Hawkeye dem fiesen Ultron entgegen und bekommen dabei Unterstützung von den ehemaligen S.H.I.E.L.D.-Agenten Nick Fury und Maria Hill. Außerdem kreuzen die geheimnisvollen und mit besonderen Fähigkeiten ausgestatteten Newcomer Wanda und Pietro Maximoff den Weg der Helden, wie auch ein alter Bekannter in neuer Gestalt: Vision. Die Rächer müssen ihre Kräfte vereinen, unsichere Allianzen schmieden und auf unerwartete Aktionen reagieren, um die Bewohner der Erde einmal mehr vor dem drohenden Untergang zu bewahren.","fr":"Alors que Tony Stark tente de relancer un programme de maintien de la paix jusque-là suspendu, les choses tournent mal et les super-héros Iron Man, Captain America, Thor, Hulk, Black Widow et Hawkeye vont devoir à nouveau unir leurs forces pour combattre le plus puissant de leurs adversaires : le terrible Ultron, un être technologique terrifiant qui s’est juré d’éradiquer l’espèce humaine. Afin d’empêcher celui-ci d’accomplir ses sombres desseins, des alliances inattendues se scellent, les entraînant dans une incroyable aventure et une haletante course contre le temps…","es":"Cuando Tony Stark intenta reactivar un programa caído en desuso cuyo objetivo es mantener la paz, las cosas empiezan a torcerse y los héroes más poderosos de la Tierra, incluyendo a Iron Man, Capitán América, Thor, El Increíble Hulk, Viuda Negra y Ojo de Halcón, tendrán que afrontar la prueba definitiva cuando el destino del planeta se ponga en juego. Cuando el villano Ultron emerge, le corresponderá a Los Vengadores detener sus terribles planes, que junto a incómodas alianzas llevarán a una inesperada acción que allanará el camino para una épica y única aventura."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/4ssDuvEDkSArWEdyBl2X5EHvYKU.jpg","it":"https://image.tmdb.org/t/p/w500/pYEHarIwyYSM1bXs5FtpL2GZELy.jpg","de":"https://image.tmdb.org/t/p/w500/woAP8YaiVIuo7YXTeqVQEhXBdfz.jpg","fr":"https://image.tmdb.org/t/p/w500/A0tw88n1byyR2vodhJMlFPQGQgF.jpg","es":"https://image.tmdb.org/t/p/w500/71wSx6MQm8EbMNDi3vVaD8nD9SL.jpg"}'::jsonb WHERE id = 50;
UPDATE public.films SET tmdb_id = 299536, titoli_i18n = '{"it":"Avengers: Infinity War","de":"Avengers: Infinity War","en":"Avengers: Infinity War","es":"Vengadores: Infinity War","fr":"Avengers : Infinity War"}'::jsonb, trame_i18n = '{"it":"Gli Avengers e i loro alleati supereroi devono essere pronti a sacrificare tutto nel tentativo di sconfiggere il potente Thanos, prima che il suo devastante attacco ponga fine all''universo. Il tiranno cosmico è alla ricerca delle sei Gemme dell''Infinito, manufatti di inimmaginabile potere, con l''obiettivo di dimezzare la popolazione dell''universo e portare un folle equilibrio.","de":"Der mächtige Titan Thanos  hat es sich zur Aufgabe gemacht das halbe Universum auszulöschen. Um diesen perfiden Plan Realität werden zu lassen, benötigt er allerdings zuerst alle sechs Infinity-Steine, die ihm in Verbindung mit einem speziell gefertigten Handschuh, gottgleiche Kräfte verleihen. Da sich unglücklicherweise auch auf der Erde zwei dieser Steine befinden, betraut er seine treu ergebene Black Order mit deren Beschaffung. Sowohl die Avengers, als auch die Guardians of the Galaxy und Thor erfahren jedoch von Thanos'' Plänen und stellen sich dem Schurken entgegen. Doch mit einen derart mächtigen Gegner hatte es bisher keiner von ihnen zu tun...","en":"As the Avengers and their allies have continued to protect the world from threats too large for any one hero to handle, a new danger has emerged from the cosmic shadows: Thanos. A despot of intergalactic infamy, his goal is to collect all six Infinity Stones, artifacts of unimaginable power, and use them to inflict his twisted will on all of reality. Everything the Avengers have fought for has led up to this moment - the fate of Earth and existence itself has never been more uncertain.","es":"El todopoderoso Thanos ha despertado con la promesa de arrasar con todo a su paso, portando el Guantelete del Infinito, que le confiere un poder incalculable. Los únicos capaces de pararle los pies son los Vengadores y el resto de superhéroes de la galaxia, que deberán estar dispuestos a sacrificarlo todo por un bien mayor. Capitán América e Ironman deberán limar sus diferencias, Black Panther apoyará con sus tropas desde Wakanda, Thor y los Guardianes de la Galaxia e incluso Spider-Man se unirán antes de que los planes de devastación y ruina pongan fin al universo. ¿Serán capaces de frenar el avance del titán del caos?","fr":"Les Avengers et leurs alliés devront être prêts à tout sacrifier pour neutraliser le redoutable Thanos avant que son attaque éclair ne conduise à la destruction complète de l’univers."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/t24aimjQLa0dyoZQEbSws7XK1U0.jpg","de":"https://image.tmdb.org/t/p/w500/2hj7diAFcApL2YfWwjiYCuRI4WW.jpg","en":"https://image.tmdb.org/t/p/w500/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg","es":"https://image.tmdb.org/t/p/w500/ksBQ4oHQDdJwND8H90ay8CbMihU.jpg","fr":"https://image.tmdb.org/t/p/w500/hSfuKPtyEryeFzapZ8UgZd4aESu.jpg"}'::jsonb WHERE id = 51;
UPDATE public.films SET tmdb_id = 299534, titoli_i18n = '{"it":"Avengers: Endgame","fr":"Avengers : Endgame","de":"Avengers: Endgame","es":"Vengadores: Endgame","en":"Avengers: Endgame"}'::jsonb, trame_i18n = '{"it":"Dopo gli eventi devastanti di Avengers: Infinity War, l''universo è in rovina a causa delle azioni di Thanos. Con l''aiuto degli alleati rimasti, gli Avengers superstiti si riuniscono ancora una volta per annullare le azioni del Titano Pazzo. Attraverso un rischioso viaggio nel tempo nel Regno Quantico, il gruppo tenta di recuperare le Gemme dell''Infinito nel passato per riportare in vita tutti coloro che sono scomparsi e ripristinare l''ordine nell''universo.","fr":"Après leur défaite face au Titan Thanos qui dans le film précédent s''est approprié toutes les pierres du Gant de l''infini, les Avengers et les Gardiens de la Galaxie ayant survécu à son claquement de doigts qui a pulvérisé « la moitié de toute forme de vie dans l''Univers », Captain America, Thor, Bruce Banner, Natasha Romanoff, War Machine, Tony Stark, Nébula et Rocket, vont essayer de trouver une solution pour ramener leurs coéquipiers disparus et vaincre Thanos en se faisant aider par Ronin alias Clint Barton, Captain Marvel et Ant-Man.","de":"Thanos hat also tatsächlich Wort gehalten, seinen Plan in die Tat umgesetzt und die Hälfte allen Lebens im Universum ausgelöscht. Die Avengers? Machtlos. Iron Man und Nebula sitzen auf dem Planeten Titan fest, während auf der Erde absolutes Chaos herrscht. Doch dann finden Captain America und die anderen überlebenden Helden auf der Erde heraus, dass Nick Fury vor den verheerenden Ereignissen gerade noch ein Notsignal absetzen konnte, um Verstärkung auf den Plan zu rufen. Die Superhelden-Gemeinschaft bekommt mit Captain Marvel kurzerhand tatkräftige Unterstützung im Kampf gegen ihren vermeintlich übermächtigen Widersacher. Und dann ist da auch noch Ant-Man, der wie aus dem Nichts auftaucht und sich der Truppe erneut anschließt, um die ganze Sache womöglich doch noch zu einem guten Ende zu bringen …","es":"Tras el chasquido de Thanos que eliminó a la mitad de la vida en el universo, los Vengadores supervivientes quedan devastados y divididos. Cinco años después, una inesperada oportunidad les permite intentar revertir la catástrofe. Reuniéndose una vez más, los héroes emprenden una misión extrema que los obliga a viajar al pasado, enfrentarse a sus propias pérdidas y hacer sacrificios definitivos para restaurar el equilibrio del universo.","en":"After the devastating events of Avengers: Infinity War, the universe is in ruins due to the efforts of the Mad Titan, Thanos. With the help of remaining allies, the Avengers must assemble once more in order to undo Thanos'' actions and restore order to the universe once and for all, no matter what consequences may be in store."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hj1xaEUGMiUxaFYoutlljtlkHSG.jpg","fr":"https://image.tmdb.org/t/p/w500/qXekTarZKRrVfnBwhS6xevt6BGU.jpg","de":"https://image.tmdb.org/t/p/w500/ibO8Pj0aA1nwj3Q9FMpMcYZkdCA.jpg","es":"https://image.tmdb.org/t/p/w500/br6krBFpaYmCSglLBWRuhui7tPc.jpg","en":"https://image.tmdb.org/t/p/w500/jtDv3lCnST0fZRvdYFwR5CVwK2x.jpg"}'::jsonb WHERE id = 52;
UPDATE public.films SET tmdb_id = 12211, titoli_i18n = '{"it":"Highlander: Endgame","en":"Highlander: Endgame","fr":"Highlander: Endgame","de":"Highlander: Endgame","es":"Los inmortales IV. Juego final"}'::jsonb, trame_i18n = '{"it":"Duncan MacLeod e suo cugino Connor uniscono le forze per affrontare Jacob Kell, un malvagio immortale che ha accumulato un potere immenso eliminando centinaia di rivali nel corso dei secoli. Per sconfiggere un nemico apparentemente invincibile, i due guerrieri scozzesi dovranno affrontare il proprio passato e compiere la scelta più difficile della loro vita.","en":"Immortals Connor and Duncan Macleod join forces against a man from Connor''s distant past in the highlands of Scotland, Kell, an immensely powerful immortal who leads an army of equally powerful and deadly immortal swordsmen and assassins. No immortal alive has been able to defeat Kell yet, and neither Connor nor Duncan are skilled enough themselves to take him on and live. The two of them eventually come to one inevitable conclusion; one of them must die so that the combined power of both the Highlanders can bring down Kell for good. There can be only one... the question is, who will it be?","fr":"Les Highlanders ont vécu à l''époque de nos ancêtres et vivent aujourd''hui à nos côtés. Depuis des siècles, Duncan MacLeod (Adrian Paul) croise le chemin de son proche ami, Connor MacLeod (Christophe Lambert), immortel également. Leur amitié a commencé au XVIIème siècle, lors de leur première rencontre sur le champ de bataille de Glen Fruin. Connor l''avait alors pris comme apprenti et lui avait enseigné les rudiments de combat et les règles des immortels. A l''aube du XXIème siècle, le destin a fait en sorte de les réunir à nouveau. Par ailleurs, les deux combattants découvrent que chacun de leurs adversaires possède un pouvoir de destruction incroyable dû à la maîtrise des arts martiaux et de l''épée. Une ultime bataille dont l''issue décidera du destin de l''espèce humaine va se dérouler entre les immortels sur la Terre. A la fin, il ne doit en rester qu''un seul.","de":"Heute: Auf der Suche nach seinem Vetter Connor MacLeod findet der unsterbliche Highlander Duncan MacLeod das geheime Refugium. Hier werden Unsterbliche, die des Lebens müde geworden sind, in einen künstlichen Schlaf versetzt. Das Refugium ist auch dafür da, dass der Kampf der Unsterblichen um die Weltherrschaft nie ein Ende finden kann, denn solange es noch mehr als einen gibt ist nichts entschieden. Auch darum ist der Standort des Refugiums geheim. Doch der kaltblütigste Unsterbliche hat es gefunden, zerstört, seine \"Einwohner\" geköpft. Nur Connor MacLeod hat er laufen lassen, nicht um ihn zu verschonen, sondern um sich an ihm zu rächen...","es":"Connor MacLeod está cansado de su condición de inmortal y de ver cómo sobrevive a todos los que ama. Se recluye en un santuario en el que los inmortales pueden reposar en paz, sin tener que luchar. Pero el santuario es atacado por un viejo enemigo, Jacob Kell, que, después de asesinar a todos los que se encontraban retirados, excepto Connor, se ha convertido en el inmortal más poderoso. Ahora, Connor y su hermano Duncan tendrán que detenerlo y evitar así que sea el malvado Kell el último inmortal que quede."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/jWo1Azj8JFiFAd7MAGkutWB8ZVW.jpg","en":"https://image.tmdb.org/t/p/w500/u7kIXMyagqcek2SaS9svfPTTGVT.jpg","fr":"https://image.tmdb.org/t/p/w500/u7kIXMyagqcek2SaS9svfPTTGVT.jpg","de":"https://image.tmdb.org/t/p/w500/wATBEDL4TboulrprMaCFv34TpVY.jpg","es":"https://image.tmdb.org/t/p/w500/5lVlajdAMI2WnX5X8OnguITpmZM.jpg"}'::jsonb WHERE id = 53;
UPDATE public.films SET tmdb_id = 1366, titoli_i18n = '{"es":"Rocky","it":"Rocky","fr":"Rocky","en":"Rocky","de":"Rocky"}'::jsonb, trame_i18n = '{"es":"Rocky Balboa es un desconocido boxeador a quien se le ofrece la posibilidad de pelear por el título mundial de los pesos pesados. Con mucha fuerza de voluntad, Rocky se preparará concienzudamente para este combate, y también para los cambios que producirá en su vida.","it":"Rocky Balboa, un pugile di poco conto di Filadelfia che vive riscuotendo crediti per un usuraio locale, ottiene una straordinaria ed inaspettata occasione: sfidare il campione del mondo dei pesi massimi, Apollo Creed. Con il duro allenamento dell''anziano Mickey e il supporto dell''amata Adriana, Rocky cercherà di riscattare la propria vita e dimostrare di non essere solo un fantoccio sul ring.","fr":"Dans les quartiers populaires de Philadelphie, Rocky Balboa collecte des dettes non payées pour Tony Gazzo, un usurier, et dispute de temps à autre, pour quelques dizaines de dollars, des combats de boxe sous l''appellation de ''l''étalon italien''. Déçu de le voir gâcher son talent, son entraîneur Mickey le laisse tomber, tandis qu''Apollo Creed, champion en titre, cherche un nouveau challenger...","en":"Rocky Balboa is a Philadelphia club fighter who seems to be going nowhere. But when a stroke of fate puts him in the ring with a world heavyweight champion, Rocky knows that it''s his one shot at the big time — a once-in-a-lifetime opportunity to go the distance and come out a winner!","de":"Rocky Balboa ist ein begnadeter Boxer. Doch der Weg zum Ruhm und dem großen Geld blieb ihm immer verwehrt. Als armer Geldeintreiber muss er ein schäbiges Dasein fristen. Da geschieht das Unglaubliche: Der Amateurboxer erhält die Möglichkeit, gegen den Schwergewichtsweltmeister Apollo Creed anzutreten. Was als PR-Gag geplant ist, entpuppt sich als brutaler und gnadenloser Kampf, denn der ehrgeizige Rocky will sich die Chance seines Lebens von niemandem nehmen lassen …"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/yyoGappf3WxXRrHz23yNbH2MffI.jpg","it":"https://image.tmdb.org/t/p/w500/drkb38iICkgy712cMWJAH4IFqSQ.jpg","fr":"https://image.tmdb.org/t/p/w500/5cfUTKtLYJx8WcTRJII4JRnlg6p.jpg","en":"https://image.tmdb.org/t/p/w500/1mcJmdbRLusxhoSGjFI3pbEboXt.jpg","de":"https://image.tmdb.org/t/p/w500/1mcJmdbRLusxhoSGjFI3pbEboXt.jpg"}'::jsonb WHERE id = 54;
UPDATE public.films SET tmdb_id = 1374, titoli_i18n = '{"it":"Rocky IV","en":"Rocky IV","es":"Rocky IV","fr":"Rocky IV","de":"Rocky IV - Der Kampf des Jahrhunderts"}'::jsonb, trame_i18n = '{"it":"Rocky Balboa accompagna l''amico fraterno ed ex rivale Apollo Creed in un match di esibizione contro il temibile e glaciale pugile sovietico Ivan Drago. Quando Apollo muore tragicamente sul ring a causa dei colpi brutali di Drago, Rocky decide di vendicare l''amico sfidando il gigante russo a Mosca il giorno di Natale. Per prepararsi, Rocky si sottopone a un durissimo allenamento tra i ghiacci della Siberia, culminando in uno scontro epico che va oltre lo sport, diventando un simbolo della Guerra Fredda.","en":"Rocky Balboa holds the world heavyweight championship, but a new challenger has stepped forward: Drago, a six-foot-four, 261-pound fighter who has the backing of the Soviet Union. This time, Rocky''s training regimen takes him to Siberia, where he prepares for a globally televised match in the heart of Moscow. But nothing can truly prepare him for what he''s about to face – a fight to the finish, in which he must defend not only himself, but also the honor of his country!","es":"Nuevas aventuras tanto personales como deportivas del boxeador Rocky Balboa, que en esta ocasión debe enfrentarse a un duro y frío boxeador soviético, llamado Ivan Drago.","fr":"Apollo Creed, ancien adversaire et dorénavant ami de Rocky Balboa, est tué sur le ring par le boxeur russe Ivan Drago. Se reprochant de n''avoir pu sauver son camarade à temps, Rocky va demander un combat contre Ivan Drago afin de le venger. Une confrontation qui se déroulera sur le sol russe.","de":"Rocky ist wieder da. Nach seinem sensationellen Sieg gegen Clubber Lang ist das Leben des Champions wieder in Ordnung. Doch da möchte bereits der nächste Herausforderer eine Chance, um gegen Rocky zu boxen. Es ist der sowjetische Boxer Ivan Drago, der Rockys bisherige Gegner in den Schatten stellt. Dies bekommt in einem mörderischen Schaukampf auch Rockys Ex-Gegner und heutiger Freund Apollo Creed nur allzu deutlich zu spüren. Nun ist es unausweichlich – Rocky muss gegen den russischen Hünen antreten. Und in Moskau kommt es schließlich zu diesem Kampf – einem Kampf der Superlative, in dem beide Boxer wirklich alles geben – aber es kann nur einer gewinnen!"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/k4mDFvQkr9CNxbK76Ih6rTnCQ4A.jpg","en":"https://image.tmdb.org/t/p/w500/2MHUit4H6OK5adcOjnCN6suCKOl.jpg","es":"https://image.tmdb.org/t/p/w500/2MHUit4H6OK5adcOjnCN6suCKOl.jpg","fr":"https://image.tmdb.org/t/p/w500/bnd1dSQZyp6wL2AqtHG2PreJyZ5.jpg","de":"https://image.tmdb.org/t/p/w500/stp9EQwMSsoyp7M79Hdf08lTeQH.jpg"}'::jsonb WHERE id = 55;
UPDATE public.films SET tmdb_id = 1367, titoli_i18n = '{"it":"Rocky II","en":"Rocky II","es":"Rocky II","fr":"Rocky II : La Revanche","de":"Rocky II"}'::jsonb, trame_i18n = '{"it":"Dopo il durissimo incontro con il campione dei pesi massimi Apollo Creed, Rocky Balboa decide di ritirarsi dal pugilato, sposa l''amata Adriana e cerca di costruirsi una vita tranquilla lontano dal ring. Ben presto però, a causa dell''inesperienza nella gestione del denaro e delle difficoltà a trovare un impiego stabile, Rocky si ritrova in gravi difficoltà economiche. Nel frattempo, Creed, tormentato dalle critiche dei tifosi e dalla stampa che insinuano che il verdetto del precedente match sia stato immeritato, lo provoca ripetutamente per convincerlo a salire di nuovo sul ring per una rivincita. Spinto dal bisogno e dal desiderio di riscatto, e confortato dal supporto di Adriana dopo un periodo critico, Rocky riprende gli allenamenti con Mickey per affrontare un drammatico secondo scontro.","en":"After Rocky goes the distance with champ Apollo Creed, both try to put the fight behind them and move on. Rocky settles down with Adrian but can''t put his life together outside the ring, while Creed seeks a rematch to restore his reputation. Soon enough, the \"Master of Disaster\" and the \"Italian Stallion\" are set on a collision course for a climactic battle that is brutal and unforgettable.","es":"Rocky Balboa, el boxeador de Philadelphia, disfruta de su efímera fama después de estar a punto de derrotar al campeón mundial de los pesos pesados Apollo Creed. Las ofertas publicitarias para el anuncio de productos no van bien debido a la limitada educación y falta de sofisticación del púgil. Por ello, y debido a la falta de dinero y al embarazo de su mujer Adrian, acepta la demanda de revancha del \"casi derrotado\" Creed.","fr":"Battu aux points lors de son dernier combat, Rocky n''accepte pas cette défaite et ne veut plus entendre parler de boxe. Il épouse Adrian, dépense sa fortune sans compter et bientôt se retrouve sans le sou. Poussé a bout par Apollo, qui veut disputer un vrai match il accepte de jouer la revanche...","de":"Obwohl Rocky seinen ersten großen Kampf gegen den Schwergewichts-Weltmeister Apollo Creed nach Punkten verloren hat, sehen ihn die meisten als den wahren Sieger. Und das hat nicht nur positive Auswirkungen auf seine finanzielle Situation, sondern auch auf das private Glück mit seiner Freundin Adrian. Doch Rocky, mit der neuen Situation überfordert, macht viele Fehler. Wieder der Armut nahe bleibt ihm nur eine Möglichkeit - die erneute Herausforderung von Apollo Creed annehmen und diesmal gewinnen. Doch die 15 Runden werden es in sich haben, und Rocky weiss das genau. Doch es geht um die Existenz von ihm ...und seiner Familie."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/vJKa9utvX1kNDCDKYdMDSzCOyX5.jpg","en":"https://image.tmdb.org/t/p/w500/nMaiiu0CzT77U4JZkUYV7KqdAjK.jpg","es":"https://image.tmdb.org/t/p/w500/nMaiiu0CzT77U4JZkUYV7KqdAjK.jpg","fr":"https://image.tmdb.org/t/p/w500/hscESJv9Gy4REpvK4aLV1Ao8dec.jpg","de":"https://image.tmdb.org/t/p/w500/xVu5e62TfXv9FFAflMxeZYm2w50.jpg"}'::jsonb WHERE id = 56;
UPDATE public.films SET tmdb_id = 22, titoli_i18n = '{"fr":"Pirates des Caraïbes : La Malédiction du Black Pearl","es":"Piratas del Caribe: La maldición de la Perla Negra","it":"Pirati dei Caraibi - La maledizione della prima luna","de":"Fluch der Karibik","en":"Pirates of the Caribbean: The Curse of the Black Pearl"}'::jsonb, trame_i18n = '{"fr":"Dans la mer des Caraïbes, au XVIIe siècle, Jack Sparrow, flibustier gentleman, voit sa vie idyllique basculer le jour où son ennemi, le perfide capitaine Barbossa, lui vole son bateau, le Black Pearl, puis attaque la ville de Port Royal, enlevant au passage la très belle fille du gouverneur, Elizabeth Swann. L''ami d''enfance de celle-ci, Will Turner, se joint à Jack pour se lancer aux trousses du capitaine. Mais Will ignore qu''une malédiction frappe Barbossa et ses pirates. Lorsque la lune brille, ils se transforment en morts-vivants. Leur terrible sort ne prendra fin que le jour où le fabuleux trésor qu''ils ont amassé sera restitué…","es":"El aventurero capitán Jack Sparrow recorre las aguas caribeñas. Pero su andanzas terminan cuando su enemigo, el capitán Barbossa le roba su barco, la Perla Negra, y ataca la ciudad de Port Royal, secuestrando a Elizabeth Swann, hija del gobernador. Will Turner, el amigo de la infancia de Elizabeth, se une a Jack para rescatarla y recuperar la Perla Negra. Pero el prometido de Elizabeth, comodoro Norrington, les persigue a bordo del HMS Impávido. Además, Barbossa y su tripulación son víctimas de un conjuro por el que están condenados a vivir eternamente, y a transformarse cada noche en esqueletos vivientes, en fantasmas guerreros.","it":"Caraibi, XVII secolo. La vita del pacifico fabbro Will Turner viene sconvolta quando l''amore della sua vita, Elizabeth Swann, figlia del governatore, viene rapita dal malvagio Capitan Barbossa e dalla sua ciurma di pirati a bordo della misteriosa nave Perla Nera. Per salvarla, Will si allea con l''eccentrico e stravagante pirata Jack Sparrow, ex capitano della Perla Nera desideroso di vendetta. I due scopriranno che Barbossa e i suoi uomini sono colpiti da una terribile maledizione azteca che li condanna a vivere come non-morti, rivelando il loro vero aspetto di scheletri solo sotto la luce della luna.","de":"Im 17.Jahrhundert sucht der Pirat Jack Sparrow nach einem sagenumwobenen Schatz in der Karibik, als ihn das Schicksal mit dem jungen Will Turner zusammenführt, der aus anderen Gründen auf derselben Fährte ist: nämlich den berüchtigten Captain Barbossa und seine Crew abzufangen, die Wills große Liebe Elizabeth, die Tochter des britischen Gouverneurs entführt haben. Doch Barbossa umhüllt selbst ein düsteres Geheimnis: er und seine Männer sind verflucht und das Licht des Mondes bringt ihre Existenz zum Vorschein: sie sind wie lebende Skelette, monströs und tödlich. Um den Fluch zu brechen, brauchen sie Elizabeth als Opfer. Ein Wettrennen zur Insel des Todes beginnt...","en":"When wily pirate Captain Barbossa seizes Jack Sparrow’s beloved ship, the Black Pearl, and kidnaps the governor’s daughter, Elizabeth Swann, blacksmith Will Turner reluctantly teams up with the unpredictable pirate Jack to rescue her—only to uncover a terrifying curse that turns Barbossa’s crew into the undead."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/jFmc6zbnx6mSoxejECYvdi3IHIs.jpg","es":"https://image.tmdb.org/t/p/w500/bVG48kmXuLaZYgPfSCmhs6EYFbX.jpg","it":"https://image.tmdb.org/t/p/w500/r6ISuJLJ5U9MACu8lyCGmdZcHq3.jpg","de":"https://image.tmdb.org/t/p/w500/k150viTPWY84dvtw2GgWE6K1CNV.jpg","en":"https://image.tmdb.org/t/p/w500/poHwCZeWzJCShH7tOjg8RIoyjcw.jpg"}'::jsonb WHERE id = 57;
UPDATE public.films SET tmdb_id = 58, titoli_i18n = '{"it":"Pirati dei Caraibi - La maledizione del forziere fantasma","fr":"Pirates des Caraïbes : Le Secret du coffre maudit","en":"Pirates of the Caribbean: Dead Man''s Chest","es":"Piratas del Caribe: El cofre del hombre muerto","de":"Pirates of the Caribbean - Fluch der Karibik 2"}'::jsonb, trame_i18n = '{"it":"Il capitano Jack Sparrow scopre di avere un debito di sangue con il temibile Davy Jones, sovrano degli abissi e capitano del fantasmagorico Olandese Volante. Se non riuscirà a trovare una via d''uscita, Jack sarà condannato alla servitù eterna nell''equipaggio dei dannati. Per salvarsi, Jack deve rintracciare il leggendario forziere fantasma, contenente il cuore pulsante di Jones, l''unica debolezza del capitano dei mari. Nel frattempo, il matrimonio di Will Turner ed Elizabeth Swann viene interrotto dall''arresto da parte della Compagnia delle Indie Orientali guidata da Lord Cutler Beckett, il quale ricatta Will affinché rintracci Sparrow e si impossessi della sua bussola magica. I destini dei tre protagonisti si intrecciano nuovamente in una pericolosa caccia al tesoro, minacciata dalla mostruosa creatura marina al servizio di Jones: il Kraken.","fr":"Le pirate Jack Sparrow est confronté à son passé. Treize ans auparavant, il signait un pacte avec Davey Jones, le maléfique maître des sept mers. En échange de son âme, ce dernier lui promettait le commandement du mythique Black Pearl… Aujourd’hui, Jones vient donc récupérer sa dette.","en":"Captain Jack Sparrow’s got a blood debt to pay: he owes his soul to the legendary Davy Jones, ghastly Ruler of the Ocean Depths. To escape eternal servitude aboard the Flying Dutchman, ever-crafty Jack must track down the still-beating heart of Jones. But he won’t do it alone: Will Turner and Elizabeth Swann are drawn back into another one of his perilous quests—assuming they can evade execution for aiding a pirate.","es":"Will Turner y Elizabeth Swann se van a casar, pero ambos son hechos prisioneros por Lord Cutler Beckett y acusados de haber liberado al capitán Jack Sparrow. Para salvar su vida, Will tendrá que encontrar a Jack y conseguir su misteriosa brújula. Esta esconde un gran poder, además de la clave de una deuda de sangre del pirata con un temible y siniestro Davy Jones, el legendario capitán del barco fantasma Holandés Errante.","de":"Diesmal sieht sich Captain Jack Sparrow, gerade erst dem Fluch der Black Pearl entkommen, mit einem neuen lebensbedrohenden Abenteuer konfrontiert: Denn Jack steht in lebenslanger Schuld bei Davy Jones, dem legendären Kapitän des Flying Dutchman und Herrscher über die Tiefen des Ozeans. Wenn er keinen Weg findet, den Bann zu brechen, ist er zu einem höllischen Leben nach dem Tode in ewiger Finsternis verdammt. Doch damit nicht genug: Jacks ausgesprochen existenzielle Probleme erweisen sich obendrein als Hindernis für die bevorstehende Hochzeit seiner Freunde Will Turner und Elizabeth Swann, die wider Willen in die andauernden Eskapaden des Kapitäns verwickelt werden. Das Abenteuer kann beginnen ..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/fLHFIx2gJ1vrLnzO7iiBsJdi0Z3.jpg","fr":"https://image.tmdb.org/t/p/w500/bzOlMYEfNmgCDnFHj3zL3RBqwau.jpg","en":"https://image.tmdb.org/t/p/w500/uXEqmloGyP7UXAiphJUu2v2pcuE.jpg","es":"https://image.tmdb.org/t/p/w500/7L7H6sHAt48EfwsqFaa0dw2NJhz.jpg","de":"https://image.tmdb.org/t/p/w500/zvfiQaOqNYvy6qVgWuvK71lv91c.jpg"}'::jsonb WHERE id = 58;
UPDATE public.films SET tmdb_id = 285, titoli_i18n = '{"en":"Pirates of the Caribbean: At World''s End","it":"Pirati dei Caraibi - Ai confini del mondo","es":"Piratas del Caribe: En el fin del mundo","fr":"Pirates des Caraïbes : Jusqu''au bout du monde","de":"Pirates of the Caribbean - Am Ende der Welt"}'::jsonb, trame_i18n = '{"en":"After losing Captain Jack Sparrow to the locker of Davy Jones, Will Turner, Elizabeth Swann, and Captain Barbossa journey to the ends of the earth to rescue him. And as the East India Trading Company tightens its grip on the seas under Lord Cutler Beckett—now in control of Davy Jones—the fate of piracy hangs by a thread. Now, they must unite the pirate lords for one final stand. But as loyalties are tested and alliances shift, each must ultimately choose where they stand in the battle for freedom on the high seas.","it":"Il capitano Barbossa, Will Turner e Elizabeth Swann si alleano per liberare Jack Sparrow dalla prigionia nello Scrigno di Davy Jones. Nel frattempo, la Compagnia delle Indie Orientali, guidata da Lord Cutler Beckett e con il controllo dell''Olandese Volante, minaccia di eliminare per sempre la pirateria dai mari.","es":"Siguiendo la estela de lo sucedido en “Piratas del caribe: el cofre del hombre muerto”, encontramos a nuestros héroes Will Turner y Elizabeth Swann aliados con el capitán Barbossa, en una búsqueda desesperada para liberar al capitán Jack Sparrow de las manos de Davy Jones. Mientras, el terrorífico barco fantasma, el Holandés Errante, bajo el control de la Compañía de las Indias Orientales, causa estragos a lo largo de los Siete Mares. Will y Elizabeth, navegando en medio de la traición, la felonía y mares salvajes, deben seguir adelante rumbo a Singapur y enfrentarse al astuto pirata chino Sao Feng. Ahora, en los mismísimos confines de la tierra, todos ellos deben elegir un bando en la batalla final, ya que no sólo sus vidas y fortunas, sino también el futuro de la piratería clásica, pende de un hilo...","fr":"L’âge d’or de la piraterie touche à sa fin. Même le terrifiant Vaisseau Fantôme et son capitaine maudit servent Lord Cutler Beckett. Il écume désormais les sept mers, massacrant sans pitié les pirates de tous bords. Une seule chance de résister à Beckett et à son armada : Rassembler les Neuf Seigneurs de la Cour des Frères.","de":"Seitdem Cutler Beckett und die East India Trading Company das Herz von Davy Jones besitzen und so über ihn und seine scheinbar unbesiegbare Flying Dutchman gebieten, machen sie erbarmungslos Jagd auf sämtliche Piraten und deren Sympathisanten. Der hohe Rat der Piraten will sich versammeln, um über eine Taktik zu beratschlagen, doch dafür müssen alle Piratenfürsten anwesend sein - auch Captain Jack Sparrow, der nun in der Unterwelt weilt. Seine Freunde Will Turner und Elizabeth Swann machen sich mit Hilfe des wieder zum Leben erweckten Kapitän Barbossa auf die Suche nach dem Ende der Welt, an dem sich der Eingang zur Unterwelt befindet. Dafür benötigen sie die Hilfe des unbarmherzigen Piratenfürsten Sao Feng..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/jGWpG4YhpQwVmjyHEGkxEkeRf0S.jpg","it":"https://image.tmdb.org/t/p/w500/wGv9fox3iIA7jrZxTueQnsKqwoE.jpg","es":"https://image.tmdb.org/t/p/w500/xHcUMez2b1QiMGQYCuQTAlqwDEe.jpg","fr":"https://image.tmdb.org/t/p/w500/3JjceHUzbtgJ4fJs6x2ow4ckH89.jpg","de":"https://image.tmdb.org/t/p/w500/ynZqp6JiraskebRAsd9FgJCT9ww.jpg"}'::jsonb WHERE id = 59;
UPDATE public.films SET tmdb_id = 1865, titoli_i18n = '{"it":"Pirati dei Caraibi - Oltre i confini del mare","es":"Piratas del Caribe: En mareas misteriosas","en":"Pirates of the Caribbean: On Stranger Tides","de":"Pirates of the Caribbean - Fremde Gezeiten","fr":"Pirates des Caraïbes : La Fontaine de jouvence"}'::jsonb, trame_i18n = '{"it":"Jack Sparrow incontra Angelica, una donna del suo passato che lo costringe a imbarcarsi sulla Queen Anne''s Revenge, la nave del temibile pirata Barbanera. Jack si ritrova così coinvolto in una pericolosa ricerca della leggendaria Fonte della Giovinezza, dovendo fare i conti con spietate sirene, zombie e la flotta rivale spagnola e inglese guidata da Barbossa, ora al servizio del Re.","es":"Cuando Jack Sparrow vuelve a encontrarse con una mujer a la que había conocido años atrás, no está seguro de si se trata de amor o si ella es una estafadora sin escrúpulos que lo está utilizando para encontrar la legendaria Fuente de la Juventud. A todo esto, Jack es capturado por el Venganza de la Reina Ana, el barco del temible pirata Barbanegra, que lo obliga a unirse a su tripulación, lo que le hará vivir una inesperada aventura en la que no sabe quién le inspira más miedo si Barbanegra o esa mujer que regresa del pasado.","en":"When Jack crosses paths with a woman from his past, he''s not sure if it''s love...or if she''s a ruthless con artist using him to find the fabled Fountain of Youth.","de":"In Pirates Of The Caribbean – Fremde Gezeiten begegnet Captain Jack Sparrow einer Frau aus seiner Vergangenheit wieder. Angelica heißt die Schöne und Sparrow war in sie verliebt. Oder hat sie ihn nur benutzt? Jedenfalls schickt Angelica den Piraten auf die Suche nach dem sagenumwobenden Jungbrunnen. Dazu muss er an Board der Queen Anne’s Revenge gehen, dem Schiff des gefürchteten Piraten Blackbeards. Captain Jack Sparrow findet sich in Fluch der Karibik 4 wie erwartet in einer abenteuerlichen Geschichte wieder, in der er nicht mehr weiß, wem er vertrauen kann: dem skrupellosen Piraten Blackbeard oder der schönen Frau aus seiner Vergangenheit. Captain Hector Barbossa kann ihm auch nicht wirklich auf die Sprünge helfen, sondern ist eher eine weitere Störung auf der Suche nach dem Jungbrunnen…","fr":"Dans cette histoire pleine d’action, où vérité, trahison, jeunesse éternelle et mort forment un cocktail explosif, le capitaine Jack Sparrow retrouve une femme qu’il a connu autrefois. Leurs liens sont‐ils faits d’amour ou, cette femme n’est‐elle qu’une aventurière sans scrupules qui cherche à l’utiliser pour découvrir la légendaire Fontaine de Jouvence ? Lorsqu’elle l’oblige à embarquer à bord du Queen Anne’s Revenge, le bateau du terrible pirate Barbe‐Noire, Jack ne sait plus ce qu’il doit craindre le plus : Le redoutable maître du bateau ou cette femme surgit de son passé…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/p0aMDd3EtOCfImHIeL9hgPnLRIo.jpg","es":"https://image.tmdb.org/t/p/w500/2oOARbiV871kCC27FyKBmYwOM3G.jpg","en":"https://image.tmdb.org/t/p/w500/keGfSvCmYj7CvdRx36OdVrAEibE.jpg","de":"https://image.tmdb.org/t/p/w500/8jhWZt5N0ZuDS9b4g9NYxq13S9R.jpg","fr":"https://image.tmdb.org/t/p/w500/b7bTneo0DkxTcsGN55OxuPCuZtA.jpg"}'::jsonb WHERE id = 60;
UPDATE public.films SET tmdb_id = 166426, titoli_i18n = '{"it":"Pirati dei Caraibi - La vendetta di Salazar","en":"Pirates of the Caribbean: Dead Men Tell No Tales","es":"Piratas del Caribe: La venganza de Salazar","de":"Pirates of the Caribbean - Salazars Rache","fr":"Pirates des Caraïbes : La Vengeance de Salazar"}'::jsonb, trame_i18n = '{"it":"Il capitano Jack Sparrow si ritrova al centro di una nuova e mortale caccia quando il terrificante capitano Armando Salazar e la sua ciurma di marinai fantasma fuggono dal Triangolo del Diavolo, decisi a sterminare tutti i pirati dei sette mari e a vendicarsi proprio di Jack. L''unica speranza di salvezza per Sparrow risiede nel leggendario Tridente di Poseidone, un potente artefatto capace di conferire il controllo totale sui mari e spezzare ogni maledizione. Per trovarlo, Jack stringe un''alleanza con Henry Turner, un giovane marinaio della Royal Navy intenzionato a liberare suo padre Will dalla maledizione dell''Olandese Volante, e Carina Smyth, una brillante e coraggiosa astronoma ingiustamente accusata di stregoneria.","en":"Thrust into an all-new adventure, a down-on-his-luck Capt. Jack Sparrow feels the winds of ill-fortune blowing even more strongly when deadly ghost sailors led by his old nemesis, the evil Capt. Salazar, escape from the Devil''s Triangle. Jack''s only hope of survival lies in seeking out the legendary Trident of Poseidon, but to find it, he must forge an uneasy alliance with a brilliant and beautiful astronomer and a headstrong young man in the British navy.","es":"El capitán Jack Sparrow se enfrentará a un grupo de piratas-fantasma comandados por una de sus viejas némesis, el terrorífico capitán Salazar, recién escapado del Triángulo de las Bermudas. La única posibilidad de Sparrow para salir con vida es encontrar el legendario Tridente de Poseidón, un poderoso artefacto que le da a su poseedor el control de los mares.","de":"Im neuen Abenteuer gerät Captain Jack Sparrow einmal mehr in große Not, als er auf eine Horde Geister-Piraten trifft, angeführt von Sparrows Nemesis Captain Salazar. Die Untoten sind aus dem Bermuda-Dreieck entkommen, in dem sie gefangen waren, und verfolgen nun nur ein Ziel: Sie wollen alle Piraten töten, zuallererst Jack Sparrow. Dessen einzige Chance liegt nun darin, Poseidons Dreizack zu finden, dessen magische Kräfte die Geister-Piraten erneut bannen können und seinem Besitzer die Kontrolle über die Weltmeere verleihen.","fr":"Jack Sparrow et ses compagnons se lancent dans la quête du Trident de Poséidon, sur lequel le Capitaine Teague détient des informations précieuses. Cet artefact légendaire, qui donne tous les pouvoirs sur les océans, est leur seul moyen d''échapper aux fantômes du redoutable Capitaine Salazar, échappés du Triangle des Bermudes pour éliminer tous les pirates des océans."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/vvglsPQgyGogyTu2e59dJYGlJNE.jpg","en":"https://image.tmdb.org/t/p/w500/6lAPOAFYFWIO3SQRemEY2wInQMC.jpg","es":"https://image.tmdb.org/t/p/w500/AookkwjZfWdigGtaEwy5IfOnBku.jpg","de":"https://image.tmdb.org/t/p/w500/qTyT5kSJ7Jw0iJy7lxyA695XBK8.jpg","fr":"https://image.tmdb.org/t/p/w500/fVMudKQfhosujwgAKhfxNGfS9sL.jpg"}'::jsonb WHERE id = 61;
UPDATE public.films SET tmdb_id = 106646, titoli_i18n = '{"en":"The Wolf of Wall Street","it":"The Wolf of Wall Street","es":"El lobo de Wall Street","fr":"Le Loup de Wall Street","de":"The Wolf of Wall Street"}'::jsonb, trame_i18n = '{"en":"A New York stockbroker refuses to cooperate in a large securities fraud case involving corruption on Wall Street, corporate banking world and mob infiltration. Based on Jordan Belfort''s autobiography.","it":"Jordan Belfort è un giovane e ambizioso broker di New York che fonda la Stratton Oakmont, diventando rapidamente milionario grazie a truffe e speculazioni finanziarie spregiudicate. Immerso in un vortice di edonismo, droga e avidità sfrenata, la sua vita di eccessi attira presto l''attenzione dell''FBI. La sua inarrestabile ascesa nel mondo della finanza rischia così di trasformarsi in una rovinosa e inevitabile caduta.","es":"Película basada en hechos reales del corredor de bolsa neoyorquino Jordan Belfort. A mediados de los años 80, Belfort era un joven honrado que perseguía el sueño americano, pero pronto en la agencia de valores aprendió que lo más importante no era hacer ganar a sus clientes, sino ser ambicioso y ganar una buena comisión. Su enorme éxito y fortuna le valió el mote de \"El lobo de Wall Street\". Dinero. Poder. Mujeres. Drogas. Las tentaciones abundaban y el temor a la ley era irrelevante. Jordan y su manada de lobos consideraban que la discreción era una cualidad anticuada; nunca se conformaban con lo que tenían.","fr":"Sa licence de courtier en poche, et les narines déjà pleines de cocaïne, Jordan Belfort est prêt à conquérir Wall Street. Ce jour d''octobre, un krach, le plus important depuis 1929, vient piétiner ses rêves de grandeur. C''est finalement à Long Island qu''il échoue et qu''il monte sa propre affaire de courtage. Son créneau : le hors-cote. Sa méthode : l''arnaque. Son équipe : des vendeurs ou des petits trafiquants.","de":"New York in den frühen 1990er Jahren. Der aufstrebende Aktienhändler Jordan Belfort gründet mit Anfang 20 die Maklerfirma \"Stratton Oakmont\", mit der er schnell zum Multimillionär aufsteigt und zum Shootingstar der New Yorker Börse wird. Schon bald ist er hauptsächlich unter seinem neuen Spitznamen \"Wolf of Wall Street\" bekannt. Mit seinem Reichtum finanziert er einen ausschweifenden Lebensstil, der von Alkohol, Drogen, Sex und Dekadenz geprägt ist. Jordans Siegeszug scheint nicht zu stoppen zu sein, doch dies lässt ihn übermütig werden. Von unstillbarer Gier getrieben und mit dem Gefühl der Unbesiegbarkeit im Rücken lassen er und seine \"Wolfsbande\", darunter sein Kumpel Donnie Azoff, sich auf illegale Geschäfte ein. Das zieht schon bald die Aufmerksamkeit der Justiz auf sich, besonders der FBI-Agent Patrick Denham schaut aufmerksam hinter die Fassade von Belforts Firmengeflecht. Als die Gesetzeshüter Jordan langsam auf die Schliche kommen, droht sein gesamtes Kartenhaus einzustürzen."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/kW9LmvYHAaS9iA0tHmZVq8hQYoq.jpg","it":"https://image.tmdb.org/t/p/w500/hwg3pXw2m4HfRGbyRMIP8laf5Lf.jpg","es":"https://image.tmdb.org/t/p/w500/uthRoUeTtiep5HCoySlOjQSPCbJ.jpg","fr":"https://image.tmdb.org/t/p/w500/dQIQZbJXn1pflQw3nwvXLJX0dHa.jpg","de":"https://image.tmdb.org/t/p/w500/uuLLAJ9JEJd4o0F9fnJhV1weisr.jpg"}'::jsonb WHERE id = 62;
UPDATE public.films SET tmdb_id = 71066, titoli_i18n = '{"en":"Robin Hood","de":"Robin Hood","fr":"Robin des Bois","es":"Robin de los Bosques","it":"Robin Hood"}'::jsonb, trame_i18n = '{"en":"The dashing Earl of Huntingdon excels in courtly life and jousting before King Richard departs for the Crusades. While away, Richard''s treacherous brother, Prince John, seizes power and inflicts brutal tyranny on the civilians. Huntingdon transforms into the heroic outlaw Robin Hood, gathers his ''merry men'', and battles to restore the true king and protect lovely Lady Marian.","de":"Für seinen Glauben begibt sich König Richard Löwenherz auf einen Kreuzzug. An seiner Stelle soll Prinz John, sein Bruder, das Land regieren. Dieser entpuppt sich als Tyrann, der das Volk unterdrückt und ausbluten lässt. Die schöne Lady Marian schickt eine verzweifelte Nachricht an ihren Geliebten, der mit auf den Kreuzzug gegangen ist. Der Earl of Huntington kehrt zurück und muss mit Entsetzen feststellen, was in seiner Abwesenheit geschehen ist. Um unerkannt zu bleiben, beginnt er als Robin Hood für Gerechtigkeit zu sorgen. Schnell wird er zum Volkshelden, dem die Häscher des Regenten stets dicht auf den Fersen sind.","fr":"Les aventures de Robin des Bois confronté au Prince John. Celui-ci est devenu tyrannique envers son peuple depuis le départ de son père, le Roi Richard.","es":"Ricardo Corazón de León, rey amado y respetado por su pueblo, decide ir a las Cruzadas al frente de su ejército, dejando temporalmente a su hermano, el príncipe Juan (Sam De Grasse), como regente del trono. En ausencia de Ricardo, el príncipe y traicionero Juan gobierna despiadadamente con mano de hierro, convirtiendo Inglaterra en un lugar donde impera la crueldad y la violencia. A está tiranía hará frente el Conde de Huntington, un valiente guerrero que, informado de la situación del país, pondrá en peligro su vida y honor para oponerse al traidor. Por ello, se verá fuera de la ley, teniendo que ejercer como el forajido Robin Hood, campeón de los débiles y oprimidos, que defenderá al pueblo frente al cruel príncipe Juan y tendrá que ocultarse en el bosque de Sherwood.","it":"Il Conte di Huntingdon parte per la Terza Crociata insieme a Re Riccardo Cuor di Leone. Durante la loro assenza, il perfido Principe Giovanni usurpa il trono d''Inghilterra instaurando un regime di terrore ed estorsione ai danni del popolo. Informato delle ingiustizie, il Conte torna in patria sotto le spoglie del fuorilegge Robin Hood e si rifugia nella foresta di Sherwood. Insieme alla sua banda di fedeli compagni, comincia a rubare ai ricchi per dare ai poveri, combattendo il tiranno per proteggere la sua amata Lady Marian e attenderne il ritorno del legittimo re."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg","de":"https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg","fr":"https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg","es":"https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg","it":"https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg"}'::jsonb WHERE id = 63;
UPDATE public.films SET tmdb_id = 10907, titoli_i18n = '{"it":"La leggenda di Robin Hood","fr":"Les Aventures de Robin des Bois","en":"The Adventures of Robin Hood","es":"Robin de los Bosques","de":"Die Abenteuer des Robin Hood"}'::jsonb, trame_i18n = '{"it":"Robin di Locksley, un nobile sassone, si ribella contro l''usurpatore Principe Giovanni, che ha preso il controllo dell''Inghilterra approfittando della prigionia di Re Riccardo Cuor di Leone. Rifugiatosi nella foresta di Sherwood con una banda di fuorilegge, Robin ruba ai ricchi normanni per dare ai poveri sassoni oppressi, conquistando anche il cuore di Lady Marian e lottando per il ritorno del legittimo sovrano.","fr":"Alors que le prince Jean, aidé de son bras droit, l''infâme Guy de Gisbourne, règne sur l''Angleterre, Robin de Loxley proclame sa fidélité à Richard Coeur de Lion, retenu prisonnier en Autriche. Dépossédé de ses biens par le prince Jean, Robin, que l''on nomme désormais Robin des Bois, a formé avec quelques hommes audacieux et courageux une bande de hors-la-loi, qui assaillent et dévalisent sans relâche les hommes du prince. L''attaque d''un convoi d''or conduit par Guy de Gisbourne permet à Robin de nouer de tendres liens avec lady Marian, la filleule du roi Richard, dont les beaux yeux s''ouvrent soudain sur la misère des Saxons et l''arrogance des Normands…","en":"Robin Hood fights nobly for justice against the evil Sir Guy of Gisbourne while striving to win the hand of the beautiful Maid Marian.","es":"Robin de Locksey regresa a Inglaterra tras combatir contra los infieles en las Cruzadas, pero Juan sin Tierra, el hermano del Rey Ricardo I, ha usurpado el trono y gobierna como un tirano, por lo que el noble sajón decide refugiarse en el bosque de Sherwood y luchar contra él para devolverle la corona a Ricardo.","de":"Als Robin von Locksley erfährt, dass Prinz John seinem Bruder Richard Löwenherz den Thron von England rauben will, flieht er in den Sherwood Forest, wo er bald seine Truppe von getreuen Gesetzlosen um sich sammelt, um es John, dem grausamen Guy von Gisbourne und dem Sheriff von Nottingham, heimzuzahlen. Nebenbei bemüht er sich natürlich auch noch um seine Jugendliebe Marian."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ks9KEeASeyeOFDnwbOBW9WDIbfE.jpg","fr":"https://image.tmdb.org/t/p/w500/5wZdLyo6SEV7L1g5gF3VcOIHilM.jpg","en":"https://image.tmdb.org/t/p/w500/c7LX3GMf9uXQTgVm3uxpm7E6Woc.jpg","es":"https://image.tmdb.org/t/p/w500/bCXYN015wb10UTPgXZxcd2RAjBI.jpg","de":"https://image.tmdb.org/t/p/w500/fWXhBHv0HsRYl5j47HbkgWoGe3s.jpg"}'::jsonb WHERE id = 64;
UPDATE public.films SET tmdb_id = 10786, titoli_i18n = '{"fr":"La Rose et la Flèche","de":"Robin und Marian","en":"Robin and Marian","it":"Robin e Marian","es":"Robin y Marian"}'::jsonb, trame_i18n = '{"fr":"Après des années d''exil, Robin des Bois revient avec son fidèle ami Petit Jean à Sherwood. Dame Marianne est entrée au couvent, le Roi Richard et son frère Jean sont devenus fous, le temps de l''aventure semble définitivement terminé pour le valeureux cambrioleur. Mais le shérif de Nottingham revient troubler la paix de Sherwood. Afin de se battre contre l''opression et la terreur qu''inspire le shérif aux habitants, Robin rassemble ses vieux amis.","de":"Um 1190. Seit zwanzig Jahren ziehen Robin Hood und sein treuer Freund Little John für den machtgierigen König Richard Löwenherz auf Kreuzzügen durch die halbe Welt. Als sie in Frankreich eine Burg plündern sollen, in der Richard einen Goldschatz vermutet, die jedoch nur noch von einem Greis, Frauen und Kindern bewohnt wird, weigert sich Robin, den Befehl auszuführen. Der König ist außer sich und befiehlt seine Hinrichtung. Doch bevor es dazu kommen kann, trifft der Greis Richard Löwenherz mit einem Pfeil. Wenige Tage später stirbt er an Wundbrand.","en":"Robin Hood, aging none too gracefully, returns exhausted from the Crusades to woo and win Maid Marian one last time.","it":"Un invecchiato Robin Hood ritorna in Inghilterra dopo vent''anni trascorsi a combattere nelle Crociate al seguito di Re Riccardo. Trova la sua amata Marian che, nel frattempo, si è ritirata in convento diventando badessa. Nonostante il tempo trascorso e le ferite della vita, il loro antico amore si riaccende. Tuttavia, Robin si ritrova ben presto a dover affrontare nuovamente il suo storico avversario, lo Sceriffo di Nottingham, in un ultimo e tragico scontro che segnerà il destino dei due amanti.","es":"Desilusionados por los años que perdieron luchando como cruzados en Tierra Santa, Robin Hood y su amigo Little John regresan a Inglaterra y se dan cuenta de que todo ha vuelto a ser como antes."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/yNSnZAgKFgJ8Qdnf69nUReXJDXk.jpg","de":"https://image.tmdb.org/t/p/w500/vIyA3bNfZj1aThwkGjtyTVUfRA2.jpg","en":"https://image.tmdb.org/t/p/w500/y2UlVt6U8mFeegVL42rZjD5y6c7.jpg","it":"https://image.tmdb.org/t/p/w500/2gTw2pwqUNtdnfWb2elA1HvmmNx.jpg","es":"https://image.tmdb.org/t/p/w500/eRaYiNt0piwfB1LdeUJnMnFcxXs.jpg"}'::jsonb WHERE id = 65;
UPDATE public.films SET tmdb_id = 8367, titoli_i18n = '{"es":"Robin Hood. Príncipe de los ladrones","it":"Robin Hood - Principe dei ladri","de":"Robin Hood - König der Diebe","fr":"Robin des Bois, prince des voleurs","en":"Robin Hood: Prince of Thieves"}'::jsonb, trame_i18n = '{"es":"Robin Hood regresa a su país de origen, cansado tras haber pasado los últimos cinco años luchando en las Cruzadas. A su vuelta se topa con el terror de la población ante el gobierno déspota del hermano Juan del rey Ricardo Corazón de León, un tirano que está en el poder, aprovechando la ausencia de éste. El guerrero, ante esta situación, jura defender a los pobres y para ello se une a las bandas de proscritos que han tomado el bosque de Sherwood como su único hogar libre.","it":"Robin di Locksley ritorna in Inghilterra dopo essere fuggito dalla prigionia a Gerusalemme durante le Crociate. Trova la sua terra natale oppressa dal tirannico Sceriffo di Nottingham, che ha fatto assassinare suo padre. Rifugiatosi nella foresta di Sherwood, Robin si unisce a una banda di fuorileggi e, affiancato dal fedele amico saraceno Azeem, assume la guida della ribellione per sconfiggere lo Sceriffo, salvare la bella Lady Marian e restituire la giustizia al popolo oppresso.","de":"Jerusalem im Jahre 1194: die Kreuzzüge im Heiligen Land haben die Gefängnisse der Stadt mit englischen Rittern gefüllt, unter denen sich auch der junge britische adelige Robin von Locksley befindet. Durch Zufall gelingt ihm gemeinsam mit dem ebenfalls zum Tode verurteilten Azeem die Flucht. Die Beiden machen sich auf den Weg in Robins englische Heimat. Dort angekommen muss Robin feststellen, dass inzwischen der machtgierige Sheriff von Nottingham die Herrschaft über das Land übernommen hat. Er führt ein brutales Regime, unterdrückt die Armen und treibt auf brutale Weise immer höher werdende Steuern ein. Gemeinsam mit den in den Wäldern lebenden Gesetzlosen setzt Robin zum Gegenschlag an: Er formt eine schlagkräftige Truppe aus den Waldbewohnern und kämpft von nun an für Gerechtigkeit und gegen den Sheriff und seine Männer, die das Land tyrannisieren …","fr":"XIIème siècle, en Angleterre. En l''absence du roi Richard, le shérif de Nottingham règne en tyran sur le pays, aidé par son cousin Guy de Gisbourne, la sorcière Mortianna et le corrompu évêque de Hereford. Lors de son retour en Angleterre aux côtés d''Azeem, Robin revient au château de son père. Mais ce dernier a été tué par les hommes du shérif après avoir refusé de se joindre à eux. Robin jure de venger son père.","en":"Nobleman crusader Robin of Locksley breaks out of a Jerusalem prison with the help of Moorish fellow prisoner Azeem and travels back home to England. But upon arrival he discovers his dead father in the ruins of his family estate, killed by the vicious sheriff of Nottingham, Robin and Azeem join forces with outlaws Little John and Will Scarlett to save the kingdom from the sheriff''s villainy."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/b0pJ0SZ9xAEpqo0tx7WOQ9xv8Ns.jpg","it":"https://image.tmdb.org/t/p/w500/2l7W3jvfiVfmpJDPpfJWg2YBGJm.jpg","de":"https://image.tmdb.org/t/p/w500/d48KIeuz1eO56onjHrWx29Oilnr.jpg","fr":"https://image.tmdb.org/t/p/w500/rOdM5PqRLLMjS8DaN5dnsU4b5Fp.jpg","en":"https://image.tmdb.org/t/p/w500/hbRnWUNJkKKVN5mkcuC5ooqjE4e.jpg"}'::jsonb WHERE id = 66;
UPDATE public.films SET tmdb_id = 8005, titoli_i18n = '{"it":"Robin Hood - Un uomo in calzamaglia","en":"Robin Hood: Men in Tights","es":"Las locas, locas aventuras de Robin Hood","de":"Robin Hood - Helden in Strumpfhosen","fr":"Sacré Robin des bois"}'::jsonb, trame_i18n = '{"it":"Tornato in Inghilterra dopo essere fuggito da una prigione a Gerusalemme durante le crociate, il nobile Robin di Locksley trova il suo castello confiscato e il paese sotto il giogo oppressivo del vile principe Giovanni e del goffo sceriffo di Ruttingham. Deciso a ristabilire la giustizia, Robin recluta un improbabile gruppo di fuorilegge nella foresta di Sherwood, gli ''Uomini in calzamaglia''. Tra frecce telecomandate, numeri musicali e situazioni demenziali, Robin tenterà di rovesciare il tiranno e conquistare il cuore della bella Lady Marian, la quale custodisce gelosamente la propria virtù protetta da una quasi indistruttibile cintura di castità.","en":"Robin Hood comes home after fighting in the Crusades to learn that the noble King Richard is in exile and that the despotic King John now rules England, with the help of the Sheriff of Rottingham. Robin Hood assembles a band of fellow patriots to do battle with King John and the Sheriff.","es":"Robin de Loxley es un valiente arquero de la Edad Media que regresa a Inglaterra. El reino está bajo el poder del avaricioso rey Juan, que no hacer más que subir los impuestos a los empodrecidos habitantes.Robin robará a los ricos para dárselo a los pobres, a la ves que vive numerosas aventuras.","de":"Robin von Loxley wird bei den Kreuzzügen unter König Richards Fahne gefangen genommen und ins Verlies gesperrt. Mit Hilfe eines arabischen Mitgefangenen namens El Niesreiz gelingt ihm die Flucht. Beim Abschied verspricht er ihm, sich um dessen Sohn Hatschi zu kümmern, der sich zur als Austauschstudent in England aufhält. Während König Richard auf den Kreuzzügen war, hat sich dessen Bruder, der kaltherzige Prinz John selber zum Alleinherrscher über England ernannt. Mit Unterstützung des skrupellosen Sheriffs von Nuttingham unterdrückt er das arme Volk und beutet es nach Strich und Faden aus. Als Robin zu seinem Schloss zurückkehrt, erfährt von Blinzler dass seine Eltern gestorben sind. Gemeinsam mit Little John und Will stellt er sich den reichen Emporkömmlingen.","fr":"Pendant que le peuple subit l''oppression du prince Jean, Robin des Bois vole aux riches pour donner aux pauvres dans cette parodie du célèbre conte signée Mel Brooks."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zqPpJmTjgTjMwCjCqb4PaAZovom.jpg","en":"https://image.tmdb.org/t/p/w500/woexOLEkUlYsPLLuZRK6LjZaF38.jpg","es":"https://image.tmdb.org/t/p/w500/5Fgy9DD8LMCb6QKzTy18rY7Tts5.jpg","de":"https://image.tmdb.org/t/p/w500/cGLsbxMh8KMiwn3aWnn754ra5do.jpg","fr":"https://image.tmdb.org/t/p/w500/a2zVlgn1AvVjfT6GLsCpFN9T5kj.jpg"}'::jsonb WHERE id = 67;
UPDATE public.films SET tmdb_id = 375588, titoli_i18n = '{"en":"Robin Hood","it":"Robin Hood - L''origine della leggenda","de":"Robin Hood","es":"Robin Hood","fr":"Robin des Bois"}'::jsonb, trame_i18n = '{"en":"A war-hardened Crusader and his Moorish commander mount an audacious revolt against the corrupt English crown.","it":"Tornato in Inghilterra dopo aver combattuto nelle Crociate, il nobile Robin di Loxley scopre che la sua casa è stata confiscata e che la contea di Nottingham è caduta sotto il giogo del corrotto Sceriffo. Insieme a Little John, un comandante moro conosciuto in guerra, Robin decide di combattere le ingiustizie. Addestrato nel combattimento furtivo e nell''uso dell''arco, Robin assume l''identità dell''incappucciato ''Robin Hood'' per rubare il denaro dello Sceriffo, guidare una rivolta popolare e riconquistare il suo amore, Marian.","de":"Robin Hood hat in den Kreuzzügen gekämpft, doch als er in seine Heimat zurückkehrt, erkennt er das Land nicht wieder: England ist zu einer von Korruption und Intrigen gezeichneten Gesellschaft geworden, die Reichen schwelgen in Luxus, während es bei den Armen kaum zum Überleben reicht. Robin beschließt, dass er nicht länger wegschauen kann, und nimmt – ausgerüstet mit Maske, Pfeil und Bogen – den Kampf gegen die Ungerechtigkeit im Land und die tyrannische Oberschicht auf. Dabei findet er mit Little John einen Verbündeten und verliebt sich in die ebenso schöne wie willensstarke Marian. Doch die herrschende Klasse will Robins Raubzüge und seinen Kampf für Gerechtigkeit nicht einfach hinnehmen und setzt den gnadenlosen Sheriff von Nottingham auf ihn an …","es":"Cuando el joven Robin Hood (Taron Egerton) regresa a su hogar, endurecido, tras luchar como guerrero en Las Cruzadas, descubre un reino en el que la corrupción es la moneda de cambio de la corona inglesa. En ese momento, junto a su compañero Little John (Jamie Foxx), toma la decisión de formar una banda de bandidos y liderar una audaz rebelión en la que se enfrentarán al malvado Sheriff de Nottingham (Ben Mendelsohn).","fr":"Récit des débuts de Robin des Bois et de la formation du gang de Sherwood. Robin de Loxley, combattant aguerri revenu des croisades, et un chef maure prennent la tête d’une audacieuse révolte contre la corruption des institutions."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/AiRfixFcfTkNbn2A73qVJPlpkUo.jpg","it":"https://image.tmdb.org/t/p/w500/9kJzfDEl8zVBvNtiqpXZBsS8XDk.jpg","de":"https://image.tmdb.org/t/p/w500/9Cm7Ue54ONtK3sCEoXR4RZyMC75.jpg","es":"https://image.tmdb.org/t/p/w500/tSxcUPAC1ihAtDpAQX2rydOucns.jpg","fr":"https://image.tmdb.org/t/p/w500/tSls6dSMuXz7AHjDuuFvRaNbxHx.jpg"}'::jsonb WHERE id = 68;
UPDATE public.films SET tmdb_id = 20662, titoli_i18n = '{"it":"Robin Hood","de":"Robin Hood","en":"Robin Hood","es":"Robin Hood","fr":"Robin des Bois"}'::jsonb, trame_i18n = '{"it":"Nell''Inghilterra del XIII secolo, dopo la morte di re Riccardo Cuor di Leone, l''arciere Robin Longstride torna in patria dalla Francia. Giunto a Nottingham, assume l''identità del defunto cavaliere Robert Loxley e si innamora della vedova Marion. Di fronte alla minaccia di un''invasione francese e alla tirannia del nuovo re Giovanni, Robin unisce i baroni ribelli e il popolo per difendere il paese, gettando le basi per la nascita della leggenda di Robin Hood.","de":"Nach dem Tode König Richards lässt der begnadete Bogenschütze Robin den Krieg gegen die Franzosen hinter sich und kehrt zurück nach England, in ein durch Korruption und einen brutalen Sheriff gebeuteltes Nottingham. Schnell verliebt er sich in die willensstarke Witwe Lady Marion, die anfangs allerdings überaus skeptisch ist, was ihn und seine Beweggründe angeht. Nicht zuletzt um ihre Hand zu gewinnen, versammelt er eine Truppe Gleichgesinnter und gemeinsam mit seinen Männern macht er dem Sheriff einen Strich durch seine gierige Rechnung und macht jagt auf die Reichen, wobei er die Beute an die Armen verteilt. Doch seine von Jahrzehnten des Krieges geschwächte Heimat hält noch eine weitaus größere Aufgabe für Robin parat. So machen sich ausgerechnet dieser unwahrscheinlichste aller Helden und seine Verbündeten auf, einen blutigen Bürgerkrieg zu verhindern und England wieder zu neuem Ruhm und Glanz zu verhelfen.","en":"When soldier Robin happens upon the dying Robert of Loxley, he promises to return the man''s sword to his family in Nottingham. There, he assumes Robert''s identity; romances his widow, Marion; and draws the ire of the town''s sheriff and King John''s henchman, Godfrey.","es":"Inglaterra, siglo XIII. Robin Longstride, un magnífico arquero al servicio del rey Ricardo Corazón de León, vuelve de las cruzadas en tierra santa saqueando poblados mientras lucha contra las tropas francesas. Cuando Ricardo muere bajo una fecha francesa, Robin se traslada a Nottingham con el objetivo de cumplir una promesa que hizo a Sir Robert Loxley antes de morir: devolver una espada a su padre, Sir Walter Loxley. Allí conoce a lady Marion, su viuda, una mujer con carácter. Mientras tanto, en un país debilitado por una larga guerra, regido por Juan, un rey débil y poco eficaz, contra las rebeliones internas y las amenazas externas maquinadas por el pérfido Godfrey, Robin y sus hombres se dejan llevar hacia una aventura mayor: deciden ayudar a impedir que el país caiga irremediablemente en una sangrienta guerra civil, y devolver la gloria a Inglaterra.","fr":"À l’aube du treizième siècle, Robin Longstride, humble archer au service de la Couronne d’Angleterre, assiste, en Normandie, à la mort de son monarque, Richard Cœur de Lion, tout juste rentré de la Troisième Croisade et venu défendre son royaume contre les Français. De retour en Angleterre et alors que le prince Jean, frère cadet de Richard et aussi inepte à gouverner qu’obnubilé par son enrichissement personnel, prend possession du trône, Robin se rend à Nottingham où il découvre l’étendue de la corruption qui ronge son pays. Il se heurte au despotique shérif du comté, mais trouve une alliée et une amante en la personne de la belle et impétueuse Lady Marianne, qui avait quelques raisons de douter des motifs et de l’identité de ce croisé venu des bois."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/dXIFYV8PR8WS5nnxspSFnMdZIGZ.jpg","de":"https://image.tmdb.org/t/p/w500/3u492UeXuQMFDTOrHenpLOMwb6t.jpg","en":"https://image.tmdb.org/t/p/w500/9NS5QGOfck24yL3bZqWeW06PgPC.jpg","es":"https://image.tmdb.org/t/p/w500/8jI4VDUWPVM4I91xBhObCLMQhnM.jpg","fr":"https://image.tmdb.org/t/p/w500/77ibaylBuzhqfFBKQ2qStQUeLyM.jpg"}'::jsonb WHERE id = 69;
UPDATE public.films SET tmdb_id = 1891, titoli_i18n = '{"it":"Star Wars: Episodio V - L''Impero colpisce ancora","es":"El imperio contraataca","en":"The Empire Strikes Back","fr":"L''Empire contre-attaque","de":"Das Imperium schlägt zurück"}'::jsonb, trame_i18n = '{"it":"Mentre l''Impero contrattacca duramente contro l''Alleanza Ribelle, Luke Skywalker inizia l''addestramento Jedi sotto la guida del maestro Yoda. Nel frattempo, i suoi amici vengono braccati da Darth Vader attraverso la galassia.","es":"Tras un ataque sorpresa de las tropas imperiales a las bases camufladas de la alianza rebelde, Luke Skywalker, en compañía de R2D2, parte hacia el planeta Dagobah en busca de Yoda, el último maestro Jedi, para que le enseñe los secretos de la Fuerza. Mientras, Han Solo, la princesa Leia, Chewbacca, y C3PO esquivan a las fuerzas imperiales y piden refugio al antiguo propietario del Halcón Milenario, Lando Calrissian, en la ciudad minera de Bespin, donde les prepara una trampa urdida por Darth Vader.","en":"The epic saga continues as Luke Skywalker, in hopes of defeating the evil Galactic Empire, learns the ways of the Jedi from aging master Yoda. But Darth Vader is more determined than ever to capture Luke. Meanwhile, rebel leader Princess Leia, cocky Han Solo, Chewbacca, and droids C-3PO and R2-D2 are thrown into various stages of capture, betrayal and despair.","fr":"Malgré la destruction de l’Étoile Noire, l''Empire maintient son emprise sur la galaxie, et poursuit sans relâche sa lutte contre l''Alliance rebelle. Basés sur la planète glacée de Hoth, les rebelles essuient un assaut des troupes impériales. Parvenus à s''échapper, la princesse Leia, Han Solo, Chewbacca et C-3P0 se dirigent vers Bespin, la cité des nuages gouvernée par Lando Calrissian, ancien compagnon de Han. Suivant les instructions d''Obi-Wan Kenobi, Luke Skywalker se rend quant à lui vers le système de Dagobah, planète marécageuse où il doit recevoir l''enseignement du dernier maître Jedi, Yoda. Apprenant l''arrestation de ses compagnons par les stormtroopers de Dark Vador après la trahison de Lando, Luke décide d''interrompre son entraînement pour porter secours à ses amis et affronter le sombre seigneur Sith...","de":"Nach der Zerstörung des Todessterns geht der Kampf zwischen den Rebellen und dem herrschenden Imperium weiter. Die Rebellen haben sich auf den Eisplaneten Hoth zurückgezogen, doch das Imperium spürt sie auf und zerstört nach hartem Kampf die dortige Basis. Daraufhin teilen sich unsere Freunde auf: Luke gerät mit R2-D2 auf den Sumpfplaneten Dagobah, wo er von dem alten Jedi-Meister Yoda eine Ausbildung im Umgang mit der Macht erhält, während Leia, Han Solo und die anderen sich nach Bespin durchschlagen, wo in einer Wolkenstadt ein alter Freund von Han residiert. Doch dort geraten sie in eine Falle des Imperiums, und Luke muß ihnen zu Hilfe kommen und Darth Vader zu einem Duell herausfordern..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/6vzDHECuUbKiqSSXHcIKb9LPcQs.jpg","es":"https://image.tmdb.org/t/p/w500/eU7KcNAOeZj9PBIcGUMSsuJz8qj.jpg","en":"https://image.tmdb.org/t/p/w500/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg","fr":"https://image.tmdb.org/t/p/w500/qDvctAykmNWAmi9G2GrVrwWx3pr.jpg","de":"https://image.tmdb.org/t/p/w500/mi08uIh7ZqYlJEMrc5l2986geSU.jpg"}'::jsonb WHERE id = 71;
UPDATE public.films SET tmdb_id = 1892, titoli_i18n = '{"it":"Star Wars: Episodio VI - Il ritorno dello Jedi","en":"Return of the Jedi","es":"El retorno del Jedi","de":"Die Rückkehr der Jedi-Ritter","fr":"Le Retour du Jedi"}'::jsonb, trame_i18n = '{"it":"I Ribelli intraprendono una missione decisiva per distruggere la seconda Morte Nera e sconfiggere l''Imperatore. Luke affronta per l''ultima volta Darth Vader nel tentativo di redimere il padre caduto nel Lato Oscuro.","en":"Luke Skywalker leads a mission to rescue his friend Han Solo from the clutches of Jabba the Hutt, the Emperor prepares to crush the Rebellion with a more powerful Death Star, and the Rebel fleet mounts a massive attack on the space station. Luke Skywalker confronts Darth Vader in a final climactic duel before the evil Emperor.","es":"Luke Skywalker y la princesa Leia deben viajar a Tatooine para liberar a Han Solo. Para conseguirlo, deben infiltrarse en la peligrosa guarida de Jabba the Hutt, el gángster más temido de la galaxia. Una vez reunidos, el equipo recluta a tribus de Ewoks para combatir a las fuerzas imperiales en los bosques de la luna de Endor. Mientras tanto, el Emperador y Darth Vader conspiran para convertir a Luke al lado oscuro, pero el joven Skywalker, por su parte, está decidido a reavivar el espíritu del Jedi en su padre. La guerra civil galáctica culmina en un último enfrentamiento entre las fuerzas rebeldes unificadas y una segunda Estrella de la Muerte, indefensa e incompleta, en una batalla que decidirá el destino de la galaxia.","de":"Wesen aus allen Ecken der Galaxis treffen die Vorbereitungen für die entscheidende Schlacht gegen die Streitkräfte des Imperiums. Ziel der Aktion ist die totale Zerstörung des zweiten Todessterns, dessen unvorstellbare Feuerkraft ganze Planeten vernichten kann. Inzwischen ist Han Solo immer noch in der Wüstenfestung des mächtigsten und skrupellosesten Verbechers des Universums, Jabba the Hutt, gefangen. Luke Skywalker gelingt es schließlich zusammen mit seinen Gefährten Prinzessin Leia, Chewbacca und Lando Calrissian, sowie den beiden Robotern C3PO und R2D2 mit Han zu fliehen. Aber Luke steht die schwerste Prüfung noch bevor: Während auf dem Waldmond Endor und beim Todesstern die alles entscheidende Schlacht entbrennt, muß er sich seinem Erzfeind Darth Vader zu einem Zweikampf auf Leben und Tod stellen...","fr":"L''Empire galactique est plus puissant que jamais : la construction de la nouvelle arme, l’Étoile de la Mort, menace l''univers tout entier... Arrêté après la trahison de Lando Calrissian, Han Solo est remis à l''ignoble contrebandier Jabba Le Hutt par le chasseur de primes Boba Fett. Après l''échec d''une première tentative d''évasion menée par la princesse Leia, également arrêtée par Jabba, Luke Skywalker et Lando parviennent à libérer leurs amis. Han, Leia, Chewbacca, C-3PO et Luke, devenu un Jedi, s''envolent dès lors pour une mission d''extrême importance sur la lune forestière d''Endor, afin de détruire le générateur du bouclier de l’Étoile de la Mort et permettre une attaque des pilotes de l''Alliance rebelle. Conscient d''être un danger pour ses compagnons, Luke préfère se rendre aux mains de Dark Vador, son père et ancien Jedi passé du côté obscur de la Force."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/rMcCqpaWEUBmATmpZilDTKOyVbL.jpg","en":"https://image.tmdb.org/t/p/w500/jQYlydvHm3kUix1f8prMucrplhm.jpg","es":"https://image.tmdb.org/t/p/w500/rKMmXzdm7eRgmlwYo7iq3klT7wJ.jpg","de":"https://image.tmdb.org/t/p/w500/xwwbeCWW1jMSDPfRPJp8X4oySPr.jpg","fr":"https://image.tmdb.org/t/p/w500/tEQlCGiiWvMvfD7Sz8d99Pouy39.jpg"}'::jsonb WHERE id = 72;
UPDATE public.films SET tmdb_id = 1893, titoli_i18n = '{"it":"Star Wars: Episodio I - La minaccia fantasma","es":"La guerra de las galaxias. Episodio I: La amenaza fantasma","en":"Star Wars: Episode I - The Phantom Menace","de":"Star Wars: Episode I - Die dunkle Bedrohung","fr":"Star Wars, épisode I - La Menace fantôme"}'::jsonb, trame_i18n = '{"it":"Due cavalieri Jedi scoprono il giovane e straordinariamente dotato Anakin Skywalker mentre tentano di sventare l''invasione del pacifico pianeta Naboo. Nel frattempo, una minaccia creduta estinta da millenni, i Sith, fa la sua ricomparsa.","es":"La Federación de Comercio ha bloqueado el pequeño planeta de Naboo, gobernado por la joven Reina Amidala, como parte de un plan ideado por Sith Darth Sidious, que manteniéndose en el anonimato dirige a los neimoidianos, que están al mando de la Federación. Amidala es convencida por los Jedis Qui-Gon Jinn y su aprendiz, o padawan, Obi-Wan Kenobi a viajar hasta Coruscant, capital de la República y sede del Consejo Jedi para intentar mediar esta amenaza. Pero esquivando el bloqueo, la nave real resulta dañada, obligando a la tripulación a aterrizar en el desértico y remoto planeta de Tatooine...","en":"Anakin Skywalker, a young slave strong with the Force, is discovered on Tatooine. Meanwhile, the evil Sith have returned, enacting their plot for revenge against the Jedi.","de":"Nachdem der friedliche Planet Naboo von der Handelsföderation angegriffen wurde, müssen die Jedi-Ritter Qui-Gon Jinn und Obi-Wan Kenobi gemeinsam mit Königin Amidala auf dem Wüstenplaneten Tatooine notlanden. Dort bekommen sie Hilfe von Anakin Skywalker, einem Sklavenjungen, in dem die Macht ungewöhnlich stark ist. Als es Königin Amidala nicht gelingt, den Senat gegen die Handelsföderation zu mobilisieren, kehrt sie mit den Jedi-Rittern und Anakin nach Naboo zurück, um den Kampf allein fortzusetzen. Eine gewaltige Schlacht beginnt!","fr":"Il y a bien longtemps, dans une galaxie très lointaine... La République connaît de nombreux tourments : la corruption fait vaciller ses bases, le Sénat s''embourbe dans des discussions politiques sans fin et de nombreux pouvoirs dissidents commencent à émerger, annonçant la chute d''un système autrefois paisible. Puissante et intouchable, la Fédération du Commerce impose par la force la taxation des routes commerciales. Refusant de céder, la pacifique planète Naboo, dirigée par la jeune Reine Amidala, subit un blocus militaire de la Fédération. Dépêchés par le Sénat pour régler cette affaire, les chevaliers Jedi Qui-Gon Jinn et Obi-Wan Kenobi découvrent qu''une véritable offensive de la Fédération est imminente. Libérant la Reine et ses proches, ils quittent la planète mais doivent se poser sur Tatooine pour réparer leur vaisseau..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/iHitEFiK8udC0GcsWUU6szWzc5K.jpg","es":"https://image.tmdb.org/t/p/w500/4rjatbWmGGmu0DZs6WNpXaUWqWN.jpg","en":"https://image.tmdb.org/t/p/w500/6wkfovpn7Eq8dYNKaG5PY3q2oq6.jpg","de":"https://image.tmdb.org/t/p/w500/4e0X8XDjgLu3H2iKiCz44WEl7dA.jpg","fr":"https://image.tmdb.org/t/p/w500/fpEC910v5DrMvZteRNlKzXeHiHY.jpg"}'::jsonb WHERE id = 73;
UPDATE public.films SET tmdb_id = 1894, titoli_i18n = '{"en":"Star Wars: Episode II - Attack of the Clones","de":"Star Wars: Episode II - Angriff der Klonkrieger","es":"La guerra de las galaxias. Episodio II: El ataque de los clones","fr":"Star Wars, épisode II - L''Attaque des clones","it":"Star Wars: Episodio II - L''attacco dei cloni"}'::jsonb, trame_i18n = '{"en":"Following an assassination attempt on Senator Padmé Amidala, Jedi Knights Anakin Skywalker and Obi-Wan Kenobi investigate a mysterious plot into the heart of the Separatist movement and the beginning of the Clone Wars.","de":"Der junge Jedi-Schüler Anakin Skywalker beginnt sich allmählich zu einem grossen und ernstzunehmenden Jediritter zu entwickeln, der unter der Führung von Obi Wan-Kenobi steht. Jedoch hat er auch seine Problemzonen - diese bestehen aus der eigenen Arroganz, seiner nicht wissentlich vorhandenen grenzenlosen Macht, und der ihm verbotenen Liebe zu Königin Amidala. Auf diese werden kurz vor wichtigen Entscheidungen im Senat der Republik mehrere Attentate verübt, die jedoch vereitelt werden können. Daraufhin teilen sich Anakin und Obi-Wan auf: während Anakin auf Amidala aufpaßt, verfolgt Kenobi den Attentäter Jango Fett. Er kommt einer erschaffenen Klon-Armee auf die Spur, die mittels mysteriösem Auftrag geschaffen wurde und findet in dem ehemaligen Jedi Count Dooku einen neuen Gegner für die Hüter der Macht...","es":"Corren tenebrosos tiempos para la República. Ésta continúa envuelta en luchas y sumida en el caos. Un movimiento separatista, formado por centenares de planetas y poderosas alianzas y y lideradas por el misterioso conde Dooku, abre nuevas amenazas para la galaxia, a la que ni siquiera los Jedi parecen poder poner freno. Estas maniobras, planeadas hace mucho por una poderosa fuerza, conducen al estallido de las guerras clones y al principio del fin de la República. Para allanar el camino, los separatistas intentan asesinar a la senadora Padme Amidala. Para evitar futuros atentados, su seguridad es encomendada a dos caballeros Jedi...","fr":"Depuis le blocus de la planète Naboo par la Fédération du commerce, la République, gouvernée par le Chancelier Palpatine, connaît une véritable crise. Un groupe de dissidents, mené par le sombre Jedi comte Dooku, manifeste son mécontentement envers le fonctionnement du régime. Le Sénat et la population intergalactique se montrent pour leur part inquiets face à l''émergence d''une telle menace.Certains sénateurs demandent à ce que la République soit dotée d''une solide armée pour empêcher que la situation ne se détériore davantage. Parallèlement, Padmé Amidala, devenue sénatrice, est menacée par les séparatistes et échappe de justesse à un attentat. Le Padawan Anakin Skywalker est chargé de sa protection. Son maître, Obi-Wan Kenobi, part enquêter sur cette tentative de meurtre et découvre la constitution d''une mystérieuse armée de clones...","it":"Anakin Skywalker, ormai cresciuto, viene incaricato di proteggere la senatrice Padmé Amidala da una serie di attentati, mentre tra i due sboccia un amore proibito. Nel frattempo, Obi-Wan Kenobi scopre la creazione di un misterioso esercito di cloni pronto a combattere i separatisti."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/oZNPzxqM2s5DyVWab09NTQScDQt.jpg","de":"https://image.tmdb.org/t/p/w500/q090XcaB783cXdRBOU9TfsmGGP8.jpg","es":"https://image.tmdb.org/t/p/w500/pwwBIUqVSWrCBuUAvbaNdf7VajF.jpg","fr":"https://image.tmdb.org/t/p/w500/3nqpcTkODCBhuKuDQJ1dtRhgTqZ.jpg","it":"https://image.tmdb.org/t/p/w500/zW4eR9utiKPnTHcIP4xuy0t09nT.jpg"}'::jsonb WHERE id = 74;
UPDATE public.films SET tmdb_id = 1895, titoli_i18n = '{"it":"Star Wars: Episodio III - La vendetta dei Sith","en":"Star Wars: Episode III - Revenge of the Sith","fr":"Star Wars, épisode III - La Revanche des Sith","es":"La guerra de las galaxias. Episodio III: La venganza de los Sith","de":"Star Wars: Episode III - Die Rache der Sith"}'::jsonb, trame_i18n = '{"it":"Le Guerre dei Cloni giungono al termine e il Cancelliere Palpatine seduce Anakin con le promesse del Lato Oscuro. Traditi i Jedi, la Repubblica crolla, dando vita al tirannico Impero Galattico e alla nascita di Darth Vader.","en":"When the sinister Sith unveil a thousand-year-old plot to rule the galaxy, the Republic crumbles and from its ashes rises the evil Galactic Empire. Jedi hero Anakin Skywalker must choose a side.","fr":"La Guerre des Clones fait rage. Une franche hostilité oppose désormais le Chancelier Palpatine au Conseil Jedi. Anakin Skywalker, jeune Chevalier Jedi pris entre deux feux, hésite sur la conduite à tenir. Séduit par la promesse d''un pouvoir sans précédent, tenté par le côté obscur de la Force, il prête allégeance au maléfique Darth Sidious et devient Dark Vador. Les Seigneurs Sith s''unissent alors pour préparer leur revanche, qui commence par l''extermination des Jedi. Seuls rescapés du massacre, Yoda et Obi-Wan se lancent à la poursuite des Sith. La traque se conclut par un spectaculaire combat au sabre entre Anakin et Obi-Wan, qui décidera du sort de la galaxie…","es":"Último capítulo de la saga de Star Wars, en el que Anakin Skywalker definitivamente se pasa al lado oscuro. En el Episodio III aparecerá el General Grievous, un ser implacable mitad-alien mitad-robot, el líder del ejército separatista Droid. Los Sith son los amos del lado oscuro de la Fuerza y los enemigos de los Jedi. Ellos fueron prácticamente exterminados por los Jedi hace mil años, pero la orden del mal sobrevivió en la clandestinidad.","de":"Nach drei Jahren nähern sich die Klonkriege endlich dem Ende. Um die Separatisten endgültig zu besiegen, soll Obi-Wan Kenobi ihren Anführer General Grevious und Count Dooku ihrer gerechten Strafe zuführen. Zur Beunruhigung der schwangeren Padme nutzt daheim der endgültig vom Bösen korrumpierte Kanzler Palpatine die Gelegenheit, um den jungen Anakin Skywalker mit Versprechungen von unbegrenzter Macht auf die dunkle Seite zu ziehen. Ratlos und hin- und hergerissen wem er dienen soll, erliegt er geblendet von deren Machtverheißungen, den Versuchungen der dunklen Seite, schwört dem bösen Darth Sidious die Treue und nimmt die Identität von Darth Vader an. Die Sith-Lords beginnen zusammen einen Rachefeldzug, der in der Ermordung der Jedi seinen Anfang nimmt..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/jM5jU9JzxnyE8CXqiOpc2ZPIbEd.jpg","en":"https://image.tmdb.org/t/p/w500/xfSAoBEm9MNBjmlNcDYLvLSMlnq.jpg","fr":"https://image.tmdb.org/t/p/w500/2RcBuU8cdxFxCJibbiYCGNLApfz.jpg","es":"https://image.tmdb.org/t/p/w500/5dj0ERxM8NxoiWBdlY6TT9PJmKi.jpg","de":"https://image.tmdb.org/t/p/w500/kW3v2VS0kRvMTS6atR4MzjrzxAP.jpg"}'::jsonb WHERE id = 75;
UPDATE public.films SET tmdb_id = 140607, titoli_i18n = '{"it":"Star Wars: Il risveglio della Forza","es":"Star Wars: El despertar de la fuerza","de":"Star Wars: Das Erwachen der Macht","en":"Star Wars: The Force Awakens","fr":"Star Wars : Le Réveil de la Force"}'::jsonb, trame_i18n = '{"it":"Trent''anni dopo la caduta dell''Impero, sorge una nuova minaccia nota come Primo Ordine guidata da Kylo Ren. Una giovane orfana di nome Rey scopre la sua potente connessione con la Forza e parte alla ricerca dello scomparso Luke Skywalker.","es":"Treinta años después de la victoria de la Alianza Rebelde sobre la segunda Estrella de la Muerte, la galaxia está todavía en guerra. Una nueva República se ha constituido, pero una siniestra organización, la Primera Orden, ha resurgido de las cenizas del Imperio Galáctico. A los héroes de antaño, que luchan ahora en la Resistencia, se suman nuevos héroes: Poe Dameron, un piloto de caza, Finn, un desertor de la Primera Orden, Rey, una joven chatarrera, y BB-8, un androide rodante. Todos ellos luchan contra las fuerzas del Mal: el Capitán Phasma, de la Primera Orden, y Kylo Ren, un temible y misterioso personaje que empuña un sable de luz roja.","de":"Über 30 Jahre sind vergangen, seitdem die Rebellen den zweiten Todesstern über Endor zerstört und damit die entscheidende Schlacht gegen die finsteren Mächte des Imperiums gewonnen haben. Doch aus der Asche des Bösen ist die Erste Ordnung empor gestiegen und hat die Herrschaft wieder an sich gerissen. Während Supreme Leader Snoke die Zügel im Hintergrund in den Händen hält, schickt er den Lichtschwert schwingenden Kylo Ren ins Feld, um die neue Weltordnung auch in den verstecktesten Winkeln der Galaxis zu verbreiten. Von großer Politik aber weiß Rey auf dem Wüstenplaneten Jakku zunächst nicht viel. Die junge Frau verbringt ihre Tage damit, die karge Landschaft nach Schrott abzusuchen, den sie danach verkauft. Sie ist allein, wartet auf ihre Familie – bis sie die Bekanntschaft von Finn macht, einem ehemaligen Sturmtruppler, den die Untaten der Ersten Ordnung abgeschreckt haben.","en":"Thirty years after defeating the Galactic Empire, Han Solo and his allies face a new threat from the evil Kylo Ren and his army of Stormtroopers.","fr":"Il y a bien longtemps, dans une galaxie lointaine… Luke Skywalker est porté disparu. Le pilote Poe est en mission secrète sur une planète pour le retrouver. Au moment où la diabolique armée \"Premier Ordre\" apparaît en détruisant tout sur son passage, il arrive à cacher la position géographique de l''ancien maître Jedi dans son droïde BB-8. Capturé par les larbins du machiavélique Kylo Ren, Poe est libéré par le soldat ennemi Finn qui est en pleine crise existentielle. Pendant ce temps, BB-8 est recueillie par Rey, une pilleuse d''épaves qui sera bientôt plongée dans une quête qui la dépasse."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/uEDFRwKiTOsIsN5dkEPCj1laIAK.jpg","es":"https://image.tmdb.org/t/p/w500/vI86GLIkT5pP3ZfNs2EvmTrBLBm.jpg","de":"https://image.tmdb.org/t/p/w500/6EyJ3fxzjDr0Ly4i4u9VD8sja1N.jpg","en":"https://image.tmdb.org/t/p/w500/wqnLdwVXoBjKibFRR5U3y0aDUhs.jpg","fr":"https://image.tmdb.org/t/p/w500/zKZ1iF1ABqL7a16u6Im8JTQKp7H.jpg"}'::jsonb WHERE id = 76;
UPDATE public.films SET tmdb_id = 181808, titoli_i18n = '{"it":"Star Wars: Gli ultimi Jedi","fr":"Star Wars : Les Derniers Jedi","en":"Star Wars: The Last Jedi","de":"Star Wars: Die letzten Jedi","es":"Star Wars: Los últimos Jedi"}'::jsonb, trame_i18n = '{"it":"Rey sviluppa le sue abilità con l''aiuto di un riluttante Luke Skywalker, tormentato dagli errori passati. Nel frattempo, la Resistenza è sull''orlo dell''annientamento totale sotto il fuoco implacabile della flotta del Primo Ordine.","fr":"Le Premier Ordre étend ses tentacules aux confins de l’univers, poussant la Résistance dans ses retranchements. Il est impossible de se sauver à la vitesse de la lumière avec cet ennemi continuellement aux trousses. Cela n’empêche pas Finn et ses camarades de tenter d’identifier une brèche chez leur adversaire. Pendant ce temps, Rey se trouve toujours sur la planète Ahch‐To pour convaincre Luke Skywalker de lui enseigner les rudiments de la Force.","en":"Rey develops her newly discovered abilities with the guidance of Luke Skywalker, who is unsettled by the strength of her powers. Meanwhile, the Resistance prepares to do battle with the First Order.","de":"Die planetenvernichtende Starkiller-Basis der Ersten Ordnung ist zwar zerstört, die Neue Republik nach der vorherigen Zerstörung von fünf Welten aber massiv geschwächt. Sie steht am Abgrund und wird nur noch von Generalin Leias Widerstand verteidigt, für den auch Pilot Poe Dameron und der desertierte Ex-Sturmtruppler Finn kämpfen. Rey, mit den Erfahrungen ihres ersten großen Abenteuers in den Knochen, geht unterdessen bei Luke Skywalker auf dem Inselplaneten Ahch-To in die Lehre. Luke ist der letzte Jedi, der letzte Vertreter des Ordens, auf dem die Hoffnung ruht, dass Frieden in der Galaxis einkehrt. Doch die Erste Ordnung wirft ihren Schatten auch auf Luke und Rey: Der verlorene, ehemalige Schützling des alten Meisters, Kylo Ren, hat die finstere Mission noch längst nicht beendet, die ihm der sinistere Strippenzieher Snoke auftrug ...","es":"La malvada Primera Orden se ha vuelto más poderosa y tiene contra las cuerdas a la Resistencia, liderada por la General Leia Organa. El piloto Poe Dameron encabeza una misión para intentar destruir un acorazado de la Primera Orden. Mientras tanto, la joven Rey tendrá que definir su futuro y su vocación, y el viejo jedi Luke Skywalker revaluar el significado de su vida."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/8qOzSPUWlBGfteuKFWJJTRpiFxI.jpg","fr":"https://image.tmdb.org/t/p/w500/prV3qBW4CqFsH14CEQNslnwvqWi.jpg","en":"https://image.tmdb.org/t/p/w500/kOVEVeg59E0wsnXmF9nrh6OmWII.jpg","de":"https://image.tmdb.org/t/p/w500/6LyUrFO0i5AgpWVQlAQyA01Euhy.jpg","es":"https://image.tmdb.org/t/p/w500/7SNzh1fY3YJ8Y8MX93pZF5cJHaH.jpg"}'::jsonb WHERE id = 77;
UPDATE public.films SET tmdb_id = 181812, titoli_i18n = '{"it":"Star Wars: L''ascesa di Skywalker","fr":"Star Wars : L''Ascension de Skywalker","es":"Star Wars: El ascenso de Skywalker","en":"Star Wars: The Rise of Skywalker","de":"Star Wars: Der Aufstieg Skywalkers"}'::jsonb, trame_i18n = '{"it":"Un anno dopo gli eventi de ''Gli ultimi Jedi'', i sopravvissuti della Resistenza affrontano ancora una volta il Primo Ordine. Rey, Finn e Poe Dameron guidano la battaglia finale contro il Leader Supremo Kylo Ren e il redivivo Imperatore Palpatine, giungendo alla conclusione della storica saga degli Skywalker.","fr":"Environ un an après la mort de Luke Skywalker, la Résistance tente de survivre face au Premier Ordre, désormais mené par un nouveau Suprême Leader, Kylo Ren. Une rumeur agite cependant toute la galaxie : l''Empereur Palpatine serait de retour. Tandis que Rey s''entraîne sous la houlette de la générale Leia Organa, Kylo Ren cherche à défier Palpatine, qu''il considère comme une menace à son pouvoir.","es":"Los restos de la Resistencia se enfrentan una vez más a la Primera Orden, involucrando conflictos del pasado y del presente. Mientras tanto, el antiguo conflicto entre los Jedi y los Sith llegará a su clímax, lo que llevará a la saga de los Skywalker a un final definitivo.","en":"The surviving Resistance faces the First Order once again as the journey of Rey, Finn and Poe Dameron continues. With the power and knowledge of generations behind them, the final battle begins.","de":"Etwa ein Jahr, nachdem der letzte Rest des Widerstands durch Luke Skywalkers Opfertat aus dem Griff der Ersten Ordnung entkommen konnte, kämpfen die völlig unterlegenen Rebellen aus dem Hinterhalt gegen Kylo Ren und dessen Truppen. Zum ersten Mal gehen dabei die neuen Helden Rey, Finn und der Super-Pilot Poe gemeinsam auf eine lange Mission ..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/3drtqLOARQEuFgEmGRlMlWpV3Eb.jpg","fr":"https://image.tmdb.org/t/p/w500/1pQc75SdFOKpo2AqoL58z5kF3YI.jpg","es":"https://image.tmdb.org/t/p/w500/oeQxq6If4DcW6ADIYCF9SQwKov.jpg","en":"https://image.tmdb.org/t/p/w500/db32LaOibwEliAmSL2jjDF6oDdj.jpg","de":"https://image.tmdb.org/t/p/w500/dAk1ClViS20eUEjfxjeknceMBi7.jpg"}'::jsonb WHERE id = 78;
UPDATE public.films SET tmdb_id = 11, titoli_i18n = '{"it":"Guerre stellari: Episodio IV - Una nuova speranza","es":"La guerra de las galaxias","fr":"La Guerre des étoiles","en":"Star Wars","de":"Krieg der Sterne"}'::jsonb, trame_i18n = '{"it":"Il giovane Luke Skywalker entra in possesso di droidi contenenti i piani segreti della Morte Nera, la potente arma dell''Impero Galattico. Guidato dal saggio maestro Jedi Obi-Wan Kenobi e affiancato dal contrabbandiere Han Solo, Luke intraprende un''audace missione per salvare la Principessa Leila. Insieme, guideranno l''Alleanza Ribelle nel disperato tentativo di distruggere la stazione imperiale.","es":"La princesa Leia, líder del movimiento rebelde que desea reinstaurar la República en la galaxia en los tiempos ominosos del Imperio, es capturada por las malévolas Fuerzas Imperiales, capitaneadas por el implacable Darth Vader, el sirviente más fiel del emperador. El intrépido Luke Skywalker, ayudado por Han Solo, capitán de la nave espacial \"El Halcón Milenario\", y los androides, R2D2 y C3PO, serán los encargados de luchar contra el enemigo y rescatar a la princesa para volver a instaurar la justicia en el seno de la Galaxia.","fr":"Il y a bien longtemps, dans une galaxie très lointaine... La guerre civile fait rage entre l''Empire galactique et l''Alliance rebelle. Capturée par les troupes de choc de l''Empereur menées par le sombre et impitoyable Dark Vador, la princesse Leia Organa dissimule les plans de l’Étoile Noire, une station spatiale invulnérable, à son droïde R2-D2 avec pour mission de les remettre au Jedi Obi-Wan Kenobi. Accompagné de son fidèle compagnon, le droïde de protocole C-3PO, R2-D2 s''échoue sur la planète Tatooine et termine sa quête chez le jeune Luke Skywalker. Rêvant de devenir pilote mais confiné aux travaux de la ferme, ce dernier se lance à la recherche de ce mystérieux Obi-Wan Kenobi, devenu ermite au cœur des montagnes désertiques de Tatooine...","en":"Princess Leia is captured and held hostage by the evil Imperial forces in their effort to take over the galactic Empire. Venturesome Luke Skywalker and dashing captain Han Solo team together with the loveable robot duo R2-D2 and C-3PO to rescue the beautiful princess and restore peace and justice in the Empire.","de":"Seit der Vernichtung der Jedi-Ritter steht die Galaxie unter der grausamen Herrschaft des Imperiums. Nur eine kleine Gruppe von Rebellen, angeführt von der schönen Prinzessin Leia, widersetzt sich der dunklen Macht. Als es ihnen gelingt, die geheimen Baupläne für den gefährlichen Todesstern zu entwenden, gerät das Imperium in Aufruhr. Durch Zufall gelangen die Pläne ausgerechnet in die Hände des Farmerjungen Luke Skywalker, der spürt, dass er sein bisheriges Leben hinter sich lassen muss. Gemeinsam mit dem weisen Obi-Wan Kenobi, den Weltraumabenteurern Han Solo und Chewbacca sowie den Droiden R2-D2 und C-3PO nimmt er den Kampf gegen das mächtige Imperium auf. Es beginnt ein Wettlauf gegen die Zeit, denn der Kampfstern kann nur vor seiner Fertigstellung zerstört werden..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/fVqKwpvobwWy0P1UImZWIDuw4RI.jpg","es":"https://image.tmdb.org/t/p/w500/4hOUzmButYUeON0prG3RpbqS7ag.jpg","fr":"https://image.tmdb.org/t/p/w500/rLi9cokiFU20mLUPvQ0IRok3ELY.jpg","en":"https://image.tmdb.org/t/p/w500/fai0rspsNeJCS69wHNjOdWxcI7P.jpg","de":"https://image.tmdb.org/t/p/w500/crUUE14AROxNWsMdmyyqZNcUB6L.jpg"}'::jsonb WHERE id = 79;
UPDATE public.films SET tmdb_id = 1891, titoli_i18n = '{"en":"The Empire Strikes Back","it":"Guerre stellari: Episodio V - L''Impero colpisce ancora","fr":"L''Empire contre-attaque","es":"El imperio contraataca","de":"Das Imperium schlägt zurück"}'::jsonb, trame_i18n = '{"en":"The epic saga continues as Luke Skywalker, in hopes of defeating the evil Galactic Empire, learns the ways of the Jedi from aging master Yoda. But Darth Vader is more determined than ever to capture Luke. Meanwhile, rebel leader Princess Leia, cocky Han Solo, Chewbacca, and droids C-3PO and R2-D2 are thrown into various stages of capture, betrayal and despair.","it":"Dopo la distruzione della Morte Nera, le forze imperiali inseguono implacabilmente i Ribelli attraverso la galassia. Mentre Han Solo e Leila sfuggono alla flotta nemica rifugiandosi nella Città delle Nuvole, Luke si reca sul pianeta Dagobah per addestrarsi con il maestro Yoda. Lo scontro imminente con Dart Fener porterà alla luce una sconvolgente verità sul suo passato.","fr":"Malgré la destruction de l’Étoile Noire, l''Empire maintient son emprise sur la galaxie, et poursuit sans relâche sa lutte contre l''Alliance rebelle. Basés sur la planète glacée de Hoth, les rebelles essuient un assaut des troupes impériales. Parvenus à s''échapper, la princesse Leia, Han Solo, Chewbacca et C-3P0 se dirigent vers Bespin, la cité des nuages gouvernée par Lando Calrissian, ancien compagnon de Han. Suivant les instructions d''Obi-Wan Kenobi, Luke Skywalker se rend quant à lui vers le système de Dagobah, planète marécageuse où il doit recevoir l''enseignement du dernier maître Jedi, Yoda. Apprenant l''arrestation de ses compagnons par les stormtroopers de Dark Vador après la trahison de Lando, Luke décide d''interrompre son entraînement pour porter secours à ses amis et affronter le sombre seigneur Sith...","es":"Tras un ataque sorpresa de las tropas imperiales a las bases camufladas de la alianza rebelde, Luke Skywalker, en compañía de R2D2, parte hacia el planeta Dagobah en busca de Yoda, el último maestro Jedi, para que le enseñe los secretos de la Fuerza. Mientras, Han Solo, la princesa Leia, Chewbacca, y C3PO esquivan a las fuerzas imperiales y piden refugio al antiguo propietario del Halcón Milenario, Lando Calrissian, en la ciudad minera de Bespin, donde les prepara una trampa urdida por Darth Vader.","de":"Nach der Zerstörung des Todessterns geht der Kampf zwischen den Rebellen und dem herrschenden Imperium weiter. Die Rebellen haben sich auf den Eisplaneten Hoth zurückgezogen, doch das Imperium spürt sie auf und zerstört nach hartem Kampf die dortige Basis. Daraufhin teilen sich unsere Freunde auf: Luke gerät mit R2-D2 auf den Sumpfplaneten Dagobah, wo er von dem alten Jedi-Meister Yoda eine Ausbildung im Umgang mit der Macht erhält, während Leia, Han Solo und die anderen sich nach Bespin durchschlagen, wo in einer Wolkenstadt ein alter Freund von Han residiert. Doch dort geraten sie in eine Falle des Imperiums, und Luke muß ihnen zu Hilfe kommen und Darth Vader zu einem Duell herausfordern..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg","it":"https://image.tmdb.org/t/p/w500/6vzDHECuUbKiqSSXHcIKb9LPcQs.jpg","fr":"https://image.tmdb.org/t/p/w500/qDvctAykmNWAmi9G2GrVrwWx3pr.jpg","es":"https://image.tmdb.org/t/p/w500/eU7KcNAOeZj9PBIcGUMSsuJz8qj.jpg","de":"https://image.tmdb.org/t/p/w500/mi08uIh7ZqYlJEMrc5l2986geSU.jpg"}'::jsonb WHERE id = 80;
UPDATE public.films SET tmdb_id = 1892, titoli_i18n = '{"it":"Guerre stellari: Episodio VI - Il ritorno dello Jedi","es":"El retorno del Jedi","en":"Return of the Jedi","de":"Die Rückkehr der Jedi-Ritter","fr":"Le Retour du Jedi"}'::jsonb, trame_i18n = '{"it":"Luke Skywalker e i suoi compagni salvano Han Solo dalla fortezza del malvagio Jabba the Hutt prima di affrontare la minaccia definitiva dell''Impero. I Ribelli pianificano un attacco coordinato contro una seconda e più potente Morte Nera in costruzione nei pressi della luna boscosa di Endor. Nel frattempo, Luke deve confrontarsi direttamente con l''Imperatore Palpatine e tentare di redimere suo padre Dart Fener.","es":"Luke Skywalker y la princesa Leia deben viajar a Tatooine para liberar a Han Solo. Para conseguirlo, deben infiltrarse en la peligrosa guarida de Jabba the Hutt, el gángster más temido de la galaxia. Una vez reunidos, el equipo recluta a tribus de Ewoks para combatir a las fuerzas imperiales en los bosques de la luna de Endor. Mientras tanto, el Emperador y Darth Vader conspiran para convertir a Luke al lado oscuro, pero el joven Skywalker, por su parte, está decidido a reavivar el espíritu del Jedi en su padre. La guerra civil galáctica culmina en un último enfrentamiento entre las fuerzas rebeldes unificadas y una segunda Estrella de la Muerte, indefensa e incompleta, en una batalla que decidirá el destino de la galaxia.","en":"Luke Skywalker leads a mission to rescue his friend Han Solo from the clutches of Jabba the Hutt, the Emperor prepares to crush the Rebellion with a more powerful Death Star, and the Rebel fleet mounts a massive attack on the space station. Luke Skywalker confronts Darth Vader in a final climactic duel before the evil Emperor.","de":"Wesen aus allen Ecken der Galaxis treffen die Vorbereitungen für die entscheidende Schlacht gegen die Streitkräfte des Imperiums. Ziel der Aktion ist die totale Zerstörung des zweiten Todessterns, dessen unvorstellbare Feuerkraft ganze Planeten vernichten kann. Inzwischen ist Han Solo immer noch in der Wüstenfestung des mächtigsten und skrupellosesten Verbechers des Universums, Jabba the Hutt, gefangen. Luke Skywalker gelingt es schließlich zusammen mit seinen Gefährten Prinzessin Leia, Chewbacca und Lando Calrissian, sowie den beiden Robotern C3PO und R2D2 mit Han zu fliehen. Aber Luke steht die schwerste Prüfung noch bevor: Während auf dem Waldmond Endor und beim Todesstern die alles entscheidende Schlacht entbrennt, muß er sich seinem Erzfeind Darth Vader zu einem Zweikampf auf Leben und Tod stellen...","fr":"L''Empire galactique est plus puissant que jamais : la construction de la nouvelle arme, l’Étoile de la Mort, menace l''univers tout entier... Arrêté après la trahison de Lando Calrissian, Han Solo est remis à l''ignoble contrebandier Jabba Le Hutt par le chasseur de primes Boba Fett. Après l''échec d''une première tentative d''évasion menée par la princesse Leia, également arrêtée par Jabba, Luke Skywalker et Lando parviennent à libérer leurs amis. Han, Leia, Chewbacca, C-3PO et Luke, devenu un Jedi, s''envolent dès lors pour une mission d''extrême importance sur la lune forestière d''Endor, afin de détruire le générateur du bouclier de l’Étoile de la Mort et permettre une attaque des pilotes de l''Alliance rebelle. Conscient d''être un danger pour ses compagnons, Luke préfère se rendre aux mains de Dark Vador, son père et ancien Jedi passé du côté obscur de la Force."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/rMcCqpaWEUBmATmpZilDTKOyVbL.jpg","es":"https://image.tmdb.org/t/p/w500/rKMmXzdm7eRgmlwYo7iq3klT7wJ.jpg","en":"https://image.tmdb.org/t/p/w500/jQYlydvHm3kUix1f8prMucrplhm.jpg","de":"https://image.tmdb.org/t/p/w500/xwwbeCWW1jMSDPfRPJp8X4oySPr.jpg","fr":"https://image.tmdb.org/t/p/w500/tEQlCGiiWvMvfD7Sz8d99Pouy39.jpg"}'::jsonb WHERE id = 81;
UPDATE public.films SET tmdb_id = 36670, titoli_i18n = '{"en":"Never Say Never Again","es":"Nunca digas nunca jamás","de":"Sag niemals nie","it":"Mai dire mai","fr":"Jamais plus jamais"}'::jsonb, trame_i18n = '{"en":"James Bond returns as the secret agent 007 to battle the evil organization SPECTRE. Bond must defeat Largo, who has stolen two atomic warheads for nuclear blackmail. But Bond has an ally in Largo''s girlfriend, the willowy Domino, who falls for Bond and seeks revenge.","es":"La temible organización criminal Spectra ha ideado un ingenioso plan que le permite conseguir dos proyectiles nucleares, los cuales harán estallar si el gobierno no cede a su chantaje. El agente 007 se encargará del caso.","de":"Von einem Nato-Stützpunkt in England werden auf spektakuläre Weise zwei Atomraketen gestohlen. Als die Nato damit erpresst werden soll, schicken die Briten ihren Topagenten James Bond, um die nukleare Bedrohung abzuwenden, und die Gangster dingfest zu machen.","it":"James Bond, ormai vicino all''età pensionabile e mandato in una clinica per rimettersi in forma, scopre una cospirazione ordita dall''organizzazione criminale SPECTRE. Guidato dal malvagio Maximilian Largo sotto gli ordini di Ernst Stavro Blofeld, il gruppo riesce a rubare due testate nucleari cruise della NATO per ricattare il mondo. L''agente 007 viene richiamato in servizio d''urgenza da M e si mette sulle tracce delle armi, scontrandosi con la letale assassina Fatima Blush e cercando di conquistare la fiducia della bellissima Domino Petachi, amante di Largo, per sventare l''olocausto nucleare.","fr":"M, le chef des services secrets britanniques, n''aime pas les méthodes expéditives de James Bond, au contraire de son prédécesseur. De plus, il le trouve en petite forme, à l''issue des tests qu''il lui a fait subir. C''est ainsi que Bond a été \"poignardé\" par la fille d''un milliardaire qu''il venait de tirer des griffes de révolutionnaires qui l''avaient enlevée. Le résultat de cette simulation conduit M à envoyer Bond dans la clinique de Shrublands, non loin de Londres, pour s''y refaire une santé et éliminer ses toxines. Là, entre deux jus de céleri et une tisane au persil, il surprend, une nuit, une lutte entre Jack Petachi, un officier américain, et son infirmière, la troublante Fatima Blush. La jeune femme, membre du Spectre, a pour mission de surveiller Petachi dont l''œil droit a été opéré, de manière à en faire la réplique exacte de celui du Président. Élément clé d''une opération baptisée \"Les larmes d''Allah\"."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/zhoAL4o1STGgLbLxJ9r1ijfyHC9.jpg","es":"https://image.tmdb.org/t/p/w500/iLfAIRwbd14HihotsomoVZbIt2K.jpg","de":"https://image.tmdb.org/t/p/w500/im3FnMct3LKIqzYdQqKMR3tkKKX.jpg","it":"https://image.tmdb.org/t/p/w500/lyPIv08a0VPrJxpGu5pvyUE0bB3.jpg","fr":"https://image.tmdb.org/t/p/w500/j8fcChPA88YlLdXMryDQwNPngPI.jpg"}'::jsonb WHERE id = 82;
UPDATE public.films SET tmdb_id = 157336, titoli_i18n = '{"es":"Interstellar","en":"Interstellar","fr":"Interstellar","de":"Interstellar","it":"Interstellar"}'::jsonb, trame_i18n = '{"es":"Un grupo de exploradores hacen uso de un agujero de gusano recientemente descubierto para superar las limitaciones de los viajes espaciales tripulados y vencer las inmensas distancias que tiene un viaje interestelar.","en":"The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.","fr":"Dans un futur proche, face à une Terre exsangue, un groupe d’explorateurs utilise un vaisseau interstellaire pour franchir un trou de ver permettant de parcourir des distances jusque‐là infranchissables. Leur but : trouver un nouveau foyer pour l’humanité.","de":"Was Wissenschaftler, Politiker und Aktivisten seit Jahrzehnten prophezeien, ist eingetreten: Die Menschheit steht kurz davor, an einer globalen Nahrungsknappheit zugrunde zu gehen. Die einzige Hoffnung der Weltbevölkerung besteht in einem geheimen Projekt der US-Regierung, das von dem findigen Wissenschaftler Professor Brand geleitet wird. Der Plan sieht vor, eine Expedition in ein anderes Sternensystem zu starten, wo bewohnbare Planeten, Rohstoffe und vor allem Leben vermutet werden. Der Ingenieur und ehemalige NASA-Pilot Cooper und Brands Tochter Amelia führen die Besatzung an, die sich auf eine Reise ins Ungewisse begibt: Wurmlöcher sind so gut wie unerforscht und niemand kann mit Sicherheit sagen, was die Crew auf der anderen Seite erwartet. Ebenso ist unsicher, ob und wann Cooper und Brand wieder auf die Erde zurückkehren. Coopers Kinder, Tochter Murph und Sohn Tom, müssen mit Schwiegervater Donald zurückbleiben und auf seine Wiederkehr hoffen...","it":"In un futuro non lontano, un''inarrestabile piaga sta distruggendo i raccolti terrestri, condannando l''umanità alla fame. Un gruppo di esploratori e scienziati, guidati dall''ex pilota della NASA Cooper, intraprende una missione interstellare attraverso un wormhole recentemente scoperto nei pressi di Saturno, nel disperato tentativo di trovare un nuovo pianeta abitabile per salvare la specie umana."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/d1QKiYtceF3GDtxvTFXFAqwwah9.jpg","en":"https://image.tmdb.org/t/p/w500/yQvGrMoipbRoddT0ZR8tPoR7NfX.jpg","fr":"https://image.tmdb.org/t/p/w500/1pnigkWWy8W032o9TKDneBa3eVK.jpg","de":"https://image.tmdb.org/t/p/w500/hHdhfkkzt0Mwec33Ux177Z7CO8w.jpg","it":"https://image.tmdb.org/t/p/w500/bMKiLh0mES4Uiococ240lbbTGXQ.jpg"}'::jsonb WHERE id = 83;
UPDATE public.films SET tmdb_id = 25237, titoli_i18n = '{"en":"Come and See","it":"Va'' e vedi","de":"Komm und sieh","fr":"Requiem pour un massacre","es":"Masacre (Ven y mira)"}'::jsonb, trame_i18n = '{"en":"The invasion of a village in Belarus by German forces sends young Flyora into the forest to join the weary Resistance fighters, against his family''s wishes. There he meets a girl, Glasha, who accompanies him back to his village. On returning home, Flyora finds his family and fellow peasants massacred. His continued survival amidst the brutal debris of war becomes increasingly nightmarish, a battle between despair and hope.","it":"Durante la seconda guerra mondiale, nella Bielorussia del 1943 occupata dalle forze naziste, il giovane Florya decide di unirsi alla resistenza partigiana contro l''invasore. Attraverso il suo tragico viaggio, il ragazzo sarà testimone diretto delle atrocità più disumane, dei massacri sistematici dei villaggi e della devastazione psicologica e fisica causata dalla guerra, perdendo prematuramente la propria innocenza in un crescendo di orrore.","de":"Weißrußland, 1943. Der 14jährige Fljora schließt sich gegen den Protest seiner Mutter den Partisanen an. Für ihn ist der Krieg noch ein Kinderspiel. Als es in den Kampf geht, darf er nicht mit an die Front. Fljora soll statt dessen mit Alten und Kindern ein Reservelager einrichten. Der Junge fühlt sich alleingelassen. In den Wäldern trifft er auf das Mädchen Glascha, die Geliebte des Partisanenführers. Fljora versucht sie zu trösten, als die Hölle über beide hereinbricht: Sie sind in einen Angriff der deutschen Wehrmacht geraten! Nur knapp können die beiden dem Tod entrinnen. Aber die Schrecken haben noch kein Ende…","fr":"Pendant la Seconde Guerre mondiale, Fliora, jeune garçon d''un village de Biélorussie occupé par les troupes nazies, s''engage, bien que trop jeune, chez les partisans. Il va découvrir l''amour, la fraternité, la souffrance, la guerre.","es":"Tras encontrar un viejo rifle, un joven se une a las fuerzas de la resistencia soviética, que lucha por expulsar a las fuerzas nazis del frente oriental. Allí, será testigo de algunos los mayores horrores cometidos en la Segunda Guerra Mundial."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/qNbMsKVzigERgJUbwf8pKyZogpb.jpg","it":"https://image.tmdb.org/t/p/w500/nGTKjc3PDPz7WcsdEAI7U0iVIjo.jpg","de":"https://image.tmdb.org/t/p/w500/6QTr0ljSaBVYN4T865QtQDzpdbQ.jpg","fr":"https://image.tmdb.org/t/p/w500/aT7fV0q7mbsN0HCrcC41NeYQoCU.jpg","es":"https://image.tmdb.org/t/p/w500/j2hzNkmwYT184eP9qYdjViiYxCO.jpg"}'::jsonb WHERE id = 84;
UPDATE public.films SET tmdb_id = 62, titoli_i18n = '{"en":"2001: A Space Odyssey","fr":"2001 : L''Odyssée de l''espace","de":"2001: Odyssee im Weltraum","es":"2001. Una odisea del espacio","it":"2001: Odissea nello spazio"}'::jsonb, trame_i18n = '{"en":"Humanity finds a mysterious object buried beneath the lunar surface and sets off to find its origins with the help of HAL 9000, the world''s most advanced super computer.","fr":"Aux temps préhistoriques, une petite tribu d’hommes‐singes installée au milieu de rochers arides lutte difficilement pour la vie. Un matin, ils trouvent devant eux une mystérieuse dalle noire monolithique. L’un des singes touche la pierre et apprend alors à se servir d’un os de quadrupède pour tuer ses ennemis. Quatre millions d’années plus tard, en 2001, un savant de l’espace, le Dr Heywood Floyd, débarque sur la lune pour examiner une dalle noire semblable à celle des singes, qui était enterrée sous la surface de l’astre. Selon les premières observations, l’objet émettrait un signal mystérieux…","de":"Als im Jahr 2001 ein Monolith auf dem Mond entdeckt wird, wird diese Entdeckung als der Beweis für außerirdisches Leben gedeutet. Eineinhalb Jahre nach der Entdeckung des Monoliths werden 2 Astronauten, Bowman und Poole, mit dem Raumschiff Discovery zum Jupiter geschickt, um weitere Erkenntnisse zu gewinnen. Das Raumschiff ist mit dem Supercomputer HAL-9000 ausgerüstet. Bald ergeben sich erste Komplikationen mit dem Computer...","es":"Mientras investigan la aparición de misteriosos monolitos en el universo, dos astronautas luchan contra la inteligencia artificial de su nave.","it":"Un misterioso monolite nero guida ed influenza i passaggi chiave dell''evoluzione umana dalla preistoria al futuro. Nel 2001, una missione spaziale diretta verso Giove a bordo della Discovery One entra in rotta di collisione con la propria intelligenza artificiale, l''infallibile e inquietante computer HAL 9000."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/ve72VxNqjGM69Uky4WTo2bK6rfq.jpg","fr":"https://image.tmdb.org/t/p/w500/uwd79G32FPIL5B9UkRgSZvS0gbe.jpg","de":"https://image.tmdb.org/t/p/w500/g16ONGwG7l3R94JFPKCx1orZvYD.jpg","es":"https://image.tmdb.org/t/p/w500/pGabanxaE2YvN4jhZuSN3oXO0mi.jpg","it":"https://image.tmdb.org/t/p/w500/uvSRVMXGHaCeYAj2pCYNdC31b2u.jpg"}'::jsonb WHERE id = 85;
UPDATE public.films SET tmdb_id = 1368, titoli_i18n = '{"it":"Rambo","en":"First Blood","de":"Rambo","fr":"Rambo","es":"Acorralado"}'::jsonb, trame_i18n = '{"it":"John Rambo, un reduce della guerra del Vietnam psicologicamente segnato, arriva in una piccola città alla ricerca di un vecchio amico. Ingiustamente perseguitato dallo sceriffo locale, Rambo si rifugia nei boschi scatenando una caccia all''uomo senza tregua.","en":"When former Green Beret John Rambo is harassed by local law enforcement and arrested for vagrancy, he is forced to flee into the mountains and wage an escalating one-man war against his pursuers.","de":"John Rambo, ein vom Krieg verstörter Vietnamveteran, irrt trampend durch die Vereinigten Staaten. Unterwegs gerät er an den bösartigen Sheriff Teasle, der ihn ohne Grund in Haft nimmt. Als Rambo in der Zelle von den Cops misshandelt wird, dreht er durch, und flüchtet in den Wald. Jetzt haben die Provinzbullen endlich einen Grund, ihn zu jagen. Doch da haben sie sich den falschen ausgesucht…","fr":"Après la guerre du Viêt Nam à l''issue humiliante pour les États Unis, les vétérans envoyés au combat et salués en héros par l''Amérique de Kennedy sûrs de leur bon droit, pour retrouver une Amérique hippie et moralisatrice sous Johnson et les traités d''assassins, sont laissés pour compte, devenus des indésirables qu''il faut cacher, enfermer. John Rambo est l''un d''eux, médaillé par le Congrès, dernier survivant d''un commando des Bérets Verts. Il est arrêté à Hope, une petite ville par le shérif Will Teasle pour vagabondage parce qu''il voulait trouver un restaurant pour s''alimenter. Jeté en cellule, maltraité, battu par les hommes du shérif, il se défend en appliquant ce qui lui a permis de survivre à la guerre, mets ces hommes à terre et s''évade du commissariat. La chasse à l’homme contre Rambo commence...","es":"John Rambo es un veterano de la guerra de Vietnam que sufre de estrés postraumático. Un día, llega a un pequeño pueblo de Oregón, donde el sheriff Will Teasle le detiene por vagabundear. Rambo logra escapar de la comisaría y se refugia en el bosque, donde usa sus habilidades de supervivencia y combate para enfrentarse a los policías que le persiguen. El coronel Samuel Trautman, el antiguo jefe de Rambo, llega al pueblo para intentar negociar con él y evitar una masacre. Rambo tendrá que luchar contra sus propios demonios y contra las fuerzas del orden que le quieren capturar o matar."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/dff9LLsvZWA6fKDlVkWeayK04od.jpg","en":"https://image.tmdb.org/t/p/w500/a9sa6ERZCpplbPEO7OMWE763CLD.jpg","de":"https://image.tmdb.org/t/p/w500/hJWuFpjvMuz9kDuoSFMnLPTg7Vm.jpg","fr":"https://image.tmdb.org/t/p/w500/gjb4xVMld19M5IS4EmgVeX7HuHv.jpg","es":"https://image.tmdb.org/t/p/w500/sYHRcd9p3rV3t3w8MHGaA7wdIBl.jpg"}'::jsonb WHERE id = 86;
UPDATE public.films SET tmdb_id = 1369, titoli_i18n = '{"it":"Rambo 2 - La vendetta","es":"Rambo: Acorralado Parte II","en":"Rambo: First Blood Part II","fr":"Rambo II : La Mission","de":"Rambo II - Der Auftrag"}'::jsonb, trame_i18n = '{"it":"Fatto uscire di prigione per una missione ricognitiva in Vietnam, Rambo ha il compito di fotografare un campo di prigionieri americani. Violando gli ordini ricevuti, il veterano decide di intervenire per liberarli affrontando le forze nemiche.","es":"Rambo es excarcelado y enviado de vuelta al Vietnam con una nueva misión: averiguar el paradero de unos soldados norteamericanos desaparecidos. Tras saltar en paracaídas en la jungla, portando únicamente un cuchillo y un arco con flechas, se le dice que no ataque al enemigo y que sólo haga fotografías de reconocimiento. Pero el plan no saldrá como estaba previsto.","en":"John Rambo is released from prison by the government for a top-secret covert mission to the last place on Earth he''d want to return - the jungles of Vietnam.","fr":"John Rambo purge une peine de prison lorsque le Colonel Trautman lui donne la possibilité de sortir pour une mission délicate : avoir la preuve qu''il reste bel et bien des prisonniers américains au Vietnam.Supposé n''être qu''un observateur, Rambo désobéit aux ordres et tente de sauver un prisonnier. Murdock, le responsable de la mission, décide alors de l''abandonner en territoire ennemi, Rambo, seul, sans armes et face à l''ennemi, prépare sa vengeance et son retour au pays.","de":"John Rambo wird von seinem alten Freund Col. Trautman aus dem Gefängnis geholt – doch nicht ohne Hintergedanken. Der Einzelkämpfer soll nach Vietnam zurückkehren, wo auch zehn Jahre nach Kriegsende immer noch amerikanische Soldaten gefangen gehalten werden. Rambo soll ein mögliches Gefangenenlager auskundschaften. Doch der Einsatz läuft gar nicht nach Plan und bald findet sich Rambo nur mit einem Messer und der Vietnamesin Co Bao im tiefsten Dschungel wieder um alleine den Kampf zu gewinnen, den Amerika vor einem Jahrzehnt verloren hat."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/mRV0Ac9EJuMRsEso9fBbJr4lExZ.jpg","es":"https://image.tmdb.org/t/p/w500/dUWHNWzrmCSTIj9zdI5b3HeO0o5.jpg","en":"https://image.tmdb.org/t/p/w500/fVwRtWqEPdsCH21BVDGqgkAQcff.jpg","fr":"https://image.tmdb.org/t/p/w500/jPMoYbpY8faABzeE8dRAfprlfTW.jpg","de":"https://image.tmdb.org/t/p/w500/sJ3Hl3M6JsNFktzxxcWmQyh8GUh.jpg"}'::jsonb WHERE id = 87;
UPDATE public.films SET tmdb_id = 1370, titoli_i18n = '{"it":"Rambo III","es":"Rambo III","en":"Rambo III","fr":"Rambo III","de":"Rambo III"}'::jsonb, trame_i18n = '{"it":"Ritiratosi in un monastero in Thailandia, Rambo viene a sapere che il suo ex comandante Trautman è stato catturato dai sovietici in Afghanistan. L''ex berretto verde parte da solo per un''audace missione di salvataggio nel territorio nemico.","es":"Cuando descubre que el coronel Trautman ha caído en manos soviéticas en Afganistán, Rambo regresa al servicio para intentar liberar a su amigo. Después de contactar a la resistencia afgana, entra en la zona sitiada por las tropas enemigas.","en":"Combat has taken its toll on Rambo, but he''s finally begun to find inner peace in a monastery. When Rambo''s friend and mentor Col. Trautman asks for his help on a top secret mission to Afghanistan, Rambo declines but must reconsider when Trautman is captured.","fr":"Le Colonel Trautman contacte Rambo dans sa retraite en Thaïlande pour qu''il l''accompagne dans une mission périlleuse en Afghanistan. Mais l''ex-soldat refuse afin de se consacrer aux moines bouddhistes qui l''ont recueilli. Lorsque, quelques jours plus tard, l''agent Griggs lui explique que Trautman a été capturé par le Colonel Zaysen, Rambo décide de sauver son ami. Il s''infiltre dans les lignes ennemies et découvre toute l''horreur du conflit qui oppose les moudjahidin à l''armée soviétique. Déterminé, il s''attaque à toute une armée sans oublier son objectif premier : récupérer Trautman.","de":"Colonel Trautman bittet seinen alten Freund John Rambo, der sich mittlerweile aus seinem tödlichen Geschäft zurückgezogen hat, um einen Gefallen: Er soll ihn bei einem Einsatz hinter sowjetischen Linien in Afganistan zur Seite stehen. Rambo lehnt zunächst ab, doch als Trautman gefangengenommen wird, eilt er natürlich zu dessen Rettung flugs hinter her…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/1eSQvGuD25ezKaiaQsyDDG3e9iN.jpg","es":"https://image.tmdb.org/t/p/w500/1eSQvGuD25ezKaiaQsyDDG3e9iN.jpg","en":"https://image.tmdb.org/t/p/w500/1eSQvGuD25ezKaiaQsyDDG3e9iN.jpg","fr":"https://image.tmdb.org/t/p/w500/gCZktvZDPltMyad4UsCZYNCIW7F.jpg","de":"https://image.tmdb.org/t/p/w500/6BjMW2tLVizIpF57RQXv4EDE73T.jpg"}'::jsonb WHERE id = 88;
UPDATE public.films SET tmdb_id = 7555, titoli_i18n = '{"it":"John Rambo","en":"Rambo","fr":"John Rambo","es":"John Rambo","de":"John Rambo"}'::jsonb, trame_i18n = '{"it":"Rambo vive isolato nel nord della Thailandia finché un gruppo di missionari non lo ingaggia per guidarli in Birmania. Quando i missionari vengono catturati dalle truppe militari locali, il veterano guida un gruppo di mercenari in una sanguinosa operazione di recupero.","en":"In Thailand, ex-Green Beret John James Rambo joins a group of mercenaries to venture into war-torn neighboring Myanmar to rescue a group of Christian aid workers who have been kidnapped by a ruthless local infantry unit.","fr":"John Rambo s''est retiré dans le nord de la Thaïlande, où il mène une existence simple dans les montagnes et se tient à l''écart de la guerre civile qui fait rage non loin de là, sur la frontière entre la Thaïlande et le Myanmar. Il pêche et capture des serpents venimeux pour les vendre. La violence du monde le rattrape lorsqu''un groupe de volontaires humanitaires mené par Sarah et Michael Bennett vient le trouver pour qu''il les guide jusqu''à un camp de réfugiés auquel ils veulent apporter une aide médicale et de la nourriture. Rambo finit par accepter et leur fait remonter la rivière, vers l''autre côté de la frontière. Deux semaines plus tard, le pasteur Arthur Marsh lui apprend que les volontaires ne sont pas revenus et que les ambassades refusent de l''aider à les retrouver. Rambo sait mieux que personne ce qu''il faut faire dans ce genre de situation…","es":"John Rambo, el ex-boina verde con una ajetreada vida marcada por la guerra, vive ahora una solitaria y apacible existencia en la jungla del norte de Tailandia, pescando y cazando cobras para luego venderlas. Todo cambia cuando un grupo de misioneros católicos necesita que les guíe hasta la frontera con Birmania para suministrar medicinas y alimentos a unos refugiados asediados por el ejército birmano, que ha hecho de las torturas y los asesinatos algo habitual. Rambo no tendrá más remedio que volver a involucrarse. Se verá obligado a hacer lo que mejor sabe porque, muy a su pesar, lleva la guerra en la sangre.","de":"John Rambo lebt seit langer Zeit zurückgezogen in Thailand. Das benachbarte Birma ist seit 60 Jahren im Würgegriff eines blutigen Bürgerkrieges. Im Kampf gegen die dort herrschende Unmenschlichkeit sucht ein Team von freiwilligen Helfern Rambo auf um sich von ihm ins Zielgebiet bringen zu lassen. Zunächst abgeneigt willigt Rambo schließlich ein. Bereits kurze Zeit später wird das besuchte Dorf brutal niedergemacht. Fast alle Einwohner werden getötet, nur das Helferteam gerät in Gefangenschaft. Da von offizieller Seite keine Hilfe zu erwarten ist, wird ein Trupp Söldner zur Befreiung der Gefangenen entsandt. Obwohl wieder nur als Fährmann gedacht, schließt sich Rambo der Eingreiftruppe an…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/3RIDyg4aUasjfZRdk6oLab0C0Ch.jpg","en":"https://image.tmdb.org/t/p/w500/3mInub5c8o00H7EJ1TrjAqOzIuc.jpg","fr":"https://image.tmdb.org/t/p/w500/eH4KkHYHA7CkWnHb0qoFbsOIV6V.jpg","es":"https://image.tmdb.org/t/p/w500/qp9Q0JeHQ6JShQPm6KA8euYhWLF.jpg","de":"https://image.tmdb.org/t/p/w500/3ZKMR799BsDAOU5zKsXQwsg4OQ9.jpg"}'::jsonb WHERE id = 89;
UPDATE public.films SET tmdb_id = 522938, titoli_i18n = '{"it":"Rambo: Last Blood","en":"Rambo: Last Blood","es":"Rambo: Last Blood","de":"Rambo - Last Blood","fr":"Rambo : Last Blood"}'::jsonb, trame_i18n = '{"it":"Ormai anziano, John Rambo cerca di condurre una vita tranquilla nel ranch di famiglia in Arizona. Quando la sua giovane nipote viene rapita in Messico da un cartello della droga, Rambo si reca oltre confine scatendando un''ultima, spietata vendetta.","en":"After fighting his demons for decades, John Rambo now lives in peace on his family ranch in Arizona, but his rest is interrupted when Gabriela, the granddaughter of his housekeeper María, disappears after crossing the border into Mexico to meet her biological father. Rambo, who has become a true father figure for Gabriela over the years, undertakes a desperate and dangerous journey to find her.","es":"Después de luchar contra sus demonios durante décadas, John Rambo vive ahora en paz en su rancho familiar en Arizona, pero su descanso se ve interrumpido cuando Gabriela, la nieta de su ama de llaves María, desaparece después de cruzar la frontera con México con el propósito de conocer a su padre biológico. Rambo, que con los años se ha convertido para Gabriela en una verdadera figura paterna, emprende un desesperado y peligroso viaje para encontrarla.","de":"John Rambo hat viele große Schlachten in seinem Leben geschlagen – nun soll endlich Schluss sein. Zurückgezogen lebt der Kriegsveteran inzwischen auf einer abgelegenen Farm in Arizona. Doch der einstige Elitekämpfer kommt nicht zur Ruhe. Als die Enkeltochter seiner Haushälterin Maria verschleppt wird, begibt sich Rambo auf eine Rettungsmission nach Mexiko. Schon bald sieht er sich dort einem der mächtigsten und skrupellosesten Drogenkartelle gegenüber. Die vielen Jahre im Kampf mögen Rambo gezeichnet haben, aber sie haben ihn nicht weniger gefährlich gemacht…","fr":"John Rambo doit sauver une jeune fille retenue captive par des trafiquants de drogues à la frontière entre le Mexique et les Etats-Unis."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qs5u7sQLLZZGvLu0yQ9alCmV7wm.jpg","en":"https://image.tmdb.org/t/p/w500/kTQ3J8oTTKofAVLYnds2cHUz9KO.jpg","es":"https://image.tmdb.org/t/p/w500/kG3pY61LWGAzcaSne12CGEeRvtg.jpg","de":"https://image.tmdb.org/t/p/w500/mVMm6BGBdB1HOpTyBCXaO2Nlt2T.jpg","fr":"https://image.tmdb.org/t/p/w500/q6h6ZK0JykZ1Jl736SM9zBZN3by.jpg"}'::jsonb WHERE id = 90;
UPDATE public.films SET tmdb_id = 4780, titoli_i18n = '{"it":"Obsession - Complesso di colpa","es":"Fascinación (Obsession)","en":"Obsession","fr":"Obsession","de":"Schwarzer Engel"}'::jsonb, trame_i18n = '{"it":"Un uomo d''affari di New Orleans subisce un grave trauma quando la moglie e la figlia muoiono durante un tragico tentativo di riscatto. Anni dopo, durante un viaggio a Firenze, incontra una giovane donna identica alla defunta moglie, sprofondando in un vortice di ossessione e inganni.","es":"Michael Courtland (Cliff Robertson), un importante hombre de negocios de Nueva Orleáns, pierde a su mujer Elizabeth (Genevieve Bujoid) y a su hija de nueve años en el fatal desenlace de un trágico secuestro. Muchos años después, durante un viaje por Italia con un socio suyo (John Lithgow), queda fascinado al conocer a Sandra, una joven que es el vivo retrato de su esposa.","en":"A wealthy New Orleans businessman becomes obsessed with a young woman who resembles his late wife.","fr":"Ayant vu sa femme mourir faute d''avoir payé la rançon exigée par leurs kidnappeurs, Michael Courtland, homme d''affaires américain, rencontre un jour en Italie une femme lui ressemblant comme deux gouttes d''eau. Malgré les avertissements de son entourage, il y voit une seconde chance qu''il ne veut pas laisser passer. Au risque de réveiller un passé douloureux...","de":"1959 werden Frau und Tochter von Immobilienmakler Michael Courtland entführt. Die Kidnapper entkommen, sterben bei einem Unfall. Michael sieht die Familie nie wieder. Sechzehn Jahre später reist er nach Florenz und begegnet in der Kirche, in der er getraut wurde, Restauratorin Sandra, die seiner Frau ähnlich sieht. Er verliebt sich in sie. Bei der Hochzeit in New York wiederholt sich die Geschichte. Sandra ist in Wahrheit seine Tochter, die sich mit Courtlands Partner verschworen hat, der auch damals für die Entführung verantwortlich war..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/g0kwlD4KLYCJ4AcCPg0yyvPhv7G.jpg","es":"https://image.tmdb.org/t/p/w500/9160yxML0m3XiBdwdfrJwBlS356.jpg","en":"https://image.tmdb.org/t/p/w500/a0bOKTldOJVJivmPNGBHfMYJU9x.jpg","fr":"https://image.tmdb.org/t/p/w500/9BsjHxDY6mYzbm34yuA25QCJf0Q.jpg","de":"https://image.tmdb.org/t/p/w500/8RlB98ebtU2m5PiuDQ2FZuOcdmK.jpg"}'::jsonb WHERE id = 91;
UPDATE public.films SET tmdb_id = 5155, titoli_i18n = '{"fr":"Les Amants diaboliques","de":"Von Liebe besessen","en":"Obsession","it":"Ossessione","es":"Obsesión"}'::jsonb, trame_i18n = '{"fr":"Bragana tient un café-garage sur la route qui longe le Po. Gino, chômeur et vagabond, demande du travail à Bragana. D''abord méfiant, celui-ci le prend en amitié quand il découvre ses talents de mécanicien. Gino a d''autres talents et devient l''amant de la femme de Bragana, Giovanna. Très vite ils vont se débarrasser du mari gênant. Mais ce meurtre transformera leur passion en enfer.","de":"Der junge Gelegenheitsarbeiter Gino kehrt in einer abgelegenen Trattoria in der Po-Ebene ein. Sie wird von dem grobschlächtigen Bragana und seiner jungen Frau Giovanna bewirtschaftet. Schon bei ihrer ersten Begegnung ist ein erotisches Knistern zwischen Giovanna und Gino zu spüren. Giovanna überredet ihren Mann, Gino als Mechaniker einzustellen. Und kaum ist der Wirt außer Haus, wird Gino zum Geliebten Giovannas. Besessen von ihrer Leidenschaft sehen die Liebenden nur einen Weg zu ihrem gemeinsamen Glück: Bragana muß sterben ...","en":"Gino, a drifter, begins an affair with inn-owner Giovanna as they plan to get rid of her older husband.","it":"Gino, un girovago senza meta, si innamora ricambiato di Giovanna, una donna insoddisfatta sposata con il proprietario di una trattoria. La passione travolgente tra i due li spinge a eliminare il marito, ma il senso di colpa e il destino distruggeranno il loro legame.","es":"Giovanna (Clara Calamai) es una hermosa joven malcasada con el viejo propietario de un restaurante. Su sórdida vida cambiará con la aparición de un vagabundo que se convierte en su amante y al que inducirá a matar a su marido. Adaptación de la novela de James Cain \"El cartero siempre llama dos veces\"."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/zDaZRT5GO6KPP1JiF4ZhLbwWiX8.jpg","de":"https://image.tmdb.org/t/p/w500/3iXqrbHty7fnDndMlKha3ddtxPk.jpg","en":"https://image.tmdb.org/t/p/w500/dHB6NdsOxO0dc71ciP2hsv3nTPf.jpg","it":"https://image.tmdb.org/t/p/w500/qgDF8yuJa9eEcfBqEQrqbJuxe5z.jpg","es":"https://image.tmdb.org/t/p/w500/dZtbu1ObXnfO0RcM5RghIrfcHQd.jpg"}'::jsonb WHERE id = 92;
UPDATE public.films SET tmdb_id = 35852, titoli_i18n = '{"es":"Obsession","de":"Der Wahnsinn des Dr. Clive","it":"Obsession","en":"Obsession","fr":"Obsession"}'::jsonb, trame_i18n = '{"es":"La hermosa esposa del Dr. Clive Riordan llega a casa una noche con el diplomático estadounidense Bill Kronin. Riordan, consumido por los celos que le producen las repetidas aventuras de su mujer, decide liquidar a su nuevo rival y planea, utilizando sus conocimientos de psiquiatría, el asesinato perfecto.","de":"Der Psychiater Dr. Clive Riordan erfährt, dass seine Frau Storm eine Affäre mit dem amerikanischen Schriftsteller Bill Cronin hat. Aus Eifersucht und verletztem Stolz fasst er einen mörderischen Plan.  Clive entführt Cronin und sperrt ihn in einem abgelegenen Raum seines Hauses ein. Er will den Rivalen nicht einfach töten, sondern ihn psychisch und körperlich zugrunde richten. Dabei entwickelt sich zwischen Täter und Opfer ein gefährliches Katz-und-Maus-Spiel.  Während Clive seinen Plan immer weiter verfolgt, beginnt seine scheinbar perfekte Kontrolle über die Situation zu zerbrechen. Storm wird zunehmend misstrauisch, und die Gefahr wächst, dass seine Tat ans Licht kommt.  Der Film ist ein düsterer Psychothriller über Eifersucht, Besessenheit und Rache, bei dem weniger körperliche Gewalt als die psychologische Manipulation im Mittelpunkt steht.","it":"Un medico londinese scopre che la moglie lo tradisce e decide di attuare una macabra vendetta. Rapisce l''amante della donna e lo tiene nascosto in un garage abbandonato, pianificando di scioglierlo gradualmente nell''acido.","en":"A British psychiatrist devises a devilish revenge plot against his wife''s lover.","fr":"L''épouse de Dr Clive Riordan, \"Storm\", rentre une nuit en compagnie d''un diplomate américain, Bill Kronin. Riordan, obsédé par la jalousie, décide d''assassiner son plus récent rival et projette, comme seul un psychiatre le ferait, non seulement de tuer Bill, mais de commettre le crime parfait dans le processus."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/7BlzTHGLBxxCiqY0fTvPqaE2hcX.jpg","de":"https://image.tmdb.org/t/p/w500/2Ml9uCOJnCv9fGb117RmFON5gNT.jpg","it":"https://image.tmdb.org/t/p/w500/rEOBZMcw29R0kGQJkrUDgtXCU2Z.jpg","en":"https://image.tmdb.org/t/p/w500/7BlzTHGLBxxCiqY0fTvPqaE2hcX.jpg","fr":"https://image.tmdb.org/t/p/w500/7BlzTHGLBxxCiqY0fTvPqaE2hcX.jpg"}'::jsonb WHERE id = 93;
UPDATE public.films SET tmdb_id = 98544, titoli_i18n = '{"es":"Obsesión","en":"Obsession","de":"Obsession","fr":"Berlin Niagara","it":"Obsession"}'::jsonb, trame_i18n = '{"es":"Una historia de dos pasiones. En la ciudad de Berlín, en vías de crecimiento y expansión, Myriam (Heike Makatsch), una trompetista, vive con Pierre (Charles Berling), a quien ama profundamente. También se siente irresistiblemente atraída hacia John (Daniel Craig), quien trata de resolver un misterio alrededor de una vieja fotografía de periódico, que muestra a un equilibrista cruzando las Cataratas del Niágara. Los tres acaban en París, tras la pista de un anciano que conoce el secreto detrás de la fotografía; un secreto que tendrá un hondo efecto en sus vidas y en el amor.","en":"Two men become entangled in a torrid love affair with the same woman. Pierre is Miriam''s longtime lover. John is desperately searching for clues about his past when he and Miriam have a fateful encounter in a Berlin train station. The allure of forbidden love becomes irresistible, and an intense love triangle is ignited. Who will Miriam choose? Who will walk away? For two men who desperately adore the same woman and for the woman who loves them equally...there is no easy way out.","de":"Obsession ist ein französisch-deutsches Filmdrama aus dem Jahr 1997.","fr":"Un été à Berlin. Trois jeunes gens sont pris dans les filets d''une étrange attirance. Myriam, la Berlinoise, étudie l''orgue et joue de la trompette dans un orchestre de salsa rock féminin. Elle rêve de pouvoir voler et veut un enfant. Pierre, le Français, est médecin biologiste et coureur de marathon. John, le blond sculpteur du Zimbabwe, vient à Berlin pour résoudre une énigme.","it":"Una giovane musicista si trova divisa tra l''amore per due uomini completamente differenti tra loro a Berlino. La situazione sfocia in un complesso triangolo amoroso guidato da passione, insicurezze e scelte dolorose."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/5Z3Y42Duzwb51kIEeMnkBOgiuLk.jpg","en":"https://image.tmdb.org/t/p/w500/5Z3Y42Duzwb51kIEeMnkBOgiuLk.jpg","de":"https://image.tmdb.org/t/p/w500/5Z3Y42Duzwb51kIEeMnkBOgiuLk.jpg","fr":"https://image.tmdb.org/t/p/w500/gXMKIGR1meZxMnKiQiUhTCjmVBh.jpg","it":"https://image.tmdb.org/t/p/w500/5Z3Y42Duzwb51kIEeMnkBOgiuLk.jpg"}'::jsonb WHERE id = 94;
UPDATE public.films SET tmdb_id = 1339713, titoli_i18n = '{"en":"Obsession","es":"Obsession","fr":"Obsession","de":"Obsession – Du sollst mich lieben","it":"Obsession"}'::jsonb, trame_i18n = '{"en":"After breaking the mysterious \"One Wish Willow\" to win his crush''s heart, a hopeless romantic finds himself getting exactly what he asked for but soon discovers that some desires come at a dark, sinister price.","es":"El anhelo romántico desesperado de un chico por su amor platónico de toda la vida desencadena un siniestro hechizo: Nikki se vuelve irracionalmente obsesiva hasta convertirse en la sombra de Bear. Una fantasía aparentemente inofensiva que se convertirá en una perturbadora pesadilla.","fr":"Et si vous pouviez réaliser votre rêve le plus fou ? Un jeune introverti met la main sur un objet magique capable d’exaucer n’importe quel souhait. Son crush de toujours tombe alors raide dingue de lui… jusqu’à l’obsession la plus totale. Faites attention à ce que vous souhaitez !","de":"Als der hoffnungslose Romantiker Bear einen magischen Gegenstand nutzt, damit sein Crush endlich Gefühle für ihn entwickelt, muss er feststellen, dass manche Wünsche einen finsteren, unheimlichen Tribut fordern.","it":"Un thriller psicologico ad alta tensione che esplora i confini della mente umana, le relazioni tossiche e le conseguenze estreme del desiderio inconfessabile e del possesso."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg","es":"https://image.tmdb.org/t/p/w500/p1QFjQ8wwlXXlxwaWlehJ37uXVj.jpg","fr":"https://image.tmdb.org/t/p/w500/mDCR1frpUvGfIKksuM440VLb7X9.jpg","de":"https://image.tmdb.org/t/p/w500/1bAhSRf3BVOCI9zNzTLrsJA1LAq.jpg","it":"https://image.tmdb.org/t/p/w500/kwprCwsIV4LvAqJC1dmiTAdZDJ1.jpg"}'::jsonb WHERE id = 95;
UPDATE public.films SET tmdb_id = 1083381, titoli_i18n = '{"en":"Backrooms","fr":"Backrooms","it":"The Backrooms","es":"Backrooms","de":"Backrooms"}'::jsonb, trame_i18n = '{"en":"A strange doorway appears in the basement of a furniture showroom.","fr":"Une étrange porte apparaît dans le sous-sol d''un magasin de meubles.","it":"Un giovane precipita accidentalmente oltre i confini della realtà ritrovandosi intrappolato nelle Backrooms, una dimensione parallela costituita da uno sconfinato e inquietante labirinto di uffici vuoti, pareti gialle, moquette umida e luci al neon ronzanti. Mentre tenta disperatamente di trovare una via d''uscita, deve eludere spietate entità ostili che cacciano all''interno di questo spazio liminale.","es":"Una extraña puerta aparece en el sótano de una tienda de muebles. Cuando el paciente de una terapeuta desaparece en una dimensión más allá de la realidad, ella deberá adentrarse en lo desconocido para intentar rescatarlo.","de":"Kahle, verschachtelte Büroflure, endlose beige-gelbe Wände, ein unaufhörliches, unerträglich lautes Surren von Leuchtstoffröhren: Die „Backrooms“ beschreiben eine neue Art von Albtraum, eine menschenleere Parallelwelt sich wiederholender, fensterloser Stockwerke, die unsere Realität auf den ersten Blick spiegelt und sich ihr doch mit jedem Schritt weiter entzieht. Verstörend verlassen wirken die labyrinthischen Räume, doch allein ist man dort nicht..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg","fr":"https://image.tmdb.org/t/p/w500/thQQ3BBBhGDtWm3UTtabhyDJd8U.jpg","it":"https://image.tmdb.org/t/p/w500/MIINS3Q31PEYGM7d3mwJE5mV4L.jpg","es":"https://image.tmdb.org/t/p/w500/ur2yYTVGPkEDmLdoQ1Obm2RKXuU.jpg","de":"https://image.tmdb.org/t/p/w500/nsp6DZb0Z2CAHcaRTsw2kwsN6ul.jpg"}'::jsonb WHERE id = 96;
UPDATE public.films SET tmdb_id = 31510, titoli_i18n = '{"it":"Ben-Hur: A Tale of the Christ","en":"Ben-Hur: A Tale of the Christ","es":"Ben-Hur","fr":"Ben-Hur","de":"Ben Hur"}'::jsonb, trame_i18n = '{"it":"Un giovane principe ebreo viene ingiustamente accusato di aver attentato alla vita del governatore romano dal suo amico d''infanzia Messala. Ridotto in schiavitù, cercherà il riscatto e la vendetta.","en":"Judah Ben-Hur, a wealthy Jewish prince in Jerusalem, is betrayed by his childhood friend, Roman tribune Messala, and wrongfully sent to the galley slaves.","es":"En los años del Imperio Romano del reinado de Augusto y su sucesor Tiberio, Judá Ben-Hur, hijo de una familia noble de Jerusalén, y Mesala, tribuno romano que dirige los ejércitos de ocupación, se han convertido en enemigos irreconciliables. Acusado de atentar contra la vida del nuevo gobernador romano, Mesala le encarcela junto a su familia. Cuando se llevan a Ben-Hur a galeras, un joven llamado Jesús de Nazaret se apiada de él y le da de beber.","fr":"Parce qu’il a refusé à son ami Messala de collaborer avec l’occupant romain, Ben-Hur est envoyé aux galères, tandis que sa sœur Tirzah et sa mère sont jetées au cachot. Il est adopté par le tribun Quintus Arrius, qui lui doit la vie.","de":"Basierend auf dem selben Buch von Lew Wallace, das auch Vorlage für die gleichnamige Monumentalverfilmung von 1959 mit Charlton Heston war, geht es in diesem Stummfilm um einen Juden, der zu Unrecht wegen eines Anschlags auf einen Römer festgenommen und in einem Sklavenschiff aus seiner Heimat Jerusalem fortgebracht wird. Da auch seine Familie festgenommen wird, schwört er, sich an den Verantwortlichen zu rächen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg","en":"https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg","es":"https://image.tmdb.org/t/p/w500/x65AGnMC5gS1VVf6BKbhJMQ3F6t.jpg","fr":"https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg","de":"https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg"}'::jsonb WHERE id = 97;
UPDATE public.films SET tmdb_id = 665, titoli_i18n = '{"it":"Ben-Hur","es":"Ben-Hur","en":"Ben-Hur","fr":"Ben-Hur","de":"Ben Hur"}'::jsonb, trame_i18n = '{"it":"Giuda Ben-Hur, un ricco principe ebreo di Gerusalemme, viene tradito dall''amico d''infanzia Messala e inviato come schiavo sulle galere. Dopo essere sopravvissuto e aver salvato un console romano, torna in patria per vendicarsi sfidando Messala in un''epica corsa con i carri.","es":"Antigua Roma, bajo el reinado de los emperadores Augusto y Tiberio (s. I d.C.). Judá Ben-Hur, hijo de una familia noble de Jerusalén, y Mesala, tribuno romano que dirige los ejércitos de ocupación, son dos antiguos amigos, pero un accidente involuntario los convierte en enemigos irreconciliables: Ben-Hur es acusado de atentar contra la vida del nuevo gobernador romano, y Mesala lo encarcela a él y a su familia. Mientras Ben-Hur es trasladado a galeras para cumplir su condena, un hombre llamado Jesús de Nazaret se apiada de él y le da de beber. En galeras conocerá al comandante de la nave y más tarde a un jeque árabe que participa con sus magníficos caballos en carreras de cuadrigas.","en":"In ancient Judea, a Jewish aristocrat opposing Roman occupation of his homeland reunites with his childhood friend, now a Roman commander — setting in motion a saga of betrayal, adventure, tragedy, revenge, and faith.","fr":"Judas Ben-Hur, prince de Judée, retrouve son ami d’enfance Messala, venu prendre la tête de la garnison de Jérusalem. Mais leur amitié ne peut résister à leurs caractères différents. Alors qu’une pierre tombe du balcon de la maison familiale de Ben‐Hur, manquant de tuer le gouverneur qui paradait plus bas, Messala trahit son ami qu’il sait innocent en l’envoyant aux galères et en jetant en prison sa mère et sa sœur. Ben-Hur jure alors de reconquérir sa liberté et prépare sa vengeance.","de":"Als Judah Ben-Hurs Jugendfreund Messala, der ihm einst das Leben rettete, nach Jerusalem kommt, um dort neuer römischer Kommandant zu werden, ist die Wiedersehensfreude auf beiden Seiten groß. Die Freundschaft zwischen Messala und Judah wird auf die Probe gestellt, als Judah die jüdischen Aufständischen verraten soll. Nachdem bei einer römischen Parade der neue Statthalter vor Judahs Haus schwer verletzt wird, verdächtigt man Judah und seine Familie des Attentats. Unschuldig in den Kerkern gefangen, schwört Judah sich blutig für das begangene Unrecht an Messala zu rächen. Mit seiner Verbannung auf eine Galeere beginnt für den stolzen Judah eine Odyssee, die ihn von den Meeren über die Wagenrennen in Rom Jahre später wieder nach Jerusalem bringt, wo Judah hofft, seine Familie zu finden und seine Rachepläne zu vollenden."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/4pHkQ4rY44zbgXh9grnqn0UzUgr.jpg","es":"https://image.tmdb.org/t/p/w500/bG0yaRTC7N0bWhlaPXsyi3ZnbMo.jpg","en":"https://image.tmdb.org/t/p/w500/m4WQ1dBIrEIHZNCoAjdpxwSKWyH.jpg","fr":"https://image.tmdb.org/t/p/w500/4KH7VM5YyGwxe4kLSNxix2PNTn6.jpg","de":"https://image.tmdb.org/t/p/w500/mn4GERBRBWmkGOYXFibcOlURpCV.jpg"}'::jsonb WHERE id = 98;
UPDATE public.films SET tmdb_id = 271969, titoli_i18n = '{"es":"Ben-Hur","it":"Ben-Hur","fr":"Ben-Hur","de":"Ben Hur","en":"Ben-Hur"}'::jsonb, trame_i18n = '{"es":"Judah Ben-Hur es un príncipe falsamente acusado de traición por su hermano adoptivo Messala, un oficial del ejército romano. Desposeído de su título y separado de su familia y de la mujer que ama, Judah es condenado a la esclavitud en las galeras. Después de varios años, Judah regresa a su tierra natal en busca de venganza, pero encontrará su propia redención.","it":"Rivisitazione moderna del classico di Lew Wallace: Giuda Ben-Hur viene accusato ingiustamente di tradimento dal fratello adottivo Messala, ufficiale dell''esercito romano. Dopo anni trascorsi in mare come schiavo, torna per cercare la resa dei conti nella grande arena dei carri.","fr":"Le prince Judah Ben-Hur est accusé à tort de trahison par Messala, son frère adoptif, officier de l’armée romaine. Déchu de son titre, séparé de sa famille et de la femme qu’il aime, Judah est réduit à l’esclavage. Après des années en mer, Judah revient sur sa terre natale dans le but de se venger. Il va y rencontrer son destin.","de":"Der jüdische Prinz Judah Ben-Hur und der Sohn eines römischen Steuereintreibers Messala wachsen gemeinsam zu jener Zeit auf, zu der auch Jesus Christus lebt. Sie sind beste Freunde, bis Messala eines Tages nach Rom geht, um sich dort weiterzubilden. Jahre später kommt er als völlig veränderter Mensch zurück, hat nur noch Spott für Judah und vor allem für dessen Religion übrig. Schon bald intrigiert er gegen seinen einstigen Freund und sorgt dafür, dass dessen Familie im Gefängnis landet und Judah auf ein Sklavenschiff gebracht wird. Der dort dem sicheren Tod geweihte Ben-Hur überlebt wie durch ein Wunder und kennt nur noch ein Ziel: Rache. Die bietet sich schließlich bei einem Wagenrennen in Rom, an welchem Ben-Hur im Dienste des ihm wohlgesonnenen Scheichs Ilderim teilnimmt …","en":"A falsely accused nobleman survives years of slavery to take vengeance on his best friend who betrayed him."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/wBGgyiRfj7poy0BBCGa0kDDRlmf.jpg","it":"https://image.tmdb.org/t/p/w500/vKtbuybPbG2DuMieD0FGU3aVcGs.jpg","fr":"https://image.tmdb.org/t/p/w500/xo6niyf90QTimKOppsIiKPuDhIL.jpg","de":"https://image.tmdb.org/t/p/w500/eKDp1MndIye89hAfAq5Fykn2bPC.jpg","en":"https://image.tmdb.org/t/p/w500/c9CoGrBA5yw8A7YBMz0hGzfzpNq.jpg"}'::jsonb WHERE id = 99;
UPDATE public.films SET tmdb_id = 653, titoli_i18n = '{"it":"Nosferatu il vampiro (Nosferatu eine Symphonie des Grauens)","fr":"Nosferatu","de":"Nosferatu, eine Symphonie des Grauens","es":"Nosferatu","en":"Nosferatu"}'::jsonb, trame_i18n = '{"it":"Il misterioso Conte Orlok decide di acquistare una casa a Wisborg, portando con sé la peste e il terrore. Il giovane Thomas Hutter e sua moglie Ellen cercheranno di fermare la letale minaccia.","fr":"En 1838, Hutter, jeune clerc de notaire, part conclure une vente avec un châtelain des Carpathes. Après des rencontres menaçantes et de funestes présages, il est reçu par le comte Orlock qui n''est autre que la réincarnation du vampire Nosferatu, créature qui ne peut vivre qu''en suçant le sang des humains. Ce chef-d''œuvre du cinéma muet d''épouvante tourné en décors naturels est la première adaptation fidèle du célèbre roman de Bram Stocker, Dracula, publié en 1897.","de":"Stummfilm aus dem Jahr 1922 von Regisseur F. W. Murnau, basierend auf dem Roman „Dracula“ von Bram Stoker. Ein Immobilienagent erhält den Auftrag, für einen Kunden namens Graf Dracula nach Transsylvanien zu reisen, der sich für den Kauf eines Hauses in Wisborg (und seine Frau) interessiert. Klassiker der Stummfilmzeit, der vielfach kopiert wurde.","es":"Año 1838. En la ciudad de Wisborg viven felices el joven Hutter y su mujer Ellen, hasta que el oscuro agente inmobiliario Knock decide enviar a Hutter a Transilvania para cerrar un negocio con el conde Orlok. Se trata de la venta de una finca de Wisborg, que linda con la casa de Hutter. Durante el largo viaje Hutter pernocta en una posada, donde hojea un viejo tratado sobre vampiros que encuentra en su habitación. Una vez en el castillo, es recibido por el siniestro conde. Al día siguiente, Hutter amanece con dos pequeñas marcas en el cuello, que interpreta como picaduras de mosquito. Una vez firmado el contrato, descubre que el conde es, en realidad, un vampiro. Al verle partir hacia su nuevo hogar, Hutter teme por Ellen.","en":"The mysterious Count Orlok summons a happily married real estate agent to his castle, located up in the Transylvanian mountains, to finalise a terrifying deal."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zx24O7VAs6NbJhiIrUhWysAiHS0.jpg","fr":"https://image.tmdb.org/t/p/w500/9WUpFfsUIHuiY4MwTEw46Rvf1Od.jpg","de":"https://image.tmdb.org/t/p/w500/zEzQTngP7F4qVmLDCWg5Hby6cgX.jpg","es":"https://image.tmdb.org/t/p/w500/z45rXmIF0zl4uxRc5XcSfz6hYO6.jpg","en":"https://image.tmdb.org/t/p/w500/zv7J85D8CC9qYagAEhPM63CIG6j.jpg"}'::jsonb WHERE id = 100;
UPDATE public.films SET tmdb_id = 6404, titoli_i18n = '{"en":"Nosferatu the Vampyre","fr":"Nosferatu, fantôme de la nuit","it":"Nosferatu, il principe della notte (Nosferatu: Phantom der Nacht)","de":"Nosferatu – Phantom der Nacht","es":"Nosferatu. Vampiro de la noche"}'::jsonb, trame_i18n = '{"en":"A real estate agent leaves behind his beautiful wife to go to Transylvania to visit the mysterious Count Dracula and formalize the purchase of a property in Wismar.","fr":"Au XIXe siècle, Jonathan Harker se rend en Transylvanie pour vendre un manoir au comte Dracula. Sur la route, les villageois lui conseillent de rebrousser chemin mais le jeune homme refuse. Au moment de la signature, Dracula aperçoit un portrait de la fiancée de Harker, identique en tous points à sa défunte épouse. Jonathan est fait prisonnier et le comte se rend à Londres pour retrouver la jeune femme.","it":"In questo celebre remake del film di Murnau, il tormentato Conte Dracula viaggia dalla Transilvania a Wismar, diffondendo la peste e cercando ossessivamente l''amore della giovane Lucy Harker.","de":"Jonathan Harker ist alles andere als begeistert, als er den Auftrag erhält, von Wismar ins ferne Transsylvanien zu reisen. Dort interessiert sich ein gewisser Graf Dracula für den Kauf eines Hauses in der Hansestadt. Schweren Herzens verabschiedet er sich von seiner geliebten Frau und reitet los. Er ahnt nicht, welches Grauen ihn erwartet.","es":"Jonathan Harker viaja desde Wismar a Transilvania, al castillo del legendario conde Drácula, con el fin de venderle una mansión en su ciudad. Atraído por una fotografía de Lucy, la mujer de Harker, Nosferatu parte inmediatamente hacia Wismar, llevando con él muerte y el horror."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/jHKzGYwf7P34vz8MhJBTN6cnaYD.jpg","fr":"https://image.tmdb.org/t/p/w500/sIWTseJwPMTXuOC3wCAhkGP4VEt.jpg","it":"https://image.tmdb.org/t/p/w500/kiwmmJIX7eUcUoR5CBxGW0xruJO.jpg","de":"https://image.tmdb.org/t/p/w500/enHF1OyflcvJHcJsJ8RttNYqfv1.jpg","es":"https://image.tmdb.org/t/p/w500/ej8BnlGwoiWmugLLsNrRUdjCm4t.jpg"}'::jsonb WHERE id = 101;
UPDATE public.films SET tmdb_id = 426063, titoli_i18n = '{"en":"Nosferatu","de":"Nosferatu - Der Untote","es":"Nosferatu","fr":"Nosferatu","it":"Nosferatu"}'::jsonb, trame_i18n = '{"en":"A gothic tale of obsession between a haunted young woman and the terrifying vampire infatuated with her, causing untold horror in its wake.","de":"Eine Geschichte über die Besessenheit zwischen einer gequälten jungen Frau und dem furchteinflößenden Vampir, der in sie vernarrt ist und unbeschreiblichen Schrecken hinterlässt.","es":"Historia gótica de obsesión entre una joven hechizada y el aterrador vampiro encaprichado de ella que causa un indescriptible terror a su paso.","fr":"Dans l''Allemagne de 1838, Thomas Hutter, agent immobilier, est envoyé en Transylvanie pour rencontrer le mystérieux comte Orlok, intéressé par l''achat d''une propriété à Wisborg. Laissant derrière lui sa jeune épouse, Ellen, sujette à des visions inquiétantes, Thomas découvre rapidement la véritable nature du comte : un vampire terrifiant. Pendant ce temps, à Wisborg, Ellen est de plus en plus tourmentée par des cauchemars prémonitoires liés à Orlok. Lorsque le comte s''installe dans sa nouvelle demeure, une série d''événements horrifiques se déclenche, plongeant la ville dans la terreur et la désolation.","it":"Una rivisitazione gotica e terrificante della classica leggenda, incentrata sull''ossessione tra una giovane donna tormentata e il mostruoso vampiro infatuato di lei."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/d0B8xDdqBZlzlPEzES8lu5LlNQn.jpg","de":"https://image.tmdb.org/t/p/w500/yig53WzBjX84iSYWKb2BCYYxFLM.jpg","es":"https://image.tmdb.org/t/p/w500/jivUhECegXI3OYtPVflWoIDtENt.jpg","fr":"https://image.tmdb.org/t/p/w500/A8UIMJTwSaflmWmUlfPOFdenSBT.jpg","it":"https://image.tmdb.org/t/p/w500/1SftujfE9iqZpGJfnREO4IBeeqV.jpg"}'::jsonb WHERE id = 102;
UPDATE public.films SET tmdb_id = 9361, titoli_i18n = '{"en":"The Last of the Mohicans","es":"El último mohicano","de":"Der letzte Mohikaner","it":"L''ultimo dei mohicani","fr":"Le Dernier des Mohicans"}'::jsonb, trame_i18n = '{"en":"In war-torn colonial America, in the midst of a bloody battle between British, the French and Native American allies, the aristocratic daughter of a British Colonel and her party are captured by a group of Huron warriors. Fortunately, a group of three Mohican trappers comes to their rescue.","es":"En 1757, a orillas del río Hudson, tropas francesas e inglesas luchan por el dominio de la región. Los ingleses reclutan a los granjeros asentados en esas tierras para formar un ejército capaz de enfrentarse a las tropas franco-indias. Hawkeye -Ojo de halcón- (Daniel Day-Lewis) es un hombre blanco adoptado por los indios mohicanos que vive con su padre (Russell Means) y su hermano Uncas (Eric Schweig). Tras rescatar de una emboscada de los hurones a Cora Munro (Madeleine Stowe) y a su hermana pequeña Alice (Jodhi May), hijas de un oficial británico, los tres deciden acompañarlas al fuerte inglés William Henry, que está siendo asediado por franceses y hurones. Allí les obligan a quedarse con un grupo de británicos que acaban de llegar de las colonias...","de":"1757 streiten Engländer und Franzosen um die Vorherrschaft in Nordamerika. Leidtragende sind die Indianer, die als Hilfstruppen verheizt werden. Chingachgooks weißer Adoptivsohn Hawkeye weigert sich, für die englische Miliz zu kämpfen, und verliebt sich in Colonelstochter Cora …","it":"Durante la guerra franco-indiana nel 1757, tre cacciatori, tra cui l''inglese adottato dai Mohicani Occhio di Falco, si ritrovano a proteggere le figlie di un colonnello britannico dall''attacco dei feroci Uroni guidati dal vendicativo Magua.","fr":"En 1757 dans l’État de New York, alors que la guerre fait rage entre Français et Anglais pour l’appropriation des territoires indiens, un jeune officier anglais, Duncan Heyward, est chargé d’escorter deux sœurs, Cora et Alice, jusqu’a leur père. Ils sont sauvés d’une embuscade par Hawkeye, un frontalier d’origine européenne, élevé par le Mohican Chingachgook et son fils Uncas. Les trois hommes acceptent d’escorter les deux jeunes filles jusqu’à leur destination finale."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/qzJMPWRtZveBkxXOv3ucWhoJuyj.jpg","es":"https://image.tmdb.org/t/p/w500/mM9ewvwSZM5DdHFeSaFtRJYDCij.jpg","de":"https://image.tmdb.org/t/p/w500/miGwamVR6zd9ADwCsrdZ6aPniE3.jpg","it":"https://image.tmdb.org/t/p/w500/rGQUmxjKg0Hx9kHkSPTm0D3dcE.jpg","fr":"https://image.tmdb.org/t/p/w500/tWaGxm8LkneIICsM8FvcTSUKvMB.jpg"}'::jsonb WHERE id = 103;
UPDATE public.films SET tmdb_id = 1204680, titoli_i18n = '{"es":"Coyote vs. Acme","en":"Coyote vs. Acme","fr":"Coyote vs. Acme","de":"Coyote vs. ACME","it":"Coyote vs. Acme"}'::jsonb, trame_i18n = '{"es":"Después de que todos los productos fabricados por ACME Corporation le salgan mal a Wile E. Coyote, en su persecución del Correcaminos, contrata a un abogado humano igualmente desafortunado para demandar a la empresa. Cuando el abogado de Wile E. descubre que el intimidante jefe de su antiguo bufete es el director general de ACME, se une a Wile E. para ganar el juicio contra él.","en":"After Acme products fail him one too many times in his dogged pursuit of the Roadrunner, Wile E. Coyote decides to hire a billboard lawyer to sue the Acme Corporation.","fr":"L''avocat Kevin Avery est engagé par Vil Coyote, un personnage des Looney Tunes qui veut attaquer en justice le conglomérat ACME. D''après lui, l''entreprise fabriquerait des produits défectueux. Kevin va découvrir que son ancien patron, Buddy Crane, est désormais le représentant légal de ladite société...","de":"Nach all den Jahren vergeblicher Liebesmüh hat Willi Kojote es satt, dass bisher jedes einzelne Produkt der ACME Corporation eine erfolgreiche Jagd auf den Road Runner vereitelt hat. Kojote beschließt deshalb, das Unternehmen für seine mangelhafte Ware in die Verantwortung zu nehmen, und engagiert den ebenso glück- wie mittellosen Anwalt Kevin Avery, um gegen ACME vor Gericht zu ziehen. Als der herausfindet, dass die Rechtsabteilung des Konzerns von Buddy Crane geleitet wird, dem selbstgefälligen Chef seiner ehemaligen Kanzlei, gibt er alles, um den Prozess zu gewinnen.","it":"Wile E. Coyote decide di fare causa alla Acme Corporation per via dei suoi prodotti costantemente difettosi. Per farlo, assume un avvocato umano di scarso successo che si ritroverà a rappresentarlo in tribunale contro il potente CEO della Acme."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/vWFz9spZFBkJvForuYrKK2ntOLB.jpg","en":"https://image.tmdb.org/t/p/w500/kYDCl2y0VPvhT5eYWbMRInPoB03.jpg","fr":"https://image.tmdb.org/t/p/w500/dFwseuSlDUNiwMuElDb3OAOQ8En.jpg","de":"https://image.tmdb.org/t/p/w500/lHiLrnVKMZS4RmPYOFgXaCh0tQb.jpg","it":"https://image.tmdb.org/t/p/w500/x2AtkVKU8IDgeScz354aqoYjUQG.jpg"}'::jsonb WHERE id = 104;
UPDATE public.films SET tmdb_id = 385704, titoli_i18n = '{"it":"Farewell Oak Street","en":"Farewell Oak Street","fr":"Farewell Oak Street","es":"Farewell Oak Street","de":"Farewell Oak Street"}'::jsonb, trame_i18n = '{"en":"This documentary presents a before-and-after picture of people in a large-scale public housing project in Toronto. Due to a housing shortage, they were forced to live in squalid, dingy flats and ramshackle dwellings on a crowded street in Regent Park North; now they have access to new, modern housing developments designed to offer them privacy, light and space.","it":"Questo documentario canadese analizza le degradate condizioni di vita nel quartiere di Regent Park a Toronto prima della sua ricostruzione. Attraverso il contrasto tra i vecchi slum di Oak Street e i nuovi complessi di edilizia popolare, l''opera illustra l''impatto positivo che una pianificazione urbana moderna e alloggi dignitosi hanno sulla salute, sulla sicurezza e sul benessere sociale delle famiglie."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg","en":"https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg","fr":"https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg","es":"https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg","de":"https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg"}'::jsonb WHERE id = 106;
UPDATE public.films SET tmdb_id = 1014049, titoli_i18n = '{"it":"Oak Street","fr":"The House on Oak Street","en":"The House on Oak Street","es":"The House on Oak Street","de":"The House on Oak Street"}'::jsonb, trame_i18n = '{"en":"Four middle school kids discover the unimaginable when, on Halloween night, they venture into the old house on Oak Street.","it":"Un intenso thriller psicologico ambientato in una tranquilla periferia americana. Quando un''intera famiglia scompare misteriosamente dal civico 42 di Oak Street senza lasciare alcuna traccia, un investigatore in pensione decide di condurre un''indagine autonoma. Con il passare dei giorni, l''uomo porterà alla luce una complessa rete di oscuri segreti e menzogne sepolte da decenni all''interno dell''apparentemente impeccabile comunità locale."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/3iJpc2rV8uN434wdDTJBE2PQwvI.jpg","fr":"https://image.tmdb.org/t/p/w500/3iJpc2rV8uN434wdDTJBE2PQwvI.jpg","en":"https://image.tmdb.org/t/p/w500/3iJpc2rV8uN434wdDTJBE2PQwvI.jpg","es":"https://image.tmdb.org/t/p/w500/3iJpc2rV8uN434wdDTJBE2PQwvI.jpg","de":"https://image.tmdb.org/t/p/w500/3iJpc2rV8uN434wdDTJBE2PQwvI.jpg"}'::jsonb WHERE id = 107;
UPDATE public.films SET tmdb_id = 1101383, titoli_i18n = '{"it":"La fine di Oak Street","es":"El final de Oak Street","fr":"La fin d''Oak Street","en":"The End of Oak Street","de":"The End of Oak Street"}'::jsonb, trame_i18n = '{"it":"In una tranquilla e apparentemente perfetta via residenziale chiamata Oak Street, una serie di eventi inspiegabili e sparizioni misteriose scatena la paranoia tra i residenti, costringendo una madre a fare i conti con un oscuro segreto del passato per salvare la sua famiglia.","es":"Después de que un misterioso fenómeno cósmico arranque Oak Street de su entorno suburbano y transporte a sus habitantes a un lugar desconocido, la familia Platt pronto descubre que su propia supervivencia depende de que permanezcan unidos mientras se orientan en un entorno que ya no reconocen.","fr":"Lorsqu’un mystérieux événement cosmique arrache Oak Street à sa paisible banlieue et la transporte vers un lieu inconnu, la famille Platt, désorientée dans ce nouvel environnement hostile, comprend vite qu’il leur faudra rester unis pour survivre.","en":"After a mysterious cosmic event rips Oak Street from suburbia and transports their neighborhood to someplace unknown, the Platt family soon discovers that their very survival depends on them sticking together as they navigate their now unrecognizable surroundings.","de":"Ein unerklärliches kosmisches Ereignis reißt die Oak Street aus ihrem Vorstadtidyll heraus und befördert die gesamte Nachbarschaft an einen unbekannten Ort. Die Mitglieder der Familie Platt müssen in dieser für sie völlig fremden Umgebung schnell feststellen, dass sie nur dann überleben können, wenn sie eng zusammenstehen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/54mt6Tg2Hj4M9A4mpkGrLktTiJR.jpg","es":"https://image.tmdb.org/t/p/w500/g9DUGw8ufetrwhCIrwq3h1NlpWO.jpg","fr":"https://image.tmdb.org/t/p/w500/yZINaQysj32K2DS2EW4Iy1bK4Bm.jpg","en":"https://image.tmdb.org/t/p/w500/7DmtuAK5gYGlMFA45Oxkl1bEpIC.jpg","de":"https://image.tmdb.org/t/p/w500/4XS0AJqgcl9uNS67hRsrO7Ff4ya.jpg"}'::jsonb WHERE id = 108;
UPDATE public.films SET tmdb_id = 9273, titoli_i18n = '{"it":"Ace Ventura - Missione Africa","en":"Ace Ventura: When Nature Calls","es":"Ace Ventura II. Operación África","fr":"Ace Ventura en Afrique","de":"Ace Ventura - Jetzt wird''s wild"}'::jsonb, trame_i18n = '{"it":"L''acchiappanimali Ace Ventura si reca in Africa per ritrovare Chicca, un raro pipistrello bianco sacro alla tribù dei Ciakaka, la cui scomparsa rischia di scatenare una guerra tribale.","en":"Summoned from an ashram in Tibet, Ace finds himself on a perilous journey into the jungles of Africa to find Shikaka, the missing sacred animal of the friendly Wachati tribe. He must accomplish this before the wedding of the Wachati''s Princess to the prince of the warrior Wachootoos. If Ace fails, the result will be a vicious tribal war.","es":"Intentando superar el trauma que le ha dejado el fracaso de su última misión, donde no pudo evitar que muriera la mofeta que tenía que rescatar, el inefable detective Ace Ventura es requerido en su retiro en un monasterio de monjes budistas por un extraño personaje que le ofrece una fuerte suma de dinero para que trate de encontrar el animal sagrado de una tribu.","fr":"Parce qu’il n’a pu sauver un raton laveur perdu en haute montagne, Ace Ventura s’est retiré dans une lamaserie au Tibet. Mais, à la faveur d’une nouvelle mission, Ace Ventura part en Afrique mettre la main sur une chauve‐souris blanche sacrée disparue avant qu’un conflit n’éclate entre les tribus Wachati et Wachootoo.","de":"Nach dem tragischen Unfall eines Klienten hat sich Tierdetektiv Ace Ventura zum Meditieren in ein tibetanisches Kloster zurückgezogen. Doch schon bald muß der gefragte Schnüffler seine spirituelle Enklave wieder verlassen, um im tiefsten Afrika eine entführte Albino-Fledermaus auftreiben - immerhin steht der Friede zwischen zwei Urwaldstämmen auf dem Spiel. Nach einigen haarsträubenden Dschungelerlebnissen macht der Meisterdetektiv die Gauner dingfest."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/5Ygaz8czBDmTGKtACnFFauUKCOC.jpg","en":"https://image.tmdb.org/t/p/w500/wcinCf1ov2D6M3P7BBZkzQFOiIb.jpg","es":"https://image.tmdb.org/t/p/w500/899yWih4ic8AyczedYiX41g7TvQ.jpg","fr":"https://image.tmdb.org/t/p/w500/pfe3WBJzufMawUiQ9agzitTFcei.jpg","de":"https://image.tmdb.org/t/p/w500/5qWRDf3nYfneEnrIQRoUXqBnLY6.jpg"}'::jsonb WHERE id = 109;
UPDATE public.films SET tmdb_id = 197, titoli_i18n = '{"es":"Braveheart","en":"Braveheart","de":"Braveheart","it":"Braveheart - Cuore impavido","fr":"Braveheart"}'::jsonb, trame_i18n = '{"es":"¿Qué clase de hombre desafiaría a un rey? ''Braveheart'' es una historia épica medieval sobre la independencia de Escocia en el siglo XIII, basada en la leyenda de William Wallace, un montañés escocés que arrastra a su clan a luchar contra la tiranía del rey Eduardo I de Inglaterra. Después del brutal asesinato de su joven esposa por los ingleses, Wallace sólo busca venganza. Hambrientos y en inferior número, Wallace lidera a los patriotas escoceses y consigue organizar un ejército de guerreros sedientos de libertad logrando recuperar con ello el espíritu que haría a Escocia libre para siempre.","en":"Enraged at the slaughter of Murron, his new bride and childhood love, Scottish warrior William Wallace slays a platoon of the local English lord''s soldiers. This leads the village to revolt and, eventually, the entire country to rise up against English rule.","de":"Ende des 13. Jahrhunderts ermorden britische Besatzer die geliebte Frau des in Schottland lebenden William Wallace. Von dieser Tat aufgestachelt und blind vor Rache, mobilisiert er seine schottischen Landleute für einen Feldzug gegen die übermächtigen Engländer. Trotz ihrer nicht nur zahlenmäßigen Unterlegenheit schafft man das Unfassbare und besiegt die Armee des britischen Königs. Nach dem Sieg stehen jedoch nicht alle Schotten hinter Wallace und verraten ihren Freiheitskämpfer.","it":"Nel XIII secolo, dopo l''uccisione della sua amata da parte dei soldati inglesi, il patriota scozzese William Wallace guida una sanguinosa ribellione contro il tirannico re Edoardo I d''Inghilterra per conquistare la libertà della Scozia.","fr":"À la fin du XIIIe siècle, le roi Edward 1er d''Angleterre s''empare du trône d’Écosse, réduisant son peuple à la misère. William Wallace donne le signe de la révolte et, à la tête d''une armée de gueux, parvient à reconquérir plusieurs places fortes. Mais les nobles écossais sont lâchés et par deux fois trahissent le héros de leur peuple…"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/cDMYybBU4COJfTwcPgnihwY5EiP.jpg","en":"https://image.tmdb.org/t/p/w500/or1gBugydmjToAEq7OZY0owwFk.jpg","de":"https://image.tmdb.org/t/p/w500/5MiqFuwgBrvIF3KJ6nWaqUeAe52.jpg","it":"https://image.tmdb.org/t/p/w500/gZvvrgehgqYNy12Z2sP333nn5Nw.jpg","fr":"https://image.tmdb.org/t/p/w500/jMDUKicyulag7KeTWVrblElCMZq.jpg"}'::jsonb WHERE id = 110;
UPDATE public.films SET tmdb_id = 597, titoli_i18n = '{"it":"Titanic","en":"Titanic","de":"Titanic","fr":"Titanic","es":"Titanic"}'::jsonb, trame_i18n = '{"it":"Un giovane artista di umili origini e una ricca nobildonna promessa sposa si innamorano a bordo del transatlantico Titanic durante il suo tragico viaggio inaugurale nel 1912.","en":"101-year-old Rose DeWitt Bukater tells the story of her life aboard the Titanic, 84 years later. A young Rose boards the ship with her mother and fiancé. Meanwhile, Jack Dawson and Fabrizio De Rossi win third-class tickets aboard the ship. Rose tells the whole story from Titanic''s departure through to its death—on its first and last voyage—on April 15, 1912.","de":"Atlantischer Ozean, 1912: Auf der Jungfernfahrt der Titanic trifft der mittellose Maler Jack Dawson auf die schöne, aber unglückliche Erste-Klasse-Passagierin Rose DeWitt Bukater. Rose reist gemeinsam mit ihrer Mutter und ihrem versnobten Verlobten Cal, den sie aus finanziellen Gründen heiraten soll, aber nicht liebt. Als Jack beobachtet, wie Rose über die Reling klettert, um sich ins Meer zu stürzen, und ihren sicheren Tod abwenden kann, beginnt für beide eine Liebesgeschichte über Klassengrenzen hinweg. Gemeinsam mit Jack entdeckt Rose das ausgelassene Leben der einfachen Passagiere unter Deck der Titanic und das wahre Wesen der Liebe. Währenddessen steuert die als unsinkbar geltende Titanic geradewegs auf einen Eisberg zu.","fr":"Southampton, 10 avril 1912. Le paquebot le plus grand et le plus moderne du monde, réputé pour son insubmersibilité, le « Titanic », appareille pour son premier voyage. Quatre jours plus tard, il heurte un iceberg. À son bord, un artiste pauvre et une grande bourgeoise tombent amoureux.","es":"Jack, un joven artista, gana en una partida de cartas un pasaje para viajar a América en el Titanic, el transatlántico más grande y seguro jamás construido. A bordo conoce a Rose, una joven de una buena familia venida a menos que va a contraer un matrimonio de conveniencia con Cal, un millonario engreído a quien sólo interesa el prestigioso apellido de su prometida. Jack y Rose se enamoran, pero el prometido y la madre de ella ponen todo tipo de trabas a su relación. Mientras, el gigantesco y lujoso transatlántico se aproxima hacia un inmenso iceberg."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/i87I2HPumcMkX5Vl48n2XkS5Os7.jpg","en":"https://image.tmdb.org/t/p/w500/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg","de":"https://image.tmdb.org/t/p/w500/MlnPG3oxhfmuiDwcoeElQWui9m.jpg","fr":"https://image.tmdb.org/t/p/w500/vpsvHLkoeKUjceIMeNSqCp3xEyY.jpg","es":"https://image.tmdb.org/t/p/w500/2tltWMvvTqscFtdujTXDsRFTqKQ.jpg"}'::jsonb WHERE id = 111;
UPDATE public.films SET tmdb_id = 333371, titoli_i18n = '{"es":"Calle Cloverfield 10","fr":"10 Cloverfield Lane","en":"10 Cloverfield Lane","it":"10 Cloverfield Lane","de":"10 Cloverfield Lane"}'::jsonb, trame_i18n = '{"es":"Una joven sufre un accidente de coche. Cuando despierta se encuentra encerrada en una celda bajo tierra, secuestrada por un hombre extraño que dice haberla salvado del día del juicio final. El excéntrico captor asegura que el exterior es inhabitable por culpa de un terrible ataque químico, algo que no sabe si creer. Es así como comienza su pesadilla, en una espiral de desconocimiento. La mente del criminal es infranqueable, y ella tendrá que intentar analizar a su enemigo para conseguir sobrevivir.","fr":"Une jeune femme se réveille dans une cave après un accident de voiture. Ne sachant pas comment elle a atterri dans cet endroit, elle pense tout d''abord avoir été kidnappée. Son gardien tente de la rassurer en lui disant qu''il lui a sauvé la vie après une attaque chimique d''envergure. En l''absence de certitude, elle décide de s''échapper…","en":"After a catastrophic car crash, a young woman wakes up in a survivalist''s underground bunker, where he claims to have saved her from an apocalyptic attack that has left the outside world uninhabitable.","it":"Dopo un incidente d''auto, una giovane donna si risveglia in un bunker sotterraneo insieme a un uomo che sostiene di averle salvato la vita da un attacco chimico apocalittico.","de":"Michelle verlässt nach einem Streit New Orleans und fährt davon. Doch dann kommt es auf der wenig befahrenen nächtlichen Straße zu einem schweren Unfall. Die junge Frau verliert das Bewusstsein. Als sie später wieder aufwacht, findet sie sich nicht in einem Krankenhaus wieder, sondern in einem Bunker tief unter der Erde. Howard behauptet, dass er sie gerettet hat und die Umgebung angegriffen wird. Die meisten Menschen sollen demnach schon tot sein. Doch Michelle möchte nicht ewig auf engstem Raum mit fremden Personen zusammenleben. Mit Emmett, dem Dritten im Bunker, schließt sie sich zusammen und plant den Ausbruch aus den Fängen des immer paranoider werdenden Howard. Noch wissen sie nicht, was sie an der Oberfläche erwartet …"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/ksLwEavVceUxYyF8LOjTewmpTp4.jpg","fr":"https://image.tmdb.org/t/p/w500/gAw5nJGNDI2hyw2ghBLoD6rSk3Y.jpg","en":"https://image.tmdb.org/t/p/w500/q8A39vcBDruhvoDTJd6L8a4lnTi.jpg","it":"https://image.tmdb.org/t/p/w500/266EUEBypO6shSfYwUpaCeNPCAb.jpg","de":"https://image.tmdb.org/t/p/w500/kbrhW3WfutKdIPd70orhh1gVZ8n.jpg"}'::jsonb WHERE id = 112;
UPDATE public.films SET tmdb_id = 384521, titoli_i18n = '{"es":"The Cloverfield Paradox","it":"The Cloverfield Paradox","fr":"The Cloverfield Paradox","en":"The Cloverfield Paradox","de":"The Cloverfield Paradox"}'::jsonb, trame_i18n = '{"es":"Con la Tierra en guerra y en mitad de una crisis energética, un equipo de astronautas se encuentra en el espacio tratando de dar con una solución a los problemas del planeta. Pero durante una maniobra fallida, quedan flotando sin saber muy bien qué o cómo volver a su lugar de origen, y las cosas dentro de la nave ocultan una realidad mucho más terrorífica.","it":"Un gruppo di scienziati a bordo di una stazione spaziale testa un acceleratore di particelle per risolvere una crisi energetica globale, ma si ritrova in una dimensione alternativa.","fr":"Une équipe de scientifiques envoyée en orbite pour sauver la planète d''une destruction imminente se retrouve face à une sombre réalité alternative.","en":"Orbiting above a planet on the brink of war, scientists test a device to solve an energy crisis and end up face-to-face with a dark alternate reality.","de":"In fünf Jahren werden die Energieressourcen der Erde komplett erschöpft sein. Im Orbit vor der Erde treibend, versuchen Wissenschaftler auf einer Raumstation, die Energiekrise zu lösen. Ein riskantes Experiment mit dem Shepard-Teilchenbeschleuniger soll die Lösung bringen: Funktioniert es, wäre die Energiekrise gelöst! Doch etwas geht schief – die Wissenschaftler entdecken eine alternative Realität und kämpfen bald um ihr Leben."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/hyeJDZxsXatr2XoPtH46NRrQ6aW.jpg","it":"https://image.tmdb.org/t/p/w500/hxKqEX748hwOkgcxs498x5qQ7Vk.jpg","fr":"https://image.tmdb.org/t/p/w500/vJi2ExTcWdJR3150VPKqqtdGxsT.jpg","en":"https://image.tmdb.org/t/p/w500/vJi2ExTcWdJR3150VPKqqtdGxsT.jpg","de":"https://image.tmdb.org/t/p/w500/3YZmwZirewbDyucLNMWZr3BZYMK.jpg"}'::jsonb WHERE id = 113;
UPDATE public.films SET tmdb_id = 763400, titoli_i18n = '{"it":"Il grande Lebowski","fr":"The Making of ''The Big Lebowski''","en":"The Making of ''The Big Lebowski''","de":"The Making of ''The Big Lebowski''","es":"The Making of ''The Big Lebowski''"}'::jsonb, trame_i18n = '{"en":"A short documentary about the production of \"The Big Lebowski\" (1998).","it":"Jeffrey ''Drugo'' Lebowski, un fannullone pacifista di Los Angeles, viene scambiato per un miliardario suo omonimo. Dopo che dei sicari urinano sul suo tappeto preferito, Drugo si mette alla ricerca di un risarcimento, finendo invischiato in un bizzarro mistero tra rapimenti e nichilisti."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg","fr":"https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg","en":"https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg","de":"https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg","es":"https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg"}'::jsonb WHERE id = 114;
UPDATE public.films SET tmdb_id = 680, titoli_i18n = '{"es":"Pulp Fiction","en":"Pulp Fiction","fr":"Pulp Fiction","de":"Pulp Fiction","it":"Pulp Fiction"}'::jsonb, trame_i18n = '{"es":"Jules y Vincent, dos asesinos a sueldo con muy pocas luces, trabajan para Marsellus Wallace. Vincent le confiesa a Jules que Marsellus le ha pedido que cuide de Mia, su mujer. Jules le recomienda prudencia porque es muy peligroso sobrepasarse con la novia del jefe. Cuando llega la hora de trabajar, ambos deben ponerse manos a la obra. Su misión: recuperar un misterioso maletín.","en":"A burger-loving hit man, his philosophical partner, a drug-addled gangster''s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.","fr":"L’odyssée sanglante et burlesque de petits malfrats dans la jungle d’Hollywood : Deux petits tueurs, un dangereux gangster marié à une camée, un boxeur roublard, des prêteurs sur gages sadiques, un caïd élégant et dévoué, un dealer bon mari et deux tourtereaux à la gâchette facile.","de":"Vincent Vega und Jules Winnfield holen für ihren Boss Marsellus Wallace eine schwarze Aktentasche aus einer Wohnung ab. Drei Jungs, die ihnen dabei im Weg stehen, lassen ihr Leben. Die Killer machen sich mit einem vierten Jungen als Geisel auf den Weg ins Hauptquartier. Doch als das Auto über eine Straßenerhöhung schaukelt, erschießt Vincent aus Versehen die Geisel. Um den blutverspritzten Wagen zu reinigen, machen die beiden einen Abstecher zu Jules''s Freund Jimmie, wo auf Befehl vom Boss ein Spezialist für schwierige Aufträge zu ihnen stößt: The Wolf...","it":"Le vite di due killer della mafia, della moglie del loro capo, di un pugile in fuga e di una coppia di rapinatori si intrecciano in una serie di bizzarri e drammatici eventi a Los Angeles."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/hNcQAuquJxTxl2fJFs1R42DrWcf.jpg","en":"https://image.tmdb.org/t/p/w500/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg","fr":"https://image.tmdb.org/t/p/w500/4TBdF7nFw2aKNM0gPOlDNq3v3se.jpg","de":"https://image.tmdb.org/t/p/w500/hOg9USqmQmglmr5kGvpyg1XkhqN.jpg","it":"https://image.tmdb.org/t/p/w500/hOpN58hkQGZph5LHhyRrryy1hzF.jpg"}'::jsonb WHERE id = 115;
UPDATE public.films SET tmdb_id = 152601, titoli_i18n = '{"it":"Lei","es":"Her","fr":"Her","en":"Her","de":"Her"}'::jsonb, trame_i18n = '{"it":"In un futuro non troppo lontano, Theodore, un uomo solitario e introverso che scrive lettere d''amore per conto terzi, acquista un nuovo sistema operativo basato su un''intelligenza artificiale estremamente avanzata. Ben presto, tra Theodore e la voce del sistema operativo, che si autodefinisce Samantha, nasce una profonda e insolita relazione sentimentale.","es":"En un futuro cercano, Theodore, un hombre solitario a punto de divorciarse que trabaja en una empresa como escritor de cartas para terceras personas, compra un día un nuevo sistema operativo basado en el modelo de Inteligencia Artificial, diseñado para satisfacer todas las necesidades del usuario. Para su sorpresa, se crea una relación romántica entre él y Samantha, la voz femenina de ese sistema operativo.","fr":"Los Angeles, dans un futur proche. Theodore Twombly, un homme sensible au caractère complexe, est inconsolable suite à une rupture difficile. Il fait alors l''acquisition d''un programme informatique ultramoderne, capable de s''adapter à la personnalité de chaque utilisateur. En lançant le système, il fait la connaissance de ''Samantha'', une voix féminine intelligente, intuitive et étonnamment drôle. Les besoins et les désirs de Samantha grandissent et évoluent, tout comme ceux de Theodore, et peu à peu, ils tombent amoureux…","en":"In the not so distant future, Theodore, a lonely writer, purchases a newly developed operating system designed to meet the user''s every need. To Theodore''s surprise, a romantic relationship develops between him and his operating system. This unconventional love story blends science fiction and romance in a sweet tale that explores the nature of love and the ways that technology isolates and connects us all.","de":"In was verliebt man sich bei seinem Gegenüber zuerst? Die Augen, das Gesicht, die Hände, die Stimme? Im Falle von Theodore Twombly ist es die Stimme. Ihm bleibt auch nichts anderes als die Stimme, denn Samantha ist körperlos. Sie ist die Stimme von Theodores neuem Betriebssystem, das über eine künstliche Intelligenz verfügt – und anscheinend auch über Emotionen. Bis vor kurzem noch trudelte Theodore, professioneller Verfasser einfühlsamer Briefe für Kunden, denen die passenden Worte fehlen, recht haltlos durchs Leben, nachdem seine langjährige Beziehung mit Catherine in die Brüche gegangen ist. Doch zu seiner Verwunderung entwickelt Theodore zur Computerstimme Samantha Gefühle, die schnell über eine bloße Schwärmerei hinausgehen. Von seiner Umwelt kritisch beäugt muss sich Theodore die Frage gefallen lassen: Ist solch eine Liebe möglich?"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ptoIaqRBgyBVMKXRG2V2afFqDut.jpg","es":"https://image.tmdb.org/t/p/w500/xPby6SuDafflEL7EWVHTFmhJsDp.jpg","fr":"https://image.tmdb.org/t/p/w500/nkWXW5blXGmOEoDejRgy83sSb6T.jpg","en":"https://image.tmdb.org/t/p/w500/eCOtqtfvn7mxGl6nfmq4b1exJRc.jpg","de":"https://image.tmdb.org/t/p/w500/eCOtqtfvn7mxGl6nfmq4b1exJRc.jpg"}'::jsonb WHERE id = 116;
UPDATE public.films SET tmdb_id = 207, titoli_i18n = '{"it":"L''attimo fuggente","es":"El club de los poetas muertos","fr":"Le Cercle des poètes disparus","en":"Dead Poets Society","de":"Der Club der toten Dichter"}'::jsonb, trame_i18n = '{"it":"In un rigido collegio maschile del Vermont nel 1959, l''arrivo di un nuovo professore di letteratura, John Keating, sconvolge le vite degli studenti. Con i suoi metodi d''insegnamento anticonformisti, Keating insegna ai ragazzi ad amare la poesia, a pensare con la propria testa e a cogliere l''attimo.","es":"En un elitista y estricto colegio privado de Nueva Inglaterra, un grupo de alumnos descubrirá la poesía, el significado de \"Carpe Diem\" -aprovechar el momento- y la importancia de perseguir los sueños, gracias a un excéntrico profesor que despierta sus mentes por medio de métodos poco convencionales.","fr":"Todd Anderson est un garçon plutôt timide. Désormais élève de la prestigieuse académie Welton, réputée pour être l''une des plus fermées et austères des États-Unis, tout le monde attend de lui qu''il suive les traces de son frère, qui avait fait à Welton de brillantes études.  C''est là qu''il va faire la rencontre de M. Keating, un professeur de lettres anglaises qui, c''est le moins que l''on puisse dire, sort des sentiers battus. Jour après jour, M. Keating encourage ses élèves à penser par eux-mêmes et à refuser l''ordre établi. Cette rencontre va bouleverser la vie du jeune Todd, mais aussi celle de ses amis.","en":"At an elite, old-fashioned boarding school in New England, a passionate English teacher inspires his students to rebel against convention and seize the potential of every day, courting the disdain of the stern headmaster.","de":"Der neue Literaturlehrer John Keating bringt 1959 frischen Wind in das Traditionsinternat Welton und inspiriert seine ansonsten zur Disziplin erzogenen Schüler durch sein unorthodoxes Vermitteln von Poesie zu freiem Denken. Des Nachts treffen sie sich zu Lesungen in einer alten Höhle. Der Junge Neil entdeckt seine Liebe zur Schauspielerei. Als sein gestrenger Vater davon erfährt, nimmt er Neil von der Schule. Seiner Träume beraubt, erschießt sich Neil. Keating wird verantwortlich gemacht und der Schule verwiesen. Als er seine Bücher abholt, sprechen ihm seine Schüler durch kollektive Verweigerung ihren Dank für seine Menschlichkeit aus."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/nIH9ZI4aA8zd0tQSduMWtpniyyH.jpg","es":"https://image.tmdb.org/t/p/w500/vsLcmuk8KBN73spAIEwm1nLNSjc.jpg","fr":"https://image.tmdb.org/t/p/w500/oHBdsvdlPhzkJZOfax7Oy3X5mm7.jpg","en":"https://image.tmdb.org/t/p/w500/erzbMlcNHOdx24AXOcn2ZKA7R1q.jpg","de":"https://image.tmdb.org/t/p/w500/qUV8UUGa1596hbOWzJ8AfppjpGd.jpg"}'::jsonb WHERE id = 117;
UPDATE public.films SET tmdb_id = 273248, titoli_i18n = '{"en":"The Hateful Eight","it":"The Hateful Eight","de":"The Hateful 8","es":"Los odiosos ocho","fr":"Les Huit Salopards"}'::jsonb, trame_i18n = '{"en":"Bounty hunters seek shelter from a raging blizzard and get caught up in a plot of betrayal and deception.","it":"Qualche anno dopo la guerra civile americana, una diligenza si fa strada nel paesaggio innevato del Wyoming. I passeggeri, tra cui il cacciatore di taglie John Ruth e la sua prigioniera Daisy Domergue, cercano rifugio da una tempesta di neve in un emporio, dove si imbattono in altri loschi personaggi. La diffidenza e la tensione tra i presenti porteranno a una sanguinosa resa dei conti.","de":"Irgendwo im verschneiten Wyoming, einige Jahre nach dem Bürgerkrieg: Eine Postkutsche kämpft sich auf dem Weg zum Städtchen Red Rock durch die Landschaft. An Bord sind der Kopfgeldjäger John Ruth, seine Gefangene Daisy Domergue und zwei erst auf dem Weg zugestiegene Passagiere: der Ex-Soldat und nun ebenfalls als Kopfgeldjäger tätige Marquis Warren sowie Chris Mannix, der angibt, der neue Sheriff von Red Rock zu sein. Aufgrund eines heftigen Schneesturms sind sie jedoch dazu gezwungen, in einer Hütte Zuflucht zu suchen. Dort verstecken sich bereits der Mexikaner Bob, der undurchsichtige Oswaldo Mobray, der Cowboy Joe Gage und der in die Jahre gekommene Südstaaten-General Sanford Smithers vor dem Wetter. Schnell nehmen die Spannungen in der Gruppe von misstrauischen Raubeinen zu, nachdem man sich anfangs noch bestens unterhalten hat. Und bald wird klar, dass längst nicht jeder von ihnen die Hütte lebend verlassen wird.","es":"Seis, ocho o doce años después de la Guerra de Secesión, una diligencia avanza a toda velocidad por el invernal paisaje de Wyoming. Los pasajeros, el cazarrecompensas John Ruth y su fugitiva Daisy Domergue, intentan llegar rápidamente al pueblo de Red Rock, donde Ruth, conocido en estos lares como ''el Verdugo'', entregará a Domergue a la justicia. Por el camino, se encuentran con dos desconocidos: el mayor Marquis Warren, un antiguo soldado negro de la Unión convertido en cazarrecompensas de mala reputación, y Chris Mannix, un renegado sureño que afirma ser el nuevo sheriff del pueblo. Como una ventisca está a punto de alcanzarlos, Ruth, Domergue, Warren y Mannix se refugian en la Mercería de Minnie, una parada para diligencias de un puerto de montaña. Cuando llegan al local de Minnie, en lugar de recibirlos su dueña, se topan con cuatro rostros desconocidos.","fr":"Après la Guerre de Sécession, huit voyageurs se retrouvent coincés dans un refuge au milieu des montagnes. Alors que la tempête s''abat au-dessus du massif, ils réalisent qu''ils n''arriveront peut-être pas à rallier Red Rock comme prévu…"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/jIywvdPjia2t3eKYbjVTcwBQlG8.jpg","it":"https://image.tmdb.org/t/p/w500/2ogVOei8k5WPixP2RVJFMn16zII.jpg","de":"https://image.tmdb.org/t/p/w500/kicXJhMpeB5xFbBG4EHcfIyOnyK.jpg","es":"https://image.tmdb.org/t/p/w500/7DYGdFT4gtiD5BI6xyOU6v0XXvi.jpg","fr":"https://image.tmdb.org/t/p/w500/kV6ogsiIYzV2qZ43bLuDKuEAIR.jpg"}'::jsonb WHERE id = 118;
UPDATE public.films SET tmdb_id = 315635, titoli_i18n = '{"it":"Spider-Man: Homecoming","en":"Spider-Man: Homecoming","es":"Spider-Man: Homecoming","de":"Spider-Man: Homecoming","fr":"Spider-Man : Homecoming"}'::jsonb, trame_i18n = '{"it":"Il giovane Peter Parker, entusiasta della sua esperienza con gli Avengers, torna a casa dove vive con la zia May. Sotto l''occhio vigile del suo mentore Tony Stark, Peter cerca di trovare un equilibrio tra la sua vita da normale studente e la sua identità segreta di Spider-Man, ma l''arrivo del villain Avvoltoio metterà tutto a rischio.","en":"Following the events of Captain America: Civil War, Peter Parker, with the help of his mentor Tony Stark, tries to balance his life as an ordinary high school student in Queens, New York City, with fighting crime as his superhero alter ego Spider-Man as a new threat, the Vulture, emerges.","es":"Peter Parker comienza a experimentar su recién descubierta identidad como el superhéroe Spider-Man. Después de la experiencia vivida con los Vengadores, Peter regresa a casa, donde vive con su tía. Bajo la atenta mirada de su mentor Tony Stark, Peter intenta mantener una vida normal como cualquier joven de su edad, pero interrumpe en su rutina diaria el nuevo villano Vulture y, con él, lo más importante de la vida de Peter comenzará a verse amenazado.","de":"Nach seinem Aufeinandertreffen mit den Avengers ist Peter Parker alias Spider-Man wieder zurück in New York, wo er bei seiner Tante May wohnt. Seitdem er mit bzw. gegen die anderen Helden kämpfte, fragt er sich, ob er mit seinen herausragenden Fähigkeiten nicht mehr machen sollte, als nur die freundliche Spinne aus der Nachbarschaft zu sein, die den einen oder anderen Einbruch verhindert und Taschendiebe stoppt. Doch daneben muss der von seinem neuen Mentor Tony Stark geförderte Jugendliche auch noch den Alltag auf die Reihe bekommen, den Alltag als Teenager an einer Highschool, wo er sich in Liz verguckt hat. Blöd, dass ausgerechnet in dieser Situation ein Bösewicht für Unruhe sorgt, der technisch bestens ausgestattet ist und von Rachedurst getrieben: der Vogelmann Vulture.","fr":"Après ses spectaculaires débuts dans Captain America : Civil War, le jeune Peter Parker découvre peu à peu sa nouvelle identité, celle de Spider-Man, le super-héros lanceur de toile. Galvanisé par son expérience avec les Avengers, Peter rentre chez lui auprès de sa tante May, sous l’œil attentif de son nouveau mentor, Tony Stark. Il s’efforce de reprendre sa vie d’avant, mais au fond de lui, Peter rêve de se prouver qu’il est plus que le sympathique super héros du quartier. L’apparition d’un nouvel ennemi, le Vautour, va mettre en danger tout ce qui compte pour lui..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9OYK3q83z0LmFOx3xZXfdaVck2d.jpg","en":"https://image.tmdb.org/t/p/w500/c24sv2weTHPsmDa7jEMN0m2P3RT.jpg","es":"https://image.tmdb.org/t/p/w500/bRl6C6FwzTndk0MBGZZ68nRFlw3.jpg","de":"https://image.tmdb.org/t/p/w500/elU7H73qN3WEQmmfdn0CdH3q8H8.jpg","fr":"https://image.tmdb.org/t/p/w500/wFNNv1ZHglNdXJLYiEgpLY5sa9S.jpg"}'::jsonb WHERE id = 119;
UPDATE public.films SET tmdb_id = 429617, titoli_i18n = '{"es":"Spider-Man: Lejos de casa","it":"Spider-Man: Far From Home","de":"Spider-Man: Far From Home","fr":"Spider-Man : Far From Home","en":"Spider-Man: Far From Home"}'::jsonb, trame_i18n = '{"es":"Peter Parker decide irse junto a MJ, Ned y el resto de sus amigos a pasar unas vacaciones a Europa. Sin embargo, el plan de Parker por dejar de lado sus superpoderes durante unas semanas se ven truncados cuando Nick Fury contacta con él para solicitarle ayuda para frenar el ataque de unas criaturas elementales que están causando el caos en el continente. En ese momento, Parker vuelve a ponerse el traje de Spider-Man para cumplir con su labor.","it":"Peter Parker decide di unirsi ai suoi migliori amici per una vacanza in Europa. Tuttavia, il piano di Peter di lasciarsi i superpoteri alle spalle per qualche settimana viene sventato quando accetta di aiutare Nick Fury a svelare il mistero degli attacchi di diverse creature elementali.","de":"Nach der epischen Schlacht gegen Thanos und den schicksalshaften Ereignissen um die Avengers ist Peter zurück an seiner alten Schule. Um vom Superheldendasein etwas auszuruhen, kommt ihm eine Klassenfahrt nach Europa gerade recht, auch um seiner heimlichen Liebe \"MJ\" endlich seine Gefühle gestehen zu können. Die erste Station ist Venedig in Italien. Nach einer entspannten Gondelfahrt mit der Reisegruppe bricht aber plötzlich das Chaos los: Ein riesiges Monster kommt aus dem Wasser und greift die Stadt an. Dem stellt sich ein bisher unbekannter Superheld namens Mysterio entgegen. Und als wäre das nicht genug, taucht dann noch Nick Fury auf, um Spider-Man für eine Mission zu rekrutieren...","fr":"Peter et ses amis passent leurs vacances d’été en Europe. Mais ils n’auront pas vraiment l’occasion de se reposer puisque Peter accepte d’aider Nick Fury pour débusquer les mystérieuses créatures qui sont la cause des catastrophes naturelles qui frappent le continent.","en":"Peter Parker and his friends go on a summer trip to Europe. However, they will hardly be able to rest - Peter will have to agree to help Nick Fury uncover the mystery of creatures that cause natural disasters and destruction throughout the continent."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/iKVR1ba3W1wCm9bVCcpnNvxQUWX.jpg","it":"https://image.tmdb.org/t/p/w500/blWCg2gs0uQiEl4e3ml6j3yDSKg.jpg","de":"https://image.tmdb.org/t/p/w500/mp2rchOm2nchJ3E3fPzTFzkuLd3.jpg","fr":"https://image.tmdb.org/t/p/w500/xVYGzjMaHVwNQ9STT5ZXcz7knsB.jpg","en":"https://image.tmdb.org/t/p/w500/4q2NNj4S5dG2RLF9CpXsej7yXl.jpg"}'::jsonb WHERE id = 120;
UPDATE public.films SET tmdb_id = 634649, titoli_i18n = '{"it":"Spider-Man: No Way Home","fr":"Spider-Man : No Way Home","de":"Spider-Man: No Way Home","en":"Spider-Man: No Way Home","es":"Spider-Man: No Way Home"}'::jsonb, trame_i18n = '{"it":"Per la prima volta nella storia cinematografica di Spider-Man, viene rivelata l''identità del nostro amichevole eroe di quartiere. Quando Peter chiede aiuto al Dottor Strange per ripristinare il suo segreto, l''incantesimo squarcia un buco nel loro mondo, liberando i più potenti nemici mai affrontati da uno Spider-Man in qualsiasi universo.","fr":"Après les événements liés à l''affrontement avec Mysterio, l''identité secrète de Spider-Man a été révélée. Il est poursuivi par le gouvernement américain, qui l''accuse du meurtre de Mysterio, et traqué par les médias. Cet événement a également des conséquences terribles sur la vie de sa petite-amie M.J. et de son meilleur ami Ned. Désemparé, Peter Parker demande alors de l''aide au docteur Strange. Ce dernier lance un sort pour que tout le monde oublie que Peter est Spider-Man. Mais les choses ne se passent pas comme prévu, et cette action altère la stabilité de l''espace-temps. Cela ouvre le « multivers », un concept terrifiant dont ils ne savent quasiment rien...","de":"Peter Parker ist demaskiert und kann sein normales Leben nicht mehr von den hohen Einsätzen als Superheld trennen. Als er Doctor Strange um Hilfe bittet, wird die Lage noch gefährlicher und er muss entdecken, was es wirklich bedeutet, Spider-Man zu sein.","en":"Peter Parker is unmasked and no longer able to separate his normal life from the high-stakes of being a super-hero. When he asks for help from Doctor Strange the stakes become even more dangerous, forcing him to discover what it truly means to be Spider-Man.","es":"Peter Parker es desenmascarado y por tanto no es capaz de separar su vida normal de los enormes riesgos que conlleva ser un súper héroe. Cuando pide ayuda a Doctor Strange, los riesgos pasan a ser aún más peligrosos, obligándole a descubrir lo que realmente significa ser Spider-Man."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/xLnZ0DB06H0MuGXcF0uhJxr6b8y.jpg","fr":"https://image.tmdb.org/t/p/w500/jwfDFqzxBkXC5bERBZrCEfK9iii.jpg","de":"https://image.tmdb.org/t/p/w500/iNKf4D0AzOj9GLq8ZyG3WZaqibL.jpg","en":"https://image.tmdb.org/t/p/w500/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg","es":"https://image.tmdb.org/t/p/w500/accAPImdjUwgNgocDNWXCGFEcvL.jpg"}'::jsonb WHERE id = 121;
UPDATE public.films SET tmdb_id = 603, titoli_i18n = '{"en":"The Matrix","es":"Matrix","fr":"Matrix","de":"Matrix","it":"Matrix"}'::jsonb, trame_i18n = '{"en":"Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.","es":"Thomas Anderson lleva una doble vida: por el día es programador en una importante empresa de software, y por la noche un hacker informático llamado Neo. Su vida no volverá a ser igual cuando unos misteriosos personajes le inviten a descubrir la respuesta a la pregunta que no le deja dormir: ¿qué es Matrix?","fr":"Programmeur anonyme dans un service administratif le jour, Thomas Anderson devient Neo la nuit venue. Sous ce pseudonyme, il est l''un des pirates les plus recherchés du cyber‐espace. À cheval entre deux mondes, Neo est assailli par d''étranges songes et des messages cryptés provenant d''un certain Morpheus. Celui‐ci l''exhorte à aller au‐delà des apparences et à trouver la réponse à la question qui hante constamment ses pensées : qu''est‐ce que la Matrice ? Nul ne le sait, et aucun homme n''est encore parvenu à en percer les défenses. Mais Morpheus est persuadé que Neo est l''Élu, le libérateur mythique de l''humanité annoncé selon la prophétie. Ensemble, ils se lancent dans une lutte sans retour contre la Matrice et ses terribles agents…","de":"Der Hacker Neo wird übers Internet von einer geheimnisvollen Untergrund-Organisation kontaktiert. Der Kopf der Gruppe – der gesuchte Terrorist Morpheus – weiht ihn in ein entsetzliches Geheimnis ein: Die Realität, wie wir sie erleben, ist nur eine Scheinwelt. In Wahrheit werden die Menschen längst von einer unheimlichen virtuellen Macht beherrscht – der „Matrix“, deren Agenten Neo bereits im Visier haben …","it":"Un programmatore e hacker di nome Neo scopre che la realtà che vive è una simulazione virtuale creata da macchine senzienti, unendosi a un gruppo di ribelli per liberare l''umanità."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/dXNAPwY7VrqMAo51EKhhCJfaGb5.jpg","es":"https://image.tmdb.org/t/p/w500/tpW2X2DvxtTHJ61iJ7zNYYrJihs.jpg","fr":"https://image.tmdb.org/t/p/w500/pEoqbqtLc4CcwDUDqxmEDSWpWTZ.jpg","de":"https://image.tmdb.org/t/p/w500/iVmDLujHcV1zaMnaahKWn4TcCS6.jpg","it":"https://image.tmdb.org/t/p/w500/3vmTUXJHlKkvenf8G35dr5HlTEh.jpg"}'::jsonb WHERE id = 122;
UPDATE public.films SET tmdb_id = 604, titoli_i18n = '{"fr":"Matrix Reloaded","es":"Matrix Reloaded","en":"The Matrix Reloaded","de":"Matrix Reloaded","it":"Matrix Reloaded"}'::jsonb, trame_i18n = '{"fr":"Neo apprend à mieux contrôler ses dons naturels, alors même que Sion s''apprête à tomber sous l''assaut de l''Armée des Machines. D''ici quelques heures, 250 000 Sentinelles programmées pour anéantir notre espèce envahiront la dernière enclave humaine de la Terre. Mais Morpheus galvanise les citoyens de Sion en leur rappelant la Parole de l''Oracle : il est encore temps pour l’Élu d''arrêter la guerre contre les Machines. Tous les espoirs se reportent dès lors sur Neo. Au long de sa périlleuse plongée au sein de la Matrice et de sa propre destinée, ce dernier sera confronté à une résistance croissante, une vérité encore plus aveuglante, un choix encore plus douloureux que tout ce qu''il avait jamais imaginé.","es":"Las máquinas avanzan imparables hacia Zion en su afán por destruir a toda la humanidad y todas las naves se preparan para la dura batalla. Neo junto con Morfeo y Trinity buscan el camino del elegido dentro de Matrix para vencer a las máquinas y se encuentran con dificultades inesperadas: el agente Smith ha vuelto y no sólo eso, otros programas dentro de Matrix intentarán acabar con su misión. Mientras tanto Neo se tendrá que adaptar a la vida real y a la fama de ser el elegido.","en":"The Resistance builds in numbers as humans are freed from the Matrix and brought to the city of Zion. Neo discovers his superpowers, including the ability to see the code inside the Matrix. With machine sentinels digging to Zion in 72 hours, Neo, Morpheus and Trinity must find the Keymaker to ultimately reach the Source.","de":"Die Wächter schwärmen aus. Smith klont sich. Neo fliegt … aber vielleicht kann selbst der Auserwählte mit seinen atemberaubenden neuen Fähigkeiten den Angriff der Maschinen nicht mehr aufhalten.  Neo. Morpheus. Trinity. Zurück im spannenden zweiten Kapitel der Matrix-Trilogie treffen sie auf außergewöhnliche Verbündete: Gemeinsam bekämpfen sie ihre Gegner, die sich klonen, durch Upgrades immer stärker werden und die letzte Festung der Menschheit belagern.","it":"Mentre l''esercito delle macchine prepara un attacco contro Zion, Neo scopre maggiori dettagli sul suo destino come l''Eletto e affronta una minaccia crescente rappresentata dall''Agente Smith."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/lF5HiiRmBlL3mc5SnO4QsdmlvOb.jpg","es":"https://image.tmdb.org/t/p/w500/7IZk3Xp3HIpRJGXFYNvzmyRwDlt.jpg","en":"https://image.tmdb.org/t/p/w500/8xEVAe84zlL9rkfYT6dZXero4KK.jpg","de":"https://image.tmdb.org/t/p/w500/eq7GAThE7piM4SsUIgRJQzU4lLB.jpg","it":"https://image.tmdb.org/t/p/w500/uWkkhMhJKBsjPkbPcRm4nlYUZxH.jpg"}'::jsonb WHERE id = 123;
UPDATE public.films SET tmdb_id = 605, titoli_i18n = '{"it":"Matrix Revolutions","es":"Matrix Revolutions","en":"The Matrix Revolutions","fr":"Matrix Revolutions","de":"Matrix Revolutions"}'::jsonb, trame_i18n = '{"it":"L''assedio a Zion raggiunge il culmine mentre Neo stringe un patto con la città delle macchine per fermare l''Agente Smith, divenuto un virus capace di distruggere entrambi i mondi.","es":"Quedan veinte horas para la irrupción de las máquinas en Sión, el último bastión de los humanos libres. Mientras el cuerpo de Neo permanece en coma, su consciencia se encuentra en tierra de nadie, en un lugar entre el mundo humano y el de las máquinas.","en":"The human city of Zion defends itself against the massive invasion of the machines as Neo fights to end the war at another front while also opposing the rogue Agent Smith.","fr":"La longue quête de liberté des rebelles culmine en une bataille finale explosive. Tandis que l''armée des Machines sème la désolation sur Sion, ses citoyens organisent une défense acharnée. Mais pourront-ils retenir les nuées implacables des Sentinelles en attendant que Neo s''approprie l''ensemble de ses pouvoirs et mette fin à la guerre ? L''agent Smith est quant à lui parvenu à prendre possession de l''esprit de Bane, l''un des membres de l''équipage de l''aéroglisseur. De plus en plus puissant, il est désormais incontrôlable et n''obéit plus aux Machines : il menace de détruire leur empire ainsi que le monde réel et la Matrice…","de":"Die letzte Schlacht gegen die Maschinen kämpfen Neo, der Auserwählte, Rebellionsführer Morpheus und ihre Verbündeten – ein Krieg, der in den Ruinen der realen Welt geführt wird, der das Schicksal der Menschheit besiegelt und dessen Sieg in den Händen von Neo liegt, der seinerseits eine Reihe von Überraschungen zu erwarten hat."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/cGprSBfxwOxgExQnwFz39XKl3H2.jpg","es":"https://image.tmdb.org/t/p/w500/zi1UMF9jIM2JnQz0u2AyUw8QFZi.jpg","en":"https://image.tmdb.org/t/p/w500/qEWiBXJGXK28jGBAm8oFKKTB0WD.jpg","fr":"https://image.tmdb.org/t/p/w500/xOCeckuZDzqydvt3vLlzftZkef1.jpg","de":"https://image.tmdb.org/t/p/w500/8lVaiIfbyZ5Oe3nLJoeAVRUXKAb.jpg"}'::jsonb WHERE id = 124;
UPDATE public.films SET tmdb_id = 624860, titoli_i18n = '{"it":"Matrix Resurrections","es":"Matrix Resurrections","de":"Matrix Resurrections","en":"The Matrix Resurrections","fr":"Matrix Resurrections"}'::jsonb, trame_i18n = '{"it":"Neo vive una vita ordinaria a San Francisco sotto l''identità di Thomas Anderson, finché non viene risvegliato da un nuovo gruppo di ribelli per liberare Trinity da una versione aggiornata di Matrix.","es":"En un mundo compuesto por dos realidades, lo cotidiano y lo oculto tras ella, Thomas Anderson se ve obligado de nuevo a ir tras el conejo blanco. Dicha elección continúa siendo la vía de acceso a Matrix, que esta vez es más poderosa e intrincada que en ocasiones anteriores.","de":"Thomas Anderson lebt ein normales Leben, arbeitet für eine große Firma und geht regelmäßig zur Therapie, wo sein Therapeut versucht, ihm seine Traumata auszutreiben. Denn Thomas hat Probleme damit, Realität und Fiktion auseinanderzuhalten. Er kann doch nicht wirklich einst als Auserwählter Neo in den Krieg gegen die Maschinen gezogen sein, oder?","en":"Plagued by strange memories, Neo''s life takes an unexpected turn when he finds himself back inside the Matrix.","fr":"Dix-huit ans après les événements de Matrix Revolutions, Thomas A. Anderson (alias Neo) ne se souvient plus de rien et mène une vie d''apparence normale à San Francisco. Il se rend régulièrement chez un psychiatre à qui il raconte ses rêves étranges et qui lui prescrit des pilules bleues. Après la réapparition de visages familiers et en quête de réponses, Neo repart à la recherche du lapin blanc. Il rencontre un certain Morpheus, qui lui offre le choix entre rester dans la Matrice et prendre son envol."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/sZCT1D5yLNVHarTpv157FaLzPCc.jpg","es":"https://image.tmdb.org/t/p/w500/dLIwpCTf4QoW01pp85KP9jcfTpu.jpg","de":"https://image.tmdb.org/t/p/w500/hF7jgEhP4ypR2oS5BQD1pxbg7QY.jpg","en":"https://image.tmdb.org/t/p/w500/8c4a8kE7PizaGQQnditMmI1xbRp.jpg","fr":"https://image.tmdb.org/t/p/w500/kCF43aQ77ShTfKyY8vAJBVHN5j3.jpg"}'::jsonb WHERE id = 125;
UPDATE public.films SET tmdb_id = 429, titoli_i18n = '{"it":"Il buono, il brutto, il cattivo","en":"The Good, the Bad and the Ugly","es":"El bueno, el feo y el malo","de":"Zwei glorreiche Halunken","fr":"Le Bon, la Brute et le Truand"}'::jsonb, trame_i18n = '{"it":"Durante la guerra di secessione americana, tre cinici fuorilegge - il ''Buono'' (Joe), il ''Brutto'' (Tuco) e il ''Cattivo'' (Sentenza) - cercano un tesoro nascosto contenente 200.000 dollari in oro confederato, muovendosi tra alleanze precarie, inganni e scontri mortali.","en":"While the Civil War rages on between the Union and the Confederacy, three men – a quiet loner, a ruthless hitman, and a Mexican bandit – comb the American Southwest in search of a strongbox containing $200,000 in stolen gold.","es":"Durante la Guerra de Secesión, tres cazadores de recompensas se lanzan a la búsqueda de un tesoro que ninguno de los tres truhanes puede localizar sin la ayuda de los otros dos. Tuco sabe que el tesoro se encuentra en un cementerio, mientras que Joe conoce el nombre inscrito en la tumba que lo esconde. Mientras tanto, Sentenza no duda en matar a mujeres y niños para conseguir su meta. De esta forma, los tres hombres colaboran en apariencia, pero al final intentarán eliminarse mutuamente.","de":"Ein mysteriöser Fremder, der mexikanische Revolverschütze Tuco und Sentenza, ein sadistischer Krimineller, sind auf der Jagd nach einer Geldkassette. Inhalt: 200.000 Dollar. Die drei Desperados haben untereinander nichts gemeinsam - werden aber zu Komplizen, wenn es die Situation erfordert. Doch jeder verfolgt nur ein Ziel: die Geldkassette. Und keiner von ihnen ist bereit, zu teilen...","fr":"Pendant la guerre de Sécession, Tuco et Joe se lancent à la recherche d''un coffre contenant 200 000 dollars en pièces d''or volés à l''armée sudiste. Ayant des indices complémentaires sur la cache, chacun a besoin de l''autre. Mais un troisième homme entre dans la course : Sentenza, un tueur qui ne recule devant rien pour parvenir à ses fins."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/n9HRt5Uq6iY9u6rdaFUHCBg14sg.jpg","en":"https://image.tmdb.org/t/p/w500/bX2xnavhMYjWDoZp1VM6VnU1xwe.jpg","es":"https://image.tmdb.org/t/p/w500/71HKV5F9bfm05ZZnjGmRuFpUVCo.jpg","de":"https://image.tmdb.org/t/p/w500/fKjmsSd6lLIanV252zqIPANfCaz.jpg","fr":"https://image.tmdb.org/t/p/w500/qEr65B4yGlsmLQjcM0xjSUMfZS2.jpg"}'::jsonb WHERE id = 126;
UPDATE public.films SET tmdb_id = 335, titoli_i18n = '{"it":"C''era una volta il West","en":"Once Upon a Time in the West","es":"Hasta que llegó su hora","de":"Spiel mir das Lied vom Tod","fr":"Il était une fois dans l''Ouest"}'::jsonb, trame_i18n = '{"it":"Una giovane vedova difende la propria terra dalle mire di un magnate delle ferrovie, aiutata da un misterioso uomo con l''armonica e da un fuorilegge romantico.","en":"As the railroad builders advance unstoppably through the Arizona desert on their way to the sea, Jill arrives in the small town of Flagstone with the intention of starting a new life.","es":"Mientras los constructores del ferrocarril avanzan imparables por el desierto de Arizona en su camino hacia el mar, Jill llega al pequeño pueblo de Flagstone con la intención de empezar una nueva vida.","de":"Während die Eisenbahnbauer auf ihrem Weg zum Meer unaufhaltsam durch die Wüste Arizonas marschieren, kommt Jill in der kleinen Stadt Flagstone an, um ein neues Leben zu beginnen.","fr":"Alors que les constructeurs de chemins de fer traversent sans relâche le désert de l''Arizona en direction de la mer, Jill arrive dans la petite ville de Flagstone avec l''intention de commencer une nouvelle vie."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/3MPqF2iK6ZBoagnB5H1pjImHpHc.jpg","en":"https://image.tmdb.org/t/p/w500/qbYgqOczabWNn2XKwgMtVrntD6P.jpg","es":"https://image.tmdb.org/t/p/w500/upiek8u4rHTrOJW9B0woXe4A4h7.jpg","de":"https://image.tmdb.org/t/p/w500/BwLUQDesx6GW6FtUrQGUPQtzcg.jpg","fr":"https://image.tmdb.org/t/p/w500/xjXKy5b2M3fDelAQItIswcDNvwm.jpg"}'::jsonb WHERE id = 127;
UPDATE public.films SET tmdb_id = 336, titoli_i18n = '{"it":"Giù la testa","en":"Duck, You Sucker","fr":"Il était une fois… la révolution","de":"Todesmelodie","es":"¡Agáchate, maldito!"}'::jsonb, trame_i18n = '{"it":"Durante la rivoluzione messicana, un ingenuo bandito locale e un tormentato dinamitardo irlandese uniscono le forze in una serie di rapine che si trasformeranno in gesta eroiche.","en":"At the beginning of the 1913 Mexican Revolution, greedy bandit Juan Miranda and idealist John H. Mallory, an Irish Republican Army explosives expert on the lam from the British, fall in with a band of revolutionaries plotting to strike a national bank. When it turns out that the government has been using the bank as a hiding place for illegally detained political prisoners -- who are freed by the blast -- Miranda becomes a revolutionary hero against his will.","fr":"Mexique, 1913. Un pilleur de diligences, Juan Miranda, fait chanter un spécialiste en explosifs, John Mallory, pour qu''ils s''associent afin de dévaliser la banque centrale de Mesa Verde. Tous deux se trouvent plongés en plein cœur de la tourmente de la révolution mexicaine.","de":"Mexiko, zur Zeit der Revolution: Juan Miranda, Anführer einer Banditenfamilie, trifft auf Sean Mallory, einen irischen Sprengstoffexperten der Armee, der sich auf der Flucht vor den Engländern befindet. Als Juan Seans ausgesprochen nützliche Fertigkeiten in Sachen Dynamit erkennt, überredet er ihn schließlich, sich seiner Truppe anzuschließen, die gerade im Begriff ist, die Bank von Mesa Verde auszurauben. Zusammen mit dem Revolutionsführer Dr. Villega planen sie die Attacke der Bank - die jedoch, wie sich herausstellt, anstelle von Geld nur politische Gefangene beherbergt und die Banditen unfreiwillig zu Helden der Revolution macht.","es":"Juan Miranda y John Mallory, veterano del IRA, se conocen en México y planean trabajar juntos robando bancos. Un día dinamitan lo que creían que era un banco local y resulta ser una prisión. La explosión libera a los revolucionarios que estaban presos y ambos se convierten en héroes de la revolución. Poco tiempo después, las tropas del gobierno, comandadas por el coronel Gutiérrez, comienzan a seguirles los pasos."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qTdmSJPOW3ts04BrBRTwieA3BY9.jpg","en":"https://image.tmdb.org/t/p/w500/nWmAtZf83qpOai0fzehf7Hn1S3R.jpg","fr":"https://image.tmdb.org/t/p/w500/5oITsFaa1MQowuQhf3H3Nr1jibW.jpg","de":"https://image.tmdb.org/t/p/w500/gfVrrpCLBqA5vTsofbQECLQvppt.jpg","es":"https://image.tmdb.org/t/p/w500/zHzv1nA9azV2lLR0nu8dhIsmbjY.jpg"}'::jsonb WHERE id = 128;
UPDATE public.films SET tmdb_id = 311, titoli_i18n = '{"en":"Once Upon a Time in America","fr":"Il était une fois en Amérique","de":"Es war einmal in Amerika","es":"Érase una vez en América","it":"C''era una volta in America"}'::jsonb, trame_i18n = '{"en":"A former Prohibition-era Jewish gangster returns to the Lower East Side of Manhattan over thirty years later, where he once again must confront the ghosts and regrets of his old life.","fr":"À New York, à la fin de la prohibition, Noodles se réfugie dans une fumerie d''opium après un coup qui a mal tourné. Plus de trente ans plus tard, il est de retour en ville et se remémore son passé de gangster : de sa jeunesse de voyou dans les années 20, marquée par sa rencontre avec son ami Max et leurs nombreux trafics dans le ghetto juif de la ville, jusqu''à la période de prohibition où leur bande, liée par une profonde amitié, s''enrichit et marque son ascension dans la pègre grâce au commerce illégal d''alcool. Noodles se rappelle aussi de sa relation amoureuse échouée avec Deborah durant toute sa vie.","de":"New York zur Zeit der Prohibition. Max, Noodles und ihre Freunde verdienen sich bereits als Kinder mit Erpressungen und Schmuggeleien den einen oder anderen Dollar dazu. Jahre später – Noodles wird nach einer langen Haftstrafe für einen Mord aus dem Gefängnis entlassen – haben es die Freunde von damals unter Max zu einem skrupellosen Gangstersyndikat gebracht. Doch Ehrgeiz und Habgier zerstört die jahrzehntelange Freundschaft, und am Ende steht ein entsetzlicher Verrat …","es":"David Aaronson \"Noodles\", un pobre joven judío, conoce en los suburbios de principios del siglo XX de Manhattan, Nueva York, a Maximilian Bercovicz \"Max\", otro joven de origen hebreo dispuesto a llegar lejos por cualquier método. Entablan una gran amistad y forman, con los 3 colegas de \"Noodles\", Patrick Goldberg \"Patsy\", Philip Stein \"Cockeye\", y Dominic una banda que prospera rápidamente. Desgraciadamente, son perseguidos por Bugsy, el tipo para el que Noodles y sus amigos trabajaban anteriormente, y en uno de sus asaltos, mata a Dominic. Rápidamente Noodles se tira encima suyo y le mata, por lo que pasará 12 años en prisión. Cuando Noodles sale de prisión le recibe Max, que sigue con su banda junto a los otros 2 amigos, Patsy y Cockeye. Rápidamente, entre los 4, llegan a convertirse, en tiempos de la prohibición, en unos de los mayores gánsteres de todo el país.","it":"La complessa epopea di un gruppo di gangster ebrei a New York, dall''infanzia nel ghetto negli anni ''20 fino al drammatico bilancio esistenziale negli anni ''60."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/i0enkzsL5dPeneWnjl1fCWm6L7k.jpg","fr":"https://image.tmdb.org/t/p/w500/qfuO1yue5bQnocFiOUM07dwLdmo.jpg","de":"https://image.tmdb.org/t/p/w500/6Vz28wZed3YDCVb14bKQV6qJ1eU.jpg","es":"https://image.tmdb.org/t/p/w500/u4VnqaxINtKVscmdldZsBojU6jm.jpg","it":"https://image.tmdb.org/t/p/w500/A0Va4hHmMfuU6WPIIeSXFUl5gjN.jpg"}'::jsonb WHERE id = 129;
UPDATE public.films SET tmdb_id = 25643, titoli_i18n = '{"es":"Love Happens","en":"Love Happens","it":"Love Happens - Qualcosa di speciale (noto anche come Brand New Day)","fr":"Coup de foudre à Seattle","de":"Love Happens"}'::jsonb, trame_i18n = '{"es":"El viudo Burke Ryan es un exitoso autor de libros de autoayuda que enseña cómo enfrentarse al dolor, pero es incapaz de seguir sus propios consejos. De mala gana, Burke vuelve a Seattle, ciudad que abandonó tras morir su mujer, para impartir una serie de conferencias y cerrar un importante acuerdo publicitario. Allí conoce inesperadamente a Eloise Chandler, una florista algo desencantada con el amor que asiste a sus seminarios y que, poco a poco y sin proponérselo, se convierte en la única persona capaz de ayudar a Burke a ayudarse a sí mismo; a la vez que él cada vez será más indispensable para Eloise.","en":"Dr. Burke Ryan is a successful self-help author and motivational speaker with a secret. While he helps thousands of people cope with tragedy and personal loss, he secretly is unable to overcome the death of his late wife. It''s not until Burke meets a fiercely independent florist named Eloise that he is forced to face his past and overcome his demons.","it":"Un autore di bestseller sul superamento del lutto, rimasto vedovo, tiene un seminario a Seattle. Qui incontra una fiorista disillusa dall''amore, che lo costringerà a fare i conti con il fatto che non ha ancora realmente superato la morte della moglie.","fr":"Un veuf décide d''écrire un livre sur le travail de deuil. L''ouvrage est un succès et fait passer son auteur pour une sorte de gourou. Lors de l''un de ses séminaires, il tombe amoureux d''une femme, et se rend alors compte qu''il n''a pas surmonté la perte de sa femme...","de":"Burke Ryan weiß auf alle Fragen eine Antwort. Zumindest wenn man den Millionen von Fans glauben darf, die gierig seine Ratgeberbücher verschlingen oder seine Selbsthilfeseminare besuchen, in der Hoffnung einen Weg zu finden, mit Trauer und Ängsten umzugehen. Aber was Burkes eigene Gefühle angeht, scheint er seinen Ratschlägen nicht zu trauen. Ausgerechnet da trifft er auf Eloise, die von den Männern eigentlich genug hat und sich endlich ihren Traum erfüllt und einen Blumenladen betreibt. Zwischen den beiden funkt es gleich, doch wenn die zwei richtigen Menschen zur falschen Zeit zusammentreffen, hat die Liebe dann eine Chance? Eloise und Burke merken bald, dass sie erst mit ihrer Vergangenheit abschließen müssen, um wirklich einen Neuanfang wagen zu können."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/ODTuap8nZNMSDyWynCTID2lTCF.jpg","en":"https://image.tmdb.org/t/p/w500/ijRJlhAZ7QMkTIVAUkIY8stWfk1.jpg","it":"https://image.tmdb.org/t/p/w500/hUMCP4Fhwvc5CKREt86cVJAUITs.jpg","fr":"https://image.tmdb.org/t/p/w500/pn9B8cYuWK9ZPGHpT6UO9UzXNHK.jpg","de":"https://image.tmdb.org/t/p/w500/ijRJlhAZ7QMkTIVAUkIY8stWfk1.jpg"}'::jsonb WHERE id = 130;
UPDATE public.films SET tmdb_id = 969681, titoli_i18n = '{"it":"Spider-Man: Brand New Day","en":"Spider-Man: Brand New Day","de":"Spider-Man: Brand New Day","es":"Spider-Man: Brand New Day","fr":"Spider-Man : Brand New Day"}'::jsonb, trame_i18n = '{"it":"Dopo gli eventi di ''Spider-Man: No Way Home'', Peter Parker cerca di rifarsi una vita in una New York che ha dimenticato la sua vera identità. Dovrà bilanciare la sua nuova e solitaria quotidianità con le responsabilità di essere un supereroe di quartiere, affrontando nuove minacce.","en":"Fighting crime full-time as Spider-Man in a world that doesn''t remember him—and the pressure of seeing his old friends move on without him—sparks a change in Peter Parker he may not have the power to control. But that transformation might also be the only thing that can stop a shocking new threat to the city and those he loves - a powerful villain no one can even see.","de":"Vier Jahre sind seit den Ereignissen von „No Way Home“ vergangen. Peter ist nun erwachsen und lebt für sich allein, nachdem er sich freiwillig aus dem Leben und den Erinnerungen derer, die er liebt, ausgelöscht hat. Er bekämpft Verbrechen in einem New York, das ihn und seinen Namen nicht mehr kennt, und widmet sich ganz dem Schutz seiner Stadt: Spider-Man in Vollzeit. Doch mit den steigenden Anforderungen löst der Druck eine überraschende körperliche Veränderung aus, die seine Existenz bedroht – gerade als eine seltsame neue Art von Verbrechen eine der mächtigsten Bedrohungen hervorbringt, denen er je gegenüberstand.","es":"Han pasado cuatro años desde los acontecimientos de No Way Home, y Peter Parker ahora es un adulto que vive completamente solo, ha desaparecido voluntariamente de las vidas y recuerdos de quienes ama. Combatiendo el crimen en una Nueva York que ya no conoce su nombre, se ha dedicado por completo a proteger su ciudad—un Spider-Man a tiempo completo—, pero a medida que aumentan las exigencias sobre él, la presión desencadena una evolución física que amenaza su existencia, al mismo tiempo que un extraño nuevo patrón de crímenes da lugar a una de las amenazas más poderosas a las que se ha enfrentado.","fr":"Quatre ans se sont écoulés, Peter, désormais adulte, vit seul, s''est volontairement effacé de la vie et des souvenirs de ses proches. Luttant contre le crime dans un New York qui ne le reconnaît plus, il se consacre entièrement à la protection de la ville - un Spider-Man à plein temps - mais à mesure que les responsabilités s''intensifient, la pression provoque une transformation physique surprenante qui menace son existence, tandis qu''une étrange nouvelle vague de crimes donne naissance à l''une des menaces les plus redoutables qu''il ait jamais affrontées."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/fRbJeDILi6nLYCT5XeFapjVTlSK.jpg","en":"https://image.tmdb.org/t/p/w500/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg","de":"https://image.tmdb.org/t/p/w500/h2R2dPbIyjxXorGL6V8Mau01hJy.jpg","es":"https://image.tmdb.org/t/p/w500/tluwRNA7k0XfTtDkdLYKX1KOSCJ.jpg","fr":"https://image.tmdb.org/t/p/w500/6OEtkkzoyusZDm2uMJojlWZSLR9.jpg"}'::jsonb WHERE id = 132;
UPDATE public.films SET tmdb_id = 466272, titoli_i18n = '{"it":"C''era una volta a... Hollywood","en":"Once Upon a Time... in Hollywood","es":"Érase una vez en… Hollywood","de":"Once Upon a Time... in Hollywood","fr":"Once Upon a Time... in Hollywood"}'::jsonb, trame_i18n = '{"it":"Nella Los Angeles del 1969, un attore televisivo in declino e la sua controfigura e migliore amico cercano di navigare nei cambiamenti dell''industria cinematografica, mentre sullo sfondo si consumano le vicende legate alla setta di Charles Manson.","en":"Los Angeles, 1969. TV star Rick Dalton, a struggling actor specializing in westerns, and stuntman Cliff Booth, his best friend, try to survive in a constantly changing movie industry. Dalton is the neighbor of the young and promising actress and model Sharon Tate, who has just married the prestigious Polish director Roman Polanski…","es":"Los Angeles, 1969. La estrella de televisión Rick Dalton, un actor en horas bajas especializado en westerns, y el doble de acción Cliff Booth, su mejor amigo, tratan de sobrevivir a una industria cinematográfica en constante cambio. Dalton es vecino de la joven y prometedora actriz y modelo Sharon Tate, que acaba de casarse con el prestigioso director polaco Roman Polanski…","de":"Es war einmal in Hollywood im Jahre 1969: Rick Dalton hat schon bessere Tage gesehen. Einst war der Schauspieler ein gefeierter Fernsehstar. Doch diese Zeiten sind längst vorbei. Inzwischen hält er sich mehr schlecht als recht mit Gastauftritten als Bösewicht in anderen TV-Produktionen über Wasser. Denn den Sprung auf die große Kinoleinwand hat er nie geschafft. Dabei ist sein Stunt-Double und Freund Cliff Booth stets an seiner Seite. Am Tiefpunkt seiner Karriere angelangt, bekommt Rick allerdings einen prominenten Nachbarn. Der Regisseur Roman Polanski ist mit seiner Frau, der Schauspielerin Sharon Tate in das Haus nebenan eingezogen. Während Tate das Leben in Amerikas Traumfabrik in vollen Zügen genießt, droht ihr Glück ein jähes Ende zu nehmen. Denn die mörderische Gruppe um Charles Manson plant eine Gräueltat, wie sie die Welt noch nicht gesehen hat …","fr":"En 1969, Rick Dalton – star déclinante d''une série télévisée de western – et Cliff Booth – sa doublure de toujours – assistent à la métamorphose artistique d''un Hollywood qu''ils ne reconnaissent plus du tout en essayant de relancer leurs carrières."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/wW5t1FNg3ZHQu5sXeShyaN3oU9Z.jpg","en":"https://image.tmdb.org/t/p/w500/8j58iEBw9pOXFD2L0nt0ZXeHviB.jpg","es":"https://image.tmdb.org/t/p/w500/vKSyaptSA7zZ9H8mSfaDnvyQl9k.jpg","de":"https://image.tmdb.org/t/p/w500/5RnMRADLB7Goin16z6l4dPIBCJR.jpg","fr":"https://image.tmdb.org/t/p/w500/gG5J1KW2Gzj0Sz7al1mGkhXLSoB.jpg"}'::jsonb WHERE id = 133;
UPDATE public.films SET tmdb_id = 1371, titoli_i18n = '{"it":"Rocky III","en":"Rocky III","es":"Rocky III","fr":"Rocky III : L''Œil du tigre","de":"Rocky III - Das Auge des Tigers"}'::jsonb, trame_i18n = '{"it":"Rocky Balboa, ormai campione del mondo dei pesi massimi e ricco, perde il titolo contro il brutale sfidante Clubber Lang e subisce la dolorosa perdita del suo storico allenatore Mickey. Sarà l''ex rivale Apollo Creed ad aiutarlo a ritrovare la \"fame\" e lo \"sguardo della tigre\" per prepararsi alla rivincita.","en":"Following Rocky Balboa''s intense battle with his most powerful adversary yet – the ferocious Clubber Lang – Rocky joins forces with former rival Apollo Creed in an effort to get back his fighting spirit.","es":"Tras haber defendido el título diez veces, el campeón mundial de boxeo Rocky Balboa ha decidido retirarse. Sin embargo Clubber Lang, un boxeador muy agresivo que ha ido escalando puestos a base de destrozar a sus rivales, desea arrebatarle el título. Pese a la negativa de Rocky, Clubber consigue provocarle para que acepte el desafío, y esta vez el resultado del combate se presume bastante incierto.","fr":"Rocky Balboa se fraie un chemin dans le cœur de millions de personnes et sa vie ne pourrait être meilleure. Mais lorsque \"Clubber\" Lang met Rocky KO dans une défaite humiliante, il devient évident que \"l''étalon italien\" a perdu son avantage. Alors qu''il envisage de raccrocher les gants, Rocky reçoit les encouragements d''un allié improbable : son vieil ennemi juré, Apollo Creed. Avec l''aide de Creed, Rocky s''efforce de retrouver \"l''œil du tigre\" avant d''affronter Lang dans un match de reprise exténuant !","de":"Rocky ist unangefochtener Weltmeister im Schwergewicht und hat seinen Titel bislang zehn Mal erfolgreich verteidigt. Auf dem Gipfel seines Ruhmes angelangt, will der Publikumsliebling aus dem Boxsport aussteigen. Doch dann wird Rocky auf einer Pressekonferenz  von Großmaul Clubber Lang  herausgefordert. Aber Rocky fehlt der Biss alter Tage und er verliert den großen Kampf. Ausgerechnet Ex-Gegner Apollo Creed animiert ihn, für eine Revanche zu trainieren …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ajcNIcmwjbVO8kA22WMeCcTKf9T.jpg","en":"https://image.tmdb.org/t/p/w500/uqw16i2kmwVqkJHzjzbDU4xZ0Pl.jpg","es":"https://image.tmdb.org/t/p/w500/5Mn0xgB8w9mi2Ifo7WdS8aSgA7V.jpg","fr":"https://image.tmdb.org/t/p/w500/zplg0q9s5pbJDQLWCTlIQfMxC9A.jpg","de":"https://image.tmdb.org/t/p/w500/Gsohe9uX4fftQRcuZOmv2muEFB.jpg"}'::jsonb WHERE id = 134;
UPDATE public.films SET tmdb_id = 1375, titoli_i18n = '{"it":"Rocky V","en":"Rocky V","de":"Rocky V","es":"Rocky V","fr":"Rocky V"}'::jsonb, trame_i18n = '{"it":"Costretto al ritiro dai combattimenti a causa dei danni cerebrali riportati contro Ivan Drago e finito in rovina finanziaria, Rocky Balboa torna con la famiglia nel suo vecchio quartiere a Philadelphia. Qui comincia ad allenare un giovane e promettente pugile, Tommy Gunn, trascurando il proprio figlio. L''ambizione e l''avidità spingeranno però Tommy a voltare le spalle a Rocky, portando i due a uno scontro finale in una rissa di strada.","en":"A lifetime of taking shots has ended Rocky’s career, and a crooked accountant has left him broke. Inspired by the memory of his trainer, however, Rocky finds glory in training and takes on an up-and-coming boxer.","de":"Sein knapper Sieg gegen die russische Kampfmaschine Ivan Drago hat Box-Weltmeister Rocky Balboa eine schwere Hirnschädigung gekostet, die ihn zum Rücktritt zwingt. Aber es kommt noch schlimmer: Durch eine Fehlspekulation seines Steuerberaters ist er plötzlich mit einem Schlag pleite. Zusammen mit seiner Familie zieht Rocky notgedrungen wieder zurück in die Slums, wo er sich mit der Box-Schule seines verstorbenen Trainers über Wasser hält. Dabei lernt er den noch unerfahrenen Boxer Tommy Gunn kennen, für den er sich aus gewissen Sympathien bereit erklärt, Trainer zu sein. Als den beiden im Team dann erste Erfolge vergönnt sind, beginnt auch der geldgierige Promoter Duke, Interesse an dem Newcomer zu zeigen...","es":"Rocky, arruinado y retirado del boxeo, se ve obligado a volver a su barrio de siempre. Allí conoce a un joven con aptitudes para boxear y decide entrenarle.","fr":"Des séquelles physiques irréversibles amènent Rocky Balboa à prendre sa retraite. Ruiné, il devient l''entraîneur d''un champion en devenir, Tommy Gunn. Mais celui-ci ne va pas rester insensible à l''appât du gain et va quitter Rocky pour rejoindre les rangs d''un coach plus fortuné."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/y6xHS5icTfYXkRZtb2NvTLhVYfn.jpg","en":"https://image.tmdb.org/t/p/w500/qCARerjCFZOEeLiVdomhwRYlDSn.jpg","de":"https://image.tmdb.org/t/p/w500/tZi4FathM1vcsDtbuOFsOce2IhB.jpg","es":"https://image.tmdb.org/t/p/w500/kbt9oSpAX8TkmpV2T72p0Cl41vR.jpg","fr":"https://image.tmdb.org/t/p/w500/829CIMdIhYgXWUSq7OjrpgtNAR7.jpg"}'::jsonb WHERE id = 135;
UPDATE public.films SET tmdb_id = 17382, titoli_i18n = '{"it":"La storia del generale Custer","en":"They Died with Their Boots On","fr":"La Charge fantastique","de":"Sein letztes Kommando","es":"Murieron con las botas puestas"}'::jsonb, trame_i18n = '{"it":"La vita romanzata di George Armstrong Custer, dalla sua giovinezza all''accademia militare di West Point, attraverso le sue eroiche imprese durante la Guerra di Secessione, fino alla sua tragica morte nella celebre battaglia di Little Bighorn.","en":"The story follows General George Armstrong Custer''s adventures from his West Point days to his death. He defies orders during the Civil War, trains the 7th Cavalry, appeases Chief Crazy Horse and later engages in bloody battle with the Sioux nation.","fr":"Un jeune élève nommé Custer se distingue par son talent et son insubordination dans le camp militaire de West Point. Durant la guerre de Sécession, la bataille d''Hanovre est remportée, bien que soldée par un véritable massacre. Il est envoyé par ses supérieurs dans le Dakota, à Fort Lincoln. Mais il se heurte à la fois aux politiciens et aux chercheurs d''or, jusqu''à ce que les indiens de Crazy Horse se soulèvent à leur tour. L''affrontement aura lieu à Little Big Horn...","de":"George Armstrong Custer absolviert die Militärschule West Point und nimmt am Bürgerkrieg teil. Als Kommandant des 7. Kavallerie-Regiments bewährt er sich in Dakota, sorgt für Frieden mit den Sioux: Kein Weißer werde ihr Gebiet in den Black Hills betreten. Eine Handelsgesellschaft durchkreuzt seine Politik, er wird suspendiert. Die Gesellschaft provoziert einen Aufstand der Krieger von Häuptling Crazy Horse. Custer wird wieder eingesetzt und reitet mit seinem Regiment am 25. Juni 1876 in die Schlacht am Little Big Horn, wo er und alle seine Leute fallen","es":"George Custer (Errol Flynn) llega a la Academia de West Point lleno de arrogancia y vanidad. Su carácter indisciplinado le ocasionará numerosos problemas con sus superiores. A pesar de todo, y debido a la acuciante necesidad de oficiales para la Guerra de Secesión (1861-1865), es enviado al frente. Terminada la guerra, se casa con Beth (Olivia de Havilland), pero pronto le asignan un nuevo destino: la guerra contra los indios. Al frente del Séptimo de Caballería, el Teniente Coronel Custer se enfrentará a los indios de Caballo Loco. La campaña termina con la famosa batalla de Little Big Horn (Montana, 1876)."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/5cZLUtSWiz0LWK1H0EZSH5RkL1L.jpg","en":"https://image.tmdb.org/t/p/w500/gx8jknFwZRuQwTPooe14Dsx5uTO.jpg","fr":"https://image.tmdb.org/t/p/w500/gxPyXi7XCwdpa98cJOVl3R1hEYC.jpg","de":"https://image.tmdb.org/t/p/w500/djt8CMaxDQkpcYGyGo3N3jj60d0.jpg","es":"https://image.tmdb.org/t/p/w500/UXrWYewjH3KNEU7IAKyynEYTYf.jpg"}'::jsonb WHERE id = 136;
UPDATE public.films SET tmdb_id = 8195, titoli_i18n = '{"es":"Ronin","en":"Ronin","it":"Ronin","fr":"Ronin","de":"Ronin"}'::jsonb, trame_i18n = '{"es":"Cuando un equipo internacional de ex-agentes de inteligencia y ex-guerreros de la guerra fría se reunen en una bodega, su aventura de amor, amistad y traición apenas comienza. Al igual que el honorable e independiente samurai de hace cientos de años, estos ronin modernos se embarcan en su más peligrosa misión secreta: recobrar una misteriosa maleta y entregársela a su desconocido jefe y a la vez conservar sus vidas. Un criminal que se vende al mejor postor lidera un grupo de profesionales del crimen que busca un misterioso maletín, cuyo contenido es desconocido incluso para el espectador.","en":"A briefcase with undisclosed contents – sought by Irish terrorists and the Russian mob – makes its way into criminals'' hands. An Irish liaison assembles a squad of mercenaries, or ''ronin'', and gives them the thorny task of recovering the case.","it":"Un gruppo di ex agenti segreti e mercenari provenienti da diversi paesi viene ingaggiato a Parigi per recuperare una misteriosa e pesantemente custodita valigetta. Tra tradimenti, doppi giochi e mozzafiato inseguimenti automobilistici, la squadra dovrà scoprire di chi potersi davvero fidare.","fr":"Cinq hommes et une femme qui ne se connaissent pas se rencontrent dans un entrepôt de la banlieue parisienne. Ces hommes de l’ombre sont d’anciens soldats de la guerre froide qui survivent en louant discrètement leurs services à des commanditaires anonymes. La jeune Irlandaise qui les a réunis manque d’expérience. Leur mission est d’affronter une équipe adverse, solidement armée d’une douzaine d’hommes pour lui arracher une précieuse mallette dont ils ignorent le contenu. Une chose est claire : tous devront tuer pour mener à bien leur mission, certains y laisseront leur peau.","de":"Die geheimnisvolle Dierdre heuert mehrere Ronins (Samurais ohne Meister), käufliche Spezialisten für alle Fälle, an, um eine Tasche zu stehlen, ehe der momentane Besitzer sie an den KGB verkaufen kann. Die Männer kennen sich nicht, und obwohl sie unterschiedliche Berufs- und Lebensauffassungen haben, führen sie den Job aus. Doch die Tasche verschwindet kurz nach dem Coup und bald stecken alle Beteiligten in einem tödlichen Spiel, bei dem niemand sicher ist und jeder ein Verräter sein kann."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/jPz0pJuEf44qVgSaZkER43W04Bg.jpg","en":"https://image.tmdb.org/t/p/w500/AirrhRJjHwytOV0pdLu7YZ4DEyr.jpg","it":"https://image.tmdb.org/t/p/w500/cNngnFz2VLJbIYQEgn3Idd20h1K.jpg","fr":"https://image.tmdb.org/t/p/w500/yiZrJDZT8Yy8bfvmwWQ7UDK1lDP.jpg","de":"https://image.tmdb.org/t/p/w500/it9iwy9SfyTjx9ggxbfycESJn1S.jpg"}'::jsonb WHERE id = 137;
UPDATE public.films SET tmdb_id = 184, titoli_i18n = '{"es":"Jackie Brown","it":"Jackie Brown","en":"Jackie Brown","de":"Jackie Brown","fr":"Jackie Brown"}'::jsonb, trame_i18n = '{"es":"Jackie Brown es una azafata de vuelo que necesita dinero y hace de correo para Robbie, un mafioso buscado por la policía. Todo parece ir bien hasta que un día es sorprendida en la aduana y acusada de tráfico de drogas y evasión de capital. Sólo podrá evitar su ingreso en prisión, si acepta una propuesta de la policía: ayudarles a llegar hasta Robbie.","it":"Una hostess di volo di mezza età, che contrabbanda denaro sporco per un trafficante d''armi, viene incastrata dall''FBI. Per salvarsi, decide di fare il doppio gioco, ideando un piano rischioso per truffare sia i federali che il suo boss e fuggire con mezzo milione di dollari.","en":"Jackie Brown is a flight attendant who gets caught in the middle of smuggling cash into the country for her gunrunner boss. When the cops try to use Jackie to get to her boss, she hatches a plan — with help from a bail bondsman — to keep the money for herself.","de":"Mit Schwarzgeld wird Jackie Brown am Flughafen gestellt. Das FBI wittert die große Chance, durch Jackies Aussage einen Schmuggler-Ring auszuheben. Die Cops sind bereit, Jackie laufen zu lassen, wenn sie den Namen ihres Auftraggebers preisgibt. Die Entscheidung fällt ihr schwer, denn Ordell Robbie, ihr Boss und Drahtzieher der dubiosen Waffen-Schmuggel-Geschäfte, würde sie umbringen, wenn er Wind von einem Deal mit dem FBI bekäme. Bevor sie sich entscheiden kann, kommt alles ganz anders: Sie lernt den Kautionsvermittler Max Cherry kennen. Die beiden schmieden einen Plan, und plötzlich hat Jackie die Idee, wie es ihr gelingen könnte, Ordell gegen die Polizei auszuspielen …","fr":"Hôtesse de l’air, Jackie Brown arrondit ses fins de mois en convoyant de l’argent liquide pour le compte de Ordell Robbie, trafiquant d’armes. Quand la police et le FBI lui signifient qu’ils comptent sur elle pour faire tomber Robbie, Jackie Brown échafaude un plan audacieux."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/vNrJ3ODvu2dvqIdHHbzgsVjgp4X.jpg","it":"https://image.tmdb.org/t/p/w500/jLnXl26rUTHryy6scittB5OMUQk.jpg","en":"https://image.tmdb.org/t/p/w500/rOUx7qg4KmEh1juEDwqzbDSL1Nr.jpg","de":"https://image.tmdb.org/t/p/w500/dyRpD0W6bJbdvNy9mRuviajaYPj.jpg","fr":"https://image.tmdb.org/t/p/w500/mc8lNVgDYMG2IQus5RmdcgvwOKx.jpg"}'::jsonb WHERE id = 138;
UPDATE public.films SET tmdb_id = 718930, titoli_i18n = '{"it":"Bullet Train","en":"Bullet Train","fr":"Bullet Train","es":"Bullet Train","de":"Bullet Train"}'::jsonb, trame_i18n = '{"it":"Un sfortunato assassino di nome Ladybug vuole svolgere una semplice missione a bordo del treno ad alta velocità più veloce del mondo in Giappone. Tuttavia, si ritrova a doversela vedere con diversi killer professionisti provenienti da tutto il mondo, tutti con obiettivi interconnessi e contrastanti.","en":"Unlucky assassin Ladybug is determined to do his job peacefully after one too many gigs gone off the rails. Fate, however, may have other plans, as Ladybug''s latest mission puts him on a collision course with lethal adversaries from around the globe—all with connected, yet conflicting, objectives—on the world''s fastest train.","fr":"Coccinelle est un assassin malchanceux et particulièrement déterminé à accomplir sa nouvelle mission paisiblement après que trop d''entre elles aient déraillé. Mais le destin en a décidé autrement et l''embarque dans le train le plus rapide au monde aux côtés d''adversaires redoutables qui ont tous un point commun, mais dont les intérêts divergent radicalement… Il doit alors tenter par tous les moyens de descendre du train.","es":"Cinco asesinos a sueldo se encuentran a bordo de un tren bala que viaja de Tokio a Morioka con unas pocas paradas intermedias. Descubren que sus misiones no son ajenas entre sí. La pregunta es quién saldrá vivo del tren y qué les espera en la estación final.","de":"Der vom Pech verfolgte Auftragskiller Ladybug ist entschlossen, seinen Job in Ruhe und Frieden zu erledigen, nachdem in letzter Zeit zu viele Dinge aus dem Ruder gelaufen sind. Das Schicksal hat jedoch andere Pläne, denn Ladybugs neueste Mission setzt ihn auf einen direkten Kollisionskurs mit tödlichen Gegnern aus der ganzen Welt – die alle irgendwie miteinander verbunden sind, dabei aber gegensätzliche Ziele verfolgen. Das alles passiert an Bord des schnellsten Zuges, den es gibt - und Ladybug muss einen Weg finden, wie er ihn verlassen kann."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zTyMbs3zTEpDhyrel35vgpJdzFS.jpg","en":"https://image.tmdb.org/t/p/w500/j8szC8OgrejDQjjMKSVXyaAjw3V.jpg","fr":"https://image.tmdb.org/t/p/w500/uJvMXO1DNEER2lZocNjJy2zXtYs.jpg","es":"https://image.tmdb.org/t/p/w500/kM6iLHkDfyoMsTIm567mUFzFO9e.jpg","de":"https://image.tmdb.org/t/p/w500/kem6mZifzyIec1TDpd9srSRTpv7.jpg"}'::jsonb WHERE id = 139;
UPDATE public.films SET tmdb_id = 152599, titoli_i18n = '{"it":"C''era una volta a New York","en":"The Immigrant","es":"El sueño de Ellis","fr":"The Immigrant","de":"The Immigrant"}'::jsonb, trame_i18n = '{"it":"Nel 1921, le sorelle polacche Ewa e Magda arrivano a Ellis Island in cerca di una vita migliore. Quando Magda viene messa in quarantena per tubercolosi, Ewa si ritrova sola e vulnerabile, finendo sotto il controllo di un ambiguo impresario che la avvia alla prostituzione.","en":"1921 New York. An immigrant woman is tricked into a life of burlesque and vaudeville until a dazzling magician tries to save her and reunite her with her sister who is being held in the confines of Ellis Island.","es":"En 1921, Ewa y su hermana Magda dejan su Polonia natal y emigran a Nueva York. Cuando llegan a Ellis Island, a Magda, enferma de tuberculosis, la ponen en cuarentena. Ewa, sola y desamparada, cae en manos de Bruno, un rufián sin escrúpulos. Para salvar a su hermana, Ewa está dispuesta a aceptar todos los sacrificios y se entrega resignada a la prostitución. La llegada de Orlando, ilusionista y primo de Bruno, le devuelve la confianza y la esperanza de alcanzar días mejores. Con lo que no cuenta es con los celos de Bruno.","fr":"1921, Ewa et sa sœur Magda quittent leur Pologne natale pour la terre promise, New York. Arrivées à Ellis Island, Magda, atteinte de tuberculose, est placée en quarantaine. Ewa, seule et désemparée, tombe dans les filets de Bruno, un souteneur sans scrupules. Pour sauver sa sœur, elle est prête à tous les sacrifices et se livre, résignée, à la prostitution.  L’arrivée d’Orlando, illusionniste et cousin de Bruno, lui redonne confiance et l''espoir de jours meilleurs. Mais c''est sans compter sur la jalousie de Bruno...","de":"Auf der Suche nach einem Neustart und dem amerikanischen Traum beschließen Ewa Cybulski und ihre Schwester Magda im Jahre 1920, ihre Heimat Polen zu verlassen und in die USA zu emigrieren. Nach der beschwerlichen Schwiffsreise müssen die Frauen die üblichen Untersuchungen auf Ellis Island über sich ergehen lassen. Dabei stellt der zuständige Arzt fest, dass Magda krank ist, woraufhin die beiden Schwestern voneinander getrennt werden. Während Ewa orientierungslos in den Straßen von Manhattan umherzieht, wird ihre Schwester unter Quarantäne gestellt. Abgeschnitten von Magda findet Ewa Zuflucht bei Bruno, der zunächst charmant und hilfsbereit ist und Ewa bei sich aufnimmt. Doch schon bald lässt Bruno seine Maske fallen und drängt Ewa in die Prostitution. Als sie eines Tages dessen Cousin kennenlernt, den Magier Orlando, verliebt sie sich in ihn. Orlando wird zu ihrer einzigen Chance, dem Alptraum zu entfliehen…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/c0R0CIjxP7D8eA4oGoJFdtBcLzk.jpg","en":"https://image.tmdb.org/t/p/w500/ArWRRQYeXL3nG4jYpMOPoBvgmy9.jpg","es":"https://image.tmdb.org/t/p/w500/AcdntsQgOPgQ1VjLlb7FMNf5flb.jpg","fr":"https://image.tmdb.org/t/p/w500/msbOO1XTPeKSaMol3EW0JulvI6E.jpg","de":"https://image.tmdb.org/t/p/w500/svLnamg54HhbMQkU9ghWibKRjH2.jpg"}'::jsonb WHERE id = 140;
UPDATE public.films SET tmdb_id = 578, titoli_i18n = '{"en":"Jaws","fr":"Les Dents de la Mer","es":"Tiburón","de":"Der weiße Hai","it":"Lo squalo"}'::jsonb, trame_i18n = '{"en":"When the seaside community of Amity finds itself under attack by a dangerous great white shark, the town''s chief of police, a young marine biologist, and a grizzled shark hunter embark on a desperate quest to kill the beast before it strikes again.","fr":"À quelques jours du début de la saison estivale, les habitants de la petite station balnéaire d''Amity sont mis en émoi par la découverte sur le littoral du corps atrocement mutilé d''une jeune vacancière. Pour Martin Brody, le chef de la police, il ne fait aucun doute que la jeune fille a été victime d''un requin. Il décide alors d''interdire l''accès aux plages mais se heurte à l''hostilité du maire uniquement intéressé par l''afflux des touristes. Pendant ce temps, le requin continue à semer la terreur le long des côtes et à dévorer les baigneurs…","es":"En la costa de un pequeño pueblo del Este de Estados Unidos, un enorme tiburón ataca a varias personas. Temiendo las fatales consecuencias que esto puede provocar en el negocio turístico, el alcalde se niega a cerrar las playas y a difundir la noticia. Pero un nuevo ataque del tiburón, en la propia playa, termina con la vida de otro bañista. El terror se ha hecho público, así que un veterano cazador de tiburones, un científico y el jefe de la policía local se unen para dar caza al temible escualo...","de":"Ein weißer Hai terrorisiert eine Badeinsel an der amerikanischen Atlantikküste. Besonnene Einheimische unter Führung von Polizeichef Brody wollen alle Strände schließen und zur großen Jagd blasen, während die Schar der Kaufleute und Gastwirte angesichts der einträglichen Badesaison lieber zur Tagesordnung übergeht und sich damit auch durchsetzt. Als der Hai erneut zuschlägt, bildet Brody mit dem erfahrenen Haifänger Quint und dem Ozeanologen Hooper ein Jagd-Team und rückt dem Gegner auf See zu Leibe.","it":"Un grande squalo bianco terrorizza le acque di una cittadina balneare. Per fermare il predatore, il capo della polizia locale stringe un''alleanza con un giovane biologo marino e un eccentrico cacciatore di squali."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/lxM6kqilAdpdhqUl2biYp5frUxE.jpg","fr":"https://image.tmdb.org/t/p/w500/wuRf6gkX0JUJsu1MeECPubhMRdd.jpg","es":"https://image.tmdb.org/t/p/w500/aCqHb3eFQV8raX30OfGurqPlpjh.jpg","de":"https://image.tmdb.org/t/p/w500/jkchPeYVLZkGg40Co7t3FC0FUti.jpg","it":"https://image.tmdb.org/t/p/w500/zHO7LcDKgAM1sLAZ1Y9yuWc7W7B.jpg"}'::jsonb WHERE id = 141;
UPDATE public.films SET tmdb_id = 579, titoli_i18n = '{"en":"Jaws 2","it":"Lo squalo 2","es":"Tiburón 2","de":"Der weiße Hai 2","fr":"Les Dents de la mer, 2e partie"}'::jsonb, trame_i18n = '{"en":"Police chief Brody must protect the citizens of Amity after a second monstrous shark begins terrorizing the waters.","it":"Quattro anni dopo i tragici eventi dell''isola di Amity, la cittadina cerca di tornare alla normalità. Tuttavia, quando iniziano a verificarsi nuove e misteriose sparizioni in acqua, il capo della polizia Martin Brody si convince che un altro grande squalo bianco stia terrorizzando la zona. Nonostante lo scetticismo delle autorità locali, Brody dovrà agire in fretta per salvare un gruppo di giovani velisti, tra cui i suoi stessi figli, finiti nel mirino del predatore.","es":"Han pasado cuatro años desde que aquel gran tiburón blanco aterrorizara al pequeño pueblo costero de Amity. El jefe de policía Brody sigue preocupado, a pesar de que hay en marcha varios proyectos para reavivar el interés turístico de las playas. El alcalde Larry Vaughn da la bienvenida al inversor Len Peterson y su equipo al pueblo. Dos submarinistas exploran la zona donde apareció el peligroso escualo en el pasado, y son devorados por otro enorme tiburón no sin antes obtener uno de ellos una foto del ojo del monstruo. La desaparición de los dos buceadores alerta a Brody, ya que es verano y los turistas llegan por centenares hasta Amity. Mientras tanto, un grupo de adolescentes entre los que se encuentra Mike y Sean, los hijos del policía, hacen una excursión hasta una península cercana...","de":"Aus dem kleinen Küstenort Amity soll ein modernes Seebad gemacht werden. Plötzlich geschehen schreckliche Unglücksfälle. Polizeichef Brody befürchtet, dass so wie vor einigen Jahren wieder ein Hai dafür verantwortlich sein könnte. Aber keiner reagiert auf seine Warnungen. Auf sich allein gestellt, versucht er, die mörderische Bestie zu bekämpfen...","fr":"Au lendemain de l''inauguration d''un luxueux complexe hôtelier, Martin Brody, le chef de la police d''Amity, apprend la disparition d''une équipe de plongeurs. Il craint le pire. Un requin est déjà venu nager dans les eaux d''Amity quelques années auparavant. Ses inquiétudes ne tardent pas à se confirmer. Un autre accident se produit et le cadavre d''une baleine portant les morsures d''un requin géant échoue sur la plage. Martin Brody alerte immédiatement le maire et lui demande d''interdire la baignade. Mais le conseil municipal refuse de prendre de telles précautions. La saison s''annonce prometteuse et l''enjeu financier est trop important. Brody, devenu trop gênant, est démis de ses fonctions. Le voilà réduit à attendre le pire…"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/cN3ijEwsn4kBaRuHfcJpAQJbeWe.jpg","it":"https://image.tmdb.org/t/p/w500/6lrBNBedNIiPpFtyeFwe63OkJoz.jpg","es":"https://image.tmdb.org/t/p/w500/gQgHcjBWzjCvdfFNY6PGMEzMN93.jpg","de":"https://image.tmdb.org/t/p/w500/8xA83bATuN2QW7k5BL5Z8jMCh6V.jpg","fr":"https://image.tmdb.org/t/p/w500/cH4ZGKS93wTl6JDDg8cwLkqt8u1.jpg"}'::jsonb WHERE id = 142;
UPDATE public.films SET tmdb_id = 17692, titoli_i18n = '{"es":"Tiburón 3","it":"Lo squalo 3","fr":"Les Dents de la mer 3","de":"Der weiße Hai 3","en":"Jaws 3-D"}'::jsonb, trame_i18n = '{"es":"¿Te imaginas quedar atrapado en un parque acuático con un gigantesco tiburón blanco asesino? La tercera parte de la clásica saga de terror hará que pienses dos veces antes de ir a un parque acuático.","it":"Un enorme grande squalo bianco s''introduce nel parco acquatico di SeaWorld in Florida poco prima dell''inaugurazione di una nuova attrazione subacquea. Quando il cucciolo dello squalo muore all''interno della struttura, la gigantesca madre comincia a seminare il terrore e la distruzione, intrappolando i visitatori e il personale nei tunnel e nelle gallerie sottomarine.","fr":"Michael Brody et Sean Brody, les deux fils du chef de la police Martin Brody de la ville plaisancière d''Amytiville, ont bien grandi. Après que leur père ait affronté deux fois la terreur des mers, le Grand Requin Blanc, une espèce animale mangeuse d''hommes de plus de sept mètres de long, ils se sont installés en Floride où ils travaillent pour un célèbre parc aquatique englouti dans la mer, dirigé par Calvin Bouchard. Peu de temps après l''ouverture du parc, l''équipe récupère dans les fonds marins un bébé requin, qui meurt sur les tables du laboratoire scientifique du parc. La mère du requin veut récupérer son petit, et elle sait qu''il se trouve quelque part dans le parc. Celle-ci décide donc de passer à l''attaque et de détruire le Sea World…","de":"Der Sohn von Polizeichef Brody, Michael, ist Ingenieur. Seine Arbeitsstätte: ein Unterwasser-Vergnügungspark im sonnigen Florida. Michael hat eine Freundin, Kathryn  die sich als Trainerin um die Meeresbewohner des Parks kümmert. Der kundige Filmfreund weiß, dass jetzt nur noch einer fehlt, damit der Plot halbwegs interessant wird - der weiße Hai! Er ist in diesem Fall eine Sie, ein trächtiges Weibchen. Das schwimmt in die Anlage, wo es sein drei Meter langes Junges gebärt. Mutter und Kind gehen fortan getrennt auf die Jagd. Nur wenig Zeit vergeht, bis sich Michael und Kathryn mit den ersten Leichen konfrontiert sehen. Währenddessen rückt der Eröffnungstermin des Wasserparks näher und näher...","en":"A giant thirty-five-foot shark becomes trapped in a SeaWorld theme park and it''s up to the sons of police chief Brody to rescue everyone."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/QmB1j0RzqPGki8o8UfJsc6CE5t.jpg","it":"https://image.tmdb.org/t/p/w500/cNNORYubcNFChvN9jAFeASNswo8.jpg","fr":"https://image.tmdb.org/t/p/w500/pgW204G6bP56grBlaCKSJpzOFYT.jpg","de":"https://image.tmdb.org/t/p/w500/jMWfK6gtkdOjzIijNkykUBXVv2t.jpg","en":"https://image.tmdb.org/t/p/w500/kqDXj53F9paqVGJLGfHtz7giJ3s.jpg"}'::jsonb WHERE id = 143;
UPDATE public.films SET tmdb_id = 16869, titoli_i18n = '{"it":"Bastardi senza gloria","en":"Inglourious Basterds","fr":"Inglourious Basterds","es":"Malditos bastardos","de":"Inglourious Basterds"}'::jsonb, trame_i18n = '{"it":"Nella Francia occupata dai nazisti durante la seconda guerra mondiale, un gruppo di soldati ebrei americani guidati dal tenente Aldo Raine, noti come ''I Bastardi'', viene paracadutato per seminare il terrore tra le truppe tedesche. Le loro strade si incroceranno con quelle di Shosanna Dreyfus, una giovane ebrea sopravvissuta all''eccidio della sua famiglia per mano del spietato colonnello SS Hans Landa, che pianifica una clamorosa vendetta all''interno del proprio cinema a Parigi.","en":"In Nazi-occupied France during World War II, a group of Jewish-American soldiers known as \"The Basterds\" are chosen specifically to spread fear throughout the Third Reich by scalping and brutally killing Nazis. The Basterds, lead by Lt. Aldo Raine soon cross paths with a French-Jewish teenage girl who runs a movie theater in Paris which is targeted by the soldiers.","fr":"Dans la France occupée de 1940, un groupe de soldats juifs américains, les bâtards, mène des actions punitives particulièrement sanglantes contre les nazis du Troisième Reich. Leur chemin rencontre celui de Shosanna Dreyfus, une jeune juive réfugiée à Paris exploitante d''une salle de cinéma qui entend elle aussi assouvir sa propre vengeance envers les nazis.","es":"Segunda Guerra Mundial. Durante la ocupación de Francia por los alemanes, Shosanna Dreyfus presencia la ejecución de su familia por orden del coronel nazi Hans Landa. Ella consigue huir a París, donde adopta una nueva identidad como propietaria de un cine. En otro lugar de Europa, el teniente Aldo Raine adiestra a un grupo de soldados judíos \"Los bastardos\" para atacar objetivos concretos. Los hombres de Raine y una actriz alemana, que trabaja para los aliados, deben llevar a cabo una misión que hará caer a los jefes del Tercer Reich. El destino quiere que todos se encuentren bajo la marquesina de un cine donde Shosanna espera para vengarse.","de":"Im von Deutschland besetzten Frankreich muss Shosanna ansehen wie ihre Familie durch Oberst Hans Landa brutal ermordet wird. Sie kann entkommen und flieht nach Paris. Gemeinsam mit seinen 8 Männern, einer Elitetruppe aus jüdisch-amerikanischen Soldaten, will Offizier Aldo Raine systematische Vergeltungsschläge gegen Nazis durchführen. Sie werden in Frankreich abgesetzt, um dort unterzutauchen. Von den Deutschen als ‚Die Bastarde'' gefürchtet versuchen sie den Führer des III. Reichs zu töten."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/aa1jLbxTTuA6o5ucHoZh2khwNSo.jpg","en":"https://image.tmdb.org/t/p/w500/aupnPtagH9JVBuMrGEanf4iqXEQ.jpg","fr":"https://image.tmdb.org/t/p/w500/lPKwFzX4TiWLA4Mo5Bnf8aIIrJm.jpg","es":"https://image.tmdb.org/t/p/w500/dqu7nUtKTLdpM7DaJvD4zcSXhn1.jpg","de":"https://image.tmdb.org/t/p/w500/7Nq9bqyloLwYLkrG7q0tHI6kO45.jpg"}'::jsonb WHERE id = 144;
UPDATE public.films SET tmdb_id = 500, titoli_i18n = '{"en":"Reservoir Dogs","it":"Le iene","es":"Reservoir Dogs","fr":"Reservoir Dogs","de":"Reservoir Dogs - Wilde Hunde"}'::jsonb, trame_i18n = '{"en":"A botched robbery indicates a police informant, and the pressure mounts in the aftermath at a warehouse. Crime begets violence as the survivors -- veteran Mr. White, newcomer Mr. Orange, psychopathic parolee Mr. Blonde, bickering weasel Mr. Pink and Nice Guy Eddie -- unravel.","it":"Dopo che una rapina a una gioielleria sfocia in un sanguinoso scontro a fuoco con la polizia, i sopravvissuti di una banda di criminali sconosciuti tra loro si rifugiano in un capannone abbandonato, convinti che tra di loro ci sia un infiltrato.","es":"Una banda organizada formada por seis individuos es contratada para dar un golpe. Anteriormente varios de los miembros no se conocían entre sí, por lo que entre ellos usan nombres en clave. El objetivo: atracar una empresa para llevarse unos diamantes. Pero, antes de que suene la alarma, la policía ya está allí. Algunos mueren en el atraco, y el resto se reúne en el lugar convenido.","fr":"Après un hold‐up manqué, des cambrioleurs de haut vol font leurs comptes dans une confrontation violente, pour découvrir lequel d’entre eux les a trahis.","de":"Ein perfekt geplanter Coup endet in einem rücksichtslosen Psycho-Horrortrip, der blutige Opfer fordert. Beteiligt sind sechs elegant gekleidete Profi-Gangster, die zu einem Überfall auf ein Juweliergeschäft zusammenkommen. Alles, was die Gentlemen voneinander wissen, sind die Decknamen, die ihnen ihr Auftraggeber Joe Cabot gegeben hat. Mr. White, Mr. Orange, Mr. Pink, Mr. Blonde, Mr. Blue, Mr. Brown. Doch der todsichere Coup misslingt, die Polizei war informiert. Am geheimen Treffpunkt, einem leerstehenden Lagerhaus, wird ein Verdacht zur Gewissheit: unter ihnen ist ein Spitzel. Tödliches Misstrauen macht sich breit. Während einer der Gangster zu verbluten droht, entwickeln sich die anderen zu reißenden Bestien, die weder vor der Folter an einem gekidnappten Polizisten noch vor blutiger Gewalt untereinander zurückschrecken."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/xi8Iu6qyTfyZVDVy60raIOYJJmk.jpg","it":"https://image.tmdb.org/t/p/w500/noWeDEXd0a8du7tWG9F16Pm3Cvv.jpg","es":"https://image.tmdb.org/t/p/w500/hxmJqXFFnXLlvPIdCW2k3UGLCgZ.jpg","fr":"https://image.tmdb.org/t/p/w500/b62t5xsAMGZ2LOLbD0l85xQE3tr.jpg","de":"https://image.tmdb.org/t/p/w500/AdXZmqOq2XcJQvHN3nKIXTd6ilq.jpg"}'::jsonb WHERE id = 145;
UPDATE public.films SET tmdb_id = 78, titoli_i18n = '{"it":"Blade Runner","en":"Blade Runner","fr":"Blade Runner","de":"Der Blade Runner","es":"Blade Runner"}'::jsonb, trame_i18n = '{"it":"In una Los Angeles distopica e piovosa del 2019, l''ex poliziotto Rick Deckard viene richiamato in servizio come ''blade runner''. Il suo compito è rintracciare e ''ritirare'' quattro replicanti della serie Nexus-6, androidi indistinguibili dagli umani, fuggiti dalle colonie extra-terrestri e giunti illegalmente sulla Terra alla ricerca del loro creatore per prolungare la propria breve vita.","en":"In the smog-choked dystopian Los Angeles of 2019, blade runner Rick Deckard is called out of retirement to terminate a quartet of replicants who have escaped to Earth seeking their creator for a way to extend their short life spans.","fr":"2019, Los Angeles. La Terre est surpeuplée et l’humanité est partie coloniser l’espace. Les nouveaux colons sont assistés de Replicants, androïdes que rien ne peut distinguer de l''être humain. Conçus comme de nouveaux esclaves, certains parmi les plus évolués s’affranchissent de leurs chaînes et s’enfuient. Rick Deckard, un ancien Blade Runner, catégorie spéciale de policiers chargés de \"retirer\" ces replicants, accepte une nouvelle mission consistant à retrouver quatre de ces individus qui viennent de regagner la Terre après avoir volé une navette spatiale.","de":"Man schreibt das Jahr 2019. Den Replikanten, künstlichen Menschen, ist bei Todesstrafe die Rückkehr zur Erde verboten. Doch trotzdem kehren eines Tages einige dieser Wesen zurück. Diese besondere Spezies verfügt über Kraft und Intelligenz mehrerer Menschen und ist von diesen kaum zu unterscheiden. Sie sollen unschädlich gemacht werden. Nur eine Spezialeinheit kann sie aufspüren: die Blade Runner. Eine atemberaubende Hetzjagd durch die futuristische Welt beginnt.","es":"A principios del siglo XXI, la Tyrell Corporation desarrolló un nuevo tipo de robot llamado Nexus, un ser virtualmente idéntico al hombre y conocido como Replicante.  Los Replicantes Nexus-6 eran superiores en fuerza y agilidad, y al menos iguales en inteligencia, a los ingenieros de genética que los crearon.  En el espacio exterior, los Replicantes fueron usados como trabajadores esclavos en la arriesgada exploración y colonización de otros planetas.  Después de la sangrienta rebelión de un equipo de combate de Nexus-6 en una colonia sideral, los Replicantes fueron declarados proscritos en la Tierra bajo pena de muerte.  Brigadas de policías especiales, con el nombre de Unidades de Blade Runners, tenían órdenes de tirar a matar al ver a cualquier Replicante invasor.  A esto no se le llamó ejecución, se le llamó retiro."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2mPclQ5v9YK0eqCefvav3YsYPYI.jpg","en":"https://image.tmdb.org/t/p/w500/63N9uy8nd9j7Eog2axPQ8lbr3Wj.jpg","fr":"https://image.tmdb.org/t/p/w500/zHKWxyG4j404HVeSYHNH4niUpkW.jpg","de":"https://image.tmdb.org/t/p/w500/iD88HsailBEKNBoxj82CxtXesHX.jpg","es":"https://image.tmdb.org/t/p/w500/pBA2J6iQMiP5Zd4ewMKdOWfq1HV.jpg"}'::jsonb WHERE id = 146;
UPDATE public.films SET tmdb_id = 9671, titoli_i18n = '{"en":"Crocodile Dundee","es":"Cocodrilo Dundee","it":"Mr. Crocodile Dundee","fr":"Crocodile Dundee","de":"Crocodile Dundee - Ein Krokodil zum Küssen"}'::jsonb, trame_i18n = '{"en":"When a New York reporter plucks crocodile hunter Mick Dundee from the Australian Outback for a visit to the Big Apple, it''s a clash of cultures and a recipe for good-natured comedy as naïve Dundee negotiates the concrete jungle. He proves that his instincts are quite useful in the city and adeptly handles everything from wily muggers to high-society snoots without breaking a sweat.","es":"Michael Dundee es un amigable y rudo cazador de cocodrilos en el salvaje outback australiano que, por su original filosofía de la vida, es considerado como un héroe entre los suyos. Su fama llega a oídos de Sue Charlton, una reportera de Nueva York que decide ir a Australia para visitarle y, una vez allí, le convence para que le acompañe en su viaje de regreso a América.","it":"Sue Charlton, una giornalista di New York, si reca nell''outback australiano per incontrare Michael J. \"Crocodile\" Dundee, un leggendario cacciatore di coccodrilli. Affascinata dal suo stile di vita, lo invita a New York, dove Dundee dovrà adattarsi alla caotica vita della metropoli.","fr":"Crocodile Dundee alias Michael J. est un aventurier qui hante les vastes étendues du Bush australien : repas de lézards, larves et fourmis, rencontres inopinées avec des serpents et crocodiles… Élevé par une tribu d’aborigènes, il « zone » dans ces terrifiantes contrées comme un poisson dans l’eau. Sue Charlton, ambitieuse journaliste américaine, découvre l’homme sauvage et veut à tout prix faire un scoop. Elle finit par le rencontrer, l’emmène à New York, succombe à ses charmes et le suit pour le meilleur et pour le pire…","de":"Die amerikanische Journalistin Sue Charlton reist nach Down Under, um Mick „Crocodile“ Dundee kennenzulernen, über den sie abenteuerliche Geschichten rund um einen Kampf gegen ein Krokodil gelesen hat. Und tatsächlich erweist sich der australische Buschmann als naturverbundener Bursche, der es mit den Gefahren der australischen Flora und Fauna locker aufnehmen kann, weil er gelernt hat, auch in schwierigen Verhältnissen zu überleben. Fasziniert von dem Hinterwäldler lädt Sue Mick ein, sie nach New York zu begleiten. Dort muss Crocodile Dundee lernen, dass die Gefahren des Natur- und die des Großstadtdschungels nicht die gleichen sind. Aber der kernige Australier weiß natürlich, wie man sich einer neuen Umgebung anpasst und seine im Busch erworbenen Fähigkeiten aus stoischer Ruhe und kämpferischem Können kann er auch in New York anwenden."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/pduPduL1ub5kok3lPYT15ryC9L6.jpg","es":"https://image.tmdb.org/t/p/w500/q0Msbpvpe6yuvIUCyJuBbQ9UhUj.jpg","it":"https://image.tmdb.org/t/p/w500/j7slCp0VJeGPpcrUNykuZS2zrhL.jpg","fr":"https://image.tmdb.org/t/p/w500/1Oghywy3zfyTu0gxbnqzrZwlwDS.jpg","de":"https://image.tmdb.org/t/p/w500/jaHYkInyWaS8c9SrSvtLX5JaP5R.jpg"}'::jsonb WHERE id = 147;
UPDATE public.films SET tmdb_id = 8619, titoli_i18n = '{"it":"Master & Commander - Sfida ai confini del mare","es":"Master and commander: Al otro lado del mundo","de":"Master and Commander - Bis ans Ende der Welt","fr":"Master and Commander : De l''autre côté du monde","en":"Master and Commander: The Far Side of the World"}'::jsonb, trame_i18n = '{"it":"Durante le guerre napoleoniche, la fregata britannica HMS Surprise, guidata dal carismatico capitano Jack Aubrey, riceve l''ordine di intercettare e catturare la nave corsara francese Acheron. Dopo un devastante attacco a sorpresa da parte di quest''ultima, Aubrey decide di inseguire il nemico attraverso gli oceani, spingendosi fino a Capo Horn e alle isole Galápagos, in una caccia ossessiva che metterà a dura prova la lealtà e la sopravvivenza del suo equipaggio.","es":"Durante las guerras napoleónicas, un impetuoso capitán británico llevará su barco y a su tripulación al límite en una formidable persecución por las costas de Sudamérica tras un gran buque de guerra francés.","de":"Während der Napoleonischen Kriege bereist der charismatische Kapitän Jack Aubrey mit seiner HMS Surprise auf Forschungsreise die Weltmeere. Immer an seiner Seite: Der friedliebende Schiffsarzt Dr. Steven Maturin. Als das französische Kaperschiff Acheron die Surprise angreift und Schiff wie Mannschaft herbe Verluste zufügt, schwört Aubrey Rache. Es entbrennt eine gnadenlose Jagd, die die geschundene Mannschaft in einer sturmumtosten Fahrt vom Kap Horn über die Galapagos Inseln bis nach Südamerika führt.","fr":"1805, durant les guerres napoléoniennes, la HMS Surprise, commandée par le Capitaine Jack Aubrey se lance à la poursuite du vaisseau français Acheron à travers l''océan Pacifique (affrontant notamment le cap Horn). Ils croisent par ailleurs au large des îles Galápagos, dont la faune et la flore vont beaucoup intéresser le chirurgien Stephen Maturin, naturaliste passionné et précurseur de Charles Darwin. Mais les événements vont changer les plans du capitaine.","en":"After an abrupt and violent encounter with a French warship inflicts severe damage upon his ship, a captain of the British Royal Navy begins a chase over two oceans to capture or destroy the enemy, though he must weigh his commitment to duty and ferocious pursuit of glory against the safety of his devoted crew, including the ship''s thoughtful surgeon, his best friend."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/6J8Cpjaan2KfLGglruBZE7MoTo7.jpg","es":"https://image.tmdb.org/t/p/w500/6wk7lrTxk6Adnzp1mVWexM1lj5b.jpg","de":"https://image.tmdb.org/t/p/w500/wCaEKGKV8DMnAWAApWYdFN1ZpY7.jpg","fr":"https://image.tmdb.org/t/p/w500/xgxlMRIrtHqmkUKv9IuMnXINYsE.jpg","en":"https://image.tmdb.org/t/p/w500/7ZUHF6P0vcA5v1Gm8NbRYyd9w4N.jpg"}'::jsonb WHERE id = 148;
UPDATE public.films SET tmdb_id = 6916, titoli_i18n = '{"it":"...altrimenti ci arrabbiamo!","es":"…Y si no, nos enfadamos","en":"Watch Out, We''re Mad","de":"Zwei wie Pech und Schwefel","fr":"Attention, on va s''fâcher !"}'::jsonb, trame_i18n = '{"it":"Ben e Kid, un meccanico e un camionista appassionati di autocross, vincono a pari merito una fantastica Dune Buggy rossa con cappottina gialla. Non potendola dividere, decidono di giocarsela in una sfida a birra e salsicce. La gara viene però interrotta dagli scagnozzi di un gangster speculatore edilizio chiamato ''il Capo'', che distruggono il locale e danno fuoco alla macchina. I due si recano dal boss per pretendere una Dune Buggy nuova identica a quella distrutta, avvertendolo con un chiaro ''...altrimenti ci arrabbiamo!'': di fronte al rifiuto, scateneranno l''inferno a suon di memorabili scazzottate.","es":"Kid y Ben, amigos pero rivales, participan en una carrera de coches cuyo premio es un estupendo «dune-buggy», un minibólido rojo con capota amarilla. Después de innumerables peripecias, Kid y Ben llegan juntos a la meta, por lo que el minibólido les pertenece a los dos. Kid propone que se lo jueguen a «cervezas y salchichas».","en":"After a tied 1st place in a local stunt race, two drivers start a contest to decide who of them will own the prize, a dune buggy. But when a mobster destroys the car, they are determined to get it back.","de":"Ben und Kid – zwei begeisterte Hobbyrennfahrer – gehen bei einem Cross-Rennen gleichzeitig als Erste ins Ziel und müssen sich den Gewinn in Form eines Strandbuggys teilen. In einem benachbarten Freizeitpark soll deshalb ein Wettessen mit Bier und Würstchen den wahren Sieger ermitteln. Als eine Ganovenbande auftaucht und im Auftrag eines Grundstückspekulanten versucht, die Bewohner des Stadtviertels zu verschrecken, bilden die einstigen Rivalen sofort ein schlagkräftiges Team. Gemeinsam haben sie nicht nur vier wirksame Argumente gegen das skrupellose Vorgehen der Verbrecher, sondern schließlich auch einen Grund zur gegenseitigen Wiedergutmachung. Im Zuge ihrer Zerstörungsorgie erwischen die Ganoven nämlich auch das neue Gefährt der beiden passionierten Fahrer und sehen sich nun deren Zorn ausgesetzt. Die Gangster lassen ab jetzt nichts mehr unversucht, um Ben und Kid unter die Erde zu bringen, doch die beiden wissen sich zu wehren.","fr":"Kid et Ben, deux coureurs automobiles finissent ex-aequo dans une course dont le prix principal est une petite voiture. Alors que les tractations vont bon train pour savoir qui gagnera finalement le véhicule, un membre de la mafia détruit ce dernier. Kid et Ben vont alors faire équipe pour se venger..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/27bKMOKfVtOicxZPP1Nk78WyCFE.jpg","es":"https://image.tmdb.org/t/p/w500/zjc73gfkJ3BbAuZV4xggB8X3P1W.jpg","en":"https://image.tmdb.org/t/p/w500/oERikPHC3cr9UDCale6YrQxkyNW.jpg","de":"https://image.tmdb.org/t/p/w500/ou7i8HuxEdMGqTDh90nUCFaVO7I.jpg","fr":"https://image.tmdb.org/t/p/w500/7uvvdb8KYc8yjpn3rkZX0s8Na7b.jpg"}'::jsonb WHERE id = 149;
UPDATE public.films SET tmdb_id = 438631, titoli_i18n = '{"fr":"Dune","es":"Dune","it":"Dune","en":"Dune","de":"Dune"}'::jsonb, trame_i18n = '{"fr":"L''histoire de Paul Atreides, jeune homme aussi doué que brillant, voué à connaître un destin hors du commun qui le dépasse totalement. Car, s''il veut préserver l''avenir de sa famille et de son peuple, il devra se rendre sur Dune, la planète la plus dangereuse de l''Univers. Mais aussi la seule à même de fournir la ressource la plus précieuse capable de décupler la puissance de l''Humanité. Tandis que des forces maléfiques se disputent le contrôle de cette planète, seuls ceux qui parviennent à dominer leur peur pourront survivre…","es":"En un lejano futuro, la galaxia conocida es gobernada mediante un sistema feudal de casas nobles bajo el mandato del Emperador. Las alianzas y la política giran entorno a un pequeño planeta, Dune,  del que extrae la ''especia melange'', la materia prima que permite los viajes espaciales. La Casa Atreides, bajo el mandato del Duque Leto Atreides recibe el encargo de custodiar el planeta, relevando en la encomienda a sus históricos enemigos, los Harkonnen. Paul Atreides, hijo del duque, se verá atrapado en las intrigas políticas mientras descubre el destino que le deparan los desiertos de Dune.","it":"In un lontano futuro dell''umanità, il duca Leto Atreides accetta la gestione del pericoloso pianeta desertico Arrakis, noto anche come Dune, l''unica fonte della sostanza più preziosa dell''universo, la \"spezia\". Paul Atreides, il giovane erede della dinastia, dovrà viaggiare verso il pianeta più pericoloso dell''universo per assicurare il futuro della sua famiglia e del suo popolo.","en":"Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet''s exclusive supply of the most precious resource in existence - a commodity capable of unlocking humanity''s greatest potential - only those who can conquer their fear will survive.","de":"„Dune“ erzählt die packende Geschichte des brillanten jungen Helden Paul Atreides, dem das Schicksal eine Rolle vorherbestimmt hat, von der er niemals geträumt hätte. Um die Zukunft seiner Familie und seines gesamten Volkes zu sichern, muss Paul auf den gefährlichsten Planeten des Universums reisen. Nur auf dieser Welt existiert ein wertvoller Rohstoff, der es der Menschheit ermöglichen könnte, ihr vollständiges geistiges Potenzial auszuschöpfen. Doch finstere Mächte wollen die Kontrolle über die kostbare Substanz an sich reißen. Es entbrennt ein erbitterter Kampf, den nur diejenigen überleben werden, die ihre eigenen Ängste besiegen."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/qpyaW4xUPeIiYA5ckg5zAZFHvsb.jpg","es":"https://image.tmdb.org/t/p/w500/szcew6yyjcDvaL0isaPBk2e3nkF.jpg","it":"https://image.tmdb.org/t/p/w500/zolKD2yscZd86GviNa6pBPc6N9o.jpg","en":"https://image.tmdb.org/t/p/w500/v1tRXZ4JtD2Iv6fjkPvT4GiwslV.jpg","de":"https://image.tmdb.org/t/p/w500/34Hr4bEzF30jd6sEvI4HihEUEI8.jpg"}'::jsonb WHERE id = 150;
UPDATE public.films SET tmdb_id = 693134, titoli_i18n = '{"it":"Dune - Parte due","en":"Dune: Part Two","es":"Dune: Parte dos","de":"Dune: Part Two","fr":"Dune : Deuxième partie"}'::jsonb, trame_i18n = '{"it":"Paul Atreides si unisce a Chani e ai Fremen sul sentiero della vendetta contro i cospiratori che hanno distrutto la sua famiglia. Di fronte alla scelta tra l''amore della sua vita e il destino dell''universo conosciuto, Paul intraprende una missione per impedire un futuro terribile che solo lui è in grado di prevedere.","en":"Follow the mythic journey of Paul Atreides as he unites with Chani and the Fremen while on a path of revenge against the conspirators who destroyed his family. Facing a choice between the love of his life and the fate of the known universe, Paul endeavors to prevent a terrible future only he can foresee.","es":"Sigue el viaje mítico de Paul Atreides mientras se une a Chani y los Fremen en una guerra de venganza contra los conspiradores que destruyeron a su familia. Al enfrentarse a una elección entre el amor de su vida y el destino del universo conocido, Paul se esfuerza por evitar un futuro terrible que solo él puede prever.","de":"Paul Atreides begibt sich mithilfe von Chani und den Fremen auf einen Rachefeldzug gegen die Verschwörer, die seine Familie vernichtet haben. Der junge Paul steht vor der Wahl zwischen der Liebe seines Lebens und dem Schicksal des gesamten Universums. Mit allen Mitteln aber muss er versuchen, eine schreckliche Zukunft zu verhindern – eine Zukunft, die niemand außer ihm vorhersehen kann.","fr":"Le voyage mythique de Paul Atreides qui s''allie à Chani et aux Fremen dans sa quête de vengeance envers les conspirateurs qui ont anéanti sa famille. Devant choisir entre l''amour de sa vie et le destin de l''univers, il fera tout pour éviter un terrible futur que lui seul peut prédire."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/nhdQxDCI64rMgypYZpsF7UvbdJA.jpg","en":"https://image.tmdb.org/t/p/w500/6izwz7rsy95ARzTR3poZ8H6c5pp.jpg","es":"https://image.tmdb.org/t/p/w500/v2NN1TMK3ifuiEyawa3ukkcSOUQ.jpg","de":"https://image.tmdb.org/t/p/w500/zYLP7Uiqz6XqoiQLAu4XQ6DRUMz.jpg","fr":"https://image.tmdb.org/t/p/w500/iRNbRAIGQQr5diGnjpwJFm0dgt4.jpg"}'::jsonb WHERE id = 151;
UPDATE public.films SET tmdb_id = 503, titoli_i18n = '{"it":"Poseidon","es":"Poseidón","fr":"Poséidon","de":"Poseidon","en":"Poseidon"}'::jsonb, trame_i18n = '{"it":"Durante la notte di Capodanno, una gigantesca onda anomala travolge e capovolge la lussuosa nave da crociera Poseidon. Un piccolo gruppo di sopravvissuti decide di non aspettare i soccorsi e tenta una disperata fuga verso la salvezza attraverso lo scafo capovolto.","es":"En el Atlántico Norte, a bordo del lujoso trasatlántico Poseidón (veinte pisos, trece cubiertas) comienza la fiesta de Nochevieja. Mientras tanto, una gigantesca ola de treinta metros de altura se dirige hacia la nave a gran velocidad. Los intentos para desviar el barco y evitar el choque son inútiles. La ola lo golpea con una fuerza colosal y lo vuelca. Los pasajeros y los miembros de la tripulación caen desde una gran altura y van a parar entre los restos del naufragio o se sumergen en el mar. Tras el espectacular y dramático vuelco, las tuberías de gas quedan rotas y escupen fuego, y la electricidad falla dejando grandes secciones del buque sumergidas en la oscuridad y el caos.","fr":"Une nuit de Saint Sylvestre festive a commencé au milieu de l''Atlantique Nord, sur le luxueux navire de croisière Poséidon. De nombreux passagers se sont rassemblés dans l''opulente salle de bal pour fêter dignement l''événement avec le capitaine Bradford. Pendant ce temps, le second scrute avec inquiétude l''horizon du haut de la passerelle. La menace surgit en quelques secondes, sous la forme d''une vague géante de plus de 30 mètres de haut, fonçant à toute allure sur le navire. Le second redresse la barre pour éviter un choc frontal, mais il est déjà trop tard. La muraille d''eau se fracasse avec une violence inouïe sur le paquebot qu''elle retourne, quille en l''air. Quelques centaines de rescapés se retrouvent dans la salle de bal, encore intacte quoique située sous la ligne de flottaison…","de":"Auf allen Decks des Kreuzfahrtschiffes \"Poseidon\" wird kräftig Silvester gefeiert. Da erfasst eine Monsterwelle den Ozeanriesen und wirft ihn einfach um. Das kopfüber gekenterte Schiff läuft mit Wasser voll. Eine Gruppe Überlebender, darunter der Zocker Dylan, die Witwe Maggie mit ihrem Sohn Connor und der Ex-Feuerwehrmann Robert Ramsey samt Tochter und deren heimlichem Verlobten, entschließt sich, das Schicksal selbst in die Hand zu nehmen. Und so macht sie sich auf zu einem Höllentrip quer durch den Rumpf des sinkenden Luxusliners.","en":"A packed cruise ship traveling the Atlantic is hit and overturned by a massive wave, compelling the passengers to begin a dramatic fight for their lives."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qWenXpjkzQ04wt5DLwzwrSjxLhl.jpg","es":"https://image.tmdb.org/t/p/w500/4OlwVoSxeeP9TuZ5OdKWnIPLvsO.jpg","fr":"https://image.tmdb.org/t/p/w500/4VrwxE0CDoXxfgTRD11gCFlYaFP.jpg","de":"https://image.tmdb.org/t/p/w500/9SXa5QKjKeFYs6nq0zDqAzXasMX.jpg","en":"https://image.tmdb.org/t/p/w500/fDPdjGc8SUEDWfTwMaZlCE6NSi3.jpg"}'::jsonb WHERE id = 152;
UPDATE public.films SET tmdb_id = 862, titoli_i18n = '{"it":"Toy Story - Il mondo dei giocattoli","en":"Toy Story","fr":"Toy Story","de":"Toy Story","es":"Toy Story"}'::jsonb, trame_i18n = '{"it":"Woody, un classico pupazzo da cowboy, è il giocattolo preferito del piccolo Andy e il leader riconosciuto di tutti gli altri giochi della cameretta. La sua posizione viene però minacciata quando per il compleanno di Andy arriva Buzz Lightyear, un supertecnologico astronauta giocattolo convinto di essere un vero spaziotraversatore. Inizialmente rivali, Woody e Buzz si ritroveranno accidentalmente divisi da Andy e dovranno unire le forze per affrontare mille pericoli e tornare a casa.","en":"Led by Woody, Andy''s toys live happily in his room until Andy''s birthday brings Buzz Lightyear onto the scene. Afraid of losing his place in Andy''s heart, Woody plots against Buzz. But when circumstances separate Buzz and Woody from their owner, the duo eventually learns to put aside their differences.","fr":"Dans un monde où les jouets vivent leur vie quand les humains ne sont pas présents, Toy Story emmène les spectateurs dans un voyage fantastique vu principalement par les yeux de deux rivaux : Woody, un cow-boy, et Buzz l''Éclair, un ranger de l’espace. Ce duo va devoir apprendre à mettre ses différences de côté et s''allier, lorsqu’il sera séparé de son propriétaire Andy.","de":"Als Andys Lieblingspuppe hat Woody im Kinderzimmer das Sagen. Kaum ist der Junge nicht da, erwacht die Cowboy-Figur zum Leben, und mit ihm auch all das andere Spielzeug um ihn herum. Aufgeregt debattiert man über Andys bevorstehenden Geburtstag. Es wird befürchtet, daß ihr Besitzer ein neues Geschenk bevorzugen wird. Und tatsächlich: Der Neuankömmling Buzz Lightyear, ein stolzer Space Ranger, avanciert zu Andys Favoriten. Diese Herabstufung will Woody nicht hinnehmen.","es":"Los juguetes de Andy, un niño de seis años, temen que haya llegado su hora y que un nuevo regalo de cumpleaños les sustituya en el corazón de su dueño. Woody, un vaquero que ha sido hasta ahora el juguete favorito de Andy, trata de tranquilizarlos hasta que aparece Buzz Lightyear, un héroe espacial dotado de todo tipo de avances tecnológicos. Woody es relegado a un segundo plano, pero su constante rivalidad se transformará en una gran amistad cuando ambos se pierden en la ciudad sin saber cómo volver a casa."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9E1UvfLS9PIO9c8TJEOQ7kfFq3Z.jpg","en":"https://image.tmdb.org/t/p/w500/uXDfjJbdP4ijW5hWSBrPrlKpxab.jpg","fr":"https://image.tmdb.org/t/p/w500/4cWLRhub0yY9VJpdw0nqoTPYyiN.jpg","de":"https://image.tmdb.org/t/p/w500/om4fMx3e4xkx27sAsacoFP4WiEd.jpg","es":"https://image.tmdb.org/t/p/w500/jvn7wy3RSNEXnFSXLpH2of2LcV6.jpg"}'::jsonb WHERE id = 153;
UPDATE public.films SET tmdb_id = 863, titoli_i18n = '{"en":"Toy Story 2","it":"Toy Story 2 - Woody e Buzz alla riscossa","de":"Toy Story 2","fr":"Toy Story 2","es":"Toy Story 2: Los juguetes vuelven a la carga"}'::jsonb, trame_i18n = '{"en":"Andy heads off to Cowboy Camp, leaving his toys to their own devices. Things shift into high gear when an obsessive toy collector named Al McWhiggen, owner of Al''s Toy Barn kidnaps Woody. Andy''s toys mount a daring rescue mission, Buzz Lightyear meets his match and Woody has to decide where he and his heart truly belong.","it":"Mentre Andy è via per il campeggio estivo, Woody viene rapito da Al McWhiggin, un gordo e avido collezionista di giocattoli deciso a venderlo a un museo di Tokyo insieme ai membri della classica serie TV ''Woody''s Roundup''. Buzz Lightyear e gli altri giocattoli di Andy partono immediatamente per una coraggiosa missione di salvataggio per riportare l''amico a casa.","de":"Als Woody von einem fiesen Sammler entführt wird macht sich die Puppen-Clique auf, ihren Freund zu befreien - aber schon auf die andere Straßenseite zu gelangen, gestaltet sich schwierig, ganz zu schweigen von den lauernden Gefahren im Spielzeugladen gegenüber: Doppelgänger stellen sich Buzz Lightyear in den Weg, durchgeknallte Barbie-Sirenen drohen die edlen Ritter vom rechten Weg abzubringen, und obendrein entkommt Zurg, der böse Imperator, aus seiner Plastikbox...","fr":"Andy part en colonie de vacances et laisse ses jouets à la maison. Les choses se gâtent quand le collectionneur Al McWhiggin kidnappe Woody. Dans l’appartement d’Al, Woody découvre qu’il est un objet de collection d’une émission des années 50, il rencontre d’autres jouets : Jessie, Pile-Poil, Papi Pépite. Buzz et les autres vont tenter de sauver Woody, avant qu’il ne devienne une pièce de musée.","es":"Cuando Andy se va de campamento dejando solos a los juguetes, Al McWhiggin, un compulsivo coleccionista de juguetes valiosos, secuestra a Woody. Buzz Lightyear y el resto de los juguetes de Andy deberán actuar con rapidez para rescatarlo, poniéndose al frente de una operación de rescate durante la cual se enfrentarán a múltiples peligros y divertidas situaciones."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/4rbcp3ng8n1MKHjpeqW0L7Fnpzz.jpg","it":"https://image.tmdb.org/t/p/w500/lHloXovbVaQ1tbOB1UaVQm6GgXo.jpg","de":"https://image.tmdb.org/t/p/w500/nS0QGWMcUFpxoML061PW50oeUS5.jpg","fr":"https://image.tmdb.org/t/p/w500/144DDQdfZxAK5xyPTETmygzGGuH.jpg","es":"https://image.tmdb.org/t/p/w500/8OTDKkJv2jXg5ZHKazFxBAttKkR.jpg"}'::jsonb WHERE id = 154;
UPDATE public.films SET tmdb_id = 10193, titoli_i18n = '{"it":"Toy Story 3 - La grande fuga","en":"Toy Story 3","es":"Toy Story 3","de":"Toy Story 3","fr":"Toy Story 3"}'::jsonb, trame_i18n = '{"it":"Andy, ormai cresciuto, sta per partire per il college. Woody, Buzz e gli altri giocattoli vengono accidentalmente donati a un asilo nido, il Sunnyside, che si rivelerà essere tutt''altro che un paradiso, sotto il controllo del malvagio orsetto Lotso. I giocattoli dovranno pianificare una grande fuga per tornare a casa.","en":"Woody, Buzz, and the rest of Andy''s toys haven''t been played with in years. With Andy about to go to college, the gang find themselves accidentally left at a nefarious day care center. The toys must band together to escape and return home to Andy.","es":"Sabiendo que su dueño Andy, que ya no es un niño, se prepara para ir a la universidad, el vaquero Woody, el astronauta Buzz y el resto de sus amigos juguetes comienzan a preocuparse ante su incierto futuro. Efectivamente todos acaban en una guardería, donde por ejemplo la muñeca Barbie conocerá al guapo Ken. Esta reunión de nuestros amigos con otros nuevos juguetes no será sino el inicio de un montón de trepidantes y divertidas aventuras.","de":"Der Moment des Abschieds ist gekommen: Andy ist den Kinderschuhen entwachsen und macht sich bereit, aufs College zu gehen. Für sein stets getreues Spielzeug hat er keine Verwendung mehr. Andys Mutter spendet die Spielsachen der Kindertagesstätte Sunnyside. Doch dieses angebliche Paradies entpuppt sich nach zuerst freundlicher Aufnahme durch die alteingesessenen Spielzeuge bald zum Gefängnis für die Freunde. Ein ausgeklügelter Ausbruchsplan wird ausgearbeitet - die Zeit drängt, denn hier geht nicht alles mit rechten Dingen zu.","fr":"Woody, Buzz l’Éclair et le reste des jouets reviennent dans une toute nouvelle aventure avec quelques nouveaux visages dont Ken et Barbie, le hérisson La Brosse et l’ours Lotso. Andy se prépare à partir pour l’université et Woody, Buzz, Jessie et les autres jouets se demandent ce qu’ils vont devenir. Quand ils arrivent à Sunnyside, c’est le début d’une nouvelle aventure."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/tTBILVsSwLRB2CiNVSlewd5XZsW.jpg","en":"https://image.tmdb.org/t/p/w500/AbbXspMOwdvwWZgVN0nabZq03Ec.jpg","es":"https://image.tmdb.org/t/p/w500/yBSISwqix2z0JiwIrM3r6fiI6Cm.jpg","de":"https://image.tmdb.org/t/p/w500/aHxQdb3Ennws1EIraHnOS3BFjVJ.jpg","fr":"https://image.tmdb.org/t/p/w500/zycAhl8iwRxu1NQ0tITqA6KXHIM.jpg"}'::jsonb WHERE id = 155;
UPDATE public.films SET tmdb_id = 301528, titoli_i18n = '{"it":"Toy Story 4","fr":"Toy Story 4","es":"Toy Story 4","de":"A Toy Story: Alles hört auf kein Kommando","en":"Toy Story 4"}'::jsonb, trame_i18n = '{"it":"Woody, Buzz e il resto della banda vivono felici con la loro nuova bambina, Bonnie. Quando Bonnie crea un nuovo riluttante giocattolo di nome Forky da un cucchiaio-forchetta usa e getta, Woody si assume il compito di proteggerlo. Durante un viaggio di famiglia on-the-road, Woody ritrova la sua vecchia amica Bo Peep, scoprendo una nuova prospettiva su cosa significhi essere un giocattolo.","fr":"Woody a toujours privilégié la joie et le bien‐être de ses jeunes propriétaires – Andy puis Bonnie – et de ses compagnons, n’hésitant pas à prendre tous les risques pour eux, aussi inconsidérés soient‐ils. L’arrivée de Forky, un nouveau jouet qui ne veut pas en être un dans la chambre de Bonnie, met toute la petite bande en émoi. C’est le début d’une grande aventure et d’un extraordinaire voyage pour Woody et ses amis. Le cowboy va découvrir à quel point le monde peut être vaste pour un jouet…","es":"Woody siempre ha tenido claro cuál es su labor en el mundo y cuál es su prioridad: cuidar a su dueño, ya sea Andy o Bonnie. Sin embargo, Woody descubrirá lo grande que puede ser el mundo para un juguete cuando Forky se convierta en su nuevo compañero de habitación. Los juguetes se embarcarán en una aventura de la que no se olvidarán jamás.","de":"Die Cowboy-Puppe Woody und sein Freund Buzz Lightyear haben sich mit den anderen Spielsachen gut im Kinderzimmer ihrer neuen Besitzerin, Bonnie, eingerichtet. Als das Mädchen aus einem Göffel (Gabel + Löffel) ein neues Spielzeug namens Forky bastelt und es ins Herz schließt, nehmen sie den ungewöhnlichen Zuwachs mit offenen Armen in ihre Mitte auf. Doch Forky sieht sich selbst eher als Abfall an und flüchtet, woraufhin Woody sich auf die Suche nach ihm macht, um ihn zurückzubringen.  Auf dem Ausflug im Wohnwagen mit Bonnies Familie nimmt Woody außerdem einen unerwarteten Umweg und trifft so in einem Antiquitätenladen seine verlorene Freundin, die Schäferin Bo Peep, wieder. Und dann taucht auch noch ein Freizeitpark am Horizont auf, der das Leben der Spielzeuge zusätzlich ins Chaos stürzt.","en":"Woody has always been confident about his place in the world, devoted to taking care of his kid—whether that''s Andy or Bonnie. But after Bonnie creates a reluctant new toy called \"Forky\", a road trip adventure alongside old and new friends challenges everything Woody believes about loyalty, purpose, and what it truly means to be a toy."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/lilCjgWKcwIpa55BuTzzI2BMZgP.jpg","fr":"https://image.tmdb.org/t/p/w500/qWtRA6rfUNm81A7ITDrq6WkfCNy.jpg","es":"https://image.tmdb.org/t/p/w500/yF1vPDuHVrAUMX5dy1tVMbAjkEL.jpg","de":"https://image.tmdb.org/t/p/w500/s1Laea6lrtQVs4HLC1Mtkjl9UAp.jpg","en":"https://image.tmdb.org/t/p/w500/w9kR8qbmQ01HwnvK4alvnQ2ca0L.jpg"}'::jsonb WHERE id = 156;
UPDATE public.films SET tmdb_id = 1084244, titoli_i18n = '{"en":"Toy Story 5","es":"Toy Story 5","it":"Toy Story 5","fr":"Toy Story 5","de":"Toy Story 5"}'::jsonb, trame_i18n = '{"en":"When Bonnie receives a Lilypad tablet as a gift and becomes obsessed, Buzz, Woody, Jessie and the rest of the gang''s jobs become exponentially harder when they have to go head to head with the all-new threat to playtime.","es":"Los juguetes de Bonnie se enfrentan a otra amenaza cuando la niña recibe una tableta llamada Lilypad, la cual absorbe toda su atención y pone en peligro el juego tradicional. Todos deben unirse para competir contra la tecnología y recuperar su lugar.","it":"In questo nuovo capitolo della celebre saga Pixar, i giocattoli si trovano ad affrontare una sfida del tutto moderna: la competizione con la tecnologia e i dispositivi elettronici, che catturano sempre di più l''attenzione dei bambini di oggi.","fr":"Buzz, Woody, Jessie et le reste de la bande verront leur travail remis en question lorsqu''ils découvriront que ce qui obsède les enfants d''aujourd''hui s’appelle... l''électronique !","de":"Die Kult-Spielzeuge sind zurück – und diesmal trifft Spielzeug auf Technik. Woody, Buzz Lightyear, Jessie und der Rest der Bande stehen vor einer ganz neuen Herausforderung, als sie auf Lilypad treffen, ein funkelnagelneues Tablet, das sehr eigenwillige Vorstellungen davon hat, was für ihr Kind Bonnie am besten ist. Wird das Spielen jemals wieder so sein wie zuvor?"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/sfQtVlIHljToOwYjhe21KPGzZWK.jpg","es":"https://image.tmdb.org/t/p/w500/pTjZfbFVWUIwUM5OzX3LVh84ejU.jpg","it":"https://image.tmdb.org/t/p/w500/i7eQGriXCmNpScSVzepNHn9nMPM.jpg","fr":"https://image.tmdb.org/t/p/w500/b2bt3UomRX41rHHZmIsSNmXzidU.jpg","de":"https://image.tmdb.org/t/p/w500/geypzdXdx8LooxB691r3bhlrybB.jpg"}'::jsonb WHERE id = 157;
UPDATE public.films SET tmdb_id = 272, titoli_i18n = '{"it":"Batman Begins","fr":"Batman Begins","es":"Batman Begins","en":"Batman Begins","de":"Batman Begins"}'::jsonb, trame_i18n = '{"it":"Dopo aver assistito all''omicidio dei suoi genitori, il giovane erede Bruce Wayne viaggia per il mondo alla ricerca di un modo per combattere le ingiustizie. Tornato a Gotham City, crea l''iconico alter ego di Batman per salvare la città dalla corruzione e dalle minacce del temibile Ra''s al Ghul e dello Spaventapasseri.","fr":"Alors que le souvenir de ses parents assassinés le hante, Bruce Wayne, désemparé, erre à travers le monde cherchant les moyens de combattre l''injustice et ses propres peurs. Avec l''aide de son dévoué majordome et homme de confiance Alfred, de l''inspecteur Jim Gordon et de son allié Lucius Fox, Wayne revient à Gotham City et révèle son alter ego : Batman, un justicier masqué qui utilise sa force, son intelligence et une batterie d''armes high-tech pour combattre les forces sinistres qui menacent la ville…","es":"¿Cómo cambia un hombre el mundo? Es una pregunta que obsesiona a Bruce Wayne al igual que el fantasma de sus padres, muertos a tiros ante sus ojos en las calles de Gotham una noche que cambió su vida para siempre. Atormentado por la culpa y la ira, el desilusionado heredero industrial desaparece de Gotham y viaja en secreto por el mundo, buscando los medios de luchar contra la injusticia y utilizar el miedo contra los que se aprovechan de los que tienen miedo. Con la ayuda de su leal mayordomo Alfred, el detective Jim Gordon - uno de los pocos buenos policías de las fuerzas del orden público de Gotham - y Lucius Fox, su aliado en la división de Ciencias Aplicadas de Wayne Enterprises, Bruce Wayne libera a su imponente alter ego: Batman, un justiciero enmascarado que utiliza la fuerza, la inteligencia y un despliegue de artefactos de alta tecnología para combatir las fuerzas siniestras que amenazan con destruir la ciudad.","en":"Driven by tragedy, billionaire Bruce Wayne dedicates his life to uncovering and defeating the corruption that plagues his home, Gotham City.  Unable to work within the system, he instead creates a new identity, a symbol of fear for the criminal underworld - The Batman.","de":"Wie wurde Bruce Wayne zu Batman? Als kleiner Junge musste Bruce Wayne mit ansehen, wie seine Eltern auf grauenhafte Weise umgebracht wurden. Deshalb kümmert sich der Butler Alfred Pennyworth um ihn und zieht ihn groß.Eines Tages macht er sich in aller Welt auf die Suche nach einem Weg, die Ungerechtigkeit zu bekämpfen. Als er nach seiner Reise wieder in seine Heimatstadt Gotham City zurückkehrt, muss er feststellen, dass die Verbrechensrate deutlich angestiegen ist. Dieser Umstand und der Drang nach Rache am Mord seiner Eltern treiben ihn langsam aber sicher dazu, sich Kampftechniken beizubringen und ein Fledermauskostüm zu entwerfen, mit deren Hilfe er Nacht für Nacht die Kriminellen der Stadt zur Strecke bringt - als Batman."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2eNeMwCncDvcJZ4AqKndWX71wDc.jpg","fr":"https://image.tmdb.org/t/p/w500/taKcn26BMWnsUcMFSlr5RfGDtFB.jpg","es":"https://image.tmdb.org/t/p/w500/6yMWU1vWkOBbNRIwOxhetd2aHhO.jpg","en":"https://image.tmdb.org/t/p/w500/sPX89Td70IDDjVr85jdSBb4rWGr.jpg","de":"https://image.tmdb.org/t/p/w500/b3UIToGx8JIpRqUTGkaoyaNLuU3.jpg"}'::jsonb WHERE id = 158;
UPDATE public.films SET tmdb_id = 155, titoli_i18n = '{"it":"Il cavaliere oscuro","en":"The Dark Knight","de":"The Dark Knight","fr":"The Dark Knight : Le Chevalier noir","es":"El caballero oscuro"}'::jsonb, trame_i18n = '{"it":"Con l''aiuto del tenente Jim Gordon e del determinato procuratore distrettuale Harvey Dent, Batman continua a combattere il crimine organizzato che affligge Gotham City. La tregua apparente viene però spezzata dall''ascesa del Joker, una mente criminale psicopatica e anarchica che sprofonda la metropoli nel terrore e costringe il Cavaliere Oscuro a camminare sul filo sottile che divide l''eroe dal vigilante.","en":"Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.","de":"Gemeinsam mit Bezirksstaatsanwalt Harvey Dent und Lieutenant James Gordon versucht der im Fledermauskostüm agierende Milliardär Bruce Wayne dem Verbrechen in Gotham City Einhalt zu gebieten. Wie aus dem Nichts taucht plötzlich ein psychotischer Superverbrecher auf - der Joker. In seiner wahnhaften Vision möchte er die Stadt in Chaos und Anarchie stürzen und Batman scheint der einzige, der ihn stoppen kann. Bis es zum endgültigen Show-Down kommt, wird aber viel Blut fließen und auch Menschen die Bruce Wayne nahe stehen, könnten Opfer werden.","fr":"Batman aborde une phase décisive de sa guerre contre le crime à Gotham City. Avec l''aide du lieutenant de police Jim Gordon et du nouveau procureur Harvey Dent, il entreprend de démanteler les dernières organisations criminelles qui infestent les rues de la ville. L''association s''avère efficace, mais le trio se heurte bientôt à un nouveau génie du crime qui répand la terreur et le chaos dans Gotham : le Joker. On ne sait pas d''où il vient ni qui il est. Ce criminel possède une intelligence redoutable doublé d''un humour sordide et n''hésite pas à s''attaquer à la pègre locale dans le seul but de semer le chaos.","es":"Batman/Bruce Wayne regresa para continuar su guerra contra el crimen. Con la ayuda del teniente Jim Gordon y del Fiscal del Distrito Harvey Dent, Batman se propone destruir el crimen organizado en la ciudad de Gotham. El triunvirato demuestra su eficacia, pero, de repente, aparece Joker, un nuevo criminal que desencadena el caos y tiene aterrados a los ciudadanos."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qIhsgno1mjbzUbs4H6DaRjhskAR.jpg","en":"https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg","de":"https://image.tmdb.org/t/p/w500/z1DfRQf2CgnROyhVZ6ch8FbWt71.jpg","fr":"https://image.tmdb.org/t/p/w500/pyNXnq8QBWoK3b37RS6C3axwUOy.jpg","es":"https://image.tmdb.org/t/p/w500/8QDQExnfNFOtabLDKqfDQuHDsIg.jpg"}'::jsonb WHERE id = 159;
UPDATE public.films SET tmdb_id = 49026, titoli_i18n = '{"it":"Il cavaliere oscuro - Il ritorno","en":"The Dark Knight Rises","es":"El caballero oscuro: La leyenda renace","fr":"The Dark Knight Rises","de":"The Dark Knight Rises"}'::jsonb, trame_i18n = '{"it":"Otto anni dopo la morte di Harvey Dent, Gotham City vive un periodo di pace grazie alle leggi speciali del Decreto Dent. Tuttavia, l''arrivo in città di Bane, un terrorista spietato e mascherato, e della misteriosa scassinatrice Selina Kyle, costringe un Bruce Wayne ormai ritirato e debilitato a indossare nuovamente il mantello di Batman per affrontare la minaccia definitiva alla sua città.","en":"Following the death of District Attorney Harvey Dent, Batman assumes responsibility for Dent''s crimes to protect the late attorney''s reputation and is subsequently hunted by the Gotham City Police Department. Eight years later, Batman encounters the mysterious Selina Kyle and the villainous Bane, a new terrorist leader who overwhelms Gotham''s finest. The Dark Knight resurfaces to protect a city that has branded him an enemy.","es":"Hace ocho años que Batman desapareció, dejando de ser un héroe para convertirse en un fugitivo. Al asumir la culpa por la muerte del fiscal del distrito Harvey Dent, el Caballero Oscuro decidió sacrificarlo todo por lo que consideraba, al igual que el Comisario Gordon, un bien mayor. La mentira funciona durante un tiempo, ya que la actividad criminal de la ciudad de Gotham se ve aplacada gracias a la dura Ley Dent. Pero todo cambia con la llegada de una astuta gata ladrona que pretende llevar a cabo un misterioso plan. Sin embargo, mucho más peligrosa es la aparición en escena de Bane, un terrorista enmascarado cuyos despiadados planes obligan a Bruce a regresar de su voluntario exilio.","fr":"Afin que l''image de l''ex-procureur Harvey Dent reste un modèle du genre pour les citoyens de Gotham City, Batman a endossé les crimes de ce dernier et a été chassé de la ville par les autorités.  Huit ans plus tard, alors que Gotham City est de nouveau sûre, le commissaire Gordon tombe sur un complot qui vise à détruire la ville de l''intérieur.  Il fait appel à Batman. Ce dernier devra faire face à la mystérieuse Selina Kyle et à Bane, un adversaire mortel, qui veut mettre en pièce le symbole Batman.","de":"Nach dem Tod des Staatsanwalts Harvey Dent alias Two-Face nahm Batman die Schuld von dessen Verbrechen auf sich, um seinen Ruf zu schützen. Daher wurde er von dem Gotham City Police Department gejagt und verließ die Stadt. Die Handlung des Films setzt acht Jahre nach den Ereignissen von The Dark Knight ein. Nachdem der bemerkbar gealterte Batman nach Gotham zurückkehrt, muss er die Wahrheit der geheimnisvollen Selina Kyle herausfinden und den Schurken Bane davon abhalten, Gotham zu zerstören"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/p2JzxFRAlbxS4EvWMo4yiYZXu1W.jpg","en":"https://image.tmdb.org/t/p/w500/hr0L2aueqlP2BYUblTTjmtn0hw4.jpg","es":"https://image.tmdb.org/t/p/w500/rrS7K8tXVFUBliIKWaRuSq65nWr.jpg","fr":"https://image.tmdb.org/t/p/w500/ApcGBERN0p9I0nDOIwJeEmpnLU5.jpg","de":"https://image.tmdb.org/t/p/w500/9NyCuhyvFKTqGRLcr4r8fWXnu9v.jpg"}'::jsonb WHERE id = 160;
UPDATE public.films SET tmdb_id = 240832, titoli_i18n = '{"es":"Lucy","en":"Lucy","fr":"Lucy","it":"Lucy","de":"Lucy"}'::jsonb, trame_i18n = '{"es":"Lucy, una joven obligada a ejercer de mula de una nueva y potente droga, adquiere de repente enormes poderes sobrenaturales cuando la bolsa de la droga se rompe y los narcóticos entran en contacto con su cuerpo. Entonces, su cerebro comienza a aumentar la capacidad de uso hasta poder ser utilizado al 100%, convirtiéndose en una máquina letal con habilidades extraordinarias.","en":"A woman, accidentally caught in a dark deal, turns the tables on her captors and transforms into a merciless warrior evolved beyond human logic.","fr":"Lucy, une jeune étudiante ordinaire, se fait kidnapper. À son réveil, elle découvre que les membres d’une organisation criminelle lui ont inséré un paquet de drogue dans l’estomac dans le but de lui faire passer la frontière. Mais lorsqu’à la suite d’un coup porté à son ventre le produit se déverse dans son corps et s’implante dans son système, la jeune femme en subit les étonnants effets. Cette substance synthétique lui permet de décupler ses capacités intellectuelles et physiques. Devenue un génie autant qu’une véritable machine de guerre, Lucy dispose désormais de pouvoirs illimités et surhumains…","it":"Lucy è una giovane studentessa che vive a Taipei. Viene costretta a fare da corriere della droga da un cartello coreano. Le viene inserito chirurgicamente nel ventre un pacchetto contenente una nuova droga sintetica, il CPH4. A causa di un pestaggio, il pacchetto si rompe e la sostanza viene assorbita dal suo corpo, permettendole di sbloccare progressivamente le capacità del suo cervello fino al 100%.","de":"Die junge Lucy soll eigentlich nur einen harmlos erscheinenden Koffer in einem Hotel abgeben. Bei der Übergabe wird jedoch ihr Freund ermordet und der Inhalt stellt sich als neuartige Droge heraus. Der Empfänger, ein skrupelloser Drogendealer, zwingt sie, ein Paket der Droge in ihrem Körper nach Europa zu transportieren. Doch der Kurierdienst schlägt fehl und die gesamte Drogendosis gerät in Lucys Blutbahn. Wie durch ein Wunder kommt sie dabei nicht ums Leben, stattdessen entwickelt sie ungeahnte Kräfte."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/uy2TvHFwgKk6UzxxKnPsLkbQwTt.jpg","en":"https://image.tmdb.org/t/p/w500/kRbpUTRNm6QbLQFPFWUcNC4czEm.jpg","fr":"https://image.tmdb.org/t/p/w500/hLKoSzjOPC8tQaA2AmFvDjBbKTw.jpg","it":"https://image.tmdb.org/t/p/w500/oQIITXMMp9mEckfFst5hySZ8DAz.jpg","de":"https://image.tmdb.org/t/p/w500/vbwslYE4LAyMAGSyJch6bXwdn6s.jpg"}'::jsonb WHERE id = 161;
UPDATE public.films SET tmdb_id = 37165, titoli_i18n = '{"it":"The Truman Show","en":"The Truman Show","es":"El show de Truman","de":"Die Truman Show","fr":"The Truman Show"}'::jsonb, trame_i18n = '{"it":"Truman Burbank è un uomo apparentemente comune che vive in una tranquilla cittadina isolana. In realtà, la sua intera vita è uno show televisivo trasmesso in diretta mondiale 24 ore su 24, popolato da attori e scenografie, a sua totale insaputa. Quando inizia a notare delle anomalie, Truman decide di scoprire la verità e fuggire.","en":"In a picture-perfect seaside town, an insurance salesman begins to realize that his entire existence may be staged and observed by a vast unseen audience as part of a long-running real-time reality TV show.","es":"Truman Burbank es un hombre corriente y algo ingenuo que ha vivido toda su vida en uno de esos pueblos donde nunca pasa nada. Sin embargo, de repente, unos extraños sucesos le hacen sospechar que algo anormal está ocurriendo. Todos sus amigos son actores, toda su ciudad es un plató, toda su vida está siendo filmada y emitida como el reality más ambicioso de la historia.","de":"Die Truman Show ist seit beinahe dreißig Jahren ein TV-Klassiker auf der ganzen Welt. Seit seiner Geburt ist Truman Burbank der Hauptdarsteller der Serie – ohne es überhaupt zu wissen. Produzent Christof entwarf eine künstliche Welt, genannt Seahaven, in der Truman von über 5000 Kameras 24 Stunden am Tag bei fast jeder Kleinigkeit beobachtet wird. Um die Fassade nicht zum Einstürzen zu bringen sind seine Frau, Freunde und Verwandte allesamt Schauspieler. In Folge 10909 kommt es jedoch zu diversen versehentlichen Vorfällen die Truman misstrauisch werden lassen. Obwohl Schauspieler und Produzenten alles daran setzen Truman wieder in Zaum zu halten, lässt sich dieser nicht davon abhalten nach Ungereimtheiten zu forschen. Sein Streben nach einer echten Welt wird immer stärker, er plant seinen Ausbruch.","fr":"Il est la vedette d’un show télévisé - mais il ne le sait pas. Jim Carrey a conquis à la fois les critiques et le public pour sa prestation inoubliable dans ce chef-d''œuvre de Peter Weir. Il interprète Truman Burbank, un homme dont la vie entière est un show télévisé - Ses moindres faits et gestes sont filmés à son insu par un créateur/réalisateur/producteur avant-gardiste : la ville entière est un immense studio de cinéma ; ses voisins, ses collègues, ses amis et même sa femme sont des acteurs professionnels d’Hollywood. Un jour pourtant, Truman se doute de quelque chose. Sa réaction face à cette découverte vous fera rire, pleurer et vous émerveillera comme aucun film ne l’a jamais fait."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/vniJPHHUpjdVPTSGxn6b3z93nyK.jpg","en":"https://image.tmdb.org/t/p/w500/vuza0WqY239yBXOadKlGwJsZJFE.jpg","es":"https://image.tmdb.org/t/p/w500/8eWVXQZ6yqKfkuHhWD5RcdHnszT.jpg","de":"https://image.tmdb.org/t/p/w500/7JxsQZbcUZiYhAKeTorrFyFptQv.jpg","fr":"https://image.tmdb.org/t/p/w500/cOkoQaOPZBxqxQYlGu2i0o00sLn.jpg"}'::jsonb WHERE id = 162;
UPDATE public.films SET tmdb_id = 724406, titoli_i18n = '{"it":"Digger","en":"The Gold-digger","es":"Les michetonneuses","de":"Les michetonneuses","fr":"Les michetonneuses"}'::jsonb, trame_i18n = '{"en":"A trio of fashion-loving best friends from the Parisian suburbs dabble in sex work while pursuing freedom and luxury goods in the city of love.","de":"Drei junge Frauen. Eden ist libanesischer Herkunft, Maya ist Gallierin, und beide sind wunderschön. Anissa, die afrikanische Wurzeln hat, beginnt, deutlich an Gewicht zuzulegen.","fr":"Elles sont trois jeunes femmes venues d''horizons différents.  Si Eden et Maya sont superbes. Anissa, souffre d’obésité naissante. La première cesse de « michetonner », la seconde continue, Anissa aurait bien voulu mais ses rondeurs la freinent…  Elles tiennent à leur liberté, rêvent d’amour. Banlieusardes, elles investissent Paris en dépensant ce qu’elles gagnent en produits de luxe. La mode est leur patrie. La vie va chambouler cette situation quand Anissa est arrêtée pour avoir volé un sac de marque…  Une comédie dont les femmes sont les héroïnes.","it":"Nikitas è un padre che vive solitario in una foresta incontaminata nel nord della Grecia, resistendo con tenacia all''espansione di un colosso minerario che minaccia il suo ambiente. La sua isolata routine viene sconvolta dal ritorno improvviso di suo figlio Johnny dopo vent''anni di assenza, intenzionato a reclamare la sua parte di eredità."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kCKJt6q72hWOd6xuGXSzlzdXozc.jpg","en":"https://image.tmdb.org/t/p/w500/rm4UZ9DLXF06npLZMOTNTBNpWhk.jpg","es":"https://image.tmdb.org/t/p/w500/kCKJt6q72hWOd6xuGXSzlzdXozc.jpg","de":"https://image.tmdb.org/t/p/w500/kCKJt6q72hWOd6xuGXSzlzdXozc.jpg","fr":"https://image.tmdb.org/t/p/w500/kCKJt6q72hWOd6xuGXSzlzdXozc.jpg"}'::jsonb WHERE id = 163;
UPDATE public.films SET tmdb_id = 2024, titoli_i18n = '{"en":"The Patriot","es":"El patriota","fr":"The Patriot : Le Chemin de la liberté","de":"Der Patriot","it":"Il patriota"}'::jsonb, trame_i18n = '{"en":"After proving himself on the field of battle in the French and Indian War, Benjamin Martin wants nothing more to do with such things, preferring the simple life of a farmer. But when his son Gabriel enlists in the army to defend their new nation, America, against the British, Benjamin reluctantly returns to his old life to protect his son.","es":"Año 1776, Guerra de Independencia entre los colonos de Nueva Inglaterra y las tropas de Jorge III (1760-1820). En Carolina del Sur, el viudo Benjamin Martin (Mel Gibson), heroico soldado en Francia y en la India, renuncia a combatir para cuidar de sus siete hijos. Pero la pacífica vida de la familia Martin se ve alterada cuando Gabriel (Heath Ledger), el hijo mayor, se alista en el ejército; mientras tanto su padre se esfuerza por sacar adelante a la prole. Sin embargo, los británicos, al mando del cruel coronel Tavington (Jason Isaacs), llegarán hasta las puertas de su casa poniendo en peligro a toda la familia...","fr":"Caroline du Sud, 1776. Le conflit entre les indépendantistes et les Anglais semble inévitable. Benjamin Martin sait trop bien ce qu''est une guerre et il n''en veut pas. Cet ancien héros des combats contre les français et les indiens n''ignore rien de la violence des affrontements armés... Aujourd''hui veuf, il élève seul ses 7 enfants dans sa plantation. Son fils aîné, Gabriel, s''engage contre l''avis de son père. Lorsque les troupes anglaises, commandées par le colonel Tavington, arrivent aux portes de sa propriété, il est trop tard.","de":"Ende des 18. Jahrhunderts, South Carolina, USA. Benjamin Martin hat sich zurückgezogen und kümmert sich nach den Tagen als Kriegsheld nur noch um sein Gut und seine Familie. Die Engländer dringen als Kolonialmacht vor und gefährden seinen Besitz, sein ältester Sohn stirbt und sein Haus wird niedergerissen. Martin möchte jedoch nur Frieden, erkennt aber relativ schnell, dass er seine Existenz samt Familie nur dann beschützen kann, wenn er gegen die Engländer zu den Waffen greift...","it":"Nel 1776, in Carolina del Sud, il veterano di guerra Benjamin Martin decide di non prendere parte alla guerra d''indipendenza americana per accudire i suoi sette figli. Tuttavia, quando un spietato ufficiale britannico uccide uno dei suoi ragazzi e dà alle fiamme la sua casa, Benjamin prende di nuovo le armi guidando una milizia di volontari contro l''esercito inglese."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/fWZd815QxUCUcrWQZwUkAp9ljG.jpg","es":"https://image.tmdb.org/t/p/w500/cizgIaq65fpq2Ft08dPmZtUxDYv.jpg","fr":"https://image.tmdb.org/t/p/w500/xckzQXDUceZFAWsenLSTLhFlStq.jpg","de":"https://image.tmdb.org/t/p/w500/1iXMmBZ0X98J8JYEeuwxXT0SaPK.jpg","it":"https://image.tmdb.org/t/p/w500/tAS04P7tuhnKA28QskKprmtuLwI.jpg"}'::jsonb WHERE id = 164;
UPDATE public.films SET tmdb_id = 1248832, titoli_i18n = '{"it":"Digger","fr":"Digger","de":"Digger","en":"Digger","es":"Digger"}'::jsonb, trame_i18n = '{"it":"Incentrato sulla storia dell''uomo più potente del mondo, il quale intraprende una missione frenetica per dimostrare di essere il salvatore dell''umanità prima che la catastrofe scatenata da lui stesso distrugga ogni cosa.","fr":"L’homme le plus puissant du monde se lance dans une mission frénétique pour prouver qu’il est le sauveur de l’humanité avant que le désastre qu’il a déclenché ne détruise tout.","de":"Digger Rockwell, der mächtigste Mann der Welt, begibt sich auf eine verzweifelte Mission, um zu beweisen, dass er der Retter der Menschheit ist, bevor die Katastrophe, die er selbst ausgelöst hat, alles vernichtet.","en":"The most powerful man in the world embarks on a frantic mission to prove he is humanity''s savior before the disaster he''s unleashed destroys everything.","es":"El hombre más poderoso del mundo se embarca en una misión frenética para demostrar que es el salvador de la humanidad antes de que el desastre que ha desencadenado lo destruya todo."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/wisikjQcsvw0XqyQQYBsxudb38Z.jpg","fr":"https://image.tmdb.org/t/p/w500/gPCCGMQCrrMNM3mR3vqIdbdJxJ5.jpg","de":"https://image.tmdb.org/t/p/w500/d8kX0IXh42znJiBGMRb32O9Iq5w.jpg","en":"https://image.tmdb.org/t/p/w500/1ATXKrIPJyKNwnJ6lcG088Sa6zi.jpg","es":"https://image.tmdb.org/t/p/w500/koqE0V2IgIPVy5o2vVkoGJvnB8b.jpg"}'::jsonb WHERE id = 165;
UPDATE public.films SET tmdb_id = 1645, titoli_i18n = '{"it":"Il momento di uccidere","en":"A Time to Kill","fr":"Le Droit de tuer ?","de":"Die Jury","es":"Tiempo de matar"}'::jsonb, trame_i18n = '{"it":"In una cittadina del Mississippi, un operaio afroamericano uccide i due uomini bianchi che hanno brutalmente violentato la sua figlioletta di dieci anni. Un giovane e ambizioso avvocato bianco decide di assumere la sua difesa, affrontando un processo ad altissima tensione razziale che risveglia le violenze del Ku Klux Klan.","en":"A young lawyer defends a black man accused of murdering two white men who raped his 10-year-old daughter, sparking a rebirth of the KKK.","fr":"Dans une bourgade du Mississippi marquée par les violences racistes, Carl Lee Hailey, après le viol de sa fille de dix ans par deux Blancs, engage un jeune avocat, Jake Brigance. Il lui confie sa crainte de voir l''affaire finir en non-lieu. Quelques heures plus tard, Carl Lee se fait justice en abattant les deux violeurs. Bien décidé à sauver la tête de son client, Jake Brigance va être entrainé dans la terrible spirale de la violence.","de":"In dem kleinen Mississippi-Städtchen Canton wird ein junger Anwalt mit einem mörderischen Fall betraut, als nach der Vergewaltigung und dem Mord an einem farbigen Mädchen der Vater im Gerichtsgebäude Rache nimmt und die vermeintlichen Täter erschießt. Nun steht der Vater vor Gericht und der Klu-Klux-Klan in der Gegend wird ebenfalls wieder aktiv. Unterstützt von einer jungen Studentin gerät das Leben aller Beteiligten in Gefahr, als Anschläge verübt werden. Doch die größte Gefahr lauert vor Gericht, in Person des gewieften Staatsanwalts Buckley","es":"En una tranquila localidad sureña de Mississippi dos jóvenes borrachos violan salvajemente a una niña negra de diez años. La mayoría blanca de la ciudad se muestra horrorizada ante tan atroz crimen. Carl Lee, el padre de la niña, armado con un rifle de asalto, decide tomarse la justicia por su mano y mata a los violadores de su hija. Mientras la tensión va creciendo y reaparecen en las calles las cruces ardiendo del Ku Klux Klan, Jake Brigance, un joven abogado blanco, hará todo lo posible por salvar la vida de Carl Lee y proteger la suya."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/u8lpYepqSQ9d58GR7K6KS1FEhZn.jpg","en":"https://image.tmdb.org/t/p/w500/w8UCke112E9jrhjKcwG32kyhTx5.jpg","fr":"https://image.tmdb.org/t/p/w500/re4C9X5a3obaaqikCGpGx9FbCRq.jpg","de":"https://image.tmdb.org/t/p/w500/tBPZl3rWcyzRsmXn6C5wjJzga11.jpg","es":"https://image.tmdb.org/t/p/w500/xqRsY5i4vAwk0bWOUToJw1pssp6.jpg"}'::jsonb WHERE id = 166;
UPDATE public.films SET tmdb_id = 1317288, titoli_i18n = '{"es":"Marty Supreme","it":"Marty Supreme","de":"Marty Supreme","fr":"Marty Supreme","en":"Marty Supreme"}'::jsonb, trame_i18n = '{"es":"Biopic de Marty Reisman, un buscavidas convertido en campeón de ping pong, desde que empezó a jugar por apuestas en Manhattan hasta ganar 22 títulos importantes y convertirse en el más veterano en ganar una competición nacional de deportes de raqueta, con 67 años.","it":"Liberamente ispirato alla vita del celebre e non convenzionale giocatore di tennistavolo Marty Reisman, il film racconta le vicende, le scommesse e l''ascesa di un eccentrico campione di ping pong nell''America degli anni Cinquanta.","de":"Schuhverkäufer Marty hat nur ein Ziel: Weltmeister im Tischtennis zu werden und somit in den Olymp der gefeierten Athleten aufzusteigen, zu denen er sich selbst schon lange zählt. Um an einem Turnier in London teilnehmen zu können, riskiert er alles.","fr":"Marty Mauser, 23 ans, aspire à devenir le meilleur athlète sur la scène mondiale du tennis de table. Le sport est sous-représenté aux États-Unis, ce qui rend difficile le financement de ses compétitions à l''étranger. Il est toutefois prêt à tout pour arriver à ses fins, y compris nouer des liens avec une ancienne actrice et son riche mari entrepreneur. Son entêtement pose un problème pour les personnes de son entourage, qui font souvent les frais de ses choix cavaliers.","en":"Marty Mauser, a young man with a dream no one respects, goes to hell and back in pursuit of greatness."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/mijSU0Rws3tBBbhdE5udxPSaZvF.jpg","it":"https://image.tmdb.org/t/p/w500/et9WEOYIel2xTEPL1xwBkifgO2V.jpg","de":"https://image.tmdb.org/t/p/w500/m3Sj2vnS9o1wcHG1fCpUIhz0Y7e.jpg","fr":"https://image.tmdb.org/t/p/w500/hjrvtc7UCrnsypfnLJuxx9ODKCi.jpg","en":"https://image.tmdb.org/t/p/w500/lYWEXbQgRTR4ZQleSXAgRbxAjvq.jpg"}'::jsonb WHERE id = 167;
UPDATE public.films SET tmdb_id = 6977, titoli_i18n = '{"de":"No Country for Old Men","fr":"No Country for Old Men","en":"No Country for Old Men","it":"Non è un paese per vecchi","es":"No es país para viejos"}'::jsonb, trame_i18n = '{"de":"Ein Mann stolpert förmlich über einen blutigen Tatort, einen Pick-up-Truck, vollgeladen mit Heroin, und unwiderstehlichen zwei Millionen Dollar in bar. Seine Entscheidung, das Geld für sich zu behalten, setzt eine gewaltvolle Kettenreaktion in Gang, die noch nicht einmal das Gesetz von West-Texas aufhalten kann.","fr":"1980, États-Unis, à la frontière qui sépare le Texas du Mexique, les trafiquants mexicains de drogue ont depuis longtemps remplacé les voleurs de bétail. Lorsque Llewelyn Moss découvre dans une plaine des véhicules abandonnés, cernée de cadavres ensanglantés, il ne sait rien de ce qui a conduit à ce drame. Mais il comprend qu''un échange a mal tourné et qu''ils se sont entre-tués. Il recherche un éventuel survivant, le piste et le retrouve mort, au pied d''un arbre avec une valise contenant deux millions de dollars qu''il emporte. Il ne se doute pas de ce que cela va provoquer, mais il se doute que les trafiquants ne vont pas abandonner l''argent. Moss a déclenché une réaction en chaîne que le shérif Ed Tom Bell, un homme proche de la retraite, lucide et clairvoyant, va suivre à la trace…","en":"Llewelyn Moss stumbles upon dead bodies, $2 million and a hoard of heroin in a Texas desert, but methodical killer Anton Chigurh comes looking for it, with local sheriff Ed Tom Bell hot on his trail. The roles of prey and predator blur as the violent pursuit of money and justice collide.","it":"Nel Texas del 1980, Llewelyn Moss si imbatte nei resti di uno scambio di droga finito male e decide di scappare con una valigetta contenente due milioni di dollari. Sulle sue tracce si mette Anton Chigurh, uno spietato e metodico killer psicopatico armato di un fucile da macello, mentre l''anziano sceriffo Ed Tom Bell cerca disperatamente di salvare Moss e riflette sull''inarrestabile evoluzione della violenza nel mondo moderno.","es":"El veterano de la Guerra de Vietnam ahora cazador Llewellyn Moss descubre por casualidad una sangrienta escena en algún lugar de la frontera entre Texas y México, mientras estaba cazando algunos animales en el árido paisaje. Se trata de un negocio que se cerró mal entre contrabandistas de drogas y algunos hombres locales de la zona, provocando la muerte de varios de ellos. Además de los cuerpos y paquetes de heroína, Llewellyn descubre en una maleta algo más de dos millones de dólares. Cuando Llewellyn toma la maleta con el dinero, provoca una reacción en cadena de catastrófica violencia y una carrera sangrienta de los que quieren darle caza."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/nVaCwvzqy14tj5mBwzjWPZdDL02.jpg","fr":"https://image.tmdb.org/t/p/w500/TIIk6p8BziUM5dh8DD048PmcHX.jpg","en":"https://image.tmdb.org/t/p/w500/6d5XOczc226jECq0LIX0siKtgHR.jpg","it":"https://image.tmdb.org/t/p/w500/2zbXKL34bwaZ2gBygwoDE8DXHs7.jpg","es":"https://image.tmdb.org/t/p/w500/x9sQnOXhvec93L6cfWMGIx7BS4h.jpg"}'::jsonb WHERE id = 168;
UPDATE public.films SET tmdb_id = 600, titoli_i18n = '{"it":"Full Metal Jacket","es":"La chaqueta metálica","fr":"Full Metal Jacket","en":"Full Metal Jacket","de":"Full Metal Jacket"}'::jsonb, trame_i18n = '{"it":"Durante la guerra del Vietnam, un gruppo di reclute dei Marines affronta un disumanizzante e brutale addestramento nel campo di Parris Island, sotto la guida dello spietato sergente Hartman. Successivamente, il soldato Joker, diventato giornalista militare, viene inviato al fronte durante l''offensiva del Têt, toccando con mano la follia e la crudeltà del conflitto.","es":"Un grupo de reclutas se prepara en Parish Island, centro de entrenamiento de la marina Norteamericana. Allí está el sargento Hartmann, duro e implacable, cuya única misión en la vida es endurecer el cuerpo y el alma de los novatos, para que puedan defenderse del enemigo. Pero no todos los jóvenes soportan igual sus métodos...","fr":"Pendant la guerre du Vietnam, la préparation et l’entraînement d’un groupe de jeunes marines, jusqu’au terrible baptême du feu et la sanglante offensive du Tết à Hue, en 1968.","en":"A pragmatic U.S. Marine observes the dehumanizing effects the U.S.-Vietnam War has on his fellow recruits from their brutal boot camp training to the bloody street fighting in Hue.","de":"South Carolina 1967. Im Camp von Parris Island werden Joker und seine Kameraden auf traditionell-brutale Art zu Marines gedrillt. Der Ausbilder bezahlt seine Profiarbeit mit dem Leben: Leonard, sein Lieblingsopfer, erschießt den Schinder, bevor er sich selbst tötet. An der Dschungelfront in Vietnam, nach der Tet-Offensive, geraten Joker – der inzwischen als Journalist Heldenberichte für die Soldatenzeitung „Stars and Stripes“ schreibt – und seine Kameraden in den Hinterhalt eines Heckenschützen. Die scheinbar einfache Wiedereroberung Huếs gerät zum verlustreichen Desaster. Der Scharfschütze, ein Vietcong-Mädchen, wird von den Soldaten getötet. Und der Wahnsinn geht weiter …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/91pR97t391im33z2xnm0nvxUyv9.jpg","es":"https://image.tmdb.org/t/p/w500/6CX7BcyD8Xd5AQ7myNs0UE4mu6c.jpg","fr":"https://image.tmdb.org/t/p/w500/cShwwkz4gBBIRj8yFy8TP2tEWZ4.jpg","en":"https://image.tmdb.org/t/p/w500/kMKyx1k8hWWscYFnPbnxxN4Eqo4.jpg","de":"https://image.tmdb.org/t/p/w500/hi9TcrQZ6HjFoNMhgnxTM7wF4Gy.jpg"}'::jsonb WHERE id = 169;
UPDATE public.films SET tmdb_id = 602, titoli_i18n = '{"it":"Independence Day","es":"Independence Day","en":"Independence Day","de":"Independence Day","fr":"Independence Day"}'::jsonb, trame_i18n = '{"it":"Alla vigilia del 4 luglio, enormi astronavi alieni posizionano sopra le principali metropoli della Terra e scatenano un attacco devastante. Un gruppo di sopravvissuti, tra cui un pilota di caccia della Marina e uno scienziato esperto in telecomunicazioni, elabora un piano disperato per sconfiggere gli invasori e salvare l''umanità dall''estinzione.","es":"En víspera del 4 de julio, unas gigantescas naves espaciales aparecen en el cielo. El estupor inicial se convierte en terror al ver cómo éstas atacan al planeta lanzando rayos destructivos en las mayores ciudades de todo el mundo. Ahora la única esperanza para la salvación de la tierra está en la voluntad de algunos supervivientes, que se unen planeando el último ataque masivo contra los alienígenas, antes de que sea demasiado tarde para la humanidad.","en":"Strange phenomena surface around the globe. The skies ignite. Terror races through the world''s major cities. As these extraordinary events unfold, it becomes increasingly clear that a force of incredible magnitude has arrived. Its mission: total annihilation over the Fourth of July weekend. The last hope to stop the destruction is an unlikely group of people united by fate and unimaginable circumstances.","de":"Eine gewaltige außerirdische Armee bedroht die Existenz der Erde. Die Invasion beginnt mit dem Auftauchen gigantischer Raumschiffe, die sich über den wichtigsten Zentren der Welt positionieren. Die bedrohliche Faszination schlägt schnell in unvorstellbare Panik um, als die Raumschiffe angreifen und bedingungslos zerstören. Nun liegt das Schicksal der Menschheit in den Händen der wenigen Überlebenden, die sich für den alles entscheidenden Kampf gegen die Invasoren bereit machen…","fr":"Une immense soucoupe volante envahit le ciel terrestre, libérant un nombre infini de plus petites soucoupes qui prennent position au-dessus des plus grandes villes du monde. Un informaticien new-yorkais décrypte les signaux émanant des étranges voyageurs. Ils ne sont pas du tout amicaux et ces extraterrestres se préparent à attaquer la Terre."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/dXaARuPnIVEQWM8TkPSJ8LBpc16.jpg","es":"https://image.tmdb.org/t/p/w500/zhYisFUKLhlrbcrABMxQRzwuAM5.jpg","en":"https://image.tmdb.org/t/p/w500/p0BPQGSPoSa8Ml0DAf2mB2kCU0R.jpg","de":"https://image.tmdb.org/t/p/w500/xCTFGyQksFAvcmUMCc2hZG4hmdr.jpg","fr":"https://image.tmdb.org/t/p/w500/bkCauryW2TOWaEkGqyJMuJ0pRUV.jpg"}'::jsonb WHERE id = 170;
UPDATE public.films SET tmdb_id = 565179, titoli_i18n = '{"it":"Il primo re","es":"El primer rey","fr":"Romulus et Rémus","de":"The First King - Romulus & Remus","en":"The First King"}'::jsonb, trame_i18n = '{"it":"Nell''VIII secolo a.C., i fratelli pastori Romolo e Remo vengono travolti dall''esondazione del Tevere e fatti prigionieri dagli abitanti di Alba Longa. Riusciti a fuggire guidando una rivolta insieme ad altri prigionieri, i due intraprendono un viaggio guidati da Remo, che sfida la volontà degli dei finendo per scontrarsi tragicamente con Romolo, destinato a fondare la città di Roma.","es":"Rómulo y Remo son dos hermanos pastores de 18 años que viven cerca del río Tíber. Convencido de que él es más importante que los deseos de Dios, Remus cree que está destinado a ser rey de la ciudad que encontrará junto a su hermano. Pero su trágico destino ya está escrito. Este increíble viaje llevará a los dos hermanos a crear uno de los más grandes imperios que el mundo haya visto jamás.","fr":"L''histoire des jumeaux Remus et Romulus, fondateurs légendaires de Rome.","de":"Die Brüder Romulus und Remus führen ein einfaches und friedliches Leben als Schafhirten an den Ufern des Tibers, bis ihnen die Götter eines Tages nicht mehr gewogen zu sein scheinen. Die Geschwister werden von einer riesigen Flutwelle überrascht und von der Strömung mitgerissen. Fernab ihrer Heimat gelingt es den geschwächten Männern sich an Land zu retten, wo sie jedoch von Kriegern der Stadt Alba Longa aufgegriffen und als Gladiatoren versklavt werden. Doch den Brüdern gelingt es, sich und ihre Mitgefangenen zu befreien. Auf der Flucht vor ihren Verfolgern beschließen Romulus und Remus, getrieben von der Hoffnung auf Freiheit, eine neue und sichere Stadt zu errichten. Aber nur einem der Brüder ist die Herrschaft über das neue Reich bestimmt, das als eines der größten Imperien in die Geschichte eingehen wird.","en":"Romulus and Remus, two shepherds and loyal brothers, end up taking part to a journey that will lead one of them to be the founder of the greatest nation ever seen. However, the fate of the chosen one will pass from killing his own brother."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/mdM3dLbzF7bVhYTRQCPQiltP4vQ.jpg","es":"https://image.tmdb.org/t/p/w500/juxZxz0KoUfk8TApxJoLHcPR9dx.jpg","fr":"https://image.tmdb.org/t/p/w500/jJCsHiR4R9ioYqoPOk2ZJkAFpwt.jpg","de":"https://image.tmdb.org/t/p/w500/mdM3dLbzF7bVhYTRQCPQiltP4vQ.jpg","en":"https://image.tmdb.org/t/p/w500/dqBU63M3cKy7pfVsmhrbgY5X8iv.jpg"}'::jsonb WHERE id = 174;
UPDATE public.films SET tmdb_id = 117, titoli_i18n = '{"fr":"Les Incorruptibles","en":"The Untouchables","de":"The Untouchables - Die Unbestechlichen","it":"The Untouchables - Gli intoccabili","es":"Los intocables de Eliot Ness"}'::jsonb, trame_i18n = '{"fr":"À Chicago en 1930, à l’époque de la prohibition, le trafic d’alcool bat son plein et permet à des truands de bâtir des fortunes colossales. Eliot Ness, jeune policier frais émoulu du FBI, est chargé de démanteler un réseau de contrebande d’alcool. L’ennemi est facilement identifiable : Al Capone, inattaquable officiellement, est pourtant impliqué dans les affaires les plus sordides. La première mission de Ness, maladroitement conduite, se solde par un échec humiliant. Loin de se laisser décourager par ce premier affront, Ness décide de s’entourer de personnes de confiance. Il recrute ainsi Jim Malone, un flic qui connaît bien le monde des truands…","en":"Elliot Ness, an ambitious prohibition agent, is determined to take down Al Capone. In order to achieve this goal, he forms a group given the nickname “The Untouchables”.","de":"Im Chicago der 1930er Jahre macht die Mafia um den Gangsterboss Alfred ''Al'' Capone während der Prohibition florierende Umsätze mit illegalem Alkohol. Die korrupte Polizei deckt ihn dabei. Eliot Ness, Beamter des Finanzamts, stellt eine kleine Truppe unbestechlicher Mitstreiter zusammen. Besonders der ausgefuchste Polizist Malone hilft dem unerfahrenen Eliot, Al Capone in einem ausgeklügelten Feldzug hinter Gitter zu bringen.","it":"Durante il periodo del proibizionismo a Chicago, l''agente federale Eliot Ness crea una squadra speciale di uomini incorruttibili per fermare l''impero criminale del celebre boss mafioso Al Capone.","es":"El joven agente del tesoro Elliot Ness llega a Chicago con la determinación de detener a Al Capone. No va a ser tarea fácil, puesto que Capone tiene a la policía en el bolsillo. Ness conoce a Jimmy Malone, un guardia veterano y probablemente el más honrado de todo el cuerpo, al que Ness pide ayuda en su cruzada contra Capone."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/xrdMy48NrJSJYRplKfuQT0sDfSI.jpg","en":"https://image.tmdb.org/t/p/w500/tPq0R4jTO4Ey8ZspFaWK9wGA4Ls.jpg","de":"https://image.tmdb.org/t/p/w500/tNusbeamCBBAbI9720FDzUrCtt2.jpg","it":"https://image.tmdb.org/t/p/w500/s2FtPcKNwfSQ2cHfv5p0mDjVttk.jpg","es":"https://image.tmdb.org/t/p/w500/pVcWaUbFDL76ObIsReIBQ5ILMHv.jpg"}'::jsonb WHERE id = 176;
UPDATE public.films SET tmdb_id = 244, titoli_i18n = '{"it":"King Kong (King Kong)","fr":"King Kong","en":"King Kong","de":"King Kong und die weiße Frau","es":"King Kong"}'::jsonb, trame_i18n = '{"it":"Una troupe cinematografica si avventura su una misteriosa isola sconosciuta, Skull Island, dove scopre un gorilla gigante venerato come un dio dai nativi. La creatura si invaghisce dell''attrice Ann Darrow, ma viene catturata e portata a New York per essere esibita al pubblico.","fr":"Figurante sans travail, la blonde Ann Darrow est engagée par le réalisateur Carl Denham pour être la vedette de son prochain film. Le Venture, le navire commandé par le capitaine Englehorn et qui comprend toute l''équipe, atteint Skull Island, une île mystérieuse où vivrait une créature légendaire vénérée par les indigènes et appelée King Kong.Durant le voyage, Ann tombe amoureuse de John Driscoll, le second du bateau. Une fois débarqués, les explorateurs sont aussitôt repérés par les indigènes et font marche arrière. Mais ces derniers enlèvent Ann, la \"femme aux cheveux d''or\", et l''attachent pour l''offrir en sacrifice à King Kong.Au moment où ses compagnons arrivent pour la délivrer, un singe gigantesque saisit la jeune fille et disparaît dans la forêt. Denham et ses hommes se lancent alors à la poursuite de King Kong.","en":"Adventurous filmmaker Carl Denham sets out to produce a motion picture unlike anything the world has seen before. Alongside his leading lady Ann Darrow and his first mate Jack Driscoll, they arrive on an island and discover a legendary creature said to be neither beast nor man. Denham captures the monster to be displayed on Broadway as King Kong, the eighth wonder of the world.","de":"Ein amerikanisches Filmteam und die Diva Ann Darrow reisen zu Dreharbeiten auf eine Dschungel-Insel. Die Insel ist das Reich unzähliger Urwelttiere und der Riesenaffe King Kong wird von den Eingeborenen als Gottheit verehrt. Von Zeit zu Zeit bringen sie ihm Menschenopfer dar. Eines Nachts wird die schöne Ann entführt und von den Wilden zur Opferstätte gebracht. Der Affenkönig verschleppt sie in den Dschungel.","es":"Un equipo de cine va a rodar una película a la misteriosa isla de Teschio, al este de Sumatra. Allí descubren la existencia de una civilización prehistórica y de una tribu ancestral que secuestra a la atractiva Ann, la actriz protagonista, para ofrecerla en sacrificio ritual a King, un gigantesco gorila."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/lHlnxKL5GbgRibyRFI7n1Ey850i.jpg","fr":"https://image.tmdb.org/t/p/w500/pFStqHTVUceciD9vineiNJ9WHpA.jpg","en":"https://image.tmdb.org/t/p/w500/lHlnxKL5GbgRibyRFI7n1Ey850i.jpg","de":"https://image.tmdb.org/t/p/w500/jr9kq0PdUmlv4AdooLvWmm7Oys0.jpg","es":"https://image.tmdb.org/t/p/w500/wlRhyQOC67Q9dxqd2Fpsh64kFHh.jpg"}'::jsonb WHERE id = 178;
UPDATE public.films SET tmdb_id = 10730, titoli_i18n = '{"it":"King Kong (King Kong)","de":"King Kong","fr":"King Kong","en":"King Kong","es":"King Kong"}'::jsonb, trame_i18n = '{"it":"Una compagnia petrolifera organizza una spedizione su un''isola perennemente avvolta dalla nebbia. Qui trovano una gigantesca creatura antropomorfa che si invaghisce di una naufraga. Il gorilla viene catturato per scopi pubblicitari e portato nella metropoli di New York.","de":"Fred Wilson Angestellter eines großen amerikanischen Öl-Konzerns, hat den Auftrag, neue Erdölquellen ausfindig zu machen. Mit einem gecharterten Boot macht er sich auf die Reise zu einer noch unbewohnten Insel. Mit an Bord ist auch ein blinder Passagier: Der Anthropologe Jack Prescott  schmuggelte sich auf das Schiff, denn er will auf dieser Insel eine seltene Affenart untersuchen. Unterwegs nehmen sie noch die hübsche Dawn  mit an Bord, die sie in einem Rettungsboot auflesen. Als das Schiff vor der Insel vor Anker geht, stellt sich jedoch heraus, dass diese doch nicht so unbewohnt ist, wie allseits angenommen. Die dort lebenden Eingeborenen führen gerade ein merkwürdiges Ritual auf, um einem überlebensgroßen Affen namens ''Kong'' zu huldigen. Als sie die blonde Dawn erblicken, haben sie ihr ''Opfer'' gefunden...","fr":"Fred Wilson dirige une expédition destinée à trouver de nouveaux gisements de pétrole sur une île inconnue. Jack Prescott, jeune savant qui veut percer les mystères de l''île du Crane et Dwan, une cover-girl recueillie en mer, se joignent à la petite troupe.","en":"An oil company expedition disturbs the peace of a giant ape and brings him back to New York to exploit him.","es":"La \"Petrox Company\" envía una expedición, dirigida por Fred Wilson, a la Micronesia con la intención de encontrar petróleo. Con ellos va Jack Prescott, cuyo objetivo es encontrar un monstruo prehistórico. Durante la travesía, se encuentran un bote con una mujer que se ha salvado del naufragio del barco en que viajaba con un productor de cine. Cuando desembarcan, descubren una gran empalizada, y dentro observan que unos nativos colocan a una mujer nativa en una plataforma, mientras invocan a una misteriosa deidad animal."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/6iSU6sfjQ2fT0wcL3AqruXErVw1.jpg","de":"https://image.tmdb.org/t/p/w500/xzRTGHQlve8ezLwBIbZKjrXMuai.jpg","fr":"https://image.tmdb.org/t/p/w500/sjVMeRoobHilaw0BIWlL9ccuvUy.jpg","en":"https://image.tmdb.org/t/p/w500/paYKhEwUaxKA05vmOfU7FlleTln.jpg","es":"https://image.tmdb.org/t/p/w500/5uNO9Ip3RE9JyaBKjAxEhut9DIV.jpg"}'::jsonb WHERE id = 179;
UPDATE public.films SET tmdb_id = 254, titoli_i18n = '{"en":"King Kong","it":"King Kong (King Kong)","fr":"King Kong","de":"King Kong","es":"King Kong"}'::jsonb, trame_i18n = '{"en":"In 1933 New York, an overly ambitious movie producer coerces his cast and hired ship crew to travel to mysterious Skull Island, where they encounter Kong, a giant ape who is immediately smitten with the leading lady.","it":"Nel 1933, un regista di spettacoli sull''orlo del fallimento convince una troupe e una giovane attrice a salpare verso l''esotica e pericolosa Isola del Teschio. Lì si scontreranno con creature preistoriche e con King Kong, un gorilla gigantesco che svilupperà un profondo legame con la donna.","fr":"Carl Denham, un cinéaste en quête de notoriété, prépare un tournage dans les mers du Sud. Il embarque avec toute son équipe à bord du «Venture». Bien que les acteurs soient persuadés de tourner un film d''amour et d''aventures, le réalisateur espère secrètement que le voyage les conduira à Skull Island (l''île du Crâne), une terre inexplorée où, dit-on, les indigènes adorent une créature mystérieuse et terrifiante. Les foules, pense-t-il, se presseront pour découvrir les images qu''il rapportera de son voyage. Ann Darrow, artiste de music-hall au chômage, a été embauchée au dernier moment pour pallier la défection de l''actrice principale.","de":"Amerika in den 30er Jahren: Für seinen neuen Film will der Regisseur Carl Denham eine ganz besondere Kulisse haben. Diese hat er auch schon in einer abgelegenen Insel, \"Skull Island\", im Gegensatz zu der weiblichen Hauptrolle gefunden. Erst kurz vor der Abreise findet sie sich in der schönen Ann Darrow, die sofort auf das Angebot einsteigt und mitreist. Keiner des Filmteams, nicht mal Denham, war bisher auf der Insel und schnell müssen sie dort feststellen, dass es ein Fehler war, sie dafür auszuwählen. Denn auf ihr lebt ein Eingeborenenstamm, der einen riesigen Gorilla, \"King Kong\", anbetet und ihm von Zeit zu Zeit Menschen opfert. Die Eingeborenen sind so von Ann beeindruckt, dass sie das nächste Opfer sein soll...","es":"La suerte de Ann Darrow cambia cuando conoce a Carl Denham, un empresario que lucha para abrirse camino en el mundo del espectáculo. A ellos se une Jack Driscoll, un autor de teatro neoyorquino. Los tres emprenden un viaje que los llevará hasta una remota isla, donde Denham tiene previsto dirigir una película. Allí descubren un ser increíble, un gorila gigante, King Kong, que habita en una frondosa selva, donde criaturas prehistóricas han vivido ocultas durante millones de años. Denham, con un apetito insaciable de grandeza, enseguida ve la fama que puede reportarle la captura del gorila y su exhibición en Nueva York."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/6a2HY6UmD7XiDD3NokgaBAXEsD2.jpg","it":"https://image.tmdb.org/t/p/w500/3YoB2B7JMn8mJ8IsZDn80Zuyocq.jpg","fr":"https://image.tmdb.org/t/p/w500/pSmIr47IDD72IboEi8SZztN0cR7.jpg","de":"https://image.tmdb.org/t/p/w500/y68X15hwEJTW2PaJkl5rrJpnHyt.jpg","es":"https://image.tmdb.org/t/p/w500/tSfZ6LoZgnz8BOrSQVo24vqv4nW.jpg"}'::jsonb WHERE id = 180;
UPDATE public.films SET tmdb_id = 1362, titoli_i18n = '{"es":"El Hobbit","fr":"Bilbo le hobbit","de":"The Hobbit","it":"Lo Hobbit (The Hobbit)","en":"The Hobbit"}'::jsonb, trame_i18n = '{"es":"Adaptación de la novela \"El Hobbit\". Es además la primera parte de la trilogía animada basada en la obra de Tolkien, formada por El Hobbit (Jules Bass, 1977), El señor de los anillos (Ralph Bakshi, 1978) y El retorno del Rey (Jules Bass, 1980).","fr":"L''histoire de Bilbon Sacquet, hobbit paisible de la Comté, entrainé malgré lui dans une formidable aventure. Accompagné du magicien Gandalf et de treize nains, il devra récupérer un trésor dérobé par le terrible dragon Smaug...Adapté du roman de J.R.R. Tolkien \"Bilbo le hobbit ou l''Histoire d''un aller et retour\" (\"The Hobbit: There and back again\").","de":"Im idyllischen, im Westen des fiktiven Kontinents Mittelerde gelegenen Auenland wohnt das Volk der kleinen, gemütlichen, friedfertigen, menschenähnlichen Hobbits. Als eines Tages der Zauberer Gandalf auftaucht und in seinem Gefolge 13 Zwerge in der Wohnhöhle des Hobbits Bilbo Beutlin einkehren, stellt sich die bisher wohlgeordnete Welt für den Hobbit auf den Kopf. Weil ihn selbst kurz die Abenteuerlust packt, sieht er sich plötzlich zum Meisterdieb ernannt: Er soll den Zwergen helfen, ihren von dem Drachen Smaug gestohlenen Schatz wieder zurückzugewinnen. Als Bezahlung soll er ein 14tel des Schatzes erhalten. Nicht nur, dass für Hobbits die Existenz von Drachen fraglich erscheint und Abenteuer von ihnen verabscheut werden: Der Berg Erebor, in dem der Drache mit dem gestohlenen Schatz lebt, befindet sich noch dazu in einem weit entfernten Land im Osten von Mittelerde.","it":"Un pacifico hobbit di nome Bilbo Baggins viene reclutato dal mago Gandalf e da una compagnia di nani per recuperare un tesoro custodito dal drago Smaug.","en":"The story follows the adventures of Bilbo Baggins, a diminutive creative who resides in a place called Middle-Earth before he is compelled to go on a quest to find a treasure buried deep in the heart of the Lonely Mountain."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/jDSUPyCbyJbFEyysXVSowHhRQWl.jpg","fr":"https://image.tmdb.org/t/p/w500/2ohvyMPhvjftLrM6S6Ljr6QrL0u.jpg","de":"https://image.tmdb.org/t/p/w500/oIBShv7BS22r2DIXUG0G3EVCVIK.jpg","it":"https://image.tmdb.org/t/p/w500/qTU84nwRmfBnukCdjoJaXZwD4qw.jpg","en":"https://image.tmdb.org/t/p/w500/2ohvyMPhvjftLrM6S6Ljr6QrL0u.jpg"}'::jsonb WHERE id = 181;
UPDATE public.films SET tmdb_id = 49051, titoli_i18n = '{"en":"The Hobbit: An Unexpected Journey","fr":"Le Hobbit : Un voyage inattendu","it":"Lo Hobbit - Un viaggio inaspettato (The Hobbit: An Unexpected Journey)","de":"Der Hobbit - Eine unerwartete Reise","es":"El hobbit: Un viaje inesperado"}'::jsonb, trame_i18n = '{"en":"Bilbo Baggins, a hobbit enjoying his quiet life, is swept into an epic quest by Gandalf the Grey and thirteen dwarves who seek to reclaim their mountain home from Smaug, the dragon.","fr":"Dans un voyage inattendu, Bilbon Sacquet cherche à reprendre le Royaume perdu des Nains d''Erebor, conquis par le redoutable dragon Smaug. Alors qu''il croise par hasard la route du magicien Gandalf le Gris, Bilbon rejoint une bande de 13 nains dont le chef n''est autre que le légendaire guerrier Thorin Écu-de-Chêne. Leur périple les conduit au cœur du Pays Sauvage, où ils devront affronter des Gobelins, des Orques, des Ouargues meurtriers, des Araignées géantes, des Métamorphes et des Sorciers… Bien qu''ils se destinent à mettre le cap sur l''Est et les terres désertiques du Mont Solitaire, ils doivent d''abord échapper aux tunnels des Gobelins, où Bilbon rencontre la créature qui changera à jamais le cours de sa vie : Gollum.","it":"Bilbo Baggins viene convinto dal mago Gandalf a unirsi a tredici nani guidati da Thorin Scudodiquercia in un''epica impresa per riconquistare il regno perduto di Erebor dal drago Smaug.","de":"Mit dem Besuch des weisen Zauberers Gandalf verändert sich das beschauliche Leben eines Hobbits für immer. Zögerlich schließt sich der unbedarfte Bilbo mit Gandalf der Mission von 13 mutigen Zwergen an, die ihr Reich zurückerobern wollen. Der furchterregende Drache Smaug, der es einst zerstörte, ist seit Jahrzehnten verschwunden. Doch ist das Monstrum wirklich tot und können die großen Gefahren dieses Abenteuers, darunter gefräßige Orks und wütende Trolle, wirklich von so kleinen Helden überwunden werden?","es":"Precuela de la trilogía \"El Señor de los Anillos\", obra de J.R.R. Tolkien. En compañía del mago Gandalf y de trece enanos, el hobbit Bilbo Bolsón emprende un viaje a través del país de los elfos y los bosques de los trolls, desde las mazmorras de los orcos hasta la Montaña Solitaria, donde el dragón Smaug esconde el tesoro de los Enanos. Finalmente, en las profundidades de la Tierra, encuentra el Anillo Único, hipnótico objeto que será posteriormente causa de tantas sangrientas batallas en la Tierra Media."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/yHA9Fc37VmpUA5UncTxxo3rTGVA.jpg","fr":"https://image.tmdb.org/t/p/w500/mdy9mG31U7jSB8edfRELv53Yfjp.jpg","it":"https://image.tmdb.org/t/p/w500/uoMnJrqlUmEc9etXvD2swUr1Tvu.jpg","de":"https://image.tmdb.org/t/p/w500/bPYCAzOB3M3PZ91BpQzJeReKkP8.jpg","es":"https://image.tmdb.org/t/p/w500/1id2xLxg750ojOWvGWeqPIxmOIF.jpg"}'::jsonb WHERE id = 182;
UPDATE public.films SET tmdb_id = 57158, titoli_i18n = '{"it":"Lo Hobbit - La desolazione di Smaug (The Hobbit: The Desolation of Smaug)","en":"The Hobbit: The Desolation of Smaug","es":"El hobbit: La desolación de Smaug","de":"Der Hobbit - Smaugs Einöde","fr":"Le Hobbit : La Désolation de Smaug"}'::jsonb, trame_i18n = '{"it":"Bilbo Baggins e la compagnia di nani proseguono il loro viaggio verso la Montagna Solitaria, affrontando pericoli come ragni giganti, elfi silvani e infine il temibile drago Smaug.","en":"The Dwarves, Bilbo and Gandalf have successfully escaped the Misty Mountains, and Bilbo has gained the One Ring. They all continue their journey to get their gold back from the Dragon, Smaug.","es":"Tras sobrevivir al inicio de su inesperado viaje, la Compañía sigue hacia el este y se encuentra por el camino con Beorn, el cambiador de piel, y con un enjambre de Arañas gigantes en el peligroso monte Mirkwood. Tras evitar que los Elfos del Bosque los capturen, los Enanos prosiguen su viaje hacia Ciudad del Lago, y finalmente llegan a la Montaña Solitaria, donde tienen que enfrentarse al mayor de los peligros, una criatura más terrorífica que cualquier otra que pondrá a prueba no solo lo profundo de su valentía sino también los límites de su amistad y la sabiduría del viaje: el dragón Smaug.","de":"Die Gefährten haben den Beginn ihrer unerwarteten Reise überstanden – auf ihrem Weg gen Osten begegnen sie nun dem Hautwechsler Beorn und im trügerischen Düsterwald einem Schwarm gigantischer Spinnen. Sie werden von den gefährlichen Waldelben gefangen genommen, können aber entkommen, erreichen Seestadt und schließlich den Einsamen Berg selbst, wo sie sich der größten Gefahr stellen müssen – einem Monster, das alle bisherigen an Grässlichkeit übertrifft: Der Drache Smaug fordert nicht nur den ganzen Mut der Gefährten heraus, sondern stellt auch ihre Freundschaft auf eine harte Probe – bis sie sich schließlich fragen müssen, ob ihre Reise überhaupt noch einen Sinn ergibt.","fr":"Bilbon Sacquet est entraîné dans une quête épique pour reconquérir le Royaume perdu des Nains d''Erebor et l''arracher aux griffes de l''effroyable dragon Smaug. Accompagné de 13 Nains et du Magicien Gandalf le Gris, Bilbon s''introduit dans la Montagne Solitaire armé du ''précieux'' anneau de Gollum et de Dard, sa lame affûtée."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/8AG3NTGNQ4613o7XB8NUFSNW28W.jpg","en":"https://image.tmdb.org/t/p/w500/xQYiXsheRCDBA39DOrmaw1aSpbk.jpg","es":"https://image.tmdb.org/t/p/w500/1s8xZDmG5IkDU0m1LeW28YcwTRx.jpg","de":"https://image.tmdb.org/t/p/w500/60O2sdzZcPX8vXyDOYHi7exrnil.jpg","fr":"https://image.tmdb.org/t/p/w500/9JPVtscMdWGmOoWxNmc1hGdkxtM.jpg"}'::jsonb WHERE id = 183;
UPDATE public.films SET tmdb_id = 122917, titoli_i18n = '{"it":"Lo Hobbit - La battaglia delle cinque armate (The Hobbit: The Battle of the Five Armies)","en":"The Hobbit: The Battle of the Five Armies","de":"Der Hobbit - Die Schlacht der fünf Heere","fr":"Le Hobbit : La Bataille des cinq armées","es":"El hobbit: La batalla de los cinco ejércitos"}'::jsonb, trame_i18n = '{"it":"Mentre Smaug scatena la sua ira su Pontelagolungo, nani, elfi, umani e orchi si scontrano in una titanica battaglia ai piedi della Montagna Solitaria per il controllo del tesoro di Erebor.","en":"Following Smaug''s attack on Laketown, Bilbo and the dwarves try to defend Erebor''s mountain of treasure from others who claim it: the men of the ruined Laketown and the elves of Mirkwood. Meanwhile an army of Orcs led by Azog the Defiler is marching on Erebor, fueled by the rise of the dark lord Sauron. Dwarves, elves and men must unite, and the hope for Middle-Earth falls into Bilbo''s hands.","de":"Nachdem Smaug besiegt wurde, sitzt Thorin endlich auf dem Zwergenthron und hat sein Reich wieder. Doch der Kampf gegen den Drachen hat Spuren hinterlassen. Die Stadt Esgaroth wurde zerstört, ihre Bewohner sind nun obdachlos. Doch Thorin verweigert jede Hilfe genauso wie die Rückgabe von Teilen des Schatzes, die Smaug gestohlen hatte. Hobbit Bilbo versucht zwischen Zwergen, Elben und den Bürgern zu vermitteln, doch vergeblich. Thorin hält ihn für einen Verräter und auch Gandalf kann nichts mehr ausrichten. Es wird aufgerüstet und bald stehen sich die Armeen gegenüber…","fr":"Atteignant enfin la Montagne Solitaire, Thorin et les Nains, aidés par Bilbon le Hobbit, ont réussi à récupérer leur royaume et leur trésor. Ils ont également réveillé le dragon Smaug qui déchaîne désormais sa colère sur les habitants de Lac-ville. À présent, les Nains, les Elfes, les Humains mais aussi les Wrags et les Orques menés par le Nécromancien, convoitent les richesses de la Montagne Solitaire.","es":"Después de haber recuperado el reino del Dragón Smaug, la Compañía ha desencadenado, sin querer, una potencia maligna. Un Smaug enfurecido vuela hacia la Ciudad del Lago para acabar con cualquier resto de vida. Obsesionado sobre todo con el reino recuperado, Thorin sacrifica la amistad y el honor para mantenerlo mientras que Bilbo intenta frenéticamente hacerle ver la razón por la que el hobbit toma una decisión desesperada y peligrosa. Pero hay aún mayores peligros por delante. Sin la ayuda aparente del mago Gandalf, su gran enemigo Sauron ha enviado legiones de orcos hacia la Montaña Solitaria en un ataque furtivo. Cuando la oscuridad se cierna sobre ellos, las razas de los Enanos, Elfos y Hombres deben decidir si unirse o ser destruidos. Bilbo se encontrará así en la batalla épica de los Cinco Ejércitos, donde el futuro de la Tierra Media está en juego."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/A2RkCwo2gcWX6OXL2B46eOU7Wv6.jpg","en":"https://image.tmdb.org/t/p/w500/xT98tLqatZPQApyRmlPL12LtiWp.jpg","de":"https://image.tmdb.org/t/p/w500/mNZ4MxL0KdW9VBMXSAhiiGFDYaa.jpg","fr":"https://image.tmdb.org/t/p/w500/h4wjbuC61iMaCqrO3bmGQ3ibuJE.jpg","es":"https://image.tmdb.org/t/p/w500/6OiNSLcRKJsBLXwb6DEi6IQ0JFk.jpg"}'::jsonb WHERE id = 184;
UPDATE public.films SET tmdb_id = 3589, titoli_i18n = '{"fr":"C''est arrivé demain","de":"Was morgen geschah","es":"Sucedió mañana","en":"It Happened Tomorrow","it":"Avvenne domani (It Happened Tomorrow)"}'::jsonb, trame_i18n = '{"fr":"Larry Stevens, journaliste à l''Evening News, rencontre par hasard un journaliste retraité qui lui remet un journal, il découvre avec stupéfaction qu''il s''agit d''un journal prémonitoire : daté du lendemain et annonçant des événements à venir...","de":"Ein junger Reporter kommt dreimal in den Besitz einer Zeitung vom nächsten Tag und weiß dadurch die Neuigkeiten von morgen schon heute. Seine sensationellen Berichte machen ihn stadtbekannt, da liest er auf der Titelseite die Nachricht von seinem eigenen Tod.","es":"Larry Stevens trabaja como reportero del Evening News de Nueva York y está a punto de celebrar sus bodas de oro con su esposa Sylvia y toda su familia. Durante la fiesta, cuenta un extraño hecho que le sucedió a fines del siglo XIX, cuando el viejo Benson, el encargado de la hemeroteca del periódico, al que apenas conocía, le entregó un ejemplar del Evening News que vaticinaba con un día de antelación las noticias que iban a producirse","en":"A young turn-of-the-century newspaper man finds he can get hold of the next day''s paper. This brings more problems than fortune, especially as his new girlfriend is part of a phony clairvoyant act.","it":"Un giovane giornalista riceve da un anziano archivista defunto copie del giornale del giorno successivo. Grazie a questa straordinaria opportunità, riesce a realizzare scoop sensazionali, ma le cose si complicano quando legge la notizia della propria morte imminente."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/wquWfiCLZqKoWR9s6tpyCkmrGKJ.jpg","de":"https://image.tmdb.org/t/p/w500/iIQ3CSZT2d84S6fZY2MPuvcKVwT.jpg","es":"https://image.tmdb.org/t/p/w500/gkaZb6YyihQKX9NSSDV5hUFgHJK.jpg","en":"https://image.tmdb.org/t/p/w500/byWjI8SYnATh0OdnaCCKhO9nY0R.jpg","it":"https://image.tmdb.org/t/p/w500/hWKQ54scA6qCU6Wtl3euUJJCKAq.jpg"}'::jsonb WHERE id = 185;
UPDATE public.films SET tmdb_id = 11352, titoli_i18n = '{"es":"Always (Para Siempre)","en":"Always","it":"Always - Per sempre (Always)","de":"Always - Der Feuerengel von Montana","fr":"Always"}'::jsonb, trame_i18n = '{"es":"Pete Sandich, un temerario piloto que se dedica a la extinción de incendios, muere en acto de servicio tras salvarle la vida a un amigo. En el cielo, se encuentra con un ángel femenino que lo conmina a regresar a la Tierra para proteger la vida y convertir en un experto piloto al novato Ted Baker. El único problema es que Ted está enamorado de la antigua novia de Pete.","en":"The spirit of a recently deceased expert pilot mentors a newer pilot while watching him fall in love with the girlfriend that he left behind.","it":"Un audace pilota di aerei antincendio muore in un incidente di volo, ma ritorna sulla Terra sotto forma di spirito guida per aiutare un giovane pilota alle prime armi e vegliare sulla donna che amava, faticando ad accettare che lei debba rifarsi una vita senza di lui.","de":"Pete Sandich ist ein legendärer Pilot mit einer Leidenschaft für waghalsige Löscheinsätze aus der Luft. Dorinda, der Frau seines Herzens, und seinem besten Freund Al ist aber längst schmerzlich bewusst, dass auch Legenden nicht ewig auf Risiko fliegen können. Als Sandich bei einem Einsatz sein Leben gibt, um Al zu retten, steht das Fliegerass plötzlich vor seiner größten Herausforderung: Pete muss Dorinda helfen, ins Leben zurückzukehren.","fr":"Pete Sandich est l’as des “Pompiers volants” du Montana. Casse-cou invétéré malgré son amour pour son amie Dorida et son amitié pour son complice de toujours, Al, l’heure de l’ultime vol arrive… Cinq mois plus tard, Pete se réveille dans une forêt carbonisée. Une femme lui sourit et lui ordonne de regagner la Terre et d’insuffler sa “Divine inspiration” à ceux qu’il aime."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/eKl56eFm2ZI0TYST1Ld82IZrOVD.jpg","en":"https://image.tmdb.org/t/p/w500/r7LTwkgqUPPABnHpxceVylMf8M0.jpg","it":"https://image.tmdb.org/t/p/w500/gV89aOidilmkQBa75HVEZwRMp1W.jpg","de":"https://image.tmdb.org/t/p/w500/z5lYFt4Qi9W3EtZAMkD032t2VSh.jpg","fr":"https://image.tmdb.org/t/p/w500/7YLy9VwVwIDXohRYyAIjFyqZRaq.jpg"}'::jsonb WHERE id = 186;
UPDATE public.films SET tmdb_id = 86000, titoli_i18n = '{"it":"Always (Ojik geudaeman)","en":"Always","de":"Always","es":"Siempre / Solo tú","fr":"Always"}'::jsonb, trame_i18n = '{"en":"A former boxer turned parking lot attendant finds hope in the love of the blind telemarketer who walks into his booth one day.","de":"Cheol-min nimmt einen Teilzeitjob als Nachtwärter auf einem Parkplatz an. Dort trifft er zufällig auf die blinde und lebensfrohe Jung-hwa, zu der er sich immer mehr hingezogen fühlt. Als sie ihn nach seiner Vergangenheit fragt, die er anderen gegenüber verheimlicht, reagiert er aggressiv und ihr Verhältnis kühlt ab. Als Jung-hwa bedroht wird, kann er sie aber beschützen und ihr beider Leben ändert sich radikal. Bei einer Untersuchung stellt sich aber heraus, dass Jung-hwa ohne eine sofortige Operation ihr Augenlicht für immer verlieren könnte. Cheol-min erkennt, dass ihre beiden Leben auf tragische Art und Weise miteinander zusammenhängen. Um die Operation zu finanzieren, macht er bei einem gefährlichen Boxkampf mit.","es":"Cheol Min, un ex-boxeador con un pasado oscuro y misterioso, acepta el trabajo nocturno atendiendo un parking. Un día,conoce a una chica llamada Jung Hwa que quedó ciega a consecuencias de un accidente de tráfico,ella entra en la cabina donde trabaja y sin saber que es él, le da caramelos y mandarinas. Pasan asi los días y entre ellos surgirá un amor mutuo. Jun Hwa, al hacerse un chequeo médico pone en conocimiento de Cheol Min que de no hacerse la operación pronto para recobrar la vista más adelante seria demasiado tarde. Cheol Min hara lo imposible por conseguir que Jun Hwa se opere, pero ¿será suficiente? ¿Que hará para poder conseguir todo el dinero de la operación?","fr":"Une histoire d''amour entre un ancien boxeur Chul-min et une spécialiste en télémarketing aveugle Jung-hwa.","it":"Un ex pugile dal passato tormentato, che ora lavora come guardiano di un parcheggio, incontra una ragazza non vedente ma piena di vitalità. Tra i due nasce un profondo legame d''amore, ma il passato dell''uomo tornerà a minacciare la loro felicità e la vista della donna."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zqw49pO0FndPZL5LVkq85JCNIVH.jpg","en":"https://image.tmdb.org/t/p/w500/7PaCGnjY87sc9088zxFf34Tamcz.jpg","de":"https://image.tmdb.org/t/p/w500/zqw49pO0FndPZL5LVkq85JCNIVH.jpg","es":"https://image.tmdb.org/t/p/w500/zqw49pO0FndPZL5LVkq85JCNIVH.jpg","fr":"https://image.tmdb.org/t/p/w500/zqw49pO0FndPZL5LVkq85JCNIVH.jpg"}'::jsonb WHERE id = 187;
UPDATE public.films SET tmdb_id = 144231, titoli_i18n = '{"de":"Always … But Not Forever","fr":"Always … But Not Forever","en":"Always … But Not Forever","it":"Always","es":"Always … But Not Forever"}'::jsonb, trame_i18n = '{"en":"A middle-aged couple, on the verge of proceeding with a divorce, find themselves questioning their decision to separate when fellow friends and neighbors, oblivious to their marital troubles, assemble at their house for a 4th of July Weekend party.","it":"Un regista e la sua ex moglie trascorrono insieme il fine settimana del Giorno dell''Indipendenza per formalizzare il loro divorzio, ma la convivenza temporanea riaccende vecchi sentimenti e costringe entrambi a confrontarsi con i motivi della fine del loro matrimonio."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg","fr":"https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg","en":"https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg","it":"https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg","es":"https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg"}'::jsonb WHERE id = 188;
